INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99c31dfe-6b2d-5611-b535-71b63d892158','Native file analysis','Examination of a recording''s own file structure, including container layout, atom or chunk ordering, encoder fields, packet and quantization structure, and embedded metadata, as written by the originating device, to assess authenticity and integrity. By comparing the structure against known exemplars from the same device or software, an examiner can detect re-encoding, editing by a different program, or inconsistencies that indicate the file is not an unaltered original. It complements listening- and waveform-based methods with container-level evidence.','This studies how a file is built inside. It looks at the wrapper, coder fields, and hidden data. These are compared to files from the same device. A mismatch can show editing or re-saving. It checks the file, not just the sound.','To test a recording''s authenticity from its internal structure, catching alterations that leave the audio sounding normal but change the file''s makeup.','Using a hex viewer and reference exemplars, an examiner compares a phone recording''s atom order and encoder settings to a genuine device capture to confirm it is an unedited original.','Forensic Audio & Investigative Acoustics',ARRAY['Container metadata','Codec lineage','Original recording','Authentication','Transcoding history']::text[],ARRAY['Assuming identical audio guarantees an identical, unaltered file','Lacking a reference exemplar from the same device or app','Confusing normal app re-encoding with deliberate tampering','Trusting metadata timestamps without structural corroboration']::text[],ARRAY['Comparing a submitted file''s structure to a genuine device capture','Detecting that audio was re-saved in an editor','Confirming a recording is an unaltered native original']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Native file analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99c31dfe-6b2d-5611-b535-71b63d892158','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99c31dfe-6b2d-5611-b535-71b63d892158') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99c31dfe-6b2d-5611-b535-71b63d892158');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4635b2b4-ff12-52df-bb58-e6a97838c71f','Container metadata','The descriptive and technical information stored within a media file''s container, such as fields in WAV or Broadcast Wave chunks, MP4 or QuickTime atoms, or ID3 tags, including creation and modification timestamps, encoder identification, sample rate, channel count, and device or software strings. In forensic examination this metadata provides evidence about a file''s origin and processing history, but because it can be absent, altered, or reset by copying and editing, it must be corroborated by structural and signal analysis rather than trusted alone.','This is data about the file, stored inside it. It can list the date, device, coder, and format. It hints at where a recording came from. But it can be changed or wiped with ease. So it must be checked against other clues.','To supply origin and history clues about a recording that guide authentication, while flagging that these fields are editable and need corroboration.','An examiner reads Broadcast Wave and encoder fields with a metadata tool, notes a creation timestamp and software string, then tests whether they agree with the file structure and audio content.','Forensic Audio & Investigative Acoustics',ARRAY['Native file analysis','Codec lineage','Original recording','Authentication','Transcoding history']::text[],ARRAY['Trusting metadata timestamps as proof of when audio was recorded','Assuming missing metadata proves tampering','Overlooking that copying or editing can rewrite these fields','Ignoring encoder strings that reveal a re-encode']::text[],ARRAY['Reading creation dates on a submitted recording','Spotting an encoder string that shows editing software','Corroborating metadata against file structure']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Container metadata');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4635b2b4-ff12-52df-bb58-e6a97838c71f','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4635b2b4-ff12-52df-bb58-e6a97838c71f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4635b2b4-ff12-52df-bb58-e6a97838c71f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ed63d16-d1d2-5909-b350-59bfa3f16c2d','Codec lineage','The sequence of encoding and decoding operations a recording has passed through, inferred from characteristic traces each codec and re-encode leaves in the signal and file structure, such as bandwidth limits, quantization patterns, block or frame boundaries, and metadata. Reconstructing codec lineage helps determine whether audio was captured natively, re-compressed, or converted between formats, which informs authenticity and integrity conclusions.','This is the chain of formats a recording went through. Each coder leaves its own marks. Examiners read these marks in the sound and file. This shows if audio was squeezed or converted. It helps judge whether a file is untouched.','To reconstruct a recording''s compression history so an examiner can tell native capture from later re-encoding and conversion.','Spotting a low upper-frequency cutoff and lossy frame traces inside a WAV file, an examiner concludes the audio was once compressed and later rewrapped, revealing its codec lineage.','Forensic Audio & Investigative Acoustics',ARRAY['Transcoding history','Lossy compression signature','Double-compression artifact','Native file analysis','Generation loss']::text[],ARRAY['Assuming a WAV file was always uncompressed','Missing that a lossless wrapper can hide earlier lossy coding','Confusing codec traces with deliberate editing','Ignoring bandwidth cues that reveal past compression']::text[],ARRAY['Finding lossy traces inside a WAV export','Reconstructing how a shared clip was re-encoded','Judging whether audio is a native device capture']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Codec lineage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ed63d16-d1d2-5909-b350-59bfa3f16c2d','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ed63d16-d1d2-5909-b350-59bfa3f16c2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ed63d16-d1d2-5909-b350-59bfa3f16c2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c364880d-98aa-5a37-97b0-062a4dc5ed5c','Transcoding history','The record of format conversions a recording has undergone, where transcoding is the decoding of one encoded form and re-encoding into another codec or the same one, each pass potentially altering bandwidth, adding quantization noise, and cascading compression artifacts. In authentication, evidence of transcoding indicates the file is a derivative and constrains what structural and metadata findings can prove about the original.','This is the list of format changes a file went through. Transcoding means decoding audio and coding it again. Each pass can add noise and cut the high end. It shows a file is a copy, not the first. That changes what the file can prove.','To document format-conversion steps so an examiner can gauge quality loss and recognize that the file is a processed derivative.','An examiner infers from stacked artifacts that a clip was recorded as one lossy format, exported to another, then rewrapped, and reports this transcoding history when assessing authenticity.','Forensic Audio & Investigative Acoustics',ARRAY['Codec lineage','Generation loss','Double-compression artifact','Derivative recording','Lossy compression signature']::text[],ARRAY['Assuming one conversion is harmless to quality','Treating a transcoded file as an original','Blaming transcoding noise on tampering','Ignoring that repeated transcoding compounds artifacts']::text[],ARRAY['Tracing a clip converted between messaging apps','Explaining quality loss from repeated re-encoding','Assessing whether a file is a heavily transcoded derivative']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transcoding history');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c364880d-98aa-5a37-97b0-062a4dc5ed5c','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c364880d-98aa-5a37-97b0-062a4dc5ed5c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c364880d-98aa-5a37-97b0-062a4dc5ed5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2838429-e07e-5f9a-a9f9-831ff1a5b891','Generation loss','The cumulative degradation of quality that occurs each time a recording is copied or re-encoded through a lossy process, so that successive generations progressively lose bandwidth and detail while accumulating quantization noise and compression artifacts. Originally describing analogue tape dubbing, the term applies to digital lossy re-encoding, where each generation discards information that cannot be recovered.','This is quality lost with each copy. Every lossy re-save throws away some detail. The loss stacks up over many copies. Later versions sound worse than the first. What is lost cannot be brought back.','To explain why repeatedly copied or re-encoded audio degrades, and why the original is preferred for analysis over later generations.','Noting hollow, artifact-laden speech in a clip shared through several apps, an examiner attributes the quality to generation loss and seeks the original for cleaner analysis.','Forensic Audio & Investigative Acoustics',ARRAY['Transcoding history','Codec lineage','Derivative recording','Lossy compression signature','Double-compression artifact']::text[],ARRAY['Expecting enhancement to restore detail lost to re-encoding','Assuming digital copies never lose quality','Confusing generation-loss artifacts with tampering','Ignoring how many generations a file has passed through']::text[],ARRAY['Explaining poor quality in a much-shared clip','Preferring the original over a degraded copy','Recognizing stacked artifacts from repeated re-encoding']::text[],'beginner',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Generation loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2838429-e07e-5f9a-a9f9-831ff1a5b891','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2838429-e07e-5f9a-a9f9-831ff1a5b891') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2838429-e07e-5f9a-a9f9-831ff1a5b891');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '417dda74-bf0e-51cc-bd6e-3e5ad4f828cd','Lossy compression signature','The characteristic set of traces that lossy audio coding, such as MP3, AAC, or speech codecs, leaves in a signal, including a codec-dependent high-frequency bandwidth limit, quantization of spectral coefficients within coding bands, time-frequency block structure, and pre-echo around transients. Detecting such a signature in a file, especially one presented as uncompressed, reveals prior lossy encoding and supports authentication and codec-lineage conclusions.','This is the mark a coder leaves in audio. Lossy coders like MP3 cut high sounds. They also make the sound coarser in blocks. These marks stay even after a change of format. Finding them shows the audio was once squeezed.','To let an examiner detect prior lossy encoding from the signal itself, exposing hidden compression history behind a lossless wrapper.','In a spectrogram an examiner sees a sharp upper-frequency cutoff and band quantization, identifies the lossy compression signature, and concludes a WAV file was previously encoded as MP3.','Forensic Audio & Investigative Acoustics',ARRAY['Spectral band edge','Codec lineage','Double-compression artifact','Transcoding history','Generation loss']::text[],ARRAY['Assuming a WAV extension means the audio was never compressed','Mistaking a codec bandwidth limit for microphone response','Overlooking faint block artifacts in a converted file','Reading compression traces as deliberate editing']::text[],ARRAY['Detecting past MP3 coding in a submitted WAV','Reading spectral clues to a file''s compression history','Supporting a codec-lineage conclusion']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lossy compression signature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '417dda74-bf0e-51cc-bd6e-3e5ad4f828cd','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='417dda74-bf0e-51cc-bd6e-3e5ad4f828cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='417dda74-bf0e-51cc-bd6e-3e5ad4f828cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6836ab71-58bc-5657-8bf3-b9c2a357a586','Spectral band edge','An abrupt upper boundary in a recording''s spectrum, seen on a spectrogram as a horizontal line above which little or no energy exists, produced when a codec or filter removes content above a set frequency. Because lossy encoders impose a bitrate-dependent low-pass limit, for example near 16 kilohertz for many common MP3 settings, the location of a spectral band edge is diagnostic of prior compression or filtering and helps identify the codec and its settings.','This is a sharp top limit in the sound''s range. On a spectrogram it looks like a flat ceiling. Above it there is almost no energy. Coders make it by cutting high sounds. Its height hints at the coder and quality used.','To provide a visible, measurable clue to prior compression or filtering and to the codec and settings that produced it.','An examiner measures a hard cutoff near 16 kilohertz in a spectrogram and infers the audio was encoded at a common MP3 bitrate, using the band edge in a codec-lineage analysis.','Forensic Audio & Investigative Acoustics',ARRAY['Lossy compression signature','Low-pass cutoff artifact','Codec lineage','Spectrogram','Transcoding history']::text[],ARRAY['Confusing a codec band edge with a microphone''s natural roll-off','Reading a gentle roll-off as a hard band edge','Assuming the band edge alone fixes the exact codec','Ignoring resampling as another cause of an upper limit']::text[],ARRAY['Estimating MP3 bitrate from a spectrogram ceiling','Distinguishing compression cutoff from microphone response','Supporting a claim of prior encoding']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral band edge');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6836ab71-58bc-5657-8bf3-b9c2a357a586','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6836ab71-58bc-5657-8bf3-b9c2a357a586') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6836ab71-58bc-5657-8bf3-b9c2a357a586');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '601f99b2-0b28-5335-948c-a34bb5480e55','Low-pass cutoff artifact','A signal feature in which energy above a particular frequency is strongly attenuated or absent because a low-pass filter or codec bandwidth limit has been applied, appearing on a spectrogram as a defined upper boundary and audibly as reduced brightness. In forensics its presence, sharpness, and frequency help distinguish deliberate filtering, codec band-limiting, resampling, and transmission-channel limits, informing both authenticity and enhancement decisions.','This means missing high-frequency sound. A filter or coder has removed the top end. It shows as a ceiling on a spectrogram. It also makes audio sound dull. Its shape helps show what caused it.','To signal that a bandwidth limit has been imposed, whose cause, whether filter, codec, resampling, or channel, affects interpretation of the recording.','Seeing energy vanish above 3.4 kilohertz, an examiner recognizes a telephone-band cutoff artifact and treats the file as narrowband phone audio during analysis and comparison.','Forensic Audio & Investigative Acoustics',ARRAY['Spectral band edge','Lossy compression signature','Telephone bandwidth','Codec lineage','Forensic audio enhancement']::text[],ARRAY['Assuming a cutoff always means intentional filtering','Overlooking the telephone channel as the cause','Confusing an anti-alias cutoff with codec band-limiting','Trying to enhance content that was never present above the cutoff']::text[],ARRAY['Identifying telephone-band audio from a 3.4 kilohertz ceiling','Separating filter cutoffs from codec limits','Setting realistic goals for enhancement']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-pass cutoff artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '601f99b2-0b28-5335-948c-a34bb5480e55','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='601f99b2-0b28-5335-948c-a34bb5480e55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='601f99b2-0b28-5335-948c-a34bb5480e55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8adc9a32-ad75-57ed-860b-0b9010cf07ff','Double-compression artifact','Traces left when audio that was already lossily encoded is decoded and re-encoded, causing a characteristic interaction between the two codecs'' quantization grids and framing. In detection, statistical irregularities in coefficient distributions or frame energies can reveal that a signal has been compressed more than once, and localized inconsistencies in double compression can indicate that part of a recording was edited and re-encoded.','This comes from squeezing audio twice. The second coder clashes with the first coder''s grid. This leaves odd patterns in the data. Finding them shows the file was re-coded. Uneven patterns can even hint at editing.','To detect that audio has been re-encoded and, through local inconsistencies, to flag possible edited-and-re-saved regions.','Using coefficient-histogram analysis, an examiner finds double compression across a clip but a different pattern in one segment, suggesting that portion was altered before re-encoding.','Forensic Audio & Investigative Acoustics',ARRAY['Lossy compression signature','Transcoding history','Codec lineage','Splice boundary','Authentication']::text[],ARRAY['Assuming double compression by itself proves tampering','Missing double coding hidden by a lossless wrapper','Confusing normal re-encoding with a malicious edit','Overreaching from weak statistical signs']::text[],ARRAY['Detecting re-encoding in a submitted clip','Localizing a possible edit within a re-saved file','Supporting an authenticity opinion with coding statistics']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Double-compression artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8adc9a32-ad75-57ed-860b-0b9010cf07ff','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8adc9a32-ad75-57ed-860b-0b9010cf07ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8adc9a32-ad75-57ed-860b-0b9010cf07ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3641bfa4-7c42-5dab-95fa-4772c790f5b4','Dropout analysis','Examination of brief losses or interruptions of signal in a recording, appearing as momentary silences, level drops, or muted samples, to determine their cause, such as media defects, buffer underruns, packet loss in networked or wireless audio, or deliberate deletion. Distinguishing benign, technically explicable dropouts from those that indicate editing or evidential gaps is central to authentication and to interpreting what a recording does and does not contain.','This studies short gaps in a recording. Sound may briefly vanish or go mute. Causes include media faults, wireless loss, or deletion. The examiner works out which cause fits. This separates normal glitches from real edits.','To explain short signal losses so an examiner can tell ordinary technical dropouts from gaps that suggest editing or missing evidence.','Finding regular muted samples in a Bluetooth recording, an examiner attributes them to packet loss rather than tampering, documenting the dropout pattern in the authenticity report.','Forensic Audio & Investigative Acoustics',ARRAY['Waveform discontinuity','Authentication','Noise-floor continuity','Splice boundary','Generation loss']::text[],ARRAY['Assuming every dropout is a deliberate deletion','Ignoring wireless packet loss as a natural cause','Missing a suspicious dropout among normal ones','Not comparing dropout timing to the recording channel used']::text[],ARRAY['Explaining muted gaps in a Bluetooth recording','Checking whether a silence marks a deletion','Documenting media-fault dropouts in an old tape transfer']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dropout analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3641bfa4-7c42-5dab-95fa-4772c790f5b4','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3641bfa4-7c42-5dab-95fa-4772c790f5b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3641bfa4-7c42-5dab-95fa-4772c790f5b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '176759e9-1028-5b93-91dc-08a050603c9d','Waveform discontinuity','An abrupt, physically implausible break in the sample-to-sample continuity of an audio waveform, such as a sudden step in amplitude or a broken periodic structure, that can indicate a cut, splice, deletion, or insertion, though it may also arise from clipping, dropouts, or coding artifacts. Locating and characterizing such discontinuities at the sample level is a core authentication technique for detecting editing.','This is a sudden break in the wave. The sample values jump in a way real sound rarely does. It can mark a cut, splice, or deletion. But clipping or gaps can cause breaks too. The examiner must find the true cause.','To flag sample-level breaks that may reveal editing, giving authentication a concrete, measurable feature to examine.','Zooming to sample level at a suspicious point, an examiner finds an abrupt amplitude step and phase break consistent with an inserted segment, marking it as a candidate splice.','Forensic Audio & Investigative Acoustics',ARRAY['Splice boundary','Phase discontinuity','Dropout analysis','Authentication','Background continuity']::text[],ARRAY['Reading every step in the waveform as an edit','Confusing clipping flat-tops with a splice break','Overlooking codec framing as a cause of small steps','Not corroborating a discontinuity with phase and background cues']::text[],ARRAY['Inspecting a suspected cut at sample level','Distinguishing a splice from clipping','Building an editing case from multiple discontinuities']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waveform discontinuity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '176759e9-1028-5b93-91dc-08a050603c9d','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='176759e9-1028-5b93-91dc-08a050603c9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='176759e9-1028-5b93-91dc-08a050603c9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '90aec6e4-5dfa-5430-b280-2e25f3b1d05a','Splice boundary','The point in a recording where two separately sourced segments have been joined, whether by physical tape editing or digital cut-and-paste, often marked by discontinuities in waveform, phase, background noise, room acoustic, or spectral content across the join. Detecting and characterizing splice boundaries is a central task of tape and digital authentication, since a splice can add, remove, or reorder content.','This is where two clips are joined. It may show a break in the wave or phase. The background noise or room sound may also jump. These clues mark where audio was cut together. Splices can add or remove content.','To identify joins between segments, revealing edits that change what a recording appears to contain.','At a suspected join an examiner finds the noise floor and room tone change abruptly along with a phase break, and reports a splice boundary in the authenticity examination.','Forensic Audio & Investigative Acoustics',ARRAY['Waveform discontinuity','Phase discontinuity','Background continuity','Noise-floor continuity','Authentication']::text[],ARRAY['Relying on one clue instead of several to call a splice','Missing a well-crafted splice hidden by a crossfade','Confusing a natural pause with an edit join','Ignoring background and room changes across the boundary']::text[],ARRAY['Detecting an edit that joins two conversations','Confirming a splice with multiple independent clues','Examining a tape for physical splice marks']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Splice boundary');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '90aec6e4-5dfa-5430-b280-2e25f3b1d05a','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='90aec6e4-5dfa-5430-b280-2e25f3b1d05a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='90aec6e4-5dfa-5430-b280-2e25f3b1d05a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '62c14d51-3a53-531b-a31b-7db85221c7de','Phase discontinuity','An abrupt break in the expected phase continuity of a waveform or of its periodic components at a point in a recording, where the ongoing cycle structure is interrupted rather than continuing smoothly. Because natural sound and continuous recording preserve phase across time, an unexplained phase discontinuity can indicate a splice, insertion, or deletion, and it is used alongside amplitude and background analysis in authentication.','This is a sudden jump in a wave''s cycle. Normally cycles flow on smoothly. A break in that flow is unusual. It can point to a cut or insert. It is one clue among several for edits.','To provide a phase-based indicator of possible editing that complements amplitude and background-noise analysis.','Examining a tonal hum through a suspected edit, an examiner sees the hum''s phase jump at one instant and treats it as evidence of a splice.','Forensic Audio & Investigative Acoustics',ARRAY['Waveform discontinuity','Splice boundary','Hum signature','Authentication','Background continuity']::text[],ARRAY['Treating a phase jump alone as proof of editing','Confusing codec or dropout effects with an edit-caused break','Overlooking that some processing can shift phase','Not checking a steady tone to test phase continuity']::text[],ARRAY['Using a hum''s phase to test for a splice','Corroborating a waveform break with a phase break','Distinguishing processing from editing']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase discontinuity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '62c14d51-3a53-531b-a31b-7db85221c7de','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='62c14d51-3a53-531b-a31b-7db85221c7de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='62c14d51-3a53-531b-a31b-7db85221c7de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '017cb2fa-f40c-5cac-a3aa-dedc57e826d4','Room impulse signature','The characteristic imprint that a space''s acoustics, its pattern of early reflections and reverberant decay captured in the room impulse response, leaves on recorded sound. Because each environment and microphone placement yields a distinctive reverberant signature, comparing this signature across a recording tests acoustic consistency; a change can indicate that segments were recorded in different places or that material was inserted.','This is the sound-print of a space. Rooms add their own echoes and decay. Each room and mic spot sounds a bit different. This print should stay steady in one recording. A sudden change can hint at an edit.','To characterize the recording space so an examiner can test whether a recording was made continuously in one environment.','Comparing reverberant tails across a clip, an examiner finds one segment carries a different room signature and flags it as possibly recorded elsewhere or inserted.','Forensic Audio & Investigative Acoustics',ARRAY['Acoustic scene consistency','Room impulse response','Background continuity','Authentication','Reverberation']::text[],ARRAY['Assuming reverberation cannot reveal edits','Ignoring microphone movement as a cause of changing acoustics','Confusing added artificial reverb with a real room','Judging the signature from too short a segment']::text[],ARRAY['Testing whether segments share one room','Spotting an inserted clip by its different acoustics','Assessing continuity in a covert recording']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room impulse signature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '017cb2fa-f40c-5cac-a3aa-dedc57e826d4','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='017cb2fa-f40c-5cac-a3aa-dedc57e826d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='017cb2fa-f40c-5cac-a3aa-dedc57e826d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '256384e0-df67-5c37-b19d-c98c56545676','Acoustic scene consistency','The degree to which the acoustic characteristics of a recording, including background sounds, reverberation, noise floor, and spatial cues, remain coherent and plausibly continuous throughout, consistent with a single continuous capture in one environment. Testing acoustic scene consistency is an authentication method: abrupt, unexplained changes in the acoustic scene can indicate editing, insertion, or the joining of separately recorded material.','This means the background stays steady. Room sound, noise, and ambience should flow smoothly. In one true recording they do not jump. A sudden shift can signal an edit. Examiners test this across the whole clip.','To provide a holistic authentication check based on whether the whole sonic environment behaves like one continuous recording.','An examiner reviews ambience, reverberation, and noise floor across a recording and, finding them consistent, reports no acoustic evidence of editing.','Forensic Audio & Investigative Acoustics',ARRAY['Background continuity','Room impulse signature','Noise-floor continuity','Authentication','Reverberation']::text[],ARRAY['Expecting perfect consistency when the source scene truly changed','Missing subtle scene shifts at a well-made edit','Relying on ambience alone without waveform checks','Confusing a moving source with an edit']::text[],ARRAY['Checking a whole recording for editing signs','Judging whether ambience supports a continuous capture','Combining scene analysis with waveform authentication']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic scene consistency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '256384e0-df67-5c37-b19d-c98c56545676','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='256384e0-df67-5c37-b19d-c98c56545676') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='256384e0-df67-5c37-b19d-c98c56545676');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef4b6124-2df5-5196-876a-4eed680f6b81','Background continuity','The uninterrupted, smoothly evolving persistence of a recording''s background sounds, such as ambient noise, hum, machinery, or environmental sound, across its duration, as expected of a single continuous capture. In authentication, breaks in background continuity, such as a sudden change or interruption in ongoing background noise at a point, are strong indicators of a splice, deletion, or insertion.','This means the background runs on smoothly. Steady sounds like hum or traffic should not jump. In one true recording they flow without breaks. A sudden change marks a possible edit. It is a key clue for editing.','To use steady background sound as a baseline whose interruption exposes edits that speech alone might hide.','Tracking a steady air-conditioning hum, an examiner finds it cut off abruptly at one point and treats the break in background continuity as evidence of a deletion.','Forensic Audio & Investigative Acoustics',ARRAY['Noise-floor continuity','Acoustic scene consistency','Splice boundary','Hum signature','Authentication']::text[],ARRAY['Assuming background noise is irrelevant to authenticity','Confusing a real change in the scene with an edit','Missing a break masked by a crossfade','Testing continuity only during speech, not in gaps']::text[],ARRAY['Following a steady hum to detect a deletion','Checking gaps between speech for background breaks','Corroborating a splice with a background change']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Background continuity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef4b6124-2df5-5196-876a-4eed680f6b81','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef4b6124-2df5-5196-876a-4eed680f6b81') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef4b6124-2df5-5196-876a-4eed680f6b81');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd31855f6-d739-5752-8182-0f318c4de690','Noise-floor continuity','The consistency of a recording''s residual background noise level and spectral character across its duration, reflecting an unbroken capture through one signal chain. In authentication the noise floor is expected to persist smoothly; a sudden change in its level or spectrum, or a break in it, can indicate editing, a change of source or device, or insertion of material recorded under different conditions.','This is a steady level of background hiss. Every recording has some faint noise. In one true capture it stays the same. A sudden change in it looks odd. It can point to an edit or a new source.','To use the ever-present noise floor as a continuous baseline whose disruptions reveal edits or changes in recording conditions.','Measuring the noise floor in quiet gaps, an examiner finds its level and spectrum steady throughout and reports no noise-based evidence of editing.','Forensic Audio & Investigative Acoustics',ARRAY['Background continuity','Hum signature','Splice boundary','Authentication','Noise floor']::text[],ARRAY['Ignoring the noise floor during silent passages','Confusing a natural quiet-to-loud scene change with an edit','Missing a subtle noise shift at a splice','Assuming noise reduction has no effect on the floor']::text[],ARRAY['Checking quiet gaps for a change in hiss','Detecting a device change by its noise signature','Supporting an authenticity opinion with noise analysis']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise-floor continuity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd31855f6-d739-5752-8182-0f318c4de690','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d31855f6-d739-5752-8182-0f318c4de690') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d31855f6-d739-5752-8182-0f318c4de690');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef8aa6b1-a791-59a2-88cf-0997898d00d4','Hum signature','The pattern of power-related interference in a recording, comprising the mains fundamental at 50 or 60 hertz and its harmonics, introduced through grounding, electromagnetic coupling, or device electronics. The precise frequencies, harmonic structure, and stability of the hum form a signature that supports authentication through continuity and splice detection and can carry electric network frequency information for time and integrity analysis.','This is the pattern of mains buzz in audio. It sits at 50 or 60 Hz plus higher steps. It comes from power wiring and gear. Its exact shape acts like a fingerprint. Examiners use it to check edits and time.','To characterize power-line interference in a way that aids continuity and splice detection and enables network-frequency analysis.','An examiner isolates a 60 hertz hum and its harmonics, tracks their steadiness across the file, and uses breaks in the hum signature to test for editing.','Forensic Audio & Investigative Acoustics',ARRAY['Mains hum analysis','Electrical network frequency','Phase discontinuity','Noise-floor continuity','Authentication']::text[],ARRAY['Assuming all hum is 60 hertz regardless of region','Confusing acoustic tones with electrical hum','Removing hum before analyzing it for evidence','Ignoring harmonics that carry useful detail']::text[],ARRAY['Tracking mains hum to test continuity','Identifying the region from a hum''s base frequency','Isolating hum for network-frequency work']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hum signature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef8aa6b1-a791-59a2-88cf-0997898d00d4','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef8aa6b1-a791-59a2-88cf-0997898d00d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef8aa6b1-a791-59a2-88cf-0997898d00d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42917712-94f4-5c9e-ad5c-235e94fd48d8','Mains hum analysis','The examination of power-line interference captured in a recording, including its fundamental frequency, harmonics, amplitude, and phase over time, to support authentication, source characterization, and electric network frequency comparison. By analyzing whether the hum is continuous and how its frequency fluctuates, an examiner can detect edits, infer the mains region of 50 or 60 hertz, and extract a network-frequency trace for time verification.','This studies the power-line buzz in audio. It looks at its base pitch and higher steps. It also tracks how the buzz changes over time. This can reveal edits and the world region. It can also help fix the recording''s time.','To extract evidence from unavoidable mains interference for authenticity, region identification, and time verification.','An examiner filters around 50 hertz, plots the hum''s frequency over time, checks for splice-related breaks, and prepares the trace for network-frequency database comparison.','Forensic Audio & Investigative Acoustics',ARRAY['Hum signature','Electrical network frequency','ENF database comparison','Phase discontinuity','Authentication']::text[],ARRAY['Assuming a clean recording has no usable hum','Mistaking the wrong region''s mains frequency','Deleting hum that could be evidence','Reading amplitude changes as edits without checking frequency']::text[],ARRAY['Extracting a network-frequency trace from a recording','Testing hum continuity for editing','Identifying 50 versus 60 hertz mains region']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mains hum analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42917712-94f4-5c9e-ad5c-235e94fd48d8','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42917712-94f4-5c9e-ad5c-235e94fd48d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42917712-94f4-5c9e-ad5c-235e94fd48d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '786822db-8f5d-5b68-aba1-6329030b7a11','Electrical network frequency','The instantaneous frequency of an electrical power grid, nominally 50 or 60 hertz depending on region, which fluctuates slightly and continuously around its nominal value as generation and load vary, in a manner shared across an interconnected grid. When mains hum is captured in a recording, this fluctuating frequency is embedded in the audio; because the grid''s variations are effectively unique over time and logged by reference databases, the extracted network-frequency trace can be used to authenticate a recording and estimate when it was made.','This is the power grid''s exact frequency. It sits near 50 or 60 Hz. It drifts up and down by tiny amounts all the time. All plugs on one grid share this drift. If a recording picks up hum, it catches this pattern. That pattern can act like a time stamp.','To provide a grid-wide, time-varying reference signal that, when captured as hum, lets examiners verify a recording''s time and integrity.','An examiner extracts the network frequency from a recording''s hum and correlates its wobble against a dated grid-frequency database to estimate the recording time and check for edits.','Forensic Audio & Investigative Acoustics',ARRAY['ENF database comparison','Mains hum analysis','Hum signature','Authentication','Clock drift analysis']::text[],ARRAY['Assuming the network frequency is exactly 50 or 60 hertz at all times','Expecting network-frequency matching to work without a reference database','Confusing traces from different grids or regions','Ignoring that battery devices may still capture ambient hum']::text[],ARRAY['Estimating when a recording was made','Verifying a recording''s claimed date','Detecting edits from breaks in the network-frequency trace']::text[],'advanced','f_ENF(t) ≈ f0 ± Δf,  f0 ∈ {50, 60} Hz','The electrical network frequency at any time is close to a nominal 50 or 60 hertz, varying by a small fluctuation around that nominal value.','0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrical network frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '786822db-8f5d-5b68-aba1-6329030b7a11','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='786822db-8f5d-5b68-aba1-6329030b7a11') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='786822db-8f5d-5b68-aba1-6329030b7a11');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '296cec94-d54e-51c6-92ea-9ad4d9c8824a','ENF database comparison','The process of matching the electric network frequency trace extracted from a questioned recording against a continuously logged reference database of grid frequency for the relevant region and period, to estimate the time of recording and test its continuity. A high, unique correlation at a specific time supports a recording time and integrity, while poor or broken correlation may indicate a different time, region, or editing.','This matches a recording''s grid trace to logged records. The stored records hold the grid''s pitch over time. The examiner lines up the recording''s wobble with them. A strong match points to a recording time. A broken match can suggest edits.','To turn an extracted network-frequency trace into a concrete time estimate and integrity check by referencing an independent grid-frequency log.','An examiner correlates a call''s network-frequency trace against a national grid database, finds a strong match on a specific evening, and reports that as the likely recording time.','Forensic Audio & Investigative Acoustics',ARRAY['Electrical network frequency','Mains hum analysis','Hum signature','Authentication','Cross-correlation']::text[],ARRAY['Comparing against the wrong grid or region''s database','Trusting a weak correlation as a firm time match','Ignoring gaps in the reference log','Assuming a match proves content was not edited elsewhere']::text[],ARRAY['Estimating the date of a questioned recording','Checking a claimed recording time against the grid','Detecting a time gap from a broken network-frequency match']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ENF database comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '296cec94-d54e-51c6-92ea-9ad4d9c8824a','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='296cec94-d54e-51c6-92ea-9ad4d9c8824a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='296cec94-d54e-51c6-92ea-9ad4d9c8824a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ef8bae1-f3ea-5912-a540-33f63e2fb668','Clock drift analysis','The examination of small deviations between a recording device''s sampling or timing clock and true time, arising because inexpensive oscillators run slightly fast or slow, so that a recording''s actual sample rate differs marginally from its nominal value and its timeline slowly diverges from real time. Measuring this drift, often expressed in parts per million, helps verify durations and timestamps, align multiple recordings, and detect inconsistencies in authentication.','This measures timing errors in a recorder. Cheap clocks run a little fast or slow. So the true sample rate differs from the label. Over time the clock slips from real time. Measuring this drift helps check and align recordings.','To quantify a device''s timing error so examiners can correct durations, synchronize recordings, and spot timeline inconsistencies.','Using a captured network-frequency hum or reference tone, an examiner measures a recorder''s clock running 40 parts per million fast and corrects the timeline before aligning it with another device''s audio.','Forensic Audio & Investigative Acoustics',ARRAY['Sample-rate mismatch','Electrical network frequency','Synchronization','Authentication','Oscillator']::text[],ARRAY['Assuming a device runs at exactly its nominal sample rate','Ignoring drift when aligning long multi-device recordings','Confusing clock drift with a deliberate speed change','Overlooking temperature effects on oscillator frequency']::text[],ARRAY['Aligning two recordings of one event','Correcting a long recording''s duration','Checking a timestamp against measured drift']::text[],'advanced','drift (ppm) = (f_actual − f_nominal) / f_nominal × 10^6','Clock drift in parts per million equals the actual clock frequency minus the nominal frequency, divided by the nominal frequency, multiplied by one million.','0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clock drift analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ef8bae1-f3ea-5912-a540-33f63e2fb668','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ef8bae1-f3ea-5912-a540-33f63e2fb668') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ef8bae1-f3ea-5912-a540-33f63e2fb668');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b8b8671-637d-5a5b-b0b7-39590a76e126','Sample-rate mismatch','The condition in which audio recorded or encoded at one sample rate is played back, interpreted, or processed at a different assumed rate, causing a proportional error in pitch, tempo, and duration equal to the ratio of the two rates. In forensics it must be detected and corrected before analysis, since an uncorrected mismatch distorts speaker characteristics, timing measurements, and frequency-based evidence such as hum.','This means audio plays at the wrong rate. The file''s true rate and the read rate differ. This shifts pitch, speed, and length. A voice may sound too high or too low. It must be fixed before any close study.','To flag and correct rate errors that would otherwise distort pitch, timing, and frequency evidence in an examination.','Noticing a 44.1 kilohertz file misread as 48 kilohertz makes a 50 hertz hum appear near 54 hertz, an examiner corrects the sample rate before speaker comparison.','Forensic Audio & Investigative Acoustics',ARRAY['Clock drift analysis','Resampling','Electrical network frequency','Pitch shift','Authentication']::text[],ARRAY['Analyzing audio without confirming its true sample rate','Reading a shifted hum frequency as the real mains frequency','Comparing voices at mismatched rates','Assuming file headers always state the correct rate']::text[],ARRAY['Correcting a wrongly flagged sample rate before analysis','Explaining an off-pitch voice in a shared file','Restoring true hum frequency for network-frequency work']::text[],'intermediate','r = f_assumed / f_actual','The pitch and speed scaling factor equals the assumed sample rate divided by the file''s actual sample rate.','0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sample-rate mismatch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b8b8671-637d-5a5b-b0b7-39590a76e126','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b8b8671-637d-5a5b-b0b7-39590a76e126') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b8b8671-637d-5a5b-b0b7-39590a76e126');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35ed89e4-dc52-53fb-8751-108140842dab','Automatic gain control artifact','A signal feature caused by automatic gain control in a recording device or channel, where the system continuously adjusts gain to keep levels within range, producing audible pumping, breathing of the noise floor, and level changes unrelated to the true acoustic scene. Recognizing such artifacts is important in forensics because they alter apparent loudness and noise, complicate authentication when level changes mimic edits, and affect enhancement and interpretation.','This comes from automatic volume control. The device keeps changing gain to hold a level. Quiet parts get boosted, so noise swells and fades. Loud parts get pulled down. These shifts are not real changes in the scene.','To identify device-driven level changes so they are not mistaken for edits or true loudness differences during analysis.','Hearing the noise floor rise during pauses in a body-camera clip, an examiner recognizes gain-control pumping and avoids reading the level changes as evidence of editing.','Forensic Audio & Investigative Acoustics',ARRAY['Noise-floor continuity','Clipping-pattern analysis','Body-worn camera audio','Compression','Authentication']::text[],ARRAY['Mistaking gain-control level shifts for splices or edits','Reading swelling noise as a change of scene','Assuming loudness reflects the true source level','Trying to compare levels across gain-controlled segments']::text[],ARRAY['Interpreting pumping noise in body-camera audio','Separating gain-control level changes from edits','Judging true loudness under automatic gain']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Automatic gain control artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35ed89e4-dc52-53fb-8751-108140842dab','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35ed89e4-dc52-53fb-8751-108140842dab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35ed89e4-dc52-53fb-8751-108140842dab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3c83b38-0e4e-5b8c-865c-3a1f83ede553','Clipping-pattern analysis','Examination of the flattened waveform peaks produced when a signal exceeds the linear range of a microphone, preamplifier, or converter, to determine where and why clipping occurred and what it implies. The shape, symmetry, and level of clipping can indicate whether it happened at capture as analogue overload or later as digital full-scale clipping, help characterize the recording chain, and reveal that peaks and true levels are unrecoverable.','This studies flattened peaks in a wave. Clipping happens when sound is too loud for the gear. The tops of the wave get chopped flat. The pattern shows where and how it clipped. It also warns that the lost peaks cannot return.','To diagnose overload in the recording chain and to set realistic limits on what enhancement and level analysis can recover.','Seeing hard, flat-topped peaks at digital full scale, an examiner identifies clipping in a converter and warns that true peak levels and some content are unrecoverable.','Forensic Audio & Investigative Acoustics',ARRAY['Automatic gain control artifact','Waveform discontinuity','Distortion','Overload','Full scale']::text[],ARRAY['Trying to restore clipped peaks that hold no data','Confusing analogue overload with digital clipping','Reading clipping flat-tops as splices','Assuming clipping proves deliberate manipulation']::text[],ARRAY['Diagnosing overload in a loud recording','Distinguishing analogue from digital clipping','Setting limits on enhancement of a clipped clip']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clipping-pattern analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3c83b38-0e4e-5b8c-865c-3a1f83ede553','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3c83b38-0e4e-5b8c-865c-3a1f83ede553') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3c83b38-0e4e-5b8c-865c-3a1f83ede553');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba8f865c-3805-56d5-a78f-3acf94c3b9f5','Wind-buffet artifact','Low-frequency noise and momentary overloads produced when wind strikes a microphone diaphragm or its housing, causing large, irregular low-frequency excursions, rumble, and sometimes clipping that mask nearby sounds. In outdoor forensic recordings from body cameras, surveillance, or mobile phones, wind buffeting degrades intelligibility and must be recognized so it is not confused with other events and so enhancement can target it.','This is noise from wind hitting a mic. It makes strong low rumble and thumps. It can overload the mic for a moment. It often covers up nearby speech. Examiners must spot it before cleaning the audio.','To identify wind-induced low-frequency noise so it is not misread as other events and so it can be targeted in enhancement.','Facing muffled speech in an outdoor body-camera clip, an examiner identifies wind buffeting, applies a high-pass filter, and reports the limits it places on intelligibility.','Forensic Audio & Investigative Acoustics',ARRAY['Forensic audio enhancement','Low-pass cutoff artifact','Body-worn camera audio','High-pass filter','Noise floor']::text[],ARRAY['Confusing wind rumble with distant explosions or impacts','Trying to recover speech fully masked by wind','Removing too much low end and thinning the voice','Ignoring wind overload as a cause of dropouts']::text[],ARRAY['Cleaning wind noise from outdoor body-camera audio','Distinguishing wind thumps from real impact sounds','Assessing intelligibility under heavy wind']::text[],'beginner',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wind-buffet artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba8f865c-3805-56d5-a78f-3acf94c3b9f5','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba8f865c-3805-56d5-a78f-3acf94c3b9f5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba8f865c-3805-56d5-a78f-3acf94c3b9f5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c5088a2-140b-51dd-bbf8-0287ac71c0db','Body-worn camera audio','The audio track captured by a body-worn camera used by law enforcement or security, characterized by close proximity to the wearer, motion and handling noise, clothing rub, wind, automatic gain control, and lossy compression, and often subject to pre-event buffering that may omit audio for the first seconds. In forensics such audio is examined for content, intelligibility, and authenticity, with these device traits central to correct interpretation.','This is sound from an officer''s worn camera. It sits close to the body and clothes. It picks up rubbing, motion, wind, and gain pumping. Many models record no sound for the first seconds. Knowing these traits is key to reading it.','To describe the distinctive capture conditions of body-camera recordings so their content and authenticity are interpreted correctly.','Analyzing a use-of-force clip, an examiner accounts for clothing rub, gain control, and the silent pre-event buffer before drawing conclusions about what was said.','Forensic Audio & Investigative Acoustics',ARRAY['Automatic gain control artifact','Wind-buffet artifact','Forensic audio enhancement','Emergency-call audio analysis','Intelligibility']::text[],ARRAY['Assuming audio exists for the whole recorded video','Reading clothing rub or motion as suspicious events','Ignoring heavy compression when judging quality','Expecting studio clarity from a body-worn microphone']::text[],ARRAY['Reviewing a use-of-force incident''s audio','Explaining a silent gap at the start of a clip','Enhancing officer-worn camera speech']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Body-worn camera audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c5088a2-140b-51dd-bbf8-0287ac71c0db','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c5088a2-140b-51dd-bbf8-0287ac71c0db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c5088a2-140b-51dd-bbf8-0287ac71c0db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e85dab2b-aaa0-5b12-9167-0fcf867ca7ae','Emergency-call audio analysis','Forensic examination of emergency call recordings, which are typically narrowband telephone audio, often compressed by the telephony and logging systems, and accompanied by system metadata and precise timestamps. Analysis covers transcription and intelligibility, background-sound interpretation, speaker characterization, and authentication, with attention to channel limits, hold and transfer artifacts, and the call-handling system''s recording characteristics.','This studies 911-type call recordings. These calls are narrow phone audio, often squeezed. They come with system time stamps and logs. Examiners write them down and study background sounds. They must respect the phone line''s limits.','To extract reliable content, timing, and background evidence from emergency-call recordings while respecting their telephone-channel constraints.','An examiner transcribes an emergency call, interprets background sounds behind the caller, checks the system timestamps, and enhances speech within the narrowband channel limits.','Forensic Audio & Investigative Acoustics',ARRAY['Forensic transcription','Low-pass cutoff artifact','Telephone bandwidth','Background continuity','Body-worn camera audio']::text[],ARRAY['Expecting full-bandwidth clarity from a phone call','Trying to recover high-frequency content the channel removed','Ignoring hold or transfer artifacts as edits','Trusting a background sound without corroboration']::text[],ARRAY['Transcribing a disputed emergency call','Interpreting background sounds behind a caller','Verifying an emergency call''s timestamp']::text[],'intermediate',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Emergency-call audio analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e85dab2b-aaa0-5b12-9167-0fcf867ca7ae','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e85dab2b-aaa0-5b12-9167-0fcf867ca7ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e85dab2b-aaa0-5b12-9167-0fcf867ca7ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cbe4a60-7528-5826-80cf-39c443f56f50','Shot sequence timing','The determination of the number, order, and precise inter-event intervals of gunshots in a recording by locating each shot''s acoustic events, the muzzle blast and, for supersonic rounds, the ballistic shockwave, on the timeline. It supports reconstruction of how many shots were fired, their rate, and whether more than one firearm was involved, and it underpins trajectory and localization analyses.','This counts and times gunshots in audio. The examiner marks each shot''s sound on the timeline. This shows how many shots and their order. It also shows the gaps between them. Rate and gaps can hint at more than one gun.','To establish how many shots were fired, in what order, and at what intervals, as a basis for reconstructing a shooting.','On a surveillance recording an examiner marks each muzzle blast, measures the intervals, and reports a sequence suggesting two firearms firing at different rates.','Forensic Audio & Investigative Acoustics',ARRAY['Muzzle-blast arrival','Supersonic bullet crack','Acoustic trajectory reconstruction','Echo-based shooter localization','Gunshot acoustics']::text[],ARRAY['Counting echoes as additional shots','Missing overlapping shots as a single event','Ignoring that clipping can hide or merge blasts','Assuming even spacing means a single shooter']::text[],ARRAY['Counting shots on a surveillance recording','Timing intervals to infer firing rate','Testing whether two firearms were present']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shot sequence timing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cbe4a60-7528-5826-80cf-39c443f56f50','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cbe4a60-7528-5826-80cf-39c443f56f50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cbe4a60-7528-5826-80cf-39c443f56f50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7f31fe8-ab80-59fe-b191-aff9b24fd7ed','Supersonic bullet crack','The sharp ballistic shockwave, an N-wave, generated by a bullet travelling faster than the speed of sound, radiating as a cone whose half-angle, the Mach angle, is set by the projectile''s Mach number. Captured in a recording, the crack precedes the muzzle blast at microphones off the line of fire, and its presence, timing relative to the blast, and waveform inform trajectory reconstruction and range estimation in gunshot acoustics.','This is the snap of a fast bullet. Bullets faster than sound push a shock wave. This wave spreads in a cone behind the bullet. At a mic, the crack comes before the gun''s blast. Its timing helps map the bullet''s path.','To identify the bullet''s own shockwave, whose geometry and timing enable trajectory and range analysis independent of the muzzle blast.','Measuring the crack-to-blast delay and the N-wave shape, an examiner estimates the bullet''s Mach number and the microphone''s offset from the line of fire.','Forensic Audio & Investigative Acoustics',ARRAY['Muzzle-blast arrival','Acoustic trajectory reconstruction','Shot sequence timing','Mach number','Gunshot acoustics']::text[],ARRAY['Confusing the bullet crack with the muzzle blast','Assuming subsonic rounds produce a crack','Ignoring that the crack only reaches microphones off the trajectory','Reading the crack''s arrival as the firing time']::text[],ARRAY['Distinguishing crack from blast on a recording','Estimating a bullet''s speed from its shockwave','Reconstructing a bullet''s path']::text[],'advanced','θ_M = arcsin(1 / M),  M = v / c','The Mach cone half-angle equals the inverse sine of one divided by the Mach number, where the Mach number is the bullet speed divided by the speed of sound.','0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Supersonic bullet crack');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7f31fe8-ab80-59fe-b191-aff9b24fd7ed','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7f31fe8-ab80-59fe-b191-aff9b24fd7ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7f31fe8-ab80-59fe-b191-aff9b24fd7ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e1f556fe-b7ca-50ff-87f2-ba14016d1f34','Muzzle-blast arrival','The arrival at a microphone of the acoustic blast produced at a firearm''s muzzle on discharge, which propagates omnidirectionally at the speed of sound from the firing point. Its arrival time, and its delay relative to the ballistic shockwave at off-axis microphones, provide range and geometry information; across multiple microphones, muzzle-blast arrival times enable source localization of the shooter.','This is when the gun''s bang reaches a mic. The blast spreads out from the muzzle in all directions. It travels at the speed of sound. Its arrival time marks distance from the gun. Across several mics it can locate the shooter.','To provide a speed-of-sound reference event whose arrival times give range and, across sensors, the shooter''s position.','Using muzzle-blast arrival times at several microphones and the speed of sound, an examiner triangulates the firing position of the shooter.','Forensic Audio & Investigative Acoustics',ARRAY['Supersonic bullet crack','Echo-based shooter localization','Shot sequence timing','Acoustic trajectory reconstruction','Time difference of arrival']::text[],ARRAY['Confusing muzzle blast with the supersonic crack','Ignoring temperature''s effect on the speed of sound','Using one microphone to claim a firing position','Mistaking an echo for the direct blast']::text[],ARRAY['Locating a shooter from multiple microphones','Measuring range from crack-to-blast delay','Timing blasts in a shot sequence']::text[],'advanced','t = r / c','The muzzle blast''s travel time to a microphone equals the distance from the muzzle divided by the speed of sound.','0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Muzzle-blast arrival');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e1f556fe-b7ca-50ff-87f2-ba14016d1f34','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e1f556fe-b7ca-50ff-87f2-ba14016d1f34') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e1f556fe-b7ca-50ff-87f2-ba14016d1f34');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56533c1f-0c2e-558f-bab2-1a6c6a743977','Echo-based shooter localization','A technique that locates a gunshot''s origin using time differences between the direct muzzle-blast arrival and its reflections, or echoes, from known surfaces, or between arrivals at spatially separated microphones. By combining measured time-difference-of-arrival values with the speed of sound and the known geometry, the possible source positions are constrained to hyperbolic loci whose intersection estimates the shooter''s location, even from a single recorder when strong echoes are present.','This finds a gun from sound timing. It uses the gap between the direct blast and its echoes. Each gap equals a distance difference. Together these gaps point back to the source. Strong echoes can even work with one recorder.','To estimate a shooter''s position from arrival-time differences of the blast and its reflections, using known geometry and the speed of sound.','From a single surveillance recording with a clear wall echo, an examiner measures the direct-to-echo delay and, with the wall''s known position, estimates the shooter''s location.','Forensic Audio & Investigative Acoustics',ARRAY['Muzzle-blast arrival','Acoustic trajectory reconstruction','Time difference of arrival','Supersonic bullet crack','Reverberation']::text[],ARRAY['Misidentifying which peak is the direct blast versus an echo','Assuming a fixed speed of sound regardless of temperature','Using uncertain surface geometry as if it were exact','Expecting a unique solution from too few time differences']::text[],ARRAY['Locating a shooter from one echo-rich recording','Using multiple microphones for time-difference localization','Reconstructing a shooting scene''s geometry']::text[],'advanced','Δd = c · Δt','The distance difference between two sound paths equals the speed of sound multiplied by the difference in their arrival times.','0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Echo-based shooter localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56533c1f-0c2e-558f-bab2-1a6c6a743977','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56533c1f-0c2e-558f-bab2-1a6c6a743977') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56533c1f-0c2e-558f-bab2-1a6c6a743977');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ea13120-2098-50e7-9092-2f559106d7f5','Acoustic trajectory reconstruction','The reconstruction of a projectile''s flight path from the acoustic signatures it and the firearm produce, principally the ballistic shockwave''s arrival angle, governed by the Mach angle, and its timing at multiple microphones, combined with muzzle-blast arrivals. By fitting these measurements to the geometry of shockwave and blast propagation, an examiner can estimate the line of fire, direction, and sometimes the projectile''s speed and the shooter''s position.','This maps a bullet''s path from sound. It uses the shock wave''s angle and timing at mics. It adds the gun blast''s arrival too. Fitting these to shapes gives the line of fire. It can also hint at bullet speed and shooter spot.','To infer where a shot came from and where the bullet went, using the physics of shockwave and blast propagation captured by microphones.','With shockwave arrivals at an array of sensors, an examiner fits the Mach-cone geometry and muzzle-blast times to reconstruct the bullet''s line of fire and the shooter''s direction.','Forensic Audio & Investigative Acoustics',ARRAY['Supersonic bullet crack','Muzzle-blast arrival','Echo-based shooter localization','Mach number','Shot sequence timing']::text[],ARRAY['Reconstructing a trajectory from too few microphones','Ignoring wind and temperature effects on propagation','Confusing shockwave and blast arrivals in the fit','Overstating precision from noisy arrival times']::text[],ARRAY['Estimating the line of fire from a sensor array','Combining crack and blast data for a path','Supporting scene reconstruction in a shooting']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic trajectory reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ea13120-2098-50e7-9092-2f559106d7f5','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ea13120-2098-50e7-9092-2f559106d7f5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ea13120-2098-50e7-9092-2f559106d7f5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31bbdfdd-0f45-5e4d-a4ed-6e612310e83b','Forensic audibility analysis','The assessment of whether a particular sound or spoken content would have been audible or intelligible to a person at a given location, given the recorded or reconstructed acoustic conditions, including source level, distance, background noise, masking, and the listener''s position. It combines acoustic measurement with psychoacoustic criteria to address questions such as whether a warning could have been heard, and it is distinct from simply enhancing a recording for a present-day listener.','This asks if a sound could be heard. It weighs the source level, distance, and noise. It uses how our ears hide quiet sounds. This answers if a warning was loud enough to hear. It is not the same as cleaning up a recording.','To answer whether specific sounds or words could have been heard or understood by a person in the scene, using acoustic and psychoacoustic evidence.','To test whether a bystander could have heard a shouted warning, an examiner models source level, distance, and traffic noise and applies masking thresholds to judge audibility.','Forensic Audio & Investigative Acoustics',ARRAY['Intelligibility','Masking','Forensic audio enhancement','Signal-to-noise ratio','Psychoacoustics']::text[],ARRAY['Confusing enhanced-recording audibility with what a person could hear','Ignoring background-noise masking at the scene','Assuming a recorder''s microphone hears like a human ear','Neglecting distance loss between source and listener']::text[],ARRAY['Judging whether a warning shout was audible','Assessing if an alarm could be heard over traffic','Modeling audibility at a witness''s position']::text[],'advanced',NULL,NULL,'0f467b36-934f-42ea-ade7-4eb6007b74ca' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forensic audibility analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31bbdfdd-0f45-5e4d-a4ed-6e612310e83b','0f467b36-934f-42ea-ade7-4eb6007b74ca',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31bbdfdd-0f45-5e4d-a4ed-6e612310e83b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31bbdfdd-0f45-5e4d-a4ed-6e612310e83b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '33fea2a9-0320-51a1-a20a-21c7a021d266','Absorption loss in seawater','The conversion of acoustic energy into heat as sound propagates through seawater, caused by shear and volume viscosity and by the chemical relaxation of dissolved boric acid and magnesium sulfate. It is quantified by an absorption coefficient, usually in decibels per kilometre, that increases strongly with frequency; the absorption loss over a path equals this coefficient multiplied by the range. Absorption adds to geometric spreading loss to form the total transmission loss, and it sets a frequency-dependent ceiling on usable sonar range.','Seawater slowly turns sound into heat as it travels. This steady drain is called absorption. It grows fast as the pitch, or frequency, rises. Salts in the sea make it worse than in fresh water. High-frequency sonar cannot reach as far because of it.','Explains why sound of a given frequency can travel only a limited range, which sets the useful range of a sonar and drives the choice of operating frequency.','Sonar designers pick low frequencies for long-range search and accept high absorption for short-range, high-resolution imaging; range-prediction models add absorption to spreading loss.','Underwater Acoustics & Sonar',ARRAY['Transmission loss','Spreading loss','Absorption coefficient','Thorp attenuation','Sonar equation']::text[],ARRAY['Assuming absorption is constant with frequency; it climbs steeply as frequency rises','Confusing absorption (energy lost to heat) with spreading (energy spread over a larger area)','Ignoring that seawater absorbs far more than fresh water because of chemical relaxation']::text[],ARRAY['Choosing a low sonar frequency to search for a target at long range','Predicting the maximum range of a high-frequency imaging sonar','Correcting echo-level estimates for a warm, saline water mass']::text[],'intermediate','A = alpha * r','Absorption loss in decibels equals the absorption coefficient, in decibels per unit distance, multiplied by the path range.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absorption loss in seawater');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '33fea2a9-0320-51a1-a20a-21c7a021d266','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='33fea2a9-0320-51a1-a20a-21c7a021d266') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='33fea2a9-0320-51a1-a20a-21c7a021d266');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fcb25fd9-197c-5514-a584-13f2feac9a6a','Bottom loss','The reduction in acoustic intensity, expressed in decibels, that a sound wave suffers on reflecting from the sea floor. It depends on grazing angle, frequency, and the geoacoustic properties of the sediment (density, compressional and shear sound speeds, and attenuation), and it accounts for energy transmitted into the bottom and scattered by roughness. For a fast bottom, reflection is nearly total below a critical grazing angle, while loss generally increases at steeper angles.','When sound hits the sea floor, part of it bounces back weaker. The lost part is called bottom loss. It depends on the sediment and the ray angle. Soft mud soaks up much more sound than hard rock. Steep rays usually lose more than shallow, grazing rays.','Describes how much a bottom-bounce path weakens a signal, which governs sonar performance in shallow water and on downward-refracting paths.','Shallow-water sonar operators and modellers use measured or modelled bottom-loss curves versus grazing angle to predict detection range over sand, mud, or rock.','Underwater Acoustics & Sonar',ARRAY['Bottom reverberation','Grazing angle','Reflection coefficient','Geoacoustic model','Transmission loss','Critical angle']::text[],ARRAY['Treating bottom loss as one fixed number instead of a function of grazing angle and frequency','Assuming a hard bottom always reflects best; a slow, soft bottom can still trap energy below the critical angle','Ignoring shear waves in the sediment, which drain extra energy at some angles']::text[],ARRAY['Predicting shallow-water sonar range over a muddy versus a rocky sea floor','Interpreting weak bottom-bounce returns in a downward-refracting profile','Building a geoacoustic model to match measured propagation loss']::text[],'intermediate','BL = -20 * log10|R|','Bottom loss in decibels equals minus twenty times the base-ten logarithm of the magnitude of the bottom pressure reflection coefficient.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bottom loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fcb25fd9-197c-5514-a584-13f2feac9a6a','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fcb25fd9-197c-5514-a584-13f2feac9a6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fcb25fd9-197c-5514-a584-13f2feac9a6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0b68eb98-5f77-5f18-875e-276191347c0e','Surface loss','The loss of acoustic intensity, in decibels, when sound reflects from the sea surface. A calm surface is a near-perfect pressure-release reflector, but wind-driven roughness scatters energy out of the specular direction and entrains a near-surface bubble layer that absorbs and scatters sound, reducing the coherent reflected level. Surface loss increases with frequency, grazing angle, and wave height, and is often parameterised by the Rayleigh roughness parameter.','Sound also bounces off the sea surface. A flat, calm sea reflects almost all of it. Wind and waves make the surface rough. Rough water and bubbles scatter sound away and weaken the echo. This weakening is called surface loss.','Quantifies how sea state degrades surface-reflected and surface-duct paths, which matters for near-surface sonar and for sound trapped in the surface layer.','Modellers raise surface loss with wind speed and frequency when predicting surface-duct propagation or when a high sea state limits sonar range.','Underwater Acoustics & Sonar',ARRAY['Surface reverberation','Rayleigh parameter','Surface duct','Sea state','Reflection coefficient','Bubble layer']::text[],ARRAY['Assuming the sea surface always reflects perfectly; roughness and bubbles cause real loss at higher frequencies','Ignoring the near-surface bubble layer, which scatters and absorbs sound','Forgetting that surface loss rises with wind speed and grazing angle']::text[],ARRAY['Predicting surface-duct range on a windy day','Explaining why a surface-ship sonar loses range in high sea states','Modelling repeated surface bounces in a shallow channel']::text[],'intermediate','SL = -20 * log10|Rs|','Surface loss in decibels equals minus twenty times the base-ten logarithm of the magnitude of the coherent surface reflection coefficient.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0b68eb98-5f77-5f18-875e-276191347c0e','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0b68eb98-5f77-5f18-875e-276191347c0e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0b68eb98-5f77-5f18-875e-276191347c0e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1d2bacb-c7a6-57d1-92e6-0559668fcb0b','Volume scattering','The redirection of acoustic energy in many directions by inhomogeneities distributed through the water volume, such as fish with gas-filled swim bladders, zooplankton, suspended particles, bubbles, and small-scale fluctuations in temperature and salinity. It removes energy from the forward beam and returns part of it toward the source, producing volume reverberation. Its strength is frequency dependent and is often dominated by resonant biological scatterers.','The open water is not empty. It holds fish, tiny animals, bubbles, and particles. These scatter sound in all directions as it passes. This spreading of sound by things in the water is volume scattering. Fish with gas-filled swim bladders scatter the most.','Explains a major source of unwanted echoes, called volume reverberation, and the basis for using sonar and echosounders to sense marine life.','Fisheries and oceanographic echosounders exploit volume scattering to map plankton and fish, while sonar designers treat it as a reverberation background that masks targets.','Underwater Acoustics & Sonar',ARRAY['Volume reverberation','Scattering strength','Deep scattering layer','Backscattering','Target strength']::text[],ARRAY['Confusing volume scattering (throughout the water) with boundary scattering at the surface or bottom','Assuming scatter is the same at all frequencies; resonant swim bladders make it strongly frequency dependent','Overlooking the day-night vertical migration of scatterers that changes the return']::text[],ARRAY['Seeing a deep scattering layer rise toward the surface at dusk on an echosounder','Estimating fish abundance from backscattered sonar energy','Explaining a reverberation-limited sonar background in biologically rich water']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volume scattering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1d2bacb-c7a6-57d1-92e6-0559668fcb0b','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1d2bacb-c7a6-57d1-92e6-0559668fcb0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1d2bacb-c7a6-57d1-92e6-0559668fcb0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e459e60d-90c9-50de-881f-40d945ce5333','Surface scattering','The redirection of incident sound by the rough air-sea interface and its associated bubble layer. Roughness spreads energy away from the specular direction into both forward and backscattered fields; the backscattered part produces surface reverberation, while forward scattering reduces the coherent reflected level. It depends on grazing angle, acoustic frequency, and the surface roughness relative to the wavelength.','The sea surface is rarely smooth. Waves make it rough and full of bubbles. When sound hits it, the surface throws energy in many directions. This is surface scattering. Part of the sound comes back as an echo from the surface.','Explains surface reverberation and the loss of coherent surface reflection, both of which limit near-surface active sonar.','Sonar performance models use surface scattering strength versus grazing angle and wind speed to predict reverberation from the surface during active search.','Underwater Acoustics & Sonar',ARRAY['Surface reverberation','Surface loss','Scattering strength','Rayleigh parameter','Sea state']::text[],ARRAY['Treating the surface as a smooth mirror when wind makes it a strong scatterer','Ignoring the bubble layer just under the surface as a scatterer','Assuming surface scatter is independent of frequency and grazing angle']::text[],ARRAY['Predicting surface reverberation for a shallow-grazing active sonar','Explaining rising sonar clutter as the wind and sea state increase','Separating surface returns from a real target near the surface']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface scattering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e459e60d-90c9-50de-881f-40d945ce5333','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e459e60d-90c9-50de-881f-40d945ce5333') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e459e60d-90c9-50de-881f-40d945ce5333');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '050f0579-f3bb-579d-b244-16f0ec5f82c0','Bottom scattering','The redirection of incident sound by the rough sea floor and by inhomogeneities within the sediment. Backscattered energy returns toward the source as bottom reverberation, while out-of-plane scattering removes energy from the specular reflection. It is governed by interface roughness, sediment volume inhomogeneity, grazing angle, and frequency, and is described by a bottom scattering strength.','The sea floor is rough and uneven. It also holds buried objects and layers. When sound hits it, the bottom scatters energy in many directions. This is bottom scattering. Much of it returns as a strong echo from the floor.','Explains bottom reverberation, a dominant background in shallow-water and downward-looking active sonar, and underlies sea-floor imaging.','Sidescan and multibeam sonar use bottom scattering to image and classify the sea floor, while sonar models treat it as reverberation that limits target detection.','Underwater Acoustics & Sonar',ARRAY['Bottom reverberation','Bottom loss','Scattering strength','Backscattering','Sidescan sonar']::text[],ARRAY['Confusing bottom scattering (energy sent in many directions) with bottom loss (weakening of the specular reflection)','Assuming only surface roughness matters and ignoring scattering from within the sediment','Expecting the same scattering from smooth mud as from rough gravel']::text[],ARRAY['Imaging the sea floor with a sidescan sonar','Predicting bottom reverberation that masks a target in shallow water','Classifying sediment type from measured backscatter strength']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bottom scattering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '050f0579-f3bb-579d-b244-16f0ec5f82c0','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='050f0579-f3bb-579d-b244-16f0ec5f82c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='050f0579-f3bb-579d-b244-16f0ec5f82c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5306494c-c92a-5cbb-ac68-a599664a834e','Scattering strength','A logarithmic measure, in decibels, of the fraction of incident acoustic intensity that a scatterer re-radiates back toward the receiver, referenced to a unit area (for surface or bottom scattering) or a unit volume (for volume scattering). It equals ten times the base-ten logarithm of the ratio of scattered to incident intensity, normalised to the ensonified area or volume, and generally varies with grazing angle and frequency.','Scattering strength is a number for how strongly a surface or a patch of water scatters sound back. It is written in decibels. A bigger number means a stronger echo. It compares scattered sound to the sound that arrived. Engineers use it to predict reverberation.','Provides the standard parameter that lets sonar models compute reverberation levels from the surface, the bottom, or the water volume.','In the sonar equation, scattering strength combines with the ensonified area or volume to predict the reverberation level competing with a target echo.','Underwater Acoustics & Sonar',ARRAY['Reverberation level','Target strength','Backscattering','Volume scattering','Bottom scattering','Surface scattering']::text[],ARRAY['Confusing scattering strength (per unit area or volume) with target strength (of a single object)','Forgetting that it varies strongly with grazing angle and frequency','Mixing surface, bottom, and volume scattering strengths, which use different reference units']::text[],ARRAY['Computing reverberation level in the active sonar equation','Comparing the bottom backscatter of sand versus mud','Estimating volume reverberation from a plankton layer']::text[],'advanced','S = 10 * log10(Iscat / Iinc)','Scattering strength in decibels equals ten times the base-ten logarithm of the scattered intensity divided by the incident intensity, referenced to unit area or unit volume.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scattering strength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5306494c-c92a-5cbb-ac68-a599664a834e','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5306494c-c92a-5cbb-ac68-a599664a834e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5306494c-c92a-5cbb-ac68-a599664a834e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6a9d1c25-0f39-5d7e-925f-2d991038b6d8','Volume reverberation','The aggregate backscattered return produced by volume scatterers distributed through the water column, including biological organisms, bubbles, and microstructure, when an active sonar transmits. Its level grows with the ensonified volume, set roughly by beam width and pulse length, and with the volume scattering strength, and it typically decays with time after transmission as the scattering shell expands outward.','When a sonar pings, echoes come back from the whole body of water. Fish, bubbles, and tiny particles each reflect a little sound. Added together they form a background hiss. This is volume reverberation. It can hide a real target.','Represents a self-generated background that limits active sonar detection in biologically rich or bubbly water.','Sonar operators recognise volume reverberation as a decaying background after each ping and set thresholds or processing to detect targets above it.','Underwater Acoustics & Sonar',ARRAY['Volume scattering','Reverberation level','Scattering strength','Deep scattering layer','Surface reverberation']::text[],ARRAY['Mistaking a dense scattering layer for a real target','Assuming reverberation is external noise; it is caused by the sonar''s own transmission','Ignoring how longer pulses and wider beams raise the reverberation level']::text[],ARRAY['Detecting a target embedded in a deep scattering layer','Explaining a decaying background after each active ping','Choosing a shorter pulse to reduce the reverberation volume']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volume reverberation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6a9d1c25-0f39-5d7e-925f-2d991038b6d8','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6a9d1c25-0f39-5d7e-925f-2d991038b6d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6a9d1c25-0f39-5d7e-925f-2d991038b6d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ed523f5-0087-5442-b1e6-110c7325d8e1','Surface reverberation','The backscattered acoustic return from the rough sea surface and its bubble layer following an active transmission. Its level is set by the surface scattering strength and the ensonified surface area (beamwidth and pulse length projected onto the surface), and it increases with wind speed and grazing angle, dominating reverberation at low grazing angles near the surface.','After a sonar pings, the rough sea surface sends echoes back. Waves and bubbles scatter the sound. Together these returns form surface reverberation. It grows stronger as the wind and waves build. It can mask targets near the surface.','Identifies a boundary reverberation background that limits detection of near-surface targets by active sonar.','Sonar models add surface reverberation, scaled with sea state, when predicting performance against shallow targets in windy conditions.','Underwater Acoustics & Sonar',ARRAY['Surface scattering','Reverberation level','Sea state','Surface loss','Volume reverberation']::text[],ARRAY['Assuming a calm surface removes reverberation; even light wind raises it','Confusing surface reverberation with ambient sea noise, which is not tied to your ping','Overlooking its rise at low grazing angles']::text[],ARRAY['Predicting sonar performance against a periscope-depth target in a high sea state','Distinguishing a surface return from a genuine contact','Explaining a rising background as the wind increases']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface reverberation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ed523f5-0087-5442-b1e6-110c7325d8e1','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ed523f5-0087-5442-b1e6-110c7325d8e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ed523f5-0087-5442-b1e6-110c7325d8e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f23d77e9-0890-5c01-bdb0-cba8b0a507f2','Bottom reverberation','The backscattered return from the sea floor after an active transmission, produced by interface roughness and sediment volume scattering. Its level depends on the bottom scattering strength and the ensonified bottom area, and it commonly dominates reverberation in shallow water and on bottom-bounce paths, often persisting to long ranges because of strong, repeated bottom interaction.','When a sonar pings near the sea floor, the bottom sends back strong echoes. Its rough, uneven surface scatters the sound. These returns are bottom reverberation. In shallow water they can be very strong. They often hide targets close to the floor.','Represents the dominant reverberation background in shallow water and downward-looking sonar, setting the detection floor there.','Shallow-water sonar operators face strong bottom reverberation and use Doppler or spatial processing to separate moving targets from the static bottom.','Underwater Acoustics & Sonar',ARRAY['Bottom scattering','Reverberation level','Bottom loss','Clutter return','Volume reverberation']::text[],ARRAY['Mistaking a bottom feature or wreck for a moving target','Assuming reverberation ends quickly; strong bottoms return energy at long range','Ignoring that rough, hard bottoms reverberate more than smooth mud']::text[],ARRAY['Detecting a bottomed mine against strong bottom reverberation','Using Doppler to reject the static bottom return','Explaining long-range clutter over a rocky sea floor']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bottom reverberation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f23d77e9-0890-5c01-bdb0-cba8b0a507f2','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f23d77e9-0890-5c01-bdb0-cba8b0a507f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f23d77e9-0890-5c01-bdb0-cba8b0a507f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c5114d36-2e03-5d2e-8657-464b0bec1569','Ambient sea noise','The background acoustic field in the ocean in the absence of a specific signal or a nearby identifiable source, arising from distant shipping, wind- and wave-driven surface agitation and breaking, rain, thermal molecular motion, seismic activity, and biological sources. Its spectrum level varies with frequency, forming recognisable regimes: traffic-dominated at low frequencies, wind-dominated at mid frequencies, and thermal-dominated at very high frequencies.','The sea is never truly silent. Ships, wind, waves, rain, and animals all make sound. Even water molecules add a faint hiss at very high pitch. Together they form the background called ambient sea noise. It sets the level a sonar must hear over.','Defines the noise background against which passive and active sonar must detect signals, entering the sonar equation as the noise level.','Sonar engineers use ambient-noise spectra to set detection thresholds and to choose frequencies where the background is quietest for a given condition.','Underwater Acoustics & Sonar',ARRAY['Shipping noise','Sea-state noise','Knudsen curves','Noise spectrum level','Sonar equation']::text[],ARRAY['Confusing ambient noise (background, not from your sonar) with reverberation (echoes of your own ping)','Assuming noise is flat with frequency; it changes regime across the spectrum','Ignoring how distant shipping raises the low-frequency background']::text[],ARRAY['Setting a passive sonar detection threshold from measured background','Choosing an operating band where ambient noise is lowest','Explaining why low frequencies are dominated by distant traffic']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambient sea noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c5114d36-2e03-5d2e-8657-464b0bec1569','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c5114d36-2e03-5d2e-8657-464b0bec1569') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c5114d36-2e03-5d2e-8657-464b0bec1569');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d9265dc-1a99-525a-bf73-fd94c4cef83b','Shipping noise','The component of ambient ocean noise produced by commercial vessel traffic, dominated by propeller cavitation and machinery, and concentrated at low frequencies of roughly tens to a few hundred hertz. Contributions from many distant ships integrate into a diffuse background whose level reflects regional and global traffic density; it is the principal ambient source below a few hundred hertz in most ocean basins.','Ships are loud underwater, mostly from their spinning propellers. Their sound is strongest at low pitch. Many far-off ships blend into a steady low rumble. This is shipping noise. It rules the low-frequency background in busy seas.','Explains the dominant low-frequency ambient background, which limits low-frequency passive sonar and long-range detection.','Passive sonar planners account for shipping noise when predicting low-frequency detection ranges, especially near busy sea lanes.','Underwater Acoustics & Sonar',ARRAY['Ambient sea noise','Cavitation','Noise spectrum level','Radiated noise','Passive sonar']::text[],ARRAY['Assuming only nearby ships matter; the diffuse sum of distant traffic sets the background','Placing shipping noise at high frequencies when it dominates the low band','Confusing a single ship''s radiated noise with the basin-wide ambient level']::text[],ARRAY['Predicting low-frequency detection range near a shipping lane','Explaining a rising low-frequency background over decades of traffic growth','Separating a target''s tonals from the traffic background']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shipping noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d9265dc-1a99-525a-bf73-fd94c4cef83b','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d9265dc-1a99-525a-bf73-fd94c4cef83b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d9265dc-1a99-525a-bf73-fd94c4cef83b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ea39545-a51e-54b6-9ab0-953a578da6c9','Biological noise','Sound contributed to the ocean ambient field by marine organisms, including whales and other cetaceans, fish choruses, and the broadband crackle of snapping shrimp. It can be highly variable in time and space, sometimes dominating the background over wide bands: snapping shrimp in warm shallow waters, fish choruses near dusk and dawn, and marine-mammal calls across many frequencies.','Sea animals make a lot of sound. Whales sing, fish call in choruses, and snapping shrimp crackle. In some places this drowns out other noise. This is biological noise. It can change with the season, the time of day, and the place.','Identifies a variable ambient source that can raise the noise background and mask or mimic sonar signals.','Sonar operators in shallow tropical waters must contend with snapping-shrimp crackle, while passive listeners recognise marine-mammal calls to avoid false contacts.','Underwater Acoustics & Sonar',ARRAY['Ambient sea noise','Snapping shrimp','Bioacoustics','Noise spectrum level','Passive sonar']::text[],ARRAY['Assuming the sea is biologically quiet; shrimp and fish can dominate the band','Mistaking a marine-mammal call or fish chorus for a man-made target','Treating biological noise as constant when it varies with time and place']::text[],ARRAY['Explaining a high shallow-water background from snapping shrimp','Rejecting a whale call as a false passive contact','Timing a listening period around a dusk fish chorus']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Biological noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ea39545-a51e-54b6-9ab0-953a578da6c9','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ea39545-a51e-54b6-9ab0-953a578da6c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ea39545-a51e-54b6-9ab0-953a578da6c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b9ccdf9-1887-572e-8e76-7c5663de7fc4','Rain noise','The underwater ambient noise generated by rainfall, produced both by the impact of drops on the surface and, more strongly, by the ringing of bubbles entrained beneath each drop. It raises the ambient spectrum over a broad band, notably around and above roughly ten to twenty kilohertz, with a level that increases with rainfall rate, and it can be used acoustically to sense precipitation.','Rain falling on the sea makes noise underwater. Each drop splashes and traps tiny bubbles. The ringing bubbles are the loudest part. This is rain noise. It gets louder as the rain falls harder.','Explains a weather-driven rise in the ambient background and provides a basis for acoustic rainfall measurement.','High-frequency sonar loses range during heavy rain as rain noise raises the background, and acoustic rain gauges measure precipitation from this sound.','Underwater Acoustics & Sonar',ARRAY['Ambient sea noise','Sea-state noise','Bubble resonance','Noise spectrum level','Wind noise']::text[],ARRAY['Assuming the drop impact is the loudest part; entrained bubbles usually dominate','Ignoring rain noise when predicting high-frequency sonar in wet weather','Treating rain noise as narrowband when it spreads across a broad band']::text[],ARRAY['Explaining reduced high-frequency sonar range in a downpour','Measuring rainfall rate with an underwater acoustic rain gauge','Correcting an ambient-noise budget for weather']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rain noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b9ccdf9-1887-572e-8e76-7c5663de7fc4','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b9ccdf9-1887-572e-8e76-7c5663de7fc4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b9ccdf9-1887-572e-8e76-7c5663de7fc4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9db67ab-3a85-5702-b8b6-199bfe60393a','Sea-state noise','The wind- and wave-dependent component of ambient ocean noise, driven by surface agitation, wave breaking, spray, and especially the resulting near-surface bubble clouds. It dominates the ambient spectrum over roughly the hundreds of hertz to tens of kilohertz range, and its level rises consistently with wind speed and sea state, forming the classic wind-dependent family of ambient-noise curves.','Wind stirs the sea and breaks waves into whitecaps. Breaking waves trap noisy bubbles near the surface. The louder the wind, the louder this sound. This is sea-state noise. It controls the middle band of the background.','Explains the wind-driven part of the ambient spectrum, which controls the mid-frequency noise background that most sonar must overcome.','Sonar range predictions use wind speed or sea state to set the mid-frequency ambient level via standard wind-dependent noise curves.','Underwater Acoustics & Sonar',ARRAY['Ambient sea noise','Knudsen curves','Wind noise','Sea state','Bubble layer']::text[],ARRAY['Confusing sea-state noise (wind-driven, mid band) with shipping noise (traffic-driven, low band)','Assuming a light breeze has no effect; the background tracks wind speed closely','Ignoring the near-surface bubble layer as the main sound generator']::text[],ARRAY['Setting the mid-frequency noise level from forecast wind speed','Explaining lost sonar range as the wind picks up','Reading sea state from measured ambient spectra']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sea-state noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9db67ab-3a85-5702-b8b6-199bfe60393a','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9db67ab-3a85-5702-b8b6-199bfe60393a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9db67ab-3a85-5702-b8b6-199bfe60393a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97f41029-30ba-5496-a540-cb227973eb18','Knudsen curves','A classic family of empirical curves giving the ambient underwater noise spectrum level as a function of frequency for different sea states or wind conditions, derived from wartime and postwar measurements. They capture the wind-dependent, mid-to-high-frequency portion of ambient noise, showing a spectrum that falls with increasing frequency and rises with sea state, and they remain a standard reference for the wind-driven noise band.','Knudsen curves are a set of graphs of sea noise. Each curve is for a different sea state. They show how loud the background is at each pitch. The rougher the sea, the higher the curve. Engineers still use them to estimate wind noise.','Provide a standard reference for estimating the wind-driven ambient noise spectrum when planning sonar performance.','An analyst reads a Knudsen curve at the operating frequency and sea state to obtain a noise spectrum level for the sonar equation.','Underwater Acoustics & Sonar',ARRAY['Sea-state noise','Ambient sea noise','Noise spectrum level','Wenz curves','Sea state']::text[],ARRAY['Using Knudsen curves at very low frequencies where shipping, not wind, dominates','Treating them as exact rather than as empirical averages','Confusing Knudsen curves (wind band) with the broader Wenz composite curves']::text[],ARRAY['Reading a noise spectrum level for a given sea state and frequency','Comparing measured ambient noise to the classic curves','Building a mid-frequency noise budget for a sonar prediction']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Knudsen curves');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97f41029-30ba-5496-a540-cb227973eb18','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97f41029-30ba-5496-a540-cb227973eb18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97f41029-30ba-5496-a540-cb227973eb18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9376edab-973f-5098-bac9-3fc66cecb029','Critical depth','In deep-water propagation, the depth below the sound-channel axis at which the sound speed again equals its maximum value found near the surface. The vertical interval between the sea floor and the critical depth, the depth excess, determines whether refracted paths can complete convergence-zone cycles without interacting with the bottom, enabling long-range, low-loss propagation.','Deep in the ocean, sound speed rises again with depth. Critical depth is where it matches the fast speed near the surface. If the sea floor is deeper than this, sound can bend back up. That allows long-range paths called convergence zones. It is a key check for deep-water sonar.','Determines whether the water is deep enough to support convergence-zone propagation, a condition for reliable long-range detection.','Sonar planners compare the critical depth with the water depth, the depth excess, to decide whether convergence zones will form on a given path.','Underwater Acoustics & Sonar',ARRAY['Deep sound channel axis','Convergence-zone propagation','Depth excess','Sound speed profile','Sonic layer depth']::text[],ARRAY['Confusing critical depth with the channel axis (the sound-speed minimum)','Assuming convergence zones form regardless of water depth','Forgetting that a bottom above the critical depth blocks the refracted path']::text[],ARRAY['Deciding whether convergence zones exist in a deep basin','Comparing water depth with critical depth for depth excess','Explaining why a shallow basin has no convergence-zone paths']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical depth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9376edab-973f-5098-bac9-3fc66cecb029','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9376edab-973f-5098-bac9-3fc66cecb029') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9376edab-973f-5098-bac9-3fc66cecb029');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d09cf3d-505f-5a9c-90c4-74453159b3f1','Deep sound channel axis','The depth of minimum sound speed in the open ocean, around which the deep sound channel, also called the SOFAR channel, is centred. Sound near this axis is refracted repeatedly toward the minimum, so energy launched near the axis is trapped and can propagate for thousands of kilometres with only cylindrical spreading and absorption, without interacting with the surface or bottom.','Sound speed in the deep ocean has a lowest point at some depth. That depth is the deep sound channel axis. Sound near it keeps bending back toward it. So it stays trapped and travels very far. Whales and long-range systems use this channel.','Marks the centre of the natural waveguide that carries low-frequency sound over ocean-basin distances with minimal loss.','Long-range acoustic systems and hydrophone arrays place sources or receivers near the axis to exploit low-loss SOFAR propagation.','Underwater Acoustics & Sonar',ARRAY['SOFAR channel','Critical depth','Convergence-zone propagation','Sound speed profile','Ray trace']::text[],ARRAY['Confusing the axis (the sound-speed minimum) with the surface duct near the top','Assuming any depth traps sound; only energy near the axis stays channelled','Mixing up the deep channel axis with the critical depth']::text[],ARRAY['Placing a long-range source near the channel axis','Explaining basin-scale propagation of whale calls','Reading a sound-speed profile to find the axis depth']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deep sound channel axis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d09cf3d-505f-5a9c-90c4-74453159b3f1','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d09cf3d-505f-5a9c-90c4-74453159b3f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d09cf3d-505f-5a9c-90c4-74453159b3f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7d24347-70f1-56c1-adae-5a666db70a0a','Shadow zone','A region that direct refracted ray paths cannot reach, so that received levels are very low, arising from downward refraction beneath a source or from a sound-speed profile whose geometry bends rays away from the region. Energy reaches it only weakly by diffraction, scattering, or bottom-bounce paths, making it a zone of poor detection.','Sometimes sound bends away from a whole region. Rays cannot reach it directly. This quiet region is a shadow zone. A target hidden there is very hard to detect. Only weak, scattered sound leaks in.','Explains regions where sonar detection fails despite short range, guiding tactics and depth choices to avoid or exploit them.','A submarine may hide in a shadow zone below a surface sonar; operators change depth or use bottom paths to fill the coverage gap.','Underwater Acoustics & Sonar',ARRAY['Ray trace','Sound speed profile','Surface duct','Downward refraction','Convergence-zone propagation']::text[],ARRAY['Assuming a short range guarantees detection; a shadow zone can blind the sonar','Confusing a shadow zone with a shallow-water dead spot from other causes','Ignoring weak diffracted or bottom-bounce energy that still enters']::text[],ARRAY['A target evading detection just below the sonar''s layer','Explaining a coverage gap under a strong downward-refracting profile','Choosing a search depth to remove a shadow zone']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shadow zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7d24347-70f1-56c1-adae-5a666db70a0a','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7d24347-70f1-56c1-adae-5a666db70a0a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7d24347-70f1-56c1-adae-5a666db70a0a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7cfc26c-f92f-5315-82f1-26bab803951e','Bottom duct','A near-bottom sound channel formed where the sound speed reaches a local minimum at or near the sea floor, so sound speed increases upward away from the bottom. Because rays bend toward lower sound speed, upward-travelling rays are refracted back down toward this minimum, and together with reflection at the relatively low-loss bottom this traps acoustic energy near the sea floor, enhancing near-bottom propagation over a flat seabed.','Near the sea floor, sound speed can be lowest right at the bottom. Rays then bend back down toward the floor. This traps sound in a layer near the bottom. That trapped layer is a bottom duct. It can carry sound farther along the floor.','Describes a propagation path that enhances near-bottom sound transmission, relevant to bottom-mounted and deep sonar.','Bottom-mounted arrays and deep sources can benefit from a bottom duct that channels energy along a smooth sea floor.','Underwater Acoustics & Sonar',ARRAY['Surface duct','Sound speed profile','Bottom loss','Ray trace','Deep sound channel axis']::text[],ARRAY['Confusing a bottom duct with the deep sound channel higher in the water','Assuming a bottom duct always exists; it needs the right profile and a low-loss bottom','Ignoring bottom loss that limits how well the duct traps energy']::text[],ARRAY['Explaining enhanced near-bottom propagation over a flat sea floor','Planning a bottom-mounted sensor to use near-bottom trapping','Reading a profile that bends rays back toward the bottom']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bottom duct');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7cfc26c-f92f-5315-82f1-26bab803951e','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7cfc26c-f92f-5315-82f1-26bab803951e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7cfc26c-f92f-5315-82f1-26bab803951e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e94d7881-40e1-5d05-bdf7-fc129f4bea5b','Convergence-zone propagation','A deep-water propagation mode in which downward-refracted rays that pass below the sound-channel axis are turned back upward by the increasing deep sound speed and re-converge near the surface at regularly spaced annular zones, typically tens of kilometres apart. Within each convergence zone the focusing produces high signal levels, that is, low transmission loss, enabling detection at ranges far beyond the direct path.','In deep water, sound can dive down and then curve back up to the surface. It focuses into rings far from the source. These rings are convergence zones. Inside them the sound is strong again. Sonar can detect targets there, far away.','Provides a mechanism for long-range detection at discrete ranges where refracted energy re-focuses near the surface.','Surface and submarine sonar exploit convergence zones for long-range contact, expecting strong returns at annular ranges roughly every few tens of kilometres.','Underwater Acoustics & Sonar',ARRAY['Critical depth','Deep sound channel axis','Depth excess','Transmission loss','Ray trace']::text[],ARRAY['Expecting continuous coverage; convergence zones are separated by intervening low-signal ranges','Assuming they form in shallow water or without adequate depth excess','Confusing convergence zones with bottom-bounce paths']::text[],ARRAY['Detecting a distant ship in the first convergence zone','Planning search geometry around convergence-zone ranges','Explaining a strong contact tens of kilometres out with a gap before it']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Convergence-zone propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e94d7881-40e1-5d05-bdf7-fc129f4bea5b','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e94d7881-40e1-5d05-bdf7-fc129f4bea5b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e94d7881-40e1-5d05-bdf7-fc129f4bea5b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7a03b828-a2f3-5be9-9c01-d930bd7b4058','Lloyd mirror effect','An interference pattern created near a reflecting boundary when the direct sound from a source combines with its surface-reflected image. Because reflection at the pressure-release sea surface introduces a 180-degree phase reversal, the direct and reflected paths alternately reinforce and cancel as a function of source depth, receiver depth, range, and frequency, producing a series of interference lobes and a null along the surface.','Sound from a shallow source can reach a receiver two ways. One path is direct; the other bounces off the surface. The surface flips the reflected wave''s phase. The two paths add and cancel in turn. This makes bands of loud and quiet, the Lloyd mirror pattern.','Explains depth- and range-dependent signal fluctuations for shallow sources and receivers, which affect near-surface detection and radiated-noise measurement.','Analysts account for the Lloyd mirror pattern when measuring a ship''s radiated noise or when a shallow source and receiver show deep interference nulls.','Underwater Acoustics & Sonar',ARRAY['Image source','Surface reflection','Interference','Pressure-release surface','Multipath']::text[],ARRAY['Forgetting the 180-degree phase flip at the surface, which puts a null along it','Mistaking interference nulls for real changes in source level','Ignoring how the pattern shifts with frequency, depth, and range']::text[],ARRAY['Measuring a surface ship''s radiated noise with a shallow hydrophone','Explaining deep signal fades as a shallow target changes range','Choosing a receiver depth to avoid an interference null']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lloyd mirror effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7a03b828-a2f3-5be9-9c01-d930bd7b4058','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7a03b828-a2f3-5be9-9c01-d930bd7b4058') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7a03b828-a2f3-5be9-9c01-d930bd7b4058');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '577c3893-a167-5bc4-b4f9-87b241db98f1','Ray trace','A method of computing sound propagation by following ray paths that obey Snell''s law through a depth- and range-varying sound-speed field, with rays bending toward regions of lower sound speed. Ray tracing yields travel times, path geometry, and, from the spreading of ray tubes, an estimate of transmission loss; it is most accurate at higher frequencies where the wavelength is small compared with the scale of sound-speed variation.','A ray trace draws the paths that sound follows in the sea. Each path bends as sound speed changes with depth. Rays curve toward slower water. The picture shows where sound goes and where it does not. Engineers use it to plan and explain sonar coverage.','Gives an intuitive, efficient way to predict propagation paths, travel times, and coverage features such as shadow zones and convergence zones.','Sonar prediction tools display ray traces from a sound-speed profile so operators can see ducts, shadow zones, and convergence zones for a given day.','Underwater Acoustics & Sonar',ARRAY['Eigenray','Sound speed profile','Snell''s law','Shadow zone','Convergence-zone propagation','Transmission loss']::text[],ARRAY['Trusting ray tracing at low frequencies where wave effects and diffraction matter','Ignoring that rays predict zero energy in shadow zones that diffraction actually fills','Forgetting that rays bend toward slower sound speed, not faster']::text[],ARRAY['Predicting daily sonar coverage from a measured profile','Identifying shadow zones and convergence zones before a search','Explaining a duct that traps sound near the surface']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ray trace');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '577c3893-a167-5bc4-b4f9-87b241db98f1','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='577c3893-a167-5bc4-b4f9-87b241db98f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='577c3893-a167-5bc4-b4f9-87b241db98f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc9b078a-3e4b-51f6-9158-c82a10427691','Eigenray','A specific ray path that connects a given source and receiver while satisfying the propagation geometry, that is, Snell''s law and the boundary interactions, so that it actually links the two points. For a given source-receiver pair there may be several eigenrays, including direct, surface-reflected, bottom-reflected, and refracted paths, each with its own travel time, angle, and amplitude, and together they define the multipath structure of the received signal.','An eigenray is a sound path that truly connects a source to a receiver. Many rays leave the source, but only some reach the receiver. Those that do are the eigenrays. Each brings its own delay and strength. Together they form the multipath signal.','Identifies the exact paths and their arrival times that build up a received signal, essential for modelling multipath and for localisation.','Propagation models find eigenrays to predict arrival times and amplitudes, used in matched-field and travel-time-based localisation.','Underwater Acoustics & Sonar',ARRAY['Ray trace','Multipath','Travel time','Matched-field localization','Sound speed profile']::text[],ARRAY['Confusing an eigenray (connects source and receiver) with any traced ray','Assuming a single path; usually several eigenrays arrive at different times','Ignoring surface- and bottom-reflected eigenrays alongside the direct path']::text[],ARRAY['Predicting multipath arrival times at a receiver','Feeding eigenray delays into a localisation algorithm','Explaining multiple arrivals from one transmission']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eigenray');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc9b078a-3e4b-51f6-9158-c82a10427691','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc9b078a-3e4b-51f6-9158-c82a10427691') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc9b078a-3e4b-51f6-9158-c82a10427691');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fcbfe5d3-93c4-5f56-9c24-46238655b810','Normal mode propagation','A full-wave description of sound in an ocean waveguide as a sum of discrete normal modes, each an eigenfunction of the depth-dependent wave equation with its own horizontal wavenumber and phase and group speed. Modes propagate with characteristic depth shapes; higher-order modes interact more strongly with the boundaries and attenuate faster, so at long range and low frequency only a few low-order modes survive. The approach is especially suited to low frequencies and shallow-water waveguides.','The ocean acts like a waveguide for low sounds. Sound in it can be split into simple patterns called modes. Each mode has its own shape with depth and its own speed. Higher modes fade faster with range. Adding the surviving modes gives the sound field.','Provides an accurate, physically insightful way to compute low-frequency and shallow-water propagation where ray methods fail.','Shallow-water and low-frequency propagation models use normal modes to predict transmission loss and to underpin matched-field processing.','Underwater Acoustics & Sonar',ARRAY['Parabolic equation propagation','Waveguide','Transmission loss','Matched-field localization','Ray trace']::text[],ARRAY['Applying modes at very high frequencies where they become too numerous to be practical','Confusing modes (full-wave patterns) with rays (high-frequency paths)','Forgetting that higher-order modes attenuate faster with range']::text[],ARRAY['Modelling low-frequency propagation in shallow water','Explaining why only low-order modes survive at long range','Providing replica fields for matched-field localisation']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Normal mode propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fcbfe5d3-93c4-5f56-9c24-46238655b810','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fcbfe5d3-93c4-5f56-9c24-46238655b810') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fcbfe5d3-93c4-5f56-9c24-46238655b810');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc04b4dc-980d-5336-9694-c67ac206ff7b','Parabolic equation propagation','A one-way, full-wave method that approximates the elliptic Helmholtz equation by a parabolic equation marched forward in range, capturing diffraction and refraction in range-dependent environments while neglecting backscatter. Starting from an initial field near the source, it steps the acoustic field outward in range using an operator built from the depth Laplacian and the local index of refraction, and it is the standard tool for low-frequency propagation over varying bathymetry and sound-speed fields.','The parabolic equation method computes sound step by step in range. It starts with a field near the source. Then it marches the field outward, one range step at a time. It handles changing depth and water properties well. It is a standard tool for low-frequency sound.','Provides an efficient, accurate way to model propagation in range-varying oceans where sound speed and bottom depth change along the path.','Ocean-acoustic prediction codes use the parabolic equation to compute transmission loss over sloping bottoms and fronts for low-frequency sonar.','Underwater Acoustics & Sonar',ARRAY['Normal mode propagation','Transmission loss','Helmholtz equation','Range-dependent environment','Ray trace']::text[],ARRAY['Expecting it to capture backscattered energy; the standard form is one-way, marching forward only','Using a narrow-angle version for steep propagation angles it cannot represent','Assuming it is exact; it approximates the full wave equation']::text[],ARRAY['Computing transmission loss over a sloping continental shelf','Modelling low-frequency propagation across an ocean front','Predicting sound fields in a range-dependent duct']::text[],'advanced','du/dr = (i / 2k0) [ d2u/dz2 + k0^2 (n^2 - 1) u ]','In the narrow-angle form, the range derivative of the reduced field equals i divided by twice the reference wavenumber, times the sum of the second depth derivative of the field and the reference wavenumber squared times the index of refraction squared minus one, times the field.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parabolic equation propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc04b4dc-980d-5336-9694-c67ac206ff7b','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc04b4dc-980d-5336-9694-c67ac206ff7b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc04b4dc-980d-5336-9694-c67ac206ff7b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d8ba535-9484-543f-9748-d39522aa6615','Matched-field localization','A signal-processing method that estimates a source''s position, in range, depth, and sometimes bearing, by correlating the acoustic field measured across an array with modelled replica fields computed for many candidate source locations using a full-wave propagation model. The candidate whose replica best matches the data, judged by a processor such as the Bartlett or an adaptive minimum-variance estimator, is taken as the source location; the method exploits the full multipath and modal structure of the waveguide.','Matched-field localization finds where a sound came from. It records the sound across an array of sensors. A model predicts the field for many possible source spots. The spot whose prediction best fits the data wins. That gives the source range and depth.','Locates a source in depth and range by using the whole waveguide''s propagation physics, not just a single arrival angle.','Research and naval systems localise a quiet source in shallow water by matching array data to modelled replica fields across a search grid.','Underwater Acoustics & Sonar',ARRAY['Normal mode propagation','Eigenray','Replica field','Array processing','Beamforming']::text[],ARRAY['Assuming it works with a poor environmental model; mismatch quickly degrades the result','Confusing it with plane-wave beamforming, which gives only bearing','Ignoring sidelobe ambiguities that create false source peaks']::text[],ARRAY['Localising a source in depth and range in shallow water','Testing the sensitivity of a localisation to sound-speed errors','Distinguishing a submerged source from a surface one by depth']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Matched-field localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d8ba535-9484-543f-9748-d39522aa6615','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d8ba535-9484-543f-9748-d39522aa6615') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d8ba535-9484-543f-9748-d39522aa6615');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3226339-af1c-5c53-a596-27e8a491c301','Doppler tolerance','The degree to which a sonar waveform maintains its matched-filter processing gain when the echo is Doppler-shifted by relative motion between platform and target. A Doppler-tolerant waveform, such as a hyperbolic or linear-period-modulated sweep, compresses well over a range of Doppler shifts, whereas a Doppler-sensitive waveform loses correlation and range accuracy unless the receiver searches over multiple Doppler-shifted replicas.','A moving target shifts the pitch of the echo. This is a Doppler shift. Some sonar pulses still process well despite the shift. They are called Doppler tolerant. Others need the receiver to test many shifted copies.','Describes how robust a waveform is to target motion, guiding waveform choice when the Doppler shift is unknown or large.','Sonar designers pick a Doppler-tolerant sweep when target speed is uncertain, avoiding a costly bank of Doppler-shifted matched filters.','Underwater Acoustics & Sonar',ARRAY['Matched filter','Frequency-modulated pulse','Doppler resolution','Pulse compression','Ambiguity function']::text[],ARRAY['Assuming any FM sweep is Doppler tolerant; only specific shapes are','Confusing Doppler tolerance (keeps gain) with Doppler resolution (measures speed)','Forgetting that a Doppler-sensitive pulse needs multiple replica filters']::text[],ARRAY['Choosing a waveform for a fast, unknown-speed target','Explaining lost detection when a pulse is not Doppler tolerant','Trading Doppler tolerance against speed-measuring ability']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Doppler tolerance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3226339-af1c-5c53-a596-27e8a491c301','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3226339-af1c-5c53-a596-27e8a491c301') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3226339-af1c-5c53-a596-27e8a491c301');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a07158cf-9d3c-5990-8443-ae164f7abcbb','Pulse compression','A technique that transmits a long, modulated pulse for high transmitted energy and processes the echo with a matched filter to produce a short output peak, thereby achieving the range resolution of a short pulse while retaining the detection energy of a long one. The processing gain and resolution are governed by the pulse''s time-bandwidth product, and the compressed width is set by the signal bandwidth.','A long pulse carries more energy and helps detection. But a long pulse gives poor range accuracy. Pulse compression fixes this. It squeezes the received long pulse into a short, sharp peak. So you gain both energy and fine range.','Decouples detection energy from range resolution, letting a sonar detect at long range and still resolve targets finely.','Modern active sonar transmits a swept, or chirp, pulse and applies matched-filter pulse compression to gain both range and resolution.','Underwater Acoustics & Sonar',ARRAY['Matched filter','Frequency-modulated pulse','Chirp sonar','Range resolution','Time-bandwidth product']::text[],ARRAY['Thinking compression adds energy; it concentrates existing energy in time','Ignoring range sidelobes that need weighting to suppress','Assuming resolution comes from pulse length rather than bandwidth']::text[],ARRAY['Detecting a distant target while keeping fine range separation','Applying a matched filter to a transmitted chirp','Weighting a compressed pulse to reduce range sidelobes']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pulse compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a07158cf-9d3c-5990-8443-ae164f7abcbb','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a07158cf-9d3c-5990-8443-ae164f7abcbb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a07158cf-9d3c-5990-8443-ae164f7abcbb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '287aa28d-83ac-5db7-847b-eeecb2297d66','Matched filter','The linear filter that maximises the peak signal-to-noise ratio at its output for a known signal in additive white noise; its impulse response is the time-reversed, complex-conjugated replica of the transmitted signal. Applied to sonar echoes it performs the correlation that underlies pulse compression, and its peak output signal-to-noise ratio depends only on the received signal energy and the noise spectral density, not on the waveform shape.','A matched filter is the best filter for spotting a known pulse in noise. It compares the incoming sound with a stored copy of the pulse. When they line up, the output peaks. This gives the strongest possible peak over the noise. Sonar uses it to detect echoes.','Provides the optimum receiver for detecting a known waveform in noise and the mechanism behind pulse compression.','Active sonar correlates each echo against a replica of the transmitted pulse in a matched filter to detect targets and mark their range.','Underwater Acoustics & Sonar',ARRAY['Pulse compression','Correlation','Frequency-modulated pulse','Signal-to-noise ratio','Range resolution']::text[],ARRAY['Assuming peak SNR depends on pulse shape; it depends only on energy and noise density','Forgetting the filter must match the actual, possibly Doppler-shifted, echo','Confusing the matched filter with a simple band-pass filter']::text[],ARRAY['Detecting a weak echo buried in noise','Implementing pulse compression by correlation','Building a replica for each transmitted waveform']::text[],'advanced','SNR_peak = 2E / N0','The peak output signal-to-noise ratio of a matched filter equals twice the received signal energy divided by the noise power spectral density, independent of the waveform shape.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Matched filter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '287aa28d-83ac-5db7-847b-eeecb2297d66','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='287aa28d-83ac-5db7-847b-eeecb2297d66') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='287aa28d-83ac-5db7-847b-eeecb2297d66');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5005ec2-71e8-5047-8aee-aaaf7ae99b89','Chirp sonar','An active sonar that transmits a frequency-swept, or chirp, pulse and applies matched-filter pulse compression on reception, obtaining fine range resolution set by the sweep bandwidth while transmitting a long, high-energy pulse for detection range. It is widely used from sub-bottom profilers to search sonars because it separates resolution, set by bandwidth, from transmitted energy, set by pulse length.','A chirp sonar sends a pulse that sweeps through a range of pitches. On return, it squeezes the echo into a sharp peak. This gives fine range while still sending strong, long pulses. Sub-bottom profilers and search sonars use it. The wide sweep gives the fine detail.','Combines long-pulse detection energy with wide-bandwidth range resolution through swept transmission and matched filtering.','Sub-bottom profilers and modern search sonar use chirp waveforms to image layers or detect targets with high range resolution.','Underwater Acoustics & Sonar',ARRAY['Frequency-modulated pulse','Pulse compression','Matched filter','Range resolution','Continuous-wave sonar']::text[],ARRAY['Thinking the long chirp gives poor resolution; compression restores fine range','Confusing a chirp (swept) with a continuous-wave (single-frequency) pulse','UNSAFE: energising a high-power sonar projector while divers or marine mammals are nearby without following exposure-control and clearance procedures']::text[],ARRAY['Profiling sediment layers beneath the sea floor','Detecting a target with a wideband swept pulse','Choosing the sweep bandwidth to set range resolution']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chirp sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5005ec2-71e8-5047-8aee-aaaf7ae99b89','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5005ec2-71e8-5047-8aee-aaaf7ae99b89') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5005ec2-71e8-5047-8aee-aaaf7ae99b89');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3f7cafce-7af5-55ed-a823-1596e40043bb','Continuous-wave sonar','An active sonar that transmits a single-frequency, constant-frequency pulse, providing fine Doppler resolution and simple processing but a range resolution limited by the pulse length. Its narrow bandwidth makes it well suited to measuring a target''s radial velocity from the Doppler shift, at the cost of poor range resolution compared with wideband swept waveforms.','A continuous-wave sonar sends a steady, single-pitch pulse. Its narrow band makes it good at measuring speed. A moving target shifts the pitch, and the sonar reads that shift. But a single-pitch pulse gives poor range detail. It trades range accuracy for speed accuracy.','Provides accurate Doppler, or radial-velocity, measurement using a narrowband tone, complementing wideband range-resolving waveforms.','Sonars use a continuous-wave ping to measure a target''s closing speed from its Doppler shift, often alongside a chirp for range.','Underwater Acoustics & Sonar',ARRAY['Continuous wave','Doppler resolution','Frequency-modulated pulse','Chirp sonar','Doppler tolerance']::text[],ARRAY['Expecting good range resolution from a long single-frequency pulse','Confusing continuous-wave sonar with a truly continuous, non-pulsed transmitter','UNSAFE: operating a high-power sonar transmitter near divers or marine life without following exposure-control and clearance procedures']::text[],ARRAY['Measuring a target''s radial speed from Doppler','Pairing a tone ping with a chirp for range and speed','Explaining poor range accuracy from a narrowband pulse']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous-wave sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3f7cafce-7af5-55ed-a823-1596e40043bb','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3f7cafce-7af5-55ed-a823-1596e40043bb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3f7cafce-7af5-55ed-a823-1596e40043bb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23b52d08-07ed-5f45-9f97-19dc871c9038','Frequency-modulated pulse','A pulse whose instantaneous frequency varies during its duration, most commonly a linear sweep, called linear frequency modulation, but also hyperbolic or other laws. Its wide bandwidth supports matched-filter pulse compression for fine range resolution, and the choice of modulation law sets its Doppler behaviour; it is the workhorse waveform of chirp and pulse-compression sonar.','A frequency-modulated pulse changes its pitch as it plays. Often the pitch rises steadily from low to high. This wide sweep lets the receiver squeeze the echo into a sharp peak. That gives fine range detail. It is the common pulse for chirp sonar.','Supplies the wide bandwidth needed for pulse compression and fine range resolution while allowing a long, energetic pulse.','Sonar and sub-bottom profilers transmit a linear FM sweep and compress the echo to resolve closely spaced targets or layers.','Underwater Acoustics & Sonar',ARRAY['Chirp sonar','Pulse compression','Matched filter','Range resolution','Doppler tolerance']::text[],ARRAY['Assuming resolution comes from pulse length rather than the swept bandwidth','Confusing linear and hyperbolic sweeps, which differ in Doppler behaviour','UNSAFE: transmitting a high-power swept pulse near divers or marine mammals without following exposure-control and clearance procedures']::text[],ARRAY['Transmitting a linear sweep for a chirp sonar','Setting the sweep bandwidth to achieve a target range resolution','Choosing a hyperbolic sweep for Doppler tolerance']::text[],'intermediate','f(t) = f0 + (B / T) * t','For a linear frequency-modulated pulse, the instantaneous frequency equals the start frequency plus the sweep bandwidth divided by the pulse duration, multiplied by elapsed time.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-modulated pulse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23b52d08-07ed-5f45-9f97-19dc871c9038','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23b52d08-07ed-5f45-9f97-19dc871c9038') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23b52d08-07ed-5f45-9f97-19dc871c9038');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74083aa5-b371-58c9-8acd-3e0b5d379196','Ping repetition interval','The time between successive active sonar transmissions, the reciprocal of the ping, or pulse, repetition frequency. It must be long enough for echoes from the maximum range of interest to return before the next transmission; otherwise second-time-around echoes create range ambiguities. It therefore sets the maximum unambiguous range and, together with platform motion, the along-track sampling.','A sonar pings over and over. The time between pings is the ping repetition interval. It must be long enough for far echoes to return first. If it is too short, distant echoes arrive after the next ping. Then their range looks wrong.','Sets how often a sonar transmits and thereby the maximum range that can be measured without ambiguity.','Operators lengthen the ping interval to search at long range and shorten it for rapid updates at short range.','Underwater Acoustics & Sonar',ARRAY['Pulse repetition frequency','Maximum unambiguous range','Range ambiguity','Ping','Range resolution']::text[],ARRAY['Setting the interval too short, so distant echoes fold into the next ping''s range','Confusing ping interval (time between pings) with pulse length (duration of one ping)','Assuming faster pinging always helps; it shortens the unambiguous range']::text[],ARRAY['Choosing a ping interval for a long-range search','Diagnosing second-time-around echoes as range ambiguities','Trading update rate against unambiguous range']::text[],'intermediate','R_max = c * T_pri / 2','The maximum unambiguous range equals the sound speed times the ping repetition interval, divided by two for the round trip.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ping repetition interval');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74083aa5-b371-58c9-8acd-3e0b5d379196','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74083aa5-b371-58c9-8acd-3e0b5d379196') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74083aa5-b371-58c9-8acd-3e0b5d379196');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b8b6cc0-95c8-5127-ba2e-6f43364aca33','Range resolution','The minimum separation in range at which a sonar can distinguish two targets as separate echoes, set by the effective pulse duration after any compression and hence inversely proportional to the signal bandwidth. For a pulse of bandwidth B, range resolution is approximately the sound speed divided by twice the bandwidth, so wider bandwidth gives finer resolution regardless of the transmitted pulse length.','Range resolution is how close two targets can be and still be told apart. It depends on the pulse bandwidth, not its length. A wider band gives finer resolution. Two targets closer than this merge into one echo. Chirp pulses widen the band to sharpen it.','Quantifies a sonar''s ability to separate closely spaced targets in range, a key performance measure.','Designers choose the signal bandwidth to meet a range-resolution requirement, and imaging sonar uses wide bandwidth for fine detail.','Underwater Acoustics & Sonar',ARRAY['Pulse compression','Frequency-modulated pulse','Bandwidth','Bearing resolution','Chirp sonar']::text[],ARRAY['Thinking a shorter pulse alone sets resolution; bandwidth is what matters','Confusing range resolution with the range accuracy of a single target','Ignoring that compression lets a long pulse still give fine resolution']::text[],ARRAY['Separating two closely spaced targets in range','Choosing bandwidth to meet an imaging requirement','Explaining merged echoes from insufficient bandwidth']::text[],'intermediate','dR = c / (2B)','Range resolution equals the sound speed divided by twice the signal bandwidth.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Range resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b8b6cc0-95c8-5127-ba2e-6f43364aca33','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b8b6cc0-95c8-5127-ba2e-6f43364aca33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b8b6cc0-95c8-5127-ba2e-6f43364aca33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6c0128d-67f4-56e1-8b0c-b510d9289a31','Bearing resolution','The minimum angular separation at which a sonar can distinguish two targets in bearing, set by the array''s beamwidth and hence proportional to the wavelength divided by the aperture length. A larger aperture measured in wavelengths yields a narrower beam and finer bearing resolution; beamforming and array shading determine the achievable value and the sidelobe structure.','Bearing resolution is how close in angle two targets can be and still be told apart. It depends on the array size compared with the wavelength. A bigger array gives a narrower beam. A narrower beam separates targets better. Two targets inside one beam look like one.','Quantifies a sonar''s angular discrimination, governing how well it separates targets by direction.','Array designers lengthen the aperture or raise the frequency to narrow the beam and improve bearing resolution in a towed or hull array.','Underwater Acoustics & Sonar',ARRAY['Beamwidth','Array aperture','Beamforming','Range resolution','Sidelobe']::text[],ARRAY['Assuming more elements alone improve bearing; the aperture in wavelengths sets the beamwidth','Confusing bearing resolution with the bearing accuracy of a single target','Ignoring sidelobes that let off-axis targets leak in']::text[],ARRAY['Separating two contacts at the same range but different bearings','Sizing a towed array for a required beamwidth','Explaining merged bearings from a short aperture']::text[],'intermediate','dtheta ~ lambda / L','Bearing, or angular, resolution in radians is approximately the wavelength divided by the array aperture length.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bearing resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6c0128d-67f4-56e1-8b0c-b510d9289a31','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6c0128d-67f4-56e1-8b0c-b510d9289a31') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6c0128d-67f4-56e1-8b0c-b510d9289a31');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5af4cab-dadf-5ba7-a2eb-605dbd3dcf60','Doppler resolution','The smallest difference in Doppler shift, and hence in radial velocity, that a sonar can distinguish, set by the effective observation time of the waveform and thus approximately the reciprocal of the pulse duration. Longer coherent integration, that is, a longer tone, gives finer Doppler resolution, trading against range resolution; the joint range-Doppler behaviour is described by the waveform''s ambiguity function.','Doppler resolution is how close two speeds can be and still be told apart. It depends on how long the pulse lasts. A longer pulse gives finer speed detail. But a longer single-pitch pulse gives poorer range detail. So range and speed detail trade off.','Quantifies a sonar''s ability to separate targets by radial velocity, complementing range resolution.','A long continuous-wave ping gives fine Doppler resolution to separate a slow target from clutter by its motion.','Underwater Acoustics & Sonar',ARRAY['Continuous-wave sonar','Doppler shift','Ambiguity function','Range resolution','Clutter return']::text[],ARRAY['Expecting fine Doppler and fine range from one short pulse; they trade off','Confusing Doppler resolution with Doppler tolerance','Ignoring the observation time that sets the achievable resolution']::text[],ARRAY['Separating a moving target from stationary clutter by speed','Choosing a long tone for fine velocity discrimination','Explaining the range-Doppler trade with the ambiguity function']::text[],'intermediate','df ~ 1 / T','Doppler, or frequency, resolution is approximately the reciprocal of the coherent pulse duration; the equivalent velocity resolution is that frequency spread scaled by half the sound speed divided by the centre frequency.','a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Doppler resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5af4cab-dadf-5ba7-a2eb-605dbd3dcf60','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5af4cab-dadf-5ba7-a2eb-605dbd3dcf60') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5af4cab-dadf-5ba7-a2eb-605dbd3dcf60');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3048aea-be2b-5479-af8d-0d1dba0c5c07','Clutter return','Unwanted echoes from the environment, such as rough boundaries, the sea floor, wrecks, rocks, biological aggregations, or oceanographic features, that compete with the target echo in an active sonar. Unlike diffuse reverberation, clutter often appears as discrete, target-like returns, and it is a leading cause of false alarms in mine-hunting and shallow-water detection.','Clutter is unwanted echoes from the surroundings. Rocks, wrecks, the sea floor, and fish all reflect the ping. Some look just like a target. These false echoes are clutter returns. They cause false alarms and confuse operators.','Names the discrete, target-like background that limits detection and drives false alarms, distinct from diffuse noise.','Mine-hunting sonar operators and classifiers must separate a true target from many clutter returns using shape, echo features, or aspect changes.','Underwater Acoustics & Sonar',ARRAY['Reverberation','Bottom reverberation','False alarm','Target strength','Backscattering']::text[],ARRAY['Confusing discrete clutter with diffuse reverberation or ambient noise','Assuming a strong, compact echo is always a target','Ignoring that clutter density rises in rocky or wreck-strewn areas']::text[],ARRAY['Sorting real mines from rocks in a mine-hunting search','Explaining false alarms over a rugged sea floor','Using multiple aspects to reject a clutter return']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clutter return');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3048aea-be2b-5479-af8d-0d1dba0c5c07','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3048aea-be2b-5479-af8d-0d1dba0c5c07') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3048aea-be2b-5479-af8d-0d1dba0c5c07');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35558f86-a2c7-56c5-8a79-7019f3bba751','Wake detection','The detection of a surface or subsurface vessel by the acoustic signature of its wake, a turbulent, bubble-filled region trailing the vessel that scatters and attenuates sound differently from the surrounding water. The bubble wake persists for a period after passage and presents enhanced acoustic backscatter and shadowing that active sonar can sense to detect or follow the vessel''s track.','A moving ship leaves a trail of churned, bubbly water. This wake scatters sound in its own way. Sonar can sense the wake even after the ship passes. Detecting a vessel this way is wake detection. The bubbles make the wake stand out.','Provides an alternative detection cue based on the persistent bubble wake rather than the vessel hull itself.','Some sonar systems detect and follow a ship''s bubble wake, which lingers and can reveal a recent track.','Underwater Acoustics & Sonar',ARRAY['Bubble layer','Backscattering','Volume scattering','Reverberation','Target strength']::text[],ARRAY['Assuming the wake fades instantly; the bubble wake can persist for a long time','Confusing wake backscatter with a return from the hull itself','Ignoring how the wake both scatters and shadows sound']::text[],ARRAY['Tracking a vessel by its lingering bubble wake','Explaining enhanced backscatter behind a moving ship','Distinguishing a wake return from the vessel echo']::text[],'advanced',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wake detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35558f86-a2c7-56c5-8a79-7019f3bba751','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35558f86-a2c7-56c5-8a79-7019f3bba751') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35558f86-a2c7-56c5-8a79-7019f3bba751');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dea074e5-8909-5e56-8d2c-f0a870c6f810','Acoustic modem','A device that transmits and receives digital data underwater using sound as the carrier, encoding bits onto acoustic waveforms and contending with a severe channel: strong multipath, limited bandwidth, high and variable latency, and Doppler from platform motion. Modems use modulation and equalisation schemes suited to this channel to link autonomous vehicles, sensors, and surface nodes where radio cannot propagate.','Radio waves do not travel far in seawater. So underwater devices send data as sound instead. An acoustic modem turns bits into sound and back again. It must fight echoes, delay, and motion. It links underwater robots and sensors.','Enables wireless digital communication underwater, where electromagnetic waves cannot propagate usefully.','Autonomous underwater vehicles and sea-floor sensors use acoustic modems to exchange commands and data with ships or other nodes.','Underwater Acoustics & Sonar',ARRAY['Underwater acoustic network','Multipath','Doppler shift','Modulation','Equalization']::text[],ARRAY['Expecting radio-like data rates; the acoustic channel is slow and multipath-limited','Ignoring the long, variable delay from the slow speed of sound','Overlooking Doppler from platform motion that distorts the signal']::text[],ARRAY['Linking an autonomous vehicle to a surface ship','Retrieving data from a sea-floor sensor node','Designing modulation to survive strong multipath']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic modem');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dea074e5-8909-5e56-8d2c-f0a870c6f810','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dea074e5-8909-5e56-8d2c-f0a870c6f810') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dea074e5-8909-5e56-8d2c-f0a870c6f810');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31929484-90a2-5742-ad82-72a1cf6c4cd5','Underwater acoustic network','A set of underwater nodes, including sensors, vehicles, and gateways, linked by acoustic modems into a communicating network, using protocols adapted to long propagation delays, low bandwidth, high error rates, and time-varying connectivity. Such networks provide distributed ocean sensing and control, requiring medium-access and routing schemes designed for the constraints of the underwater acoustic channel.','An underwater acoustic network links many underwater devices by sound. Sensors, robots, and relay nodes pass data to each other. The slow, noisy channel makes this hard. Special rules manage who talks and when. The network spreads sensing across a wide area.','Connects distributed underwater assets for cooperative sensing, monitoring, and control where cabling or radio is impractical.','Ocean-observation systems and vehicle fleets form acoustic networks to relay data from many sensors back to a gateway or ship.','Underwater Acoustics & Sonar',ARRAY['Acoustic modem','Multipath','Medium access control','Doppler shift','Latency']::text[],ARRAY['Applying radio-network protocols directly, ignoring long acoustic delays','Assuming stable links; connectivity varies with the changing channel','Underestimating collisions caused by the long propagation time between nodes']::text[],ARRAY['Relaying data from a field of sensors to a surface gateway','Coordinating a fleet of autonomous vehicles acoustically','Designing access rules for long-delay acoustic links']::text[],'intermediate',NULL,NULL,'a439fbe5-f3ef-4736-a20c-6c2ae3b42678' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Underwater acoustic network');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31929484-90a2-5742-ad82-72a1cf6c4cd5','a439fbe5-f3ef-4736-a20c-6c2ae3b42678',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31929484-90a2-5742-ad82-72a1cf6c4cd5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31929484-90a2-5742-ad82-72a1cf6c4cd5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3eb0dede-dea8-533a-901a-dabe5acb94f1','Computational aeroacoustics','The branch of aeroacoustics that predicts flow-generated sound by numerically solving the governing fluid-dynamic and acoustic equations. It couples computational fluid dynamics for the unsteady turbulent sources with methods for acoustic propagation, typically using high-order, low-dissipation and low-dispersion schemes and non-reflecting boundary conditions to resolve small acoustic fluctuations without corrupting them, or hybrid schemes that pass computed source data to an acoustic analogy such as the Ffowcs Williams-Hawkings equation.','This field uses computers to predict the sound that moving air makes. It solves the math for air flow and sound waves together. Special methods keep the tiny sound waves from being smeared away. Engineers use it to test quiet designs before they build them.','Provides quantitative sound predictions where experiments are costly, hazardous, or impossible, and exposes the flow features responsible for noise so a design can be changed before it is built.','Used to predict jet, fan, wind-turbine, and airframe noise; engineers run a scale-resolving CFD simulation such as LES or DES, then extract the sources on an FW-H surface to compute far-field spectra and directivity.','Aeroacoustics & Flow-Induced Sound',ARRAY['Ffowcs Williams-Hawkings equation','Large-eddy simulation','Acoustic analogy','Lighthill acoustic analogy','Permeable FW-H surface','Direct noise computation']::text[],ARRAY['Using dissipative low-order CFD schemes that smear the acoustic waves before they reach the observer','Placing the FW-H data surface where strong turbulence still crosses it, adding spurious noise','Treating a steady RANS mean field as if it already contained the unsteady sound sources']::text[],ARRAY['Predicting installed jet noise for a new engine before any hardware exists','Assessing wind-turbine trailing-edge noise from a blade simulation','Comparing serrated versus straight trailing edges ahead of a wind-tunnel test']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Computational aeroacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3eb0dede-dea8-533a-901a-dabe5acb94f1','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3eb0dede-dea8-533a-901a-dabe5acb94f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3eb0dede-dea8-533a-901a-dabe5acb94f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b8cc8bc5-1607-567b-9ea3-b0349977cec8','Lighthill acoustic analogy','An exact rearrangement of the compressible continuity and momentum equations, due to Lighthill, into an inhomogeneous wave equation for the density (or pressure) perturbation propagating in a uniform medium at rest, with all nonlinear, convective, and viscous effects collected into a quadrupole source, the Lighthill stress tensor T_ij = rho u_i u_j + (p'' - a0^2 rho'')delta_ij - tau_ij. It recasts sound generation by turbulence as radiation from an equivalent source distribution embedded in a stationary acoustic medium.','Lighthill showed that the sound from turbulence can be found in two steps. First, rewrite the flow equations as a wave equation. All the flow effects become one source term. Then treat that source as if it sat in still air. This lets engineers predict the sound made by moving air.','Separates sound generation (the source) from sound propagation (the wave operator), giving a tractable framework and predicting the famous eighth-power growth of jet noise with jet speed.','Underpins jet-noise scaling laws and hybrid computational aeroacoustics; measured or simulated turbulence statistics feed the stress-tensor source to estimate the radiated far-field sound.','Aeroacoustics & Flow-Induced Sound',ARRAY['Lighthill stress tensor','Acoustic analogy','Turbulent mixing noise','Quadrupole source','Ffowcs Williams-Hawkings equation','Goldstein acoustic analogy']::text[],ARRAY['Believing the analogy is itself an approximation when the rearrangement is mathematically exact','Forgetting that convection and refraction by the real flow are hidden inside the source term','Assuming the source is known independently of the sound field it helps generate']::text[],ARRAY['Deriving the eighth-power jet-noise scaling law','Explaining why heating a jet changes its radiated noise','Building a source model for a hybrid aeroacoustic prediction']::text[],'advanced','d^2rho''/dt^2 - a0^2 nabla^2 rho'' = d^2 T_ij / dx_i dx_j,  T_ij = rho u_i u_j + (p'' - a0^2 rho'')delta_ij - tau_ij','The wave operator acting on the density perturbation equals the double spatial divergence of the Lighthill stress tensor, which combines the momentum flux, the excess pressure, and the viscous stresses.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lighthill acoustic analogy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b8cc8bc5-1607-567b-9ea3-b0349977cec8','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b8cc8bc5-1607-567b-9ea3-b0349977cec8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b8cc8bc5-1607-567b-9ea3-b0349977cec8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1eb439e3-6cb5-5a77-a790-904b297017dd','Powell vortex-sound theory','A reformulation of the acoustic analogy, due to Powell, in which the effective aerodynamic sound source at low Mach number is expressed through the vorticity field, identifying the Lamb vector rho0(omega x u) - the cross product of vorticity and velocity - as the physical agent of sound. The theory shows that, in low-speed flow, sound arises from the unsteady motion, growth, and interaction of vortices, giving a compact and physically interpretable source.','Powell''s theory says that spinning eddies in the air make the sound. It rewrites the sound source using the swirl in the flow. Where swirl moves or changes, sound is produced. This gives a clear picture of what makes flow noise. It works best for slow, low-speed flows.','Gives a physically intuitive source, moving vortices, in place of an abstract stress tensor, aiding understanding and modelling of low-Mach-number flow noise such as edge and cavity tones.','Used to interpret edge tones, whistles, cavity oscillations, and bluff-body sound, and to guide noise control by managing where vortices form, convect, and interact with surfaces.','Aeroacoustics & Flow-Induced Sound',ARRAY['Vortex sound','Lamb vector','Lighthill acoustic analogy','Aeolian tone','Vorticity','Acoustic source term']::text[],ARRAY['Applying the simple vorticity source at high Mach number, where entropy and compressibility terms also matter','Forgetting that it is a low-Mach-number approximation of the full acoustic analogy','Assuming vorticity radiates directly rather than through its unsteady motion near surfaces']::text[],ARRAY['Explaining whistle and edge-tone production','Analysing the sources of cavity resonance','Guiding vortex-based passive noise control']::text[],'advanced','source ~ rho0 div(omega x u);  L = rho0 (omega x u)','The vortex-sound source is proportional to the divergence of the Lamb vector, which is the cross product of the flow vorticity and the flow velocity.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Powell vortex-sound theory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1eb439e3-6cb5-5a77-a790-904b297017dd','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1eb439e3-6cb5-5a77-a790-904b297017dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1eb439e3-6cb5-5a77-a790-904b297017dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '363a31a2-23a3-5c20-b9d8-9254a5745bcb','Goldstein acoustic analogy','A generalized acoustic analogy, due to Goldstein, that extends Lighthill''s approach by rearranging the flow equations about an arbitrary non-uniform, possibly moving base flow rather than a medium at rest. Mean-flow convection and refraction then appear in a linearized propagation operator describing waves travelling through the real mean flow, while the residual fluctuations act as the equivalent sources, improving fidelity for high-speed and heated jets where mean-flow effects are strong.','Goldstein improved Lighthill''s idea for real flows. Lighthill treated the source as sitting in still air. But a jet moves fast, and it bends sound. Goldstein splits the flow into a steady part and a changing part. The steady part carries and bends the sound. The changing part is the source.','Handles convection and refraction by the mean flow correctly, so predictions stay accurate for high-speed and heated jets where those effects are large and cannot be buried in the source.','Basis for modern jet-noise models that use Green''s functions of the mean flow; applied in RANS-based prediction tools that account for refraction and the downstream cone of silence.','Aeroacoustics & Flow-Induced Sound',ARRAY['Lighthill acoustic analogy','Acoustic analogy','Turbulent mixing noise','Ffowcs Williams-Hawkings equation','Acoustic source term','Convective wavepacket']::text[],ARRAY['Assuming it is only a cosmetic relabelling of Lighthill''s equation','Ignoring that the split between source and propagation depends on the chosen base flow','Neglecting mean-flow refraction that the propagation operator is meant to capture']::text[],ARRAY['Predicting heated high-speed jet noise','Building a RANS-based jet-noise tool','Accounting for the downstream cone of silence from refraction']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Goldstein acoustic analogy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '363a31a2-23a3-5c20-b9d8-9254a5745bcb','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='363a31a2-23a3-5c20-b9d8-9254a5745bcb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='363a31a2-23a3-5c20-b9d8-9254a5745bcb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1977bb8a-b594-5941-8ad1-f9f1b948101b','Kirchhoff surface method','An integral method that predicts far-field sound by enclosing all nonlinear source regions within a control surface on which the pressure, its normal derivative, and its time derivative are known from CFD or measurement, then propagating that data to the observer with the linear wave equation via the Kirchhoff integral. It requires the surface to lie in a linear, uniform region where only wave propagation, not sound generation, occurs.','The Kirchhoff method finds far-off sound from data on a chosen surface. The surface wraps around the noisy flow region. On it, engineers record the pressure and how fast it changes. Outside the surface the air is calm, so sound just travels. The method carries that sound to a distant listener.','Extends a near-field CFD result to the far field cheaply, avoiding the enormous grids that computing sound directly out to a distant observer would require.','Used to obtain far-field noise from scale-resolving simulations of jets and rotors; the surface must be placed outside the turbulence in a region of linear wave propagation.','Aeroacoustics & Flow-Induced Sound',ARRAY['Ffowcs Williams-Hawkings equation','Permeable FW-H surface','Computational aeroacoustics','Far-field directivity','Wave equation','Impermeable FW-H surface']::text[],ARRAY['Placing the Kirchhoff surface inside nonlinear or turbulent flow, which violates its core assumption','Confusing it with the FW-H method, which tolerates flow crossing a permeable surface far better','Assuming a poorly placed surface still gives a correct far-field result']::text[],ARRAY['Post-processing a jet simulation to far-field spectra','Helicopter rotor noise prediction','Cross-checking a permeable FW-H result against a Kirchhoff surface']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kirchhoff surface method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1977bb8a-b594-5941-8ad1-f9f1b948101b','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1977bb8a-b594-5941-8ad1-f9f1b948101b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1977bb8a-b594-5941-8ad1-f9f1b948101b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3bab1a19-408c-51f6-b14e-764b484816e2','Permeable FW-H surface','An application of the Ffowcs Williams-Hawkings equation in which the integration surface is a fictitious, porous control surface surrounding the flow rather than the physical body, so fluid may cross it. Flow quantities gathered on this surface capture both the surface (thickness and loading) and the enclosed volume (quadrupole) contributions, allowing the exterior volume integral to be neglected when the surface encloses the significant sources.','This is a way to use the FW-H sound equation with an imaginary surface. The surface wraps around the flow, and air passes through it. Because it surrounds the noisy region, it captures nearly all the sound sources. Then only the surface data is needed to find the far sound.','Captures the volume quadrupole sources through surface data alone, so the costly volume integral can be dropped, while still letting the wake convect through the surface.','The standard far-field method in jet and rotor aeroacoustics; the porous surface sits just outside the strong turbulence, and end-cap averaging suppresses spurious noise from wake crossing.','Aeroacoustics & Flow-Induced Sound',ARRAY['Ffowcs Williams-Hawkings equation','Impermeable FW-H surface','Kirchhoff surface method','Quadrupole source','Computational aeroacoustics','End-cap correction']::text[],ARRAY['Letting strong vortical structures cross the surface without an end-cap or averaging correction, adding spurious noise','Placing the surface so tightly that quadrupole sources leak outside it','Assuming a single surface position gives a converged answer without a sensitivity check']::text[],ARRAY['Extracting far-field jet noise from a large-eddy simulation','Open-rotor noise prediction','Testing the sensitivity of the result to surface placement']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Permeable FW-H surface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3bab1a19-408c-51f6-b14e-764b484816e2','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3bab1a19-408c-51f6-b14e-764b484816e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3bab1a19-408c-51f6-b14e-764b484816e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4149afe5-b3f3-547a-a03c-e9f70ccc0129','Impermeable FW-H surface','The classical Ffowcs Williams-Hawkings formulation in which the data surface coincides with the physical, solid body, so no fluid crosses it. The surface integrals then represent the thickness (monopole) source from the body displacing fluid and the loading (dipole) source from the unsteady surface pressure, while any quadrupole sound from the surrounding volume must be added through a separate volume integral, often neglected at low Mach number.','Here the FW-H surface is the solid body itself. No air passes through it. The surface gives two sound sources. One comes from the body''s shape pushing air aside. The other comes from the changing forces on the body. Sound made by the flow away from the body is left out unless added on its own.','Predicts thickness and loading noise directly from surface pressures on a moving body, the sources that dominate many propeller, rotor, and fan tonal-noise cases.','Standard for propeller, helicopter, and fan tonal noise computed from blade surface pressures; the neglected volume quadrupole limits accuracy for transonic blade tips.','Aeroacoustics & Flow-Induced Sound',ARRAY['Ffowcs Williams-Hawkings equation','Permeable FW-H surface','Loading noise','Thickness noise','Quadrupole source','Blade passing frequency']::text[],ARRAY['Ignoring the volume quadrupole term for transonic blade tips, where it becomes significant','Assuming the solid-surface result captures shock or broadband quadrupole sound','Confusing the impermeable formulation with the permeable one that surrounds the flow']::text[],ARRAY['Propeller tonal noise prediction','Helicopter main-rotor thickness and loading noise','Fan blade-passing-frequency tone prediction']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impermeable FW-H surface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4149afe5-b3f3-547a-a03c-e9f70ccc0129','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4149afe5-b3f3-547a-a03c-e9f70ccc0129') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4149afe5-b3f3-547a-a03c-e9f70ccc0129');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5595d324-7b5b-5dd8-9d94-26085dca3601','Acoustic source term','In an acoustic analogy, the right-hand-side forcing of the wave (or convected wave) operator that represents the equivalent sound-generating mechanism: for example the double divergence of the Lighthill stress tensor (quadrupole), the divergence of unsteady surface loading (dipole), or the time derivative of mass injection (monopole). It encapsulates all the flow physics that produces sound, distinct from the propagation described by the operator on the left-hand side.','An acoustic source term is the part of a sound equation that makes the sound. In an analogy, the equation has two sides. One side describes how sound travels. The other side is the source. The source holds all the flow effects that create noise.','Isolates the generation physics so it can be modelled, computed, or measured apart from propagation, and classified by multipole type as monopole, dipole, or quadrupole.','Extracted from CFD to drive an FW-H or Lighthill prediction; its multipole type tells engineers how the radiated sound should scale with flow speed.','Aeroacoustics & Flow-Induced Sound',ARRAY['Lighthill stress tensor','Quadrupole source','Dipole source','Monopole source','Acoustic analogy','Ffowcs Williams-Hawkings equation']::text[],ARRAY['Confusing the mathematical source term with a real, physically isolated sound source','Assuming it is independent of the flow''s own sound field','Forgetting that different analogies define the source differently']::text[],ARRAY['Classifying jet mixing noise as a quadrupole','Identifying unsteady blade loading as a dipole source','Setting up the source input for a hybrid prediction']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic source term');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5595d324-7b5b-5dd8-9d94-26085dca3601','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5595d324-7b5b-5dd8-9d94-26085dca3601') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5595d324-7b5b-5dd8-9d94-26085dca3601');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96d73255-545d-56ae-93ed-bd3d0d597a93','Turbulent mixing noise','The broadband sound radiated by the unsteady turbulent mixing in a jet''s shear layers, modelled in Lighthill''s analogy as quadrupole radiation from fluctuating Reynolds stresses. For subsonic jets it dominates the low- and mid-frequency spectrum, peaks toward shallow downstream angles because of convective amplification, and its radiated acoustic power scales approximately with the eighth power of jet exit velocity.','Turbulent mixing noise is the roar of a jet. Fast jet air mixes with still air and forms many eddies. These swirling eddies make broadband sound. The mixing sends most of the sound toward the back of the jet. The power grows very fast as the jet speeds up.','Describes the dominant broadband noise of subsonic jets, setting the baseline that exhaust noise-reduction devices such as chevrons are designed to lower.','Governs commercial jet exhaust noise; chevrons and higher-bypass engine cycles cut mixing noise by lowering jet velocity and smoothing the mixing region.','Aeroacoustics & Flow-Induced Sound',ARRAY['Lighthill acoustic analogy','Quadrupole source','Convective amplification','Mach wave radiation','Shear layer','Shock-cell noise']::text[],ARRAY['Assuming it is tonal when it is broadband','Expecting the simple eighth-power scaling to hold for hot or supersonic jets','UNSAFE: Working near a running jet exhaust without hearing protection, where near-field mixing noise can reach hearing-damaging levels']::text[],ARRAY['Predicting takeoff jet roar','Assessing the benefit of a chevron nozzle','Ground engine run-up noise near a test cell']::text[],'intermediate','P ~ rho0 U^8 D^2 / a0^5','The radiated acoustic power grows roughly with the eighth power of jet speed, with the square of nozzle diameter, and inversely with the fifth power of the ambient sound speed.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Turbulent mixing noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96d73255-545d-56ae-93ed-bd3d0d597a93','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96d73255-545d-56ae-93ed-bd3d0d597a93') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96d73255-545d-56ae-93ed-bd3d0d597a93');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0862b37b-6c7e-5f40-824d-de1b6ef061bd','Jet screech','A discrete, high-amplitude tonal component of imperfectly expanded supersonic jet noise generated by a resonant aeroacoustic feedback loop: shear-layer instability waves interact with the quasi-periodic shock-cell structure to radiate sound upstream, which excites new instabilities at the nozzle lip, closing the loop. Screech tones can be intense enough to cause sonic-fatigue damage to nearby structures.','Jet screech is a loud, pure tone from a fast supersonic jet. The jet holds a row of shock cells inside it. Waves along the jet edge hit these shocks and send sound back upstream. That sound starts new waves at the nozzle, and the loop repeats. The tone can be strong enough to crack nearby metal.','Identifies a feedback-driven discrete tone, distinct from broadband noise, whose focused energy can damage structures and therefore must be predicted and suppressed.','Seen on under- or over-expanded military and model supersonic jets; tabs, chevrons, and nozzle changes are used to break the feedback and suppress the tone.','Aeroacoustics & Flow-Induced Sound',ARRAY['Shock-cell noise','Broadband shock-associated noise','Shock cell','Convective Mach number','Feedback loop','Mach wave radiation']::text[],ARRAY['Confusing screech, a discrete tone, with broadband shock-associated noise','Assuming it appears in perfectly expanded jets, when it needs off-design shock cells','UNSAFE: Underestimating screech sonic-fatigue loads, which can fatigue and crack nearby panels and hardware']::text[],ARRAY['Diagnosing a strong tone on a supersonic model jet','Assessing sonic-fatigue risk on an aircraft afterbody','Testing nozzle tabs to eliminate screech']::text[],'advanced','f_s ~ U_c / [s(1 + M_c)]','The screech frequency is about the convection speed of the shear-layer structures divided by the shock-cell spacing times one plus the convective Mach number.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Jet screech');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0862b37b-6c7e-5f40-824d-de1b6ef061bd','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0862b37b-6c7e-5f40-824d-de1b6ef061bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0862b37b-6c7e-5f40-824d-de1b6ef061bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '700524f9-951b-5c1e-bb75-2d5fc0f93ce4','Mach wave radiation','The intense, highly directional sound produced when large-scale turbulent structures in a jet convect at supersonic speed relative to the ambient sound speed, so their phase velocity exceeds a0 and they radiate Mach waves, analogous to a supersonically travelling pressure disturbance. The radiation concentrates near the Mach angle measured from the jet axis and dominates the peak noise of high-speed and heated supersonic jets.','Mach wave radiation is strong, beamed sound from very fast jets. Big waves along the jet edge travel faster than sound in the still air. Like a small sonic boom, they throw sound out at a set angle. This makes the loudest noise of high-speed jets. It points toward the back of the jet.','Explains the dominant, directional peak noise of supersonic and heated jets, a mechanism distinct from ordinary subsonic turbulent mixing noise.','Governs peak noise and crew exposure for fighter and rocket exhausts; predicted with wavepacket models and targeted by nozzle and chevron designs that slow the eddy convection.','Aeroacoustics & Flow-Induced Sound',ARRAY['Convective Mach number','Convective wavepacket','Turbulent mixing noise','Convective amplification','Acoustic wavepacket','Jet screech']::text[],ARRAY['Assuming all jet noise is omnidirectional','Confusing Mach wave radiation with shock-cell or screech noise','UNSAFE: Approaching a supersonic or rocket exhaust, where Mach-wave noise reaches extreme levels requiring strict hearing protection and stand-off distance']::text[],ARRAY['Fighter-jet takeoff peak noise','Rocket-launch acoustic environment','Predicting directivity of a heated supersonic jet']::text[],'advanced','cos(theta_M) ~ a0 / U_c = 1 / M_c  (U_c > a0)','The cosine of the Mach-wave angle from the jet axis equals the ambient sound speed divided by the eddy convection speed, valid when the eddies move supersonically.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mach wave radiation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '700524f9-951b-5c1e-bb75-2d5fc0f93ce4','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='700524f9-951b-5c1e-bb75-2d5fc0f93ce4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='700524f9-951b-5c1e-bb75-2d5fc0f93ce4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ad28da58-432d-5ad2-9b68-f2d8696c497b','Shock-cell noise','The broadband shock-associated noise of imperfectly expanded supersonic jets, produced when turbulent structures in the shear layer convect through and scatter off the quasi-periodic shock-cell structure. Unlike screech, which is its discrete tonal counterpart, it is broadband, and its spectral peak frequency shifts with observation angle and rises with the degree of off-design shock strength.','Shock-cell noise comes from fast jets that are not perfectly expanded. Such jets hold a repeating pattern of shocks inside. Eddies along the jet edge pass through these shocks and scatter sound. The sound is broadband, not a single tone. Its pitch changes with listening angle.','Characterizes the broadband part of off-design supersonic jet noise, important for community noise and for unsteady loading on the aircraft afterbody.','Present on over- or under-expanded cruise nozzles and military jets; reduced by improving nozzle expansion matching and by chevrons that weaken the shock cells.','Aeroacoustics & Flow-Induced Sound',ARRAY['Jet screech','Broadband shock-associated noise','Shock cell','Convective Mach number','Turbulent mixing noise','Mach wave radiation']::text[],ARRAY['Confusing broadband shock-cell noise with tonal screech','Assuming perfectly expanded jets produce it, when it needs off-design shocks','Ignoring the angle dependence of its spectral peak frequency']::text[],ARRAY['Predicting cruise noise of a non-ideally-expanded nozzle','Separating shock noise from mixing noise in a measured spectrum','Assessing afterbody unsteady loading']::text[],'advanced','f_p ~ U_c / [L_s (1 + M_c cos(theta))]','The broadband shock-noise peak frequency is about the eddy convection speed divided by the shock-cell spacing times one plus the convective Mach number times the cosine of the observer angle.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shock-cell noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ad28da58-432d-5ad2-9b68-f2d8696c497b','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ad28da58-432d-5ad2-9b68-f2d8696c497b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ad28da58-432d-5ad2-9b68-f2d8696c497b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86190402-024e-56b4-b9a7-63d8c0c3d533','Buzz-saw noise','Multiple-pure-tone noise radiated forward from a transonic fan or propfan when the relative flow over the blade tips is supersonic, producing a system of shock waves attached to the blades. Small blade-to-blade geometric differences make the shocks unequal, so the rotating shock pattern radiates a rich set of tones at harmonics of the shaft rotation frequency, not only at blade passing frequency, heard as a rasping buzz-saw sound at takeoff.','Buzz-saw noise is a rasping sound from a jet engine fan at takeoff. The fan blade tips move faster than sound. Each blade makes a small shock wave. The blades are never exactly alike, so the shocks differ. The spinning, uneven shocks make many tones. Together they sound like a buzz saw.','Explains forward-radiated transonic fan tones that fall at shaft-order harmonics and dominate inlet noise at takeoff, guiding inlet liner and blade design.','Heard from high-bypass turbofan inlets at takeoff; controlled with acoustic inlet liners and careful blade tip geometry and matching.','Aeroacoustics & Flow-Induced Sound',ARRAY['Multiple pure tones','Blade passing frequency','Rotor-alone noise','Fan interaction tone','Shock wave','Transonic fan']::text[],ARRAY['Assuming the tones fall only at blade-passing harmonics, when they occur at shaft-order harmonics','Thinking it needs a downstream stator, when it is a rotor-alone shock phenomenon','Confusing the rasp of buzz-saw noise with a single fan tone']::text[],ARRAY['Turbofan inlet noise at takeoff','Designing an inlet liner for multiple pure tones','Explaining shaft-order tones in an inlet spectrum']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Buzz-saw noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86190402-024e-56b4-b9a7-63d8c0c3d533','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86190402-024e-56b4-b9a7-63d8c0c3d533') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86190402-024e-56b4-b9a7-63d8c0c3d533');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '750fa991-730d-5815-b182-d64525f7d82c','Fan interaction tone','A discrete tone from a ducted fan stage generated by aerodynamic interaction between the rotor and neighbouring stationary components such as stators, struts, or a distorted inlet, as opposed to the rotor acting alone. Rotor wakes and potential fields impinging on the vanes produce unsteady blade loading whose spinning pressure pattern radiates tones at harmonics of blade passing frequency, with duct cut-on governed by the Tyler-Sofrin mode orders.','A fan interaction tone is a pure tone from a ducted engine fan. The spinning fan blades leave wakes in the air. These wakes hit the still vanes behind the fan. The hits make changing forces that create sound. The tone rings at multiples of the blade passing rate.','Identifies the main tonal noise source of a fan stage due to rotor interaction with stators or inlet distortion, central to vane-count and duct-mode design choices.','Dominates fan tonal noise in turbofans; rotor-blade and stator-vane counts are chosen so the interaction modes are cut off inside the duct.','Aeroacoustics & Flow-Induced Sound',ARRAY['Rotor-stator interaction tone','Blade passing frequency','Tyler-Sofrin modes','Rotor-alone noise','Cut-on frequency','Duct mode']::text[],ARRAY['Confusing interaction tones with rotor-alone tones','Assuming any vane count works, ignoring Tyler-Sofrin mode cut-on','Forgetting inlet distortion can also drive interaction tones']::text[],ARRAY['Reducing a turbofan fan tone','Choosing rotor and stator counts','Diagnosing blade-passing harmonics in engine test data']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fan interaction tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '750fa991-730d-5815-b182-d64525f7d82c','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='750fa991-730d-5815-b182-d64525f7d82c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='750fa991-730d-5815-b182-d64525f7d82c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'acaab273-5ace-581a-8211-2737200a45cf','Rotor-alone noise','The tonal noise a rotor, fan, or propeller would radiate in perfectly uniform, steady inflow, produced by the steady blade thickness and steady blade loading rotating with the blades. It appears at blade passing frequency and its harmonics; because the sources are steady in the blade frame, in a uniform duct these tones are often weak or cut off, but at transonic tip speeds the blade shocks make the radiation strong, giving buzz-saw noise.','Rotor-alone noise is the tone a fan makes in perfectly smooth air. Each blade pushes air by its shape and its lift. As the blades spin, this makes a tone. The tone rings at the blade passing rate and its multiples. In smooth flow it is often weak, unless the tips go supersonic.','Isolates the tonal noise due to the rotor by itself, separating it from the interaction tones caused by other components in the stage.','The baseline propeller and fan tone; propeller blade-passing harmonics come from steady loading and thickness, and the radiation turns strong at transonic tips.','Aeroacoustics & Flow-Induced Sound',ARRAY['Blade passing frequency','Thickness noise','Loading noise','Buzz-saw noise','Fan interaction tone','Rotor-stator interaction tone']::text[],ARRAY['Confusing rotor-alone tones with interaction tones','Assuming they are always strong, when steady sources in a uniform duct are often cut off','Forgetting that transonic tips change the picture entirely']::text[],ARRAY['Propeller blade-passing tone prediction','Separating rotor-alone from interaction tones','Explaining why a fan tone is weak in clean inflow']::text[],'intermediate','BPF = B * N / 60','The blade passing frequency in hertz equals the number of blades times the shaft speed in revolutions per minute divided by sixty.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rotor-alone noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'acaab273-5ace-581a-8211-2737200a45cf','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='acaab273-5ace-581a-8211-2737200a45cf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='acaab273-5ace-581a-8211-2737200a45cf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7fcf8ff-f856-5953-b854-5036feb0fba3','Rotor-stator interaction tone','A fan or compressor tone produced when the viscous wakes and potential field of the upstream rotor sweep past the downstream stator vanes (or vice versa), imposing periodic unsteady loading on the vanes that radiates sound at harmonics of blade passing frequency. The circumferential spinning mode orders excited follow the Tyler-Sofrin relation, and whether each mode propagates in the duct depends on acoustic cut-on.','This tone comes from a fan''s spinning blades and its still vanes. The blades leave wakes that strike the vanes. Each strike changes the force on a vane, making sound. The pattern spins around the duct. Only some spinning patterns can travel out; the rest die away.','Explains the dominant tonal mechanism in fans and compressors and, through the Tyler-Sofrin relation, how blade and vane counts control which modes radiate.','Central to turbofan fan-tone design; engineers pick blade and vane counts so the loudest interaction modes are cut off inside the duct.','Aeroacoustics & Flow-Induced Sound',ARRAY['Tyler-Sofrin modes','Fan interaction tone','Blade passing frequency','Duct mode','Cut-on frequency','Rotor-alone noise']::text[],ARRAY['Assuming tones occur at blade passing frequency regardless of vane count','Ignoring that mode cut-on decides whether a mode radiates','Swapping the blade and vane counts in the Tyler-Sofrin relation']::text[],ARRAY['Selecting a vane count to cut off the blade-passing mode','Diagnosing a strong fan tone','Compressor tone analysis']::text[],'advanced','m = nB - sV','The spinning circumferential mode order equals the harmonic number times the rotor-blade count minus any integer times the stator-vane count.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rotor-stator interaction tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7fcf8ff-f856-5953-b854-5036feb0fba3','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7fcf8ff-f856-5953-b854-5036feb0fba3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7fcf8ff-f856-5953-b854-5036feb0fba3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47dffb96-8aca-542b-80b8-9933cf0711c2','Tip-clearance noise','Broadband, and sometimes tonal, noise generated in the gap between a rotor blade tip and the surrounding casing or shroud, where the pressure difference across the blade drives a leakage flow that rolls up into a tip-clearance vortex and interacts with the blade tip, the casing boundary layer, and downstream blades. Larger clearances generally increase both the unsteadiness of the leakage flow and the associated noise.','Tip-clearance noise comes from the small gap at a fan blade''s tip. Air leaks through the gap because the two sides have different pressure. The leak rolls into a swirling flow near the tip. This unsteady flow makes noise. A bigger gap usually makes more noise.','Identifies a casing-gap noise source in fans, compressors, and turbines that couples aerodynamic loss with an acoustic penalty, informing clearance control.','Relevant to ducted fans, cooling and HVAC fans, and turbomachinery; tighter, well-controlled clearances and casing treatments reduce it.','Aeroacoustics & Flow-Induced Sound',ARRAY['Tip-leakage vortex noise','Casing treatment','Broadband fan noise','Blade tip','Turbulent inflow noise','Trailing-vortex noise']::text[],ARRAY['Confusing tip-clearance noise with blade trailing-edge noise','Assuming zero clearance is achievable or always best, ignoring the rubbing risk','Overlooking the casing boundary-layer interaction']::text[],ARRAY['Reducing cooling-fan noise','Turbofan tip-gap design','Diagnosing a broadband hump from the blade-tip region']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tip-clearance noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47dffb96-8aca-542b-80b8-9933cf0711c2','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47dffb96-8aca-542b-80b8-9933cf0711c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47dffb96-8aca-542b-80b8-9933cf0711c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c6d1ff2-ae1d-5e65-a0d5-b618c3bb23c9','Tip-leakage vortex noise','Noise produced by the tip-leakage vortex - the concentrated streamwise vortex formed as flow leaks across a blade tip gap under the blade loading - through its own unsteadiness and its interaction with the blade surface, the casing, and following blades. It is a specific and often dominant contributor to tip-region broadband noise, with a signature that depends on gap size, blade loading, and the vortex trajectory.','This noise comes from a swirling tube of air at a blade tip. Air leaking over the tip rolls up into this spinning vortex. The vortex wobbles and brushes the blade and casing. That makes broadband noise. Its strength depends on the gap and the blade''s load.','Pins the tip-region broadband source to the leakage vortex specifically, guiding tip and casing design to weaken or steer that vortex.','Studied in fans, pumps, and turbines with scale-resolving simulation and PIV; grooved casings, tip winglets, and gap control mitigate it.','Aeroacoustics & Flow-Induced Sound',ARRAY['Tip-clearance noise','Casing treatment','Trailing-vortex noise','Broadband fan noise','Vortex sound','Blade tip']::text[],ARRAY['Treating tip-leakage vortex noise as identical to overall tip-clearance noise, when it is one component','Ignoring how the vortex path over adjacent blades affects the noise','Assuming a small gap removes it entirely']::text[],ARRAY['Axial-fan broadband noise study','Linking pump tip-vortex cavitation to noise','Casing-groove design to control the leakage vortex']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tip-leakage vortex noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c6d1ff2-ae1d-5e65-a0d5-b618c3bb23c9','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c6d1ff2-ae1d-5e65-a0d5-b618c3bb23c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c6d1ff2-ae1d-5e65-a0d5-b618c3bb23c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a046643d-63a1-5004-91c5-5c7191a4a814','Trailing-vortex noise','Sound associated with the trailing tip vortices shed from lifting surfaces such as wings, blades, and rotors, arising from the unsteadiness of the rolled-up vortex sheet and, more importantly, from the interaction of these vortices with downstream surfaces (blade-vortex interaction) or with turbulence. An isolated, steady trailing vortex radiates little; the noise grows sharply when the vortex is unsteady or impinges on a surface.','Trailing-vortex noise comes from the swirling air left behind a wing or blade tip. A lifting wing sheds a spinning vortex at each tip. On its own this vortex is fairly quiet. It gets loud when it wobbles or hits another blade. Helicopter blade-vortex hits are a well-known case.','Links lift-generated tip vortices to noise, chiefly through impingement such as blade-vortex interaction, guiding rotor spacing and blade-tip design.','Central to helicopter blade-vortex interaction slap on approach; also seen on fans and propellers where a tip vortex strikes a following blade.','Aeroacoustics & Flow-Induced Sound',ARRAY['Blade-vortex interaction','Tip-leakage vortex noise','Trailing-edge noise','Vortex sound','Tip vortex','Turbulent wake noise']::text[],ARRAY['Expecting a steady, isolated tip vortex to be loud, when it is not','Confusing trailing-vortex or blade-vortex noise with trailing-edge noise','Ignoring impingement as the main amplifier of the noise']::text[],ARRAY['Helicopter blade-vortex interaction slap on approach','Propeller tip-vortex interaction with a following blade','Wind-turbine tip-vortex noise']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Trailing-vortex noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a046643d-63a1-5004-91c5-5c7191a4a814','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a046643d-63a1-5004-91c5-5c7191a4a814') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a046643d-63a1-5004-91c5-5c7191a4a814');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0555d663-c1cd-50e7-bf5a-898cee7dd00b','Leading-edge interaction noise','Broadband noise generated when turbulence in the oncoming flow, such as atmospheric turbulence, an upstream wake, or an ingested boundary layer, is chopped by the leading edge of an airfoil or blade, producing unsteady leading-edge loading that radiates as a dipole. Also called turbulence-airfoil interaction or inflow-turbulence noise, it is well described by Amiet''s theory and typically dominates the low-to-mid-frequency range for blades in turbulent inflow.','This noise happens when rough, swirling air meets the front edge of a wing or blade. The gusts hit the sharp edge and change the lift quickly. These fast lift changes make broadband sound. It is loudest at low and middle pitches. Fans and turbines in gusty air show it.','Identifies the front-edge dipole source driven by inflow turbulence, key to predicting fan, propeller, and wind-turbine broadband noise.','Predicted with Amiet''s model from the inflow turbulence spectrum; wavy or serrated leading edges are used to reduce it.','Aeroacoustics & Flow-Induced Sound',ARRAY['Turbulent inflow noise','Trailing-edge noise','Amiet''s theory','Dipole source','Gust response','Broadband fan noise']::text[],ARRAY['Confusing leading-edge inflow noise with trailing-edge self-noise','Assuming it is tonal when it is broadband','Forgetting that an inflow turbulence spectrum is needed to predict it']::text[],ARRAY['Wind-turbine noise in atmospheric turbulence','Fan rotor ingesting inlet turbulence','Front blade of a contra-rotating propeller in a wake']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Leading-edge interaction noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0555d663-c1cd-50e7-bf5a-898cee7dd00b','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0555d663-c1cd-50e7-bf5a-898cee7dd00b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0555d663-c1cd-50e7-bf5a-898cee7dd00b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '954116ef-c579-518c-bf75-fd031862b871','Boundary-layer ingestion noise','The noise arising when a propulsor is deliberately embedded to ingest the fuselage or airframe boundary layer, so its rotor operates in a thick, distorted, turbulent, and circumferentially non-uniform inflow. The distortion produces extra tonal noise from the periodic inflow non-uniformity, which excites additional circumferential modes, and elevated broadband noise from the ingested turbulence, trading propulsive efficiency against an acoustic penalty.','Boundary-layer ingestion noise comes from a fan built into an aircraft body. The fan sucks in the slow, rough air along the surface. This air is uneven around the fan and full of eddies. The uneven flow adds tones, and the eddies add broadband noise. It saves fuel but can be louder.','Characterizes the acoustic penalty of boundary-layer-ingesting propulsion concepts, needed to weigh their fuel savings against noise in novel airframes.','Studied for blended-wing-body and embedded-engine designs, using distortion-tolerant rotor design and measured inflow distortion.','Aeroacoustics & Flow-Induced Sound',ARRAY['Turbulent inflow noise','Fan interaction tone','Leading-edge interaction noise','Tyler-Sofrin modes','Broadband fan noise','Inflow distortion']::text[],ARRAY['Assuming boundary-layer ingestion changes only efficiency, not noise','Ignoring the extra tonal modes from circumferential distortion','Treating the ingested inflow as clean and uniform']::text[],ARRAY['Assessing a blended-wing-body propulsor''s noise','Embedded-fan distortion-tone study','Trading efficiency against noise in a new airframe']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary-layer ingestion noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '954116ef-c579-518c-bf75-fd031862b871','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='954116ef-c579-518c-bf75-fd031862b871') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='954116ef-c579-518c-bf75-fd031862b871');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '83d05fe7-6556-53b8-b892-ed6ec4513d6a','Turbulent inflow noise','Broadband noise produced when a body or blade encounters turbulence in its oncoming flow, so unsteady surface loading is generated by the impinging velocity fluctuations; for an airfoil this is the leading-edge turbulence-interaction noise. Its level and spectrum depend on the inflow turbulence intensity, integral length scale, and spectral shape, and on the airfoil response, which is aerodynamically compact at low frequency and non-compact at high frequency.','Turbulent inflow noise happens when a blade meets gusty, swirling air. The gusts push and pull on the blade surface. These changing forces make broadband sound. Rougher, larger gusts make more noise. It is common for fans and rotors in real, unsteady air.','Names the general class of noise from ingested turbulence, the input for leading-edge interaction models across fans, rotors, and wind turbines.','Drives fan and wind-turbine broadband noise from atmospheric or duct turbulence; measured inflow spectra feed Amiet-type predictions.','Aeroacoustics & Flow-Induced Sound',ARRAY['Leading-edge interaction noise','Amiet''s theory','Broadband fan noise','Gust response','Boundary-layer ingestion noise','Inflow distortion']::text[],ARRAY['Confusing inflow leading-edge noise with trailing-edge self-noise','Assuming a blade in clean flow has none','Ignoring how the turbulence length scale shapes the spectrum']::text[],ARRAY['Wind-turbine noise in turbulent wind','Cooling fan in a turbulent ducted inflow','Rotor ingesting an upstream wake']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Turbulent inflow noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '83d05fe7-6556-53b8-b892-ed6ec4513d6a','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='83d05fe7-6556-53b8-b892-ed6ec4513d6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='83d05fe7-6556-53b8-b892-ed6ec4513d6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b829d8c7-4c66-5e5c-bdd0-3150532468a6','Airframe noise','The non-propulsive aerodynamic noise generated by an aircraft''s airframe in flight, produced by the interaction of the airflow with the wings, high-lift devices such as slats and flaps, the landing gear, cavities, and the turbulent boundary layer. It becomes the dominant aircraft noise source on approach, when the engines run at low power and the high-lift system and gear are deployed, and it sets a floor on how quiet an aircraft can be made.','Airframe noise is the sound an aircraft body makes as it flies. It does not come from the engines. It comes from air rushing over the wings, flaps, slats, and landing gear. It is loudest on landing, when the engines are quiet and the gear is down. It limits how quiet a plane can be.','Defines the engine-independent noise floor of an aircraft, driving high-lift and landing-gear noise research for quieter approaches.','Measured in flyover and wind-tunnel tests; addressed with slat and flap-edge treatments, gear fairings, and porous edges.','Aeroacoustics & Flow-Induced Sound',ARRAY['Landing-gear noise','Slat noise','Flap side-edge noise','Trailing-edge noise','High-lift device','Approach noise']::text[],ARRAY['Assuming the engines are always the loudest source, when airframe noise dominates on approach','Treating airframe noise as one source rather than several distinct ones','Ignoring the effect of deploying gear and high-lift devices']::text[],ARRAY['Approach-noise certification','High-lift wind-tunnel noise test','Assessing the benefit of a landing-gear fairing']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Airframe noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b829d8c7-4c66-5e5c-bdd0-3150532468a6','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b829d8c7-4c66-5e5c-bdd0-3150532468a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b829d8c7-4c66-5e5c-bdd0-3150532468a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b08a1128-7f82-5fed-ab74-389986c2c941','Landing-gear noise','A major airframe-noise component produced by the highly separated, unsteady flow around the bluff, geometrically complex landing-gear assembly of wheels, struts, axles, dressings, and cavities. It is predominantly broadband, generated by turbulent wakes and shear layers shed from the many bluff elements and their mutual interaction, with some tonal content from cavities and small cylindrical members, and it is a leading approach-noise source on large aircraft.','Landing-gear noise is the broadband roar from a plane''s wheels and struts when the gear is down. The gear is a bluff, boxy shape with many parts. Air breaks into eddies around each part. These eddies make broadband noise. On big jets it is one of the loudest sounds on landing.','Identifies a dominant approach-noise source and the target for fairings, mesh screens, and gear-geometry noise treatments.','Studied in wind tunnels and flyovers; add-on fairings, wheel-hub caps, and flow deflectors reduce it.','Aeroacoustics & Flow-Induced Sound',ARRAY['Airframe noise','Bluff-body noise','Cavity noise','Approach noise','Turbulent wake noise','Trailing-vortex noise']::text[],ARRAY['Treating gear noise as purely tonal, when it is mostly broadband','Ignoring the flow interaction between neighbouring components','Assuming a single simple fairing removes all of it']::text[],ARRAY['Approach-noise reduction program','Landing-gear fairing wind-tunnel test','Ranking component noise on a landing aircraft']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Landing-gear noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b08a1128-7f82-5fed-ab74-389986c2c941','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b08a1128-7f82-5fed-ab74-389986c2c941') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b08a1128-7f82-5fed-ab74-389986c2c941');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48166b21-bf3e-58c6-a931-e15618844448','Slat noise','An airframe-noise source generated by the deployed leading-edge slat of a high-lift system, dominated by the unsteady flow in the slat cove: the shear layer separating from the slat cusp reattaches near the trailing edge, producing broadband noise plus narrowband or tonal components from cove shear-layer feedback resonance, together with slat trailing-edge and gap-flow noise. It is a principal mid-to-high-frequency airframe source on approach.','Slat noise comes from the small wing part at the front edge, used for landing. Behind the slat is a hollow called the cove. Air separates there and forms an unsteady shear layer. It makes broadband noise and some tones. On approach it is a main source of higher-pitched airframe noise.','Pinpoints the high-lift leading-edge source, guiding cove fillers, seals, and slat-edge treatments for quieter approach.','Studied with high-lift models and aeroacoustic simulation; cove fillers and slat-gap seals reduce broadband and tonal slat noise.','Aeroacoustics & Flow-Induced Sound',ARRAY['Airframe noise','Flap side-edge noise','High-lift device','Cavity noise','Trailing-edge noise','Shear layer']::text[],ARRAY['Assuming slat noise is only broadband, when it also has cove-resonance tones','Ignoring the cove shear layer as the main source','Confusing leading-edge slat noise with trailing-edge flap noise']::text[],ARRAY['High-lift approach-noise test','Cove-filler design','Separating slat noise from flap noise in a spectrum']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slat noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48166b21-bf3e-58c6-a931-e15618844448','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48166b21-bf3e-58c6-a931-e15618844448') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48166b21-bf3e-58c6-a931-e15618844448');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b320fd05-fac0-5b59-8103-8a0128a14a08','Flap side-edge noise','An airframe-noise source produced at the side (lateral) edge of a deployed trailing-edge flap, where the pressure difference between the flap''s suction and pressure sides drives flow around the edge, forming a strong, unsteady side-edge vortex system. The unsteady vortices and their interaction with the flap surface and edge radiate broadband noise, with some tonal features, making the flap side edge a dominant low-to-mid-frequency airframe source on approach.','Flap side-edge noise comes from the outer end of a landing flap. The two sides of the flap have different pressure. Air curls around the side edge and forms a spinning vortex. This unsteady vortex makes broadband noise. It is a main airframe source when a plane lands.','Identifies the flap-edge vortex source, guiding edge fences, porous edges, and continuous-moldline treatments to cut approach noise.','Studied with high-lift models and flow-field measurement; porous or rounded flap edges and edge fences reduce the side-edge noise.','Aeroacoustics & Flow-Induced Sound',ARRAY['Airframe noise','Slat noise','Trailing-edge noise','Trailing-vortex noise','High-lift device','Vortex sound']::text[],ARRAY['Confusing flap side-edge noise with flap trailing-edge noise','Ignoring the dual-vortex structure that forms at the edge','Assuming a sharp edge is always quietest']::text[],ARRAY['High-lift approach-noise test','Porous flap-edge design','Localizing airframe sources with a microphone array']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flap side-edge noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b320fd05-fac0-5b59-8103-8a0128a14a08','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b320fd05-fac0-5b59-8103-8a0128a14a08') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b320fd05-fac0-5b59-8103-8a0128a14a08');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1d4171d7-dbec-5956-b36a-a453af407943','Rossiter mode','A resonant mode of open-cavity flow oscillation, described by Rossiter''s semi-empirical model, in which a self-sustaining feedback loop couples shear-layer instabilities across the cavity mouth with acoustic waves: vortices shed at the leading edge convect downstream, impinge on the trailing edge, and radiate acoustic waves that travel upstream to trigger new shedding. The discrete resonant frequencies are indexed by an integer mode number.','A Rossiter mode is a tone made by air flowing over an open cavity. Eddies form at the front edge and drift to the back edge. When they hit the back, they send sound waves upstream. Those waves start new eddies at the front, and the loop repeats. This makes tones at set pitches.','Predicts cavity resonance tones so engineers can anticipate and suppress intense, potentially damaging cavity oscillations.','Predicts weapons-bay and landing-gear-bay tones; addressed with leading-edge spoilers, rods, and ramps that disrupt the shear layer.','Aeroacoustics & Flow-Induced Sound',ARRAY['Cavity noise','Shear layer','Feedback loop','Strouhal number','Aeolian tone lock-in','Separated-flow noise']::text[],ARRAY['Using Rossiter''s empirical constants outside their calibrated range','Ignoring coupling with depth-mode acoustic resonance','UNSAFE: Ignoring cavity resonance acoustic loads, which can fatigue bay structure and stored equipment']::text[],ARRAY['Weapons-bay tone prediction','Landing-gear-bay resonance','Testing a leading-edge spoiler to suppress cavity tones']::text[],'advanced','St_m = f_m L / U = (m - alpha) / (M + 1/kappa)','The Rossiter Strouhal number for mode m equals the mode number minus a phase constant, divided by the Mach number plus the inverse of the vortex convection ratio.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rossiter mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1d4171d7-dbec-5956-b36a-a453af407943','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1d4171d7-dbec-5956-b36a-a453af407943') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1d4171d7-dbec-5956-b36a-a453af407943');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66055017-0ed9-5cd2-8d51-a8774b40a28f','Aeolian tone lock-in','The phenomenon in which the vortex-shedding frequency behind a bluff body, the source of the Aeolian tone, synchronizes to and is captured by a nearby resonance - a structural natural frequency of an elastically vibrating body or an acoustic resonance - over a finite range of flow speeds, instead of following the linear Strouhal relation. During lock-in the shedding locks to the resonant frequency, the vortex strength and spanwise coherence increase, and the tone amplifies.','Lock-in happens when a wind tone grabs onto a resonance. Air past a wire or pipe sheds eddies at a set rate. Normally this rate rises with wind speed. But if it nears a natural frequency, it locks to it. Over a speed range the tone stays fixed and grows louder.','Explains why Aeolian tones can grow strong and why flow-induced vibration can become self-sustaining and damaging near a resonance.','Governs singing wires, chimney and heat-exchanger tube vibration, and structural fatigue; countered with helical strakes, spoilers, and detuning.','Aeroacoustics & Flow-Induced Sound',ARRAY['Aeolian tone','Vortex shedding','Strouhal tone','Vortex-induced vibration','Strouhal number','Aeroelastic-acoustic coupling']::text[],ARRAY['Assuming the Strouhal relation still holds through lock-in','Ignoring the amplified spanwise coherence of the shedding','UNSAFE: Overlooking lock-in vortex-induced vibration, where sustained resonant shedding can fatigue and fail stacks, cables, and tubes']::text[],ARRAY['Chimney-stack vortex-induced vibration','Heat-exchanger tube-bundle resonance','Assessing a singing power line or cable']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aeolian tone lock-in');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66055017-0ed9-5cd2-8d51-a8774b40a28f','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66055017-0ed9-5cd2-8d51-a8774b40a28f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66055017-0ed9-5cd2-8d51-a8774b40a28f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '58776ea9-f00f-509f-9caa-19eefef17cc3','Strouhal tone','The discrete tone radiated by periodic vortex shedding from a bluff body in cross-flow, such as a cylinder, whose frequency is set by the Strouhal number, a dimensionless similarity parameter relating the shedding frequency, a characteristic cross-stream dimension, and the flow speed. For a circular cylinder over a wide subcritical Reynolds-number range the Strouhal number is close to 0.2, and the radiated sound is the Aeolian tone.','A Strouhal tone is the whistle made by air flowing past a bluff object. The flow sheds eddies from each side in turn. This regular shedding sets the pitch of the tone. A number called the Strouhal number links pitch, size, and speed. For a round rod it is about 0.2.','Provides the scaling law that predicts shedding-tone frequency from body size and flow speed, the basis of Aeolian-tone and flow-induced-vibration analysis.','Predicts tones from wires, masts, tubes, and struts; used to set flow speeds in tests and to design structures away from resonance.','Aeroacoustics & Flow-Induced Sound',ARRAY['Aeolian tone','Vortex shedding','Strouhal number','Aeolian tone lock-in','Turbulent wake noise','Vortex-induced vibration']::text[],ARRAY['Assuming the Strouhal number is exactly 0.2 for all bodies and Reynolds numbers','Ignoring the drop and scatter in the critical Reynolds-number range','Confusing the discrete shedding tone with broadband wake noise']::text[],ARRAY['Predicting a wire''s singing frequency','Sizing a strut to avoid a resonance','Setting tunnel speed to reach a target shedding frequency']::text[],'intermediate','St = f d / U  (cylinder: St ~ 0.2)','The Strouhal number equals the shedding frequency times the body''s cross-stream size divided by the flow speed; for a cylinder it is near 0.2.','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Strouhal tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '58776ea9-f00f-509f-9caa-19eefef17cc3','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='58776ea9-f00f-509f-9caa-19eefef17cc3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='58776ea9-f00f-509f-9caa-19eefef17cc3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bc273af2-32ca-5204-bedd-1adaa42f8600','Acoustic pressure fluctuation','The small, propagating perturbation in fluid pressure about the local mean that constitutes sound, satisfying to leading order the wave equation and carrying energy to the far field at the speed of sound. In aeroacoustics it is distinguished from the much larger, non-propagating hydrodynamic (pseudo-sound) pressure fluctuations within a turbulent flow, which decay rapidly with distance and do not radiate.','An acoustic pressure fluctuation is a tiny change in air pressure that we hear as sound. It rides outward as a wave at the speed of sound. It carries energy to far places. In a flow it is much smaller than the pushing and pulling inside the turbulence. Only the true sound part travels far.','Defines the radiating pressure that microphones and the far field register, separating genuine sound from the local flow pressure.','What far-field microphones measure; in a simulation it must be separated from hydrodynamic pressure to extract the radiated noise.','Aeroacoustics & Flow-Induced Sound',ARRAY['Pseudo-sound','Sound pressure level','Acoustic wavepacket','Far-field directivity','Wave equation','Turbulent mixing noise']::text[],ARRAY['Treating every pressure fluctuation in a flow as sound','Forgetting the acoustic part is far smaller than the hydrodynamic part near the flow','Ignoring the far-field decay of amplitude with distance']::text[],ARRAY['Extracting radiated noise from a jet near-field simulation','Interpreting a near-field microphone that senses pseudo-sound','Far-field sound pressure level measurement']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic pressure fluctuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bc273af2-32ca-5204-bedd-1adaa42f8600','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bc273af2-32ca-5204-bedd-1adaa42f8600') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bc273af2-32ca-5204-bedd-1adaa42f8600');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e521eda-5523-53ee-b917-4ccd096d478a','Pseudo-sound','The non-propagating, hydrodynamic pressure fluctuations carried within a turbulent or unsteady flow, such as the convecting pressure field of turbulent eddies, which are not sound because they do not satisfy the wave equation and decay rapidly, typically much faster than the inverse-distance law, away from the flow. Pseudo-sound generally dominates the near-field pressure and must be distinguished from the far smaller radiating acoustic component.','Pseudo-sound is pressure that feels like sound but does not travel. It is the pushing and pulling inside turbulent air. It stays with the flow and fades fast with distance. It is not a true sound wave. Near a flow it is much stronger than the real sound.','Names the large near-field hydrodynamic pressure so it is not mistaken for radiated sound in measurements and simulations.','Explains why a near-field microphone in a jet or duct reads high levels that do not reach the far field; separated from sound by wavenumber and phase-speed filtering.','Aeroacoustics & Flow-Induced Sound',ARRAY['Acoustic pressure fluctuation','Convective wavepacket','Turbulent mixing noise','Near-field','Wavenumber filtering','Sound pressure level']::text[],ARRAY['Reporting near-field pseudo-sound levels as radiated noise','Assuming a pressure sensor in the flow measures sound','Ignoring its fast decay away from the flow']::text[],ARRAY['Interpreting in-flow pressure probes','Separating hydrodynamic from acoustic pressure in a jet','Wind noise on an outdoor microphone']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pseudo-sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e521eda-5523-53ee-b917-4ccd096d478a','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e521eda-5523-53ee-b917-4ccd096d478a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e521eda-5523-53ee-b917-4ccd096d478a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0f24adff-df4f-5f5c-8ab9-12ac04a94894','Convective wavepacket','A spatially and temporally coherent, wavelike disturbance in a turbulent shear flow, notably a jet, whose envelope grows and then decays as it convects downstream at a fraction of the flow speed, representing the large-scale coherent structures (instability waves) of the flow. Its convective, subsonic part is largely hydrodynamic pseudo-sound, but its coherent, low-wavenumber tail is an efficient radiator, making wavepackets a leading model for jet-noise sources.','A convective wavepacket is an orderly, wavy pattern that rides along a jet. It is a train of large eddies that grow, then fade. It moves downstream slower than the jet. Most of it does not radiate sound. But its smooth, coherent part can send noise to the far field.','Provides a low-order, coherent-source model of jet noise that captures the peak downstream radiation better than random-eddy models.','Fitted to simulation or PIV data to model and predict jet peak noise; central to modern jet-noise source modelling.','Aeroacoustics & Flow-Induced Sound',ARRAY['Acoustic wavepacket','Turbulent mixing noise','Mach wave radiation','Convective Mach number','Pseudo-sound','Coherent structure']::text[],ARRAY['Assuming the whole wavepacket radiates, when most of it is subsonic and non-radiating','Confusing the convective hydrodynamic packet with its small acoustic field','Ignoring envelope coherence as the key to radiation']::text[],ARRAY['Modelling jet peak noise from coherent structures','Fitting wavepacket models to PIV data','Explaining downstream jet-noise directivity']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Convective wavepacket');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0f24adff-df4f-5f5c-8ab9-12ac04a94894','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0f24adff-df4f-5f5c-8ab9-12ac04a94894') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0f24adff-df4f-5f5c-8ab9-12ac04a94894');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ca27931-abd0-504a-af6d-e31c0a891680','Acoustic wavepacket','The radiating counterpart of a flow wavepacket: the coherent, low-wavenumber portion of a convecting wavepacket''s spectrum whose phase speed matches acoustic conditions and therefore couples to and radiates sound to the far field. It represents the acoustically matched part of the coherent structure, and its amplitude and coherence largely control a jet''s far-field peak noise.','An acoustic wavepacket is the sound-making part of a jet wavepacket. A wavepacket is a train of large, orderly eddies. Most of it stays with the flow. But a small, smooth part travels at sound speed. That part radiates to the far field. Its size sets the jet''s loudest noise.','Isolates the radiating fraction of a coherent structure, linking near-field flow coherence to far-field sound.','Used in jet-noise modelling to connect measured coherent structures to far-field spectra and directivity, and to target noise control at the coherent source.','Aeroacoustics & Flow-Induced Sound',ARRAY['Convective wavepacket','Turbulent mixing noise','Mach wave radiation','Far-field directivity','Wavenumber filtering','Coherent structure']::text[],ARRAY['Equating the acoustic wavepacket with the full, mostly non-radiating convective packet','Ignoring that only the low-wavenumber tail radiates','Assuming all coherent energy reaches the far field']::text[],ARRAY['Linking near-field wavepackets to far-field jet noise','Wavenumber-filtering a jet pressure field','Targeting the coherent source in jet-noise control']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic wavepacket');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ca27931-abd0-504a-af6d-e31c0a891680','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ca27931-abd0-504a-af6d-e31c0a891680') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ca27931-abd0-504a-af6d-e31c0a891680');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7379a9aa-61fe-5254-ab89-554a251df7de','Turbulent wake noise','Broadband sound produced by the turbulent wake shed downstream of a body in flow, generated by the unsteady vorticity and Reynolds stresses in the wake as a quadrupole-type volume source and, when the wake interacts with a surface or the body itself, by unsteady surface loading as a dipole. For bluff bodies it includes a periodic vortex-shedding tone superposed on the broadband wake noise.','Turbulent wake noise is the broadband sound from the churning air behind a body. As air passes an object, it leaves a messy, eddying wake. The unsteady eddies make broadband noise. For bluff shapes a shedding tone can sit on top. Struts, masts, and mirrors show this noise.','Describes the broadband component of bluff-body and profiled-body noise, complementing the discrete vortex-shedding tone.','Relevant to struts, antennas, mirrors, and cylinders in flow; reduced by streamlining, splitter plates, and surface treatments.','Aeroacoustics & Flow-Induced Sound',ARRAY['Bluff-body noise','Vortex shedding','Strouhal tone','Trailing-edge noise','Vortex sound','Separated-flow noise']::text[],ARRAY['Assuming wake noise is purely tonal, when broadband dominates for many shapes','Ignoring the dipole from wake-surface interaction','Treating a streamlined wake as noiseless']::text[],ARRAY['Car side-mirror wind noise','Strut or antenna noise in flow','Cylinder wake-noise measurement']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Turbulent wake noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7379a9aa-61fe-5254-ab89-554a251df7de','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7379a9aa-61fe-5254-ab89-554a251df7de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7379a9aa-61fe-5254-ab89-554a251df7de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0278e966-7b62-5fd4-83c9-07c0e1f9acbe','Separated-flow noise','Broadband noise generated when the boundary layer separates from a surface due to an adverse pressure gradient, high angle of attack, or bluff geometry, creating an unsteady separated shear layer and recirculation region with large, energetic, low-frequency pressure fluctuations. The separated shear layer and its reattachment, if any, impose strong unsteady loading on the surface, radiating as a low-frequency-dominated dipole source.','Separated-flow noise happens when air peels away from a surface. This can occur at a steep angle or over a blunt shape. The peeled-off flow forms an unsteady, swirling region. It makes strong, low-pitched, broadband noise. Stalled wings and blades show this noise.','Identifies the low-frequency broadband source tied to flow separation and stall, important for off-design blade and airfoil noise.','Seen on stalled airfoils, diffusers, and over-loaded fan blades; delayed or controlled by vortex generators and by avoiding stall.','Aeroacoustics & Flow-Induced Sound',ARRAY['Trailing-edge noise','Turbulent wake noise','Laminar separation bubble noise','Boundary layer','Dipole source','Bluff-body noise']::text[],ARRAY['Confusing separated-flow stall noise with attached trailing-edge noise','Assuming it is high-frequency, when it is low-frequency dominated','Ignoring the large loading fluctuations produced by separation']::text[],ARRAY['Stalled wind-turbine blade noise','Over-loaded fan low-frequency hump','Diffuser separation noise']::text[],'intermediate',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Separated-flow noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0278e966-7b62-5fd4-83c9-07c0e1f9acbe','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0278e966-7b62-5fd4-83c9-07c0e1f9acbe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0278e966-7b62-5fd4-83c9-07c0e1f9acbe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba12da96-8951-551c-a601-84ee3964a930','Laminar separation bubble noise','Tonal or narrowband airfoil self-noise produced at low-to-moderate Reynolds numbers when a laminar boundary layer separates, forms a separation bubble, and transitions to turbulence, setting up an acoustic feedback loop between Tollmien-Schlichting instability waves and the trailing edge. The feedback selects discrete frequencies, giving the characteristic tonal, sometimes ladder-structured, airfoil noise; tripping the boundary layer to turbulence usually removes it.','This noise is a tone from a wing at low speeds. A smooth boundary layer lifts off and forms a small bubble. Inside, the flow becomes unsteady and turns turbulent. Waves in the layer and the sharp edge form a feedback loop. The loop picks out tones. Roughening the surface usually stops it.','Explains discrete airfoil tones at low Reynolds number and why boundary-layer tripping suppresses them, key for gliders, drones, and model rotors.','Occurs on low-Reynolds-number airfoils such as small drones, wind turbines, and model rotors; suppressed by trips, roughness, or changing the pressure-side flow.','Aeroacoustics & Flow-Induced Sound',ARRAY['Trailing-edge noise','Boundary-layer transition','Feedback loop','Separated-flow noise','Airfoil self-noise','Laminar separation bubble']::text[],ARRAY['Assuming all airfoil trailing-edge noise is broadband, when this source is tonal','Expecting it at high Reynolds number','Forgetting a boundary-layer trip usually removes it']::text[],ARRAY['Drone-propeller tonal noise','Small wind-turbine airfoil tone','Using a trip strip to remove a wind-tunnel tone']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laminar separation bubble noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba12da96-8951-551c-a601-84ee3964a930','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba12da96-8951-551c-a601-84ee3964a930') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba12da96-8951-551c-a601-84ee3964a930');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '07f56728-da6f-5f21-b13e-6d4f380a855e','Aeroelastic-acoustic coupling','The mutual interaction between an elastic structure''s flow-induced vibration and the aerodynamic sound field, in which unsteady aerodynamic loading deforms the structure, the structural motion in turn modifies the flow and its acoustic sources, and the radiated or near-field sound (or an acoustic resonance) can feed back on the structure. It couples aeroelasticity, or fluid-structure interaction, with aeroacoustics and can lead to amplified tones, lock-in, or self-sustained oscillation.','This is a two-way link between a bending structure and flow sound. Flow forces make a part vibrate. The vibration changes the flow and its sound. That changed sound can push back on the part. The loop can grow tones or shake the structure. Panels, blades, and cables can show it.','Captures cases where sound and structural motion feed each other, needed to predict amplified tones, resonance, and fatigue in flexible flow structures.','Relevant to flexible panels, blades, cables, and cavity covers; assessed with coupled fluid-structure-acoustic models and mitigated by detuning and damping.','Aeroacoustics & Flow-Induced Sound',ARRAY['Vortex-induced vibration','Aeolian tone lock-in','Flutter','Fluid-structure interaction','Aeroacoustic resonance','Panel flutter']::text[],ARRAY['Treating the flow, structure, and sound as one-way when they are coupled','Ignoring feedback that can drive a resonance','UNSAFE: Neglecting aeroelastic-acoustic feedback, where coupled resonance can grow to flutter or fatigue failure of the structure']::text[],ARRAY['Flexible-panel flow-induced vibration','Cable or tube resonance in wind','Cavity-cover coupled oscillation']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aeroelastic-acoustic coupling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '07f56728-da6f-5f21-b13e-6d4f380a855e','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='07f56728-da6f-5f21-b13e-6d4f380a855e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='07f56728-da6f-5f21-b13e-6d4f380a855e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f552f9f0-09c8-54ee-bd08-7baced57be75','Porous trailing-edge treatment','A trailing-edge noise-reduction method in which the solid trailing edge of an airfoil or blade is replaced or augmented with a porous or permeable material, or with perforations, brushes, or finlets, which relaxes the abrupt hydrodynamic-to-acoustic scattering at the edge and allows pressure communication across it. This weakens the efficiency of turbulent boundary-layer trailing-edge noise scattering, lowering broadband noise chiefly at mid frequencies, at some aerodynamic-performance cost.','A porous trailing-edge treatment makes a blade''s back edge leaky, not solid. Turbulent air near a sharp edge scatters into loud broadband noise. A porous or brushed edge softens this scattering. Pressure can pass through the edge, so less noise is made. It is used on quiet, owl-inspired blades, with a small drag cost.','Reduces broadband trailing-edge noise by weakening the edge-scattering mechanism, a leading passive airfoil and blade noise-control approach.','Applied to wind-turbine and fan blades as porous edges, serrations, brushes, or finlets; trades a small aerodynamic penalty for quieter operation.','Aeroacoustics & Flow-Induced Sound',ARRAY['Trailing-edge noise','Trailing-edge serrations','Edge scattering','Broadband fan noise','Boundary layer','Bio-inspired noise control']::text[],ARRAY['Assuming porosity removes all trailing-edge noise','Ignoring the drag penalty and the risk of the pores clogging','Confusing porous treatments with serrations, which work by a different mechanism']::text[],ARRAY['Quieting a wind-turbine blade edge','Fan-blade porous-edge test','Comparing serrations against porous edges']::text[],'advanced',NULL,NULL,'7c49f93b-69cd-4a9c-ba3b-1cd05e86a546' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Porous trailing-edge treatment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f552f9f0-09c8-54ee-bd08-7baced57be75','7c49f93b-69cd-4a9c-ba3b-1cd05e86a546',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f552f9f0-09c8-54ee-bd08-7baced57be75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f552f9f0-09c8-54ee-bd08-7baced57be75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c51f794e-0d5b-55ce-84eb-e344e2041567','A-scan','A one-dimensional ultrasonic display presenting received echo amplitude on the vertical axis against time-of-flight (or an equivalent sound-path/depth scale) on the horizontal axis for a single fixed beam position. Each interface or reflector along the beam appears as a discrete signal peak, whose height indicates echo strength and whose horizontal position indicates range. It is the fundamental data form from which B-, C-, and sector scans are constructed.','An A-scan is a simple graph from one sound-beam spot. Height shows how strong an echo is. The left-to-right position shows how far away the reflector sits. Each flaw or back wall makes its own peak. It is the basic view used in flaw testing.','To provide the raw amplitude-versus-range signal used to detect, locate, and size reflectors and to set gates, gain, and calibration references.','Technicians read the A-scan on a flaw detector to find weld defects, gauge remaining wall thickness, and set reference echoes during calibration.','Ultrasonics, NDT & Industrial Inspection',ARRAY['B-scan','C-scan','S-scan','Sound path','Reference reflector','Back-wall echo']::text[],ARRAY['Reading a peak''s horizontal position as physical depth without accounting for probe angle or wedge delay','Assuming echo height alone gives flaw size without a reference reflector or DAC/DGS']::text[],ARRAY['Setting a back-wall echo to full screen height during calibration','Watching an A-scan peak rise as the probe passes over a weld crack']::text[],'beginner',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='A-scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c51f794e-0d5b-55ce-84eb-e344e2041567','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c51f794e-0d5b-55ce-84eb-e344e2041567') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c51f794e-0d5b-55ce-84eb-e344e2041567');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '16d1ff3b-8087-539b-934b-888f854933c1','B-scan','A two-dimensional ultrasonic image showing a cross-sectional profile through the test object, built by plotting reflector depth (time-of-flight) on one axis against probe position along a scan line on the other, with echo amplitude usually encoded as brightness or colour. It reveals the depth and through-thickness distribution of reflectors along the scan path, such as the back-wall contour, corrosion profiles, or the depth extent of a discontinuity.','A B-scan is a side-view picture of the part. One axis is depth. The other axis is where the probe moved along a line. Bright spots mark echoes at each depth. It shows how deep flaws or thinning reach.','To visualise the depth and length of reflectors along a scan line, giving a cross-section that a single A-scan cannot show at a glance.','Used for corrosion mapping of pipe and plate wall loss and to show the through-wall depth profile of weld flaws during encoded scanning.','Ultrasonics, NDT & Industrial Inspection',ARRAY['A-scan','C-scan','S-scan','Encoded scan','Sound path','Corrosion mapping']::text[],ARRAY['Confusing a B-scan (depth cross-section) with a C-scan (plan view)','Forgetting that beam spread widens indications, so a B-scan can overstate reflector length']::text[],ARRAY['Producing a wall-thickness cross-section along a corroded pipe','Reviewing weld defect depth on an encoded line scan']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='B-scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '16d1ff3b-8087-539b-934b-888f854933c1','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='16d1ff3b-8087-539b-934b-888f854933c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='16d1ff3b-8087-539b-934b-888f854933c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9d65e8e-7ed8-59e1-ab0b-e06a7b98a90b','C-scan','A two-dimensional plan-view ultrasonic image in which the probe is scanned over an area (X-Y) and, at each position, a gated feature of the A-scan (typically peak amplitude or time-of-flight within a depth gate) is mapped to a colour or greyscale pixel. The result is a top-down projection showing the lateral position, shape, and extent of reflectors within the selected depth range, without directly displaying their depth.','A C-scan is a top-down map of an area. The probe moves across the surface in a grid. At each spot the tool records the echo inside a set depth window. Colours show where reflectors sit and how big they are. It does not show depth by itself.','To display the size, shape, and location of reflectors over a surface area, aiding rapid coverage assessment and defect mapping.','Common in immersion testing of aerospace composites and rolled plate to map delaminations, inclusions, and bond quality.','Ultrasonics, NDT & Industrial Inspection',ARRAY['A-scan','B-scan','Immersion testing','Raster scan UT','Encoded scan','Delamination']::text[],ARRAY['Expecting depth information from a plan-view C-scan','Setting the depth gate wrongly so reflectors outside the window are missed']::text[],ARRAY['Mapping delaminations in a carbon-fibre panel in an immersion tank','Imaging inclusions across a rolled steel plate']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='C-scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9d65e8e-7ed8-59e1-ab0b-e06a7b98a90b','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9d65e8e-7ed8-59e1-ab0b-e06a7b98a90b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9d65e8e-7ed8-59e1-ab0b-e06a7b98a90b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ce8888a-0c4b-544d-b393-6b8639d1a4fb','S-scan','A phased-array ultrasonic image in which the beam is electronically swept through a range of refraction angles from a fixed array position, with each angle''s A-scan plotted along its true refracted path to form a fan-shaped (sector) cross-section. It maps reflectors across a span of angles and depths simultaneously, allowing a stationary probe to interrogate a volume, such as a weld, from multiple incidence angles.','An S-scan is a fan-shaped picture from a phased-array probe. The beam angle is swept across a range while the probe stays still. Each angle draws its echoes along its true path. Together they build a slice of the part. One probe can then check a weld from many angles.','To image a cross-sectional volume over many angles from one probe position, improving flaw detection and coverage in welds and complex geometry.','Widely used in phased-array weld inspection to cover the weld volume and root without moving the probe through many separate angle setups.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Sectorial scan','Linear scan','Phased-array probe aperture','Refracted angle','Dynamic focusing','Electronic scanning']::text[],ARRAY['Treating an S-scan as geometrically exact without correct velocity and wedge calibration','Assuming full coverage when steering beyond the array''s usable angle range weakens sensitivity']::text[],ARRAY['Scanning a pipe girth weld with a phased-array probe on a wedge','Steering through 40 to 70 degrees to catch differently oriented weld flaws']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='S-scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ce8888a-0c4b-544d-b393-6b8639d1a4fb','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ce8888a-0c4b-544d-b393-6b8639d1a4fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ce8888a-0c4b-544d-b393-6b8639d1a4fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c870f9de-d567-5cd8-a257-03942090aa44','Sectorial scan','A phased-array scanning technique in which the acoustic beam is steered electronically through a sequence of refraction angles from a fixed aperture, sweeping a sector of the material; the composite of the angular A-scans forms the S-scan image. Because the probe remains stationary while the beam fans through an angular range, a sectorial scan interrogates a wedge-shaped volume and suits fixed-access or limited-clearance inspections.','A sectorial scan sweeps the beam angle across a range from a fixed probe. The probe does not move while the angle fans out. The set of angles covers a wedge-shaped slice of the part. The picture it makes is called an S-scan. It suits spots with little room to move the probe.','To cover a range of beam angles from one aperture position, enabling volumetric inspection where probe movement is restricted.','Applied in phased-array weld and nozzle inspections where clearance is tight and multi-angle coverage is needed from one position.','Ultrasonics, NDT & Industrial Inspection',ARRAY['S-scan','Linear scan','Phased-array probe aperture','Refracted angle','Electronic scanning','Dynamic focusing']::text[],ARRAY['Using excessive steering angles where sensitivity and beam shape degrade','Neglecting angle-dependent wedge attenuation and calibration across the sweep']::text[],ARRAY['Fanning 35 to 75 degrees across a weld from a fixed wedge','Inspecting a nozzle inner radius with limited probe access']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sectorial scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c870f9de-d567-5cd8-a257-03942090aa44','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c870f9de-d567-5cd8-a257-03942090aa44') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c870f9de-d567-5cd8-a257-03942090aa44');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '21d55faf-0325-578a-a8c6-001651a74087','Linear scan','A phased-array scanning mode in which a fixed sub-aperture (a group of active elements) is stepped element-by-element along the length of the array at a constant refraction angle, effectively translating the beam electronically across the probe footprint without mechanical movement. Each aperture position yields an A-scan, and successive positions build a line image resembling a mechanically scanned single-element probe but produced electronically.','A linear scan moves the active beam along a phased-array probe. A group of elements fires, then the group shifts by one element. The angle stays the same the whole time. This slides the beam along the probe with no motion. It acts like dragging a single probe, but done by electronics.','To achieve coverage along the array length at a set angle without mechanical scanning, speeding inspection and improving positional repeatability.','Used for corrosion mapping and bond-line inspection where a long array covers width electronically while an encoder tracks the perpendicular scan axis.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Sectorial scan','Electronic scanning','Element pitch','Phased-array probe aperture','Encoded scan','Dynamic focusing']::text[],ARRAY['Confusing electronic linear scanning with a mechanical raster scan','Choosing an aperture too small, giving poor focusing and low sensitivity']::text[],ARRAY['Sweeping a long array along a plate for corrosion coverage','Electronically stepping the aperture at zero degrees for a bond-line check']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '21d55faf-0325-578a-a8c6-001651a74087','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='21d55faf-0325-578a-a8c6-001651a74087') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='21d55faf-0325-578a-a8c6-001651a74087');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d5e7eb3-b0fe-5ed1-8d33-9c015cab1d64','Encoded scan','An ultrasonic scan in which probe position is recorded synchronously with the acquired A-scan data by a position encoder, so every waveform is tagged with its true spatial coordinate. Position encoding enables geometrically accurate B-, C-, and merged imaging, repeatable re-inspection, and permanent archived records, in contrast to non-encoded (free-running) scanning where data is not tied to position.','An encoded scan links each reading to where the probe was. A position sensor tracks probe travel as data is taken. Every echo then has a true location on the part. This lets the tool build accurate maps and images. The record can be saved and repeated later.','To tie ultrasonic data to physical position for accurate imaging, sizing, coverage proof, and repeatable re-examination.','Standard in coded weld inspection and corrosion mapping, where an encoder wheel logs position for archived, auditable results.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Linear scan','C-scan','B-scan','Raster scan UT','Index point','Corrosion mapping']::text[],ARRAY['Assuming position accuracy without calibrating the encoder resolution','Letting the probe slip or lift so recorded position drifts from true position']::text[],ARRAY['Logging a girth-weld scan with an encoder for a permanent record','Corrosion mapping a tank floor with position-tagged data']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Encoded scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d5e7eb3-b0fe-5ed1-8d33-9c015cab1d64','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d5e7eb3-b0fe-5ed1-8d33-9c015cab1d64') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d5e7eb3-b0fe-5ed1-8d33-9c015cab1d64');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d4060f0-c0e3-526d-b404-d62b02c7f497','Raster scan UT','A mechanical scanning pattern in which the probe is moved over a surface in a series of parallel, evenly spaced passes (a raster grid), typically with an index step between passes, to acquire full-area coverage for C-scan imaging. Each raster line collects A-scan data along one axis while the orthogonal index advances between lines, producing a regularly sampled two-dimensional data set.','A raster scan moves the probe over an area in a grid. The probe runs in parallel lines, one after another. After each line it steps sideways by a set amount. This covers the whole surface evenly. The data builds a top-down map of the part.','To achieve complete, uniformly sampled area coverage so that reflectors anywhere in the region are detected and mapped.','Used in immersion and automated squirter systems to C-scan plates and composite panels with a scanner running a fixed raster grid.','Ultrasonics, NDT & Industrial Inspection',ARRAY['C-scan','Immersion testing','Encoded scan','Index point','Electronic scanning','Beam spread']::text[],ARRAY['Setting the index step wider than the beam width, leaving unscanned gaps between lines','Confusing mechanical raster scanning with electronic linear scanning']::text[],ARRAY['Automated immersion C-scan of an aerospace panel','Gantry raster scan of a large rolled plate']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Raster scan UT');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d4060f0-c0e3-526d-b404-d62b02c7f497','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d4060f0-c0e3-526d-b404-d62b02c7f497') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d4060f0-c0e3-526d-b404-d62b02c7f497');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '607a6e91-fa68-50fa-b4d7-d84b92f03988','Immersion testing','An ultrasonic technique in which the probe and test object are coupled through a liquid path (usually water) with a controlled standoff between the transducer face and the part, rather than direct contact. The water column provides consistent, low-loss coupling, permits focused transducers and normal or angled incidence via manipulator control, and produces a distinct water-path (front-surface) echo ahead of the part echoes.','In immersion testing the part sits in water. The probe stays above it and does not touch the surface. Water carries the sound between them. This gives steady, even coupling for scanning. A water-path echo shows up before the part echoes.','To provide uniform coupling and precise, focused beam control for automated scanning and high-resolution imaging.','Used in automated C-scan systems for aerospace composites, billets, and plate, where focused probes and water paths give repeatable, high-resolution results.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Contact testing','C-scan','Raster scan UT','Couplant','Focused probe','Front-surface echo']::text[],ARRAY['Letting air bubbles on the surface or transducer scatter the beam and cause false or lost echoes','Setting the water path so the front-surface multiple overlaps the region of interest','UNSAFE: operating mains-powered equipment around immersion tanks without proper electrical isolation and safeguards against water contact']::text[],ARRAY['Scanning a turbine disc in a water tank with a focused probe','Setting a water path so its multiple echo falls clear of the part signals']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Immersion testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '607a6e91-fa68-50fa-b4d7-d84b92f03988','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='607a6e91-fa68-50fa-b4d7-d84b92f03988') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='607a6e91-fa68-50fa-b4d7-d84b92f03988');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2640dba3-951b-5e8d-b51e-ca3db45f697f','Contact testing','An ultrasonic technique in which the probe is placed in direct contact with the test surface, coupled by a thin film of couplant (gel, oil, paste, or water) that excludes air and permits sound transmission across the interface. Contact testing uses hand-held or fixture-held probes, is portable and fast, but depends on operator pressure and surface condition for consistent coupling, unlike immersion methods.','In contact testing the probe sits right on the part. A thin layer of gel or oil fills the gap. This lets sound cross into the material. It is quick and easy to carry out in the field. Steady hand pressure and a clean surface keep the coupling even.','To couple ultrasound directly into a part for portable, on-site flaw detection and thickness measurement without a water tank.','The everyday method for weld inspection, thickness gauging, and structural checks using a hand-held flaw detector and couplant.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Immersion testing','Couplant','Angle-beam testing','Straight-beam testing','Dual-element probe','Delay line probe']::text[],ARRAY['Varying hand pressure or couplant thickness so echo amplitude drifts during a scan','Scanning rough or scaled surfaces without recognising the coupling loss']::text[],ARRAY['Hand-scanning a pipe weld with couplant and an angle-beam probe','Spot-checking plate thickness on-site with a contact probe']::text[],'beginner',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Contact testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2640dba3-951b-5e8d-b51e-ca3db45f697f','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2640dba3-951b-5e8d-b51e-ca3db45f697f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2640dba3-951b-5e8d-b51e-ca3db45f697f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73a5b729-f4fa-53de-8e82-2e7f88cfbda9','Angle-beam testing','An ultrasonic contact technique in which sound is introduced into the material at an oblique angle, typically as a refracted shear wave produced by a probe mounted on an angled wedge, so the beam travels at a known refracted angle and reflects off the far surface in a zig-zag skip path. It is used to reach reflectors not accessible to a normal beam, especially weld fusion faces and cracks oriented perpendicular to the surface.','Angle-beam testing sends sound into the part at a slant. A wedge tilts the probe so the beam bends to a set angle. The beam then zig-zags off the far wall through the metal. This reaches flaws a straight-down beam would miss. It is the main way welds are checked.','To direct the beam at reflectors that a straight beam cannot reach, such as weld sidewalls and surface-connected cracks.','The standard approach for manual weld inspection, using shear-wave wedge probes and skip-distance calculations to locate flaws.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Straight-beam testing','Shear-wave probe','Refracted angle','Skip distance','Half-skip','Sound path']::text[],ARRAY['Using the marked nominal angle without verifying the true refracted angle in the actual material','Miscalculating skip distance and mislocating a flaw between the first and second leg']::text[],ARRAY['Inspecting a butt weld with a 60-degree shear-wave probe','Using half-skip and full-skip to place a probe for root and cap coverage']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Angle-beam testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73a5b729-f4fa-53de-8e82-2e7f88cfbda9','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73a5b729-f4fa-53de-8e82-2e7f88cfbda9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73a5b729-f4fa-53de-8e82-2e7f88cfbda9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fc14efd5-2c0e-5c12-8a79-cc334715978f','Straight-beam testing','An ultrasonic technique in which a longitudinal (compression) wave is introduced normal to the test surface, so the beam travels straight into the material and reflects from the back wall or from reflectors lying roughly parallel to the surface. Also called normal-beam or zero-degree testing, it is used for thickness measurement, laminar-flaw detection, and back-wall monitoring.','Straight-beam testing sends sound straight down into the part. The beam goes in square to the surface. It bounces back from the far wall or a flat flaw. This is used to measure thickness and find layered flaws. It is the simplest sound-beam setup.','To detect reflectors parallel to the surface and to measure wall thickness using a normal-incidence longitudinal beam.','Used for corrosion thickness gauging, lamination checks in plate, and bond testing where flaws lie parallel to the surface.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Angle-beam testing','Longitudinal-wave probe','Dual-element probe','Metal path','Back-wall echo','Lamination']::text[],ARRAY['Missing angled or vertical cracks that a normal beam does not favourably strike','Mistaking mode-converted or geometry echoes for flaw indications']::text[],ARRAY['Gauging remaining wall thickness on a corroded pipe','Checking rolled plate for laminations before fabrication']::text[],'beginner',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Straight-beam testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fc14efd5-2c0e-5c12-8a79-cc334715978f','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fc14efd5-2c0e-5c12-8a79-cc334715978f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fc14efd5-2c0e-5c12-8a79-cc334715978f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d7004bc-9a91-5852-9eb6-cc9803a18531','Shear-wave probe','An ultrasonic probe configured to generate a transverse (shear) wave in the test material, most commonly a longitudinal-wave element mounted on an angled wedge so that, above the first critical angle, only a refracted shear wave propagates in the part. Shear waves travel at roughly half the longitudinal velocity, giving shorter wavelengths for the same frequency, and are central to angle-beam weld inspection.','A shear-wave probe makes a side-to-side sound wave in the metal. It is usually a normal element on an angled wedge. Past a certain angle, only the shear wave stays in the part. Shear waves move slower than straight-down waves. They are the workhorse for angled weld checks.','To produce a refracted shear beam at a known angle for detecting weld flaws and cracks oriented across the beam path.','Used on wedges at set angles such as 45, 60, or 70 degrees for manual and phased-array weld inspection.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Angle-beam testing','Refracted angle','Shear-wave velocity','Longitudinal-wave probe','Wedge delay','Skip distance']::text[],ARRAY['Assuming the wedge''s marked angle equals the refracted angle in every material','Ignoring mode conversion that reintroduces a longitudinal component near critical angles']::text[],ARRAY['Selecting a 60-degree shear probe for a pipe weld','Verifying the refracted angle on a calibration block before scanning']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shear-wave probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d7004bc-9a91-5852-9eb6-cc9803a18531','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d7004bc-9a91-5852-9eb6-cc9803a18531') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d7004bc-9a91-5852-9eb6-cc9803a18531');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6dd79fe4-3135-5455-997d-578cf5483f91','Longitudinal-wave probe','An ultrasonic probe that generates a longitudinal (compression) wave, in which particle motion is parallel to the direction of propagation. In contact straight-beam form it launches the wave normal to the surface for thickness and laminar-flaw work; longitudinal waves have the highest velocity of the bulk modes and thus the longest wavelength for a given frequency.','A longitudinal-wave probe makes a push-pull sound wave. The material moves back and forth along the beam. Placed flat, it sends the beam straight into the part. These waves are the fastest type in solids. They are used for thickness and flat-flaw checks.','To send a compression wave into the material for normal-incidence thickness gauging and detection of reflectors parallel to the surface.','Used as straight-beam contact and immersion probes for thickness measurement, lamination detection, and back-wall monitoring.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Straight-beam testing','Longitudinal-wave velocity','Shear-wave probe','Dual-element probe','Metal path','Back-wall echo']::text[],ARRAY['Expecting a normal longitudinal probe to find vertical cracks it cannot favourably strike','Confusing longitudinal velocity with shear velocity when calibrating']::text[],ARRAY['Thickness gauging a vessel wall with a straight-beam probe','Detecting laminations in plate with a normal compression beam']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Longitudinal-wave probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6dd79fe4-3135-5455-997d-578cf5483f91','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6dd79fe4-3135-5455-997d-578cf5483f91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6dd79fe4-3135-5455-997d-578cf5483f91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df970714-353a-5903-9667-e9cf8659be0e','Dual-element probe','A contact ultrasonic probe housing two separate elements (one transmitter and one receiver) mounted on delay lines and slightly angled (roofed) toward each other so their beams cross at a focal zone in the near-surface region. This pitch-catch arrangement suppresses the interface ringing that blinds single-element probes near the surface, giving good near-surface resolution for thin-wall and corrosion thickness measurement.','A dual-element probe has two crystals in one case. One sends the sound and the other receives it. Small delay blocks tilt the two beams to meet just below the surface. This clears the dead zone that blinds single probes near the top. It is ideal for thin walls and corrosion checks.','To improve near-surface resolution and reduce the dead zone so thin sections and remaining wall can be measured reliably.','The common choice for corrosion thickness gauging of pipe and plate, especially on rough or pitted surfaces.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Straight-beam testing','Delay line probe','Longitudinal-wave probe','Contact testing','Dead zone','Back-wall echo']::text[],ARRAY['Ignoring the V-path error that makes readings least accurate away from the crossover focus','Using a dual probe beyond its designed thickness range and misreading echoes']::text[],ARRAY['Gauging corroded pipe wall with a dual-element thickness probe','Measuring thin plate where a single probe''s dead zone hides the back wall']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dual-element probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df970714-353a-5903-9667-e9cf8659be0e','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df970714-353a-5903-9667-e9cf8659be0e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df970714-353a-5903-9667-e9cf8659be0e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80545f5f-34a6-5345-8fa9-78a0fb6617dc','Delay line probe','A contact ultrasonic probe fitted with a short, replaceable column of low-attenuation material (the delay line or standoff) between the element and the test surface, which delays the entry of sound into the part so that the excitation and interface signals clear the screen before the first back-wall echo. This moves reflections of interest away from the initial pulse, improving near-surface resolution and enabling thin-material and high-frequency measurements.','A delay line probe has a small block in front of the crystal. Sound travels through this block before entering the part. The delay pushes the start pulse off to the side of the screen. That clears the view of the first echo from the part. It helps measure thin or near-surface features.','To separate the excitation pulse and interface echo from part echoes, improving near-surface resolution and thin-section measurement.','Used for thin-wall thickness gauging, high-frequency inspection, and hot-surface work with heat-resistant delay tips.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Dual-element probe','Probe delay','Contact testing','Straight-beam testing','Wedge delay','Dead zone']::text[],ARRAY['Forgetting to zero the instrument for the delay-line travel time, offsetting all readings','Ignoring wear of the delay tip that changes the delay and calibration']::text[],ARRAY['Measuring thin tube wall with a high-frequency delay-line probe','Zeroing an instrument for the delay-tip travel time before gauging']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Delay line probe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80545f5f-34a6-5345-8fa9-78a0fb6617dc','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80545f5f-34a6-5345-8fa9-78a0fb6617dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80545f5f-34a6-5345-8fa9-78a0fb6617dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a752099-27f3-5b88-8117-4d65a970fe08','Phased-array probe aperture','The active aperture of a phased-array probe is the total width of the group of simultaneously excited elements used to form a beam, equal to the number of active elements multiplied by the element pitch. Aperture size governs beam width, focusing ability, and near-field length: a larger active aperture produces a narrower, more focusable beam and greater penetration, while a smaller aperture gives a broader, less controllable beam.','The active aperture is the strip of elements firing together. Its width equals the element count times the spacing. A wider group makes a tighter, more focused beam. It also reaches deeper into the part. A narrow group gives a wider, weaker-focused beam.','To set beam width, focal depth, and sensitivity by choosing how many elements act together to form each beam.','Set in phased-array focal-law software; technicians pick active element counts to balance focusing, coverage, and penetration for a weld or component.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Element pitch','Element aperture','Virtual aperture','Dynamic focusing','Beam spread','Electronic scanning']::text[],ARRAY['Choosing too few active elements and getting a poorly focused, low-sensitivity beam','Assuming aperture can grow without limit when the array''s element count and steering set the ceiling']::text[],ARRAY['Building a focal law with a 16-element active aperture for a weld','Increasing active elements to focus deeper in a thick section']::text[],'advanced','A = N · p','The active aperture width equals the number of active elements multiplied by the element pitch.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phased-array probe aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a752099-27f3-5b88-8117-4d65a970fe08','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a752099-27f3-5b88-8117-4d65a970fe08') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a752099-27f3-5b88-8117-4d65a970fe08');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d93413f-829b-516c-a6e1-cbb89914c089','Element pitch','The element pitch of a phased-array probe is the centre-to-centre distance between adjacent elements, equal to the element width plus the inter-element gap (kerf). Pitch is a primary design parameter: it sets the maximum steering angle before grating lobes appear (finer pitch allows greater steering) and, together with element count, determines the active aperture and thus focusing and beam width.','Element pitch is the spacing from one element''s centre to the next. It equals the element width plus the small gap between them. Smaller pitch lets the beam steer to wider angles. It also shapes how the beam focuses. It is a key number in probe design.','To control steering range and grating-lobe onset while contributing to aperture size and beam formation.','Considered when selecting a phased-array probe: fine-pitch probes for wide steering in weld sectors, coarser pitch for larger apertures and penetration.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Element aperture','Phased-array probe aperture','Virtual aperture','Grating lobe','Beam spread','Refracted angle']::text[],ARRAY['Ignoring that too-large pitch causes grating lobes that create false indications','Confusing pitch (centre-to-centre) with element width (the active strip alone)']::text[],ARRAY['Selecting a fine-pitch array for wide-angle weld sector scanning','Checking pitch against required steering to avoid grating lobes']::text[],'intermediate','p = e + g','The element pitch equals the element width plus the gap, or kerf, between adjacent elements.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Element pitch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d93413f-829b-516c-a6e1-cbb89914c089','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d93413f-829b-516c-a6e1-cbb89914c089') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d93413f-829b-516c-a6e1-cbb89914c089');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e9c159e-34e4-52d5-b1da-49b43edc179f','Element aperture','The element aperture is the radiating dimension of an individual phased-array element: its active width, and in the passive direction its elevation height. Because each small element behaves as a near-point source, its width controls the element''s individual directivity and beam spread; narrow elements radiate a wide angular pattern that permits beam steering, while the elevation dimension sets the unfocused beam behaviour in the passive plane.','Element aperture is the size of one single element''s face. Its width sets how wide that one element spreads sound. Narrow elements spread widely, which lets the array steer the beam. The height sets the beam shape in the other direction. It is a per-element size, not the whole group.','To define the directivity of each element, which underlies the array''s steering ability and passive-plane beam shape.','A probe design factor; the passive-aperture height is often chosen or lens-focused to control beam shape perpendicular to the scan plane.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Element pitch','Phased-array probe aperture','Virtual aperture','Beam spread','Grating lobe','Passive aperture']::text[],ARRAY['Confusing the single-element aperture with the whole active aperture of the element group','Overlooking the passive (elevation) dimension when beam shape matters out of plane']::text[],ARRAY['Considering element width when wide steering is needed','Choosing a probe whose passive height suits the required focal shape']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Element aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e9c159e-34e4-52d5-b1da-49b43edc179f','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e9c159e-34e4-52d5-b1da-49b43edc179f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e9c159e-34e4-52d5-b1da-49b43edc179f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7331a7a-2945-559c-b15a-a735e7ea960e','Virtual aperture','A virtual aperture (virtual probe aperture) is the effective radiating aperture synthesised by a phased-array focal law rather than by a single physical element: typically the group of elements combined for one beam, whose collective width and applied time delays act as one larger effective source. In advanced processing such as total-focusing and synthetic-aperture methods, virtual apertures are formed to shape, focus, or steer the beam beyond what individual elements provide.','A virtual aperture is an effective source made from several elements. Time delays make the group act like one bigger element. This lets the system shape and focus the beam. It is built by software, not by one physical crystal. Advanced imaging uses these to sharpen results.','To synthesise a larger, controllable effective aperture from grouped elements for improved focusing, steering, and image resolution.','Used in phased-array and total-focusing-method setups where grouped elements form virtual sources for higher-resolution imaging.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Phased-array probe aperture','Element aperture','Element pitch','Dynamic focusing','Electronic scanning','Total focusing method']::text[],ARRAY['Treating a virtual aperture as a physical part rather than a computed grouping','Assuming it removes physical limits set by real element size and pitch']::text[],ARRAY['Forming virtual source groups in a total-focusing setup','Combining elements into one effective aperture for a focused weld inspection']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Virtual aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7331a7a-2945-559c-b15a-a735e7ea960e','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7331a7a-2945-559c-b15a-a735e7ea960e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7331a7a-2945-559c-b15a-a735e7ea960e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30f7ce88-5f9e-5247-acc1-fc97b2be1957','Dynamic focusing','Dynamic focusing (dynamic depth focusing) is a phased-array reception technique in which the receive focal law is continuously updated as echoes return from increasing depths, so the array is effectively focused at each range in turn rather than at a single fixed focal depth. By tracking the optimum receive delays with time-of-flight, it keeps the beam sharply focused over an extended depth range, improving resolution and sensitivity across the full A-scan.','Dynamic focusing sharpens the beam at every depth on receive. As echoes come back from deeper points, the delays update. This keeps the beam in focus all the way down. A fixed focus is sharp at only one depth. Dynamic focus stays sharp over a range.','To maintain optimal focus across a depth range on reception, improving resolution and sensitivity beyond a single fixed focal point.','Used in phased-array systems to keep sensitivity even through thick sections without running multiple fixed-focus scans.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Phased-array probe aperture','Electronic scanning','Sectorial scan','Virtual aperture','Beam spread','Element pitch']::text[],ARRAY['Believing dynamic focusing improves the transmitted beam, when it acts mainly on receive','Assuming it overcomes near-field or aperture limits on achievable focus']::text[],ARRAY['Keeping focus sharp through a thick weld on receive','Using dynamic depth focusing to avoid multiple fixed-focus passes']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic focusing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30f7ce88-5f9e-5247-acc1-fc97b2be1957','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30f7ce88-5f9e-5247-acc1-fc97b2be1957') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30f7ce88-5f9e-5247-acc1-fc97b2be1957');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54d74008-84ad-54e4-8827-3e775e539751','Electronic scanning','Electronic scanning is the movement of the ultrasonic beam by controlling element timing in a phased array, through delay laws that step, steer, or sweep the beam, rather than by mechanically moving the probe. It encompasses electronic linear (translating) scanning, sectorial (angular) sweeping, and electronic focusing, enabling rapid, repeatable beam positioning from a stationary or slowly moving probe.','Electronic scanning moves the sound beam using timing, not motion. The system fires elements with set delays to aim the beam. It can slide the beam along, fan it, or focus it. The probe can stay still while the beam moves. This is fast and repeatable.','To position, steer, and focus the beam electronically for fast, repeatable coverage without mechanical scanning motion.','The basis of phased-array inspection, enabling linear and sectorial scans and multi-angle weld coverage from a fixed or encoded probe.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Phased-array probe aperture','Sectorial scan','Linear scan','Dynamic focusing','Element pitch','Encoded scan']::text[],ARRAY['Assuming electronic scanning removes the need for mechanical scanning across the whole part','Overlooking that steering range is bounded by element pitch and grating lobes']::text[],ARRAY['Running a linear electronic scan along an array for coverage','Combining electronic sector sweeps with an encoder for full weld data']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic scanning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54d74008-84ad-54e4-8827-3e775e539751','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54d74008-84ad-54e4-8827-3e775e539751') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54d74008-84ad-54e4-8827-3e775e539751');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41a46b8d-7ea6-530e-8aab-42c5aef54033','Beam skew','Beam skew is the deviation of the ultrasonic beam''s actual propagation direction out of the intended plane of incidence, causing the sound path to run off to one side rather than straight ahead. It arises from material anisotropy (notably in austenitic and dissimilar-metal welds), from probe or wedge misalignment, and from grain-oriented structures that bend or split the beam, and it can lead to mislocation or missed detection of reflectors.','Beam skew is when the sound beam drifts sideways off its planned line. Instead of going straight ahead, it leans to one side. Grainy or welded metals can bend the beam this way. Probe misalignment can also cause it. Skew can put a flaw in the wrong place or hide it.','To describe and account for off-plane beam deviation that distorts flaw location and detection, especially in anisotropic materials.','A key concern in austenitic and dissimilar-metal weld inspection, where skew is estimated or compensated to avoid mislocating indications.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Refracted angle','Beam spread','Beam divergence','Sound path','Angle-beam testing','Anisotropy']::text[],ARRAY['Assuming the beam travels only in the incidence plane in coarse-grained or austenitic welds','Attributing skew-mislocated echoes to true flaw position without considering deviation']::text[],ARRAY['Inspecting an austenitic stainless weld where grain structure skews the beam','Checking probe and wedge alignment to rule out mechanical skew']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beam skew');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41a46b8d-7ea6-530e-8aab-42c5aef54033','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41a46b8d-7ea6-530e-8aab-42c5aef54033') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41a46b8d-7ea6-530e-8aab-42c5aef54033');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5419eeda-aecf-5905-97ff-90dfec61eaec','Beam spread','Beam spread is the angular widening of the ultrasonic beam beyond the near field, where the diverging far-field beam broadens with distance from the transducer. For a circular element the half-angle of spread is governed by the wavelength-to-diameter ratio, sin(theta) = k(lambda/D), with the constant k set by the chosen edge criterion (for example, the beam edge to the first null or a defined amplitude drop). Larger diameter or higher frequency narrows the spread.','Beam spread is how the sound beam fans out with distance. Past the near field the beam gets wider as it travels. A bigger probe or higher frequency keeps the beam tighter. A small probe spreads more. The spread angle depends on wavelength divided by probe width.','To quantify how the beam widens with range, which affects coverage, resolution, and how reflector size relates to indication size.','Considered when setting scan index steps and interpreting indication length, since spread widens echoes from small reflectors.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Beam divergence','Element aperture','Beam skew','Sound path','Near-field length','Wavelength']::text[],ARRAY['Reading indication length as true reflector size without allowing for beam spread','Assuming a high-frequency probe never spreads enough to matter at range']::text[],ARRAY['Setting a raster index smaller than the spread-widened beam width','Explaining why a small side-drilled hole gives a long indication']::text[],'intermediate','sin(θ) = k · λ / D','The sine of the beam-spread half-angle equals a constant, set by the edge criterion, times wavelength over element diameter.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beam spread');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5419eeda-aecf-5905-97ff-90dfec61eaec','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5419eeda-aecf-5905-97ff-90dfec61eaec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5419eeda-aecf-5905-97ff-90dfec61eaec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd77d4ec6-86f4-583a-bb76-29c47097fc31','Beam divergence','Beam divergence is the far-field angular spreading of the ultrasonic beam from a transducer, conventionally expressed as the half-angle between the beam axis and its edge, with sin(theta) = 1.22(lambda/D) to the first pressure null for a circular piston source (or a smaller constant for a defined amplitude-drop edge). Divergence increases with wavelength and decreases with element diameter, so lower frequencies and smaller elements diverge more.','Beam divergence is the spreading angle of the beam far from the probe. It is measured from the centre line out to the beam edge. Longer wavelengths spread the beam more. Bigger probes keep it narrower. It is closely tied to beam spread.','To describe the far-field spreading angle used to estimate beam width at depth and predict coverage and resolution loss with range.','Used to estimate beam coverage at depth and to choose frequency and element size for a required beam width in a section.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Beam spread','Element aperture','Sound path','Beam skew','Near-field length','Wavelength']::text[],ARRAY['Confusing the half-angle with the full divergence angle when calculating beam width','Ignoring that divergence widens the beam and lowers resolution deep in a section']::text[],ARRAY['Estimating beam width at the far wall of a thick section','Selecting element diameter to limit divergence for deep inspection']::text[],'intermediate','sin(θ) = 1.22 · λ / D','For a circular element, the sine of the divergence half-angle to the first null equals 1.22 times wavelength over element diameter.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beam divergence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd77d4ec6-86f4-583a-bb76-29c47097fc31','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d77d4ec6-86f4-583a-bb76-29c47097fc31') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d77d4ec6-86f4-583a-bb76-29c47097fc31');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '29d53f78-92ee-5418-b429-f1ce68c35782','Sound path','The sound path is the total distance the ultrasonic pulse travels through the test material along the beam axis from the entry (index) point to the reflector, derived from time-of-flight and the material velocity. In angle-beam inspection it relates to reflector depth and surface distance by the refracted angle: for a first-leg reflector, depth = sound path x cos(theta) and surface distance = sound path x sin(theta). It is the primary distance read on the instrument.','The sound path is how far the pulse travels in the part to reach a flaw. It is found from travel time and the material''s speed. For an angled beam, depth equals sound path times the cosine of the angle. Surface distance equals sound path times the sine of the angle. It is the main distance the tool shows.','To give the beam-travel distance from which reflector depth and surface position are computed in angle-beam inspection.','Read directly from a flaw detector to locate weld flaws, using trigonometry with the refracted angle to find depth and surface distance.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Metal path','Refracted angle','Skip distance','Half-skip','Index point','Angle-beam testing']::text[],ARRAY['Reading sound path as vertical depth instead of beam-travel distance','Forgetting to subtract the wedge or probe delay, so sound path is overstated']::text[],ARRAY['Locating a weld flaw from the sound path and refracted angle','Converting sound path to depth and surface distance on a calculation sheet']::text[],'intermediate','depth = S · cosθ ; surface = S · sinθ','For a first-leg reflector, depth equals the sound path times the cosine of the refracted angle, and surface distance equals the sound path times its sine.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound path');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '29d53f78-92ee-5418-b429-f1ce68c35782','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='29d53f78-92ee-5418-b429-f1ce68c35782') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='29d53f78-92ee-5418-b429-f1ce68c35782');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7017f869-5f90-5f6a-923c-8508c6efbd30','Metal path','The metal path (material path) is the distance the ultrasonic beam travels within the metal itself along the refracted beam axis, as distinct from any travel in a wedge or delay line. In angle-beam work it is the in-material sound path; combined with the refracted angle it yields the reflector''s true depth and, across skip legs, its through-thickness position (for example depth = metal path x cos(theta) in the first leg, and 2T minus that product in the second leg).','The metal path is how far the beam travels inside the metal only. It leaves out any travel through the wedge. With the beam angle it gives the flaw''s true depth. On the first leg, depth equals metal path times cosine of the angle. On the second leg the depth is measured from the far wall.','To isolate in-material travel distance so reflector depth is computed correctly, excluding wedge or delay-line travel.','Used in angle-beam weld sizing where wedge travel must be removed to convert beam travel into true depth across skip legs.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Sound path','Wedge delay','Refracted angle','Skip distance','Half-skip','Full-skip']::text[],ARRAY['Including wedge travel in the metal path and overstating depth','Forgetting to switch the depth relation between the first and second legs']::text[],ARRAY['Sizing a weld flaw depth from metal path in the second leg','Subtracting wedge travel to get the true in-material path']::text[],'intermediate','depth = MP·cosθ (leg 1); depth = 2T − MP·cosθ (leg 2)','In the first leg, depth equals the metal path times the cosine of the angle; in the second leg, subtract that product from twice the thickness.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Metal path');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7017f869-5f90-5f6a-923c-8508c6efbd30','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7017f869-5f90-5f6a-923c-8508c6efbd30') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7017f869-5f90-5f6a-923c-8508c6efbd30');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11b7dd33-317e-58df-b5bc-d75e7dc1bc6a','Skip distance','The skip distance is the surface distance a shear-wave angle beam covers between successive reflections from the two parallel surfaces of a plate or pipe wall. A full skip (the beam travelling down to the far wall and back up to the near surface) spans a surface distance of 2T(tan theta), where T is the wall thickness and theta the refracted angle. Skip distance governs where the probe must sit to place the beam on a target such as a weld root or fusion face.','The skip distance is how far along the surface the beam travels between wall bounces. A full skip goes down to the far wall and back to the top. That surface distance equals twice the thickness times the tangent of the angle. It tells the tester where to place the probe. This aims the beam at the weld.','To determine probe placement so the beam strikes the intended part of a weld or wall at the desired leg.','Used to mark probe positions on a weld cap for root and sidewall coverage using half-skip and full-skip distances.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Half-skip','Full-skip','Refracted angle','Sound path','Metal path','Angle-beam testing']::text[],ARRAY['Using the nominal probe angle instead of the true refracted angle in the skip calculation','Forgetting that skip distance changes with thickness across a tapered or corroded wall']::text[],ARRAY['Marking half-skip and full-skip lines on a plate for weld coverage','Positioning the probe to hit the weld root at full skip']::text[],'intermediate','Skip = 2·T·tanθ','The full-skip surface distance equals twice the wall thickness multiplied by the tangent of the refracted angle.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Skip distance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11b7dd33-317e-58df-b5bc-d75e7dc1bc6a','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11b7dd33-317e-58df-b5bc-d75e7dc1bc6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11b7dd33-317e-58df-b5bc-d75e7dc1bc6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f4155200-6034-5ba3-93ed-5aac57fc5fa1','Half-skip','Half-skip refers to the beam path from the probe index point down to the first reflection at the far surface of the wall. The half-skip surface distance is T(tan theta) and the half-skip beam (sound) path is T/cos(theta), where T is thickness and theta the refracted angle. Reflectors reached before this first bounce lie in the first leg, and the half-skip position places the beam on the far surface.','Half-skip is the beam''s first trip down to the far wall. Its surface distance equals thickness times the tangent of the angle. Its beam path equals thickness divided by the cosine of the angle. Flaws reached before the bounce are in the first leg. Half-skip aims the beam at the far surface.','To define the first-leg beam geometry so reflectors up to the far surface can be located and probe placement set.','Used to place the probe for root inspection and to decide whether an indication lies in the first or second leg.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Full-skip','Skip distance','Sound path','Metal path','Refracted angle','Index point']::text[],ARRAY['Confusing the half-skip surface distance with the beam-path length','Assigning a second-leg indication to the first leg and mislocating its depth']::text[],ARRAY['Placing the probe at half-skip to inspect the weld root','Deciding an indication is first-leg because it appears before half-skip range']::text[],'intermediate','surface = T·tanθ ; sound path = T/cosθ','The half-skip surface distance equals thickness times the tangent of the angle, and the beam path equals thickness divided by the cosine of the angle.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Half-skip');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f4155200-6034-5ba3-93ed-5aac57fc5fa1','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f4155200-6034-5ba3-93ed-5aac57fc5fa1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f4155200-6034-5ba3-93ed-5aac57fc5fa1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b0a5be8-fb8e-5f99-82ac-93415a119a09','Full-skip','Full-skip refers to the beam path that travels from the index point down to the far surface and back up to the near surface (one complete skip) before reaching a reflector in the second leg. The full-skip surface distance is 2T(tan theta) and the full-skip beam path is 2T/cos(theta). Probe positions between half-skip and full-skip cover reflectors that must be caught on the second leg, such as the upper weld and cap region.','Full-skip is the beam''s trip down and back up to the top surface. Its surface distance equals twice the thickness times the tangent of the angle. Its beam path equals twice the thickness divided by the cosine. Flaws reached after the bounce are in the second leg. Full-skip helps cover the upper weld and cap.','To define second-leg beam geometry so upper-wall and cap reflectors are covered and correctly located.','Used to set probe stand-off for cap and upper-fusion-face coverage and to confirm second-leg indications.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Half-skip','Skip distance','Sound path','Metal path','Refracted angle','Angle-beam testing']::text[],ARRAY['Treating a full-skip (second-leg) echo as a first-leg reflector and misplacing its depth','Ignoring extra attenuation and beam spread over the longer full-skip path']::text[],ARRAY['Positioning the probe near full-skip to inspect the weld cap','Confirming a second-leg indication using full-skip geometry']::text[],'intermediate','surface = 2·T·tanθ ; sound path = 2T/cosθ','The full-skip surface distance equals twice the thickness times the tangent of the angle, and the beam path equals twice the thickness divided by the cosine.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Full-skip');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b0a5be8-fb8e-5f99-82ac-93415a119a09','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b0a5be8-fb8e-5f99-82ac-93415a119a09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b0a5be8-fb8e-5f99-82ac-93415a119a09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77f60adf-7315-55ba-b081-ef847ccb5f33','Index point','The index point (beam exit point) is the location on the contact face of an angle-beam probe or wedge where the beam axis leaves the probe and enters the test material. It is the reference origin from which surface distance and skip distances are measured, and it is established by maximising the echo from a calibration-block radius (for example the 100 mm arc of an IIW block).','The index point is where the angled beam leaves the wedge into the part. It is the spot all surface distances are measured from. Testers find it using a curved slot on a calibration block. They slide the probe to peak the arc echo. That peak marks the exit point.','To provide the measurement origin on the probe for locating reflectors by surface and skip distance.','Marked on the wedge during setup by peaking the calibration-block radius echo, then used for all flaw-location measurements.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Refracted angle','Calibration block','Sound path','Skip distance','Wedge delay','Half-skip']::text[],ARRAY['Using an outdated index point after wedge wear shifts the exit point','Measuring surface distance from the probe edge instead of the true index point']::text[],ARRAY['Peaking the calibration-block arc echo to mark the index point','Re-checking the index point after wedge wear before a weld scan']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Index point');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77f60adf-7315-55ba-b081-ef847ccb5f33','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77f60adf-7315-55ba-b081-ef847ccb5f33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77f60adf-7315-55ba-b081-ef847ccb5f33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76e3383d-490a-550c-aeb6-ad7ff4ea29d1','Probe delay','Probe delay (probe zero, or zero offset) is the fixed time interval between the instrument''s electrical excitation pulse and the moment sound actually enters the test material, arising from travel through the transducer wear face, matching layers, and any internal delay element. It must be measured and subtracted during calibration so that displayed sound-path or thickness readings represent only travel within the material.','Probe delay is the time before the sound leaves the probe and enters the part. Sound must first cross the probe''s face and inner layers. This delay adds to every reading. Calibration measures it and takes it out. Then the display shows only travel in the material.','To account for the internal travel time of the probe so measured distances reflect only the material path.','Set during instrument zeroing on known thicknesses so thickness and sound-path readings are accurate.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Wedge delay','Delay line probe','Calibration block','Sound path','Contact testing','Reference reflector']::text[],ARRAY['Failing to re-zero probe delay after changing probes or wear faces','Confusing probe delay with wedge delay in angle-beam setups']::text[],ARRAY['Zeroing a thickness gauge on a step wedge before measuring','Re-checking probe zero after fitting a new wear face']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Probe delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76e3383d-490a-550c-aeb6-ad7ff4ea29d1','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76e3383d-490a-550c-aeb6-ad7ff4ea29d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76e3383d-490a-550c-aeb6-ad7ff4ea29d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '18f9d168-2b04-5737-9855-8bc7ab4f0068','Wedge delay','Wedge delay is the time the ultrasonic pulse spends travelling within the angle-beam wedge (or delay line) before entering the test material, equal to the round-trip path length in the wedge divided by the wedge sound velocity. It is measured during calibration, typically by maximising a calibration-block radius echo, and subtracted so that displayed sound path and depth represent only in-material travel.','Wedge delay is the time the pulse spends inside the wedge. Sound travels through the wedge before reaching the metal. This time equals the wedge path divided by its sound speed. Calibration measures it and removes it. Then readings show only travel in the part.','To remove the wedge travel time from measurements so reflector depth and sound path reflect only the material.','Calibrated on an IIW or similar block by peaking the radius echo, then applied to all angle-beam location calculations.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Probe delay','Refracted angle','Calibration block','Index point','Sound path','Shear-wave probe']::text[],ARRAY['Neglecting wedge wear that changes the delay and shifts all readings','Using a wedge delay calibrated at one temperature when wedge velocity has changed with heat']::text[],ARRAY['Calibrating wedge delay on an IIW block before weld scanning','Rechecking wedge delay after the wedge wears down']::text[],'intermediate','t_wedge = 2·L_w / c_wedge','The wedge delay equals twice the beam path length in the wedge divided by the sound velocity of the wedge material.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wedge delay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '18f9d168-2b04-5737-9855-8bc7ab4f0068','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='18f9d168-2b04-5737-9855-8bc7ab4f0068') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='18f9d168-2b04-5737-9855-8bc7ab4f0068');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a687e104-431f-55d0-86fc-5bd63920106b','Refracted angle','The refracted angle is the angle between the beam axis and the surface normal after the ultrasonic wave crosses from the wedge into the test material, governed by Snell''s law: sin(theta1)/c1 = sin(theta2)/c2, where c1 and c2 are the sound velocities in the wedge and material. Because velocity differs between materials, the actual refracted angle in the part may differ from the wedge''s nominal marking and must be verified on the intended material.','The refracted angle is the beam''s angle inside the part after it bends. The beam bends as it crosses from wedge to metal. Snell''s law links the angles to the sound speeds. Because speeds differ, the real angle can differ from the wedge label. Testers check it on the actual material.','To define the true beam angle in the material, which underlies all flaw-location and skip-distance calculations.','Verified on a calibration block for the specific material so depth and surface-distance calculations are correct.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Angle-beam testing','Shear-wave probe','Skip distance','Sound path','Beam skew','Wedge delay']::text[],ARRAY['Assuming the wedge''s marked angle is the refracted angle regardless of material velocity','Ignoring that the angle shifts if material velocity differs from the calibration standard']::text[],ARRAY['Verifying a 60-degree probe''s true angle on a steel block','Recalculating the refracted angle for a material with a different velocity']::text[],'intermediate','sinθ₁ / c₁ = sinθ₂ / c₂','The sine of the angle divided by the sound speed is equal on both sides of the interface, relating the wedge angle to the refracted angle.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Refracted angle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a687e104-431f-55d0-86fc-5bd63920106b','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a687e104-431f-55d0-86fc-5bd63920106b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a687e104-431f-55d0-86fc-5bd63920106b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8fb51809-8637-56c3-ab7b-210b0c9f9e39','Shear-wave velocity','The shear-wave (transverse) velocity is the propagation speed of a wave whose particle motion is perpendicular to the direction of travel, given for an isotropic solid by c_s = sqrt(G/rho) = sqrt(E / [2 rho (1+nu)]), where G is the shear modulus, rho density, E Young''s modulus, and nu Poisson''s ratio. In steel it is roughly half the longitudinal velocity (about 3230 m/s), a value used to calibrate angle-beam instruments and compute refracted angles and paths.','Shear-wave velocity is the speed of a side-to-side sound wave in a solid. It depends on the material''s stiffness in shear and its density. In steel it is about half the straight-wave speed. Testers use this value to set up angle-beam gear. It also fixes the refracted angle.','To provide the velocity constant needed for angle-beam calibration, refracted-angle calculation, and depth measurement.','Entered into flaw detectors for shear-wave weld inspection and used to compute sound paths and refracted angles.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Longitudinal-wave velocity','Shear-wave probe','Refracted angle','Angle-beam testing','Sound path','Acoustic impedance']::text[],ARRAY['Using the longitudinal velocity when the beam is actually a shear wave','Assuming one fixed steel value for all alloys and temperatures without verification']::text[],ARRAY['Entering the shear velocity to calibrate a weld inspection','Computing the refracted angle from wedge and shear velocities']::text[],'intermediate','c_s = √(G/ρ) = √(E / [2ρ(1+ν)])','Shear velocity equals the square root of the shear modulus divided by density, which also equals Young''s modulus over twice the density times one plus Poisson''s ratio.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shear-wave velocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8fb51809-8637-56c3-ab7b-210b0c9f9e39','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8fb51809-8637-56c3-ab7b-210b0c9f9e39') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8fb51809-8637-56c3-ab7b-210b0c9f9e39');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1bc7753b-cc18-5f14-a08e-4ee01433f4bf','Longitudinal-wave velocity','The longitudinal-wave (compression) velocity is the propagation speed of a wave whose particle motion is parallel to the direction of travel, given for an isotropic bulk solid by c_l = sqrt(E(1-nu) / [rho (1+nu)(1-2nu)]), where E is Young''s modulus, nu Poisson''s ratio, and rho density. It is the fastest bulk mode (about 5900 m/s in steel) and is used for thickness gauging and straight-beam calibration.','Longitudinal-wave velocity is the speed of a push-pull sound wave in a solid. The material moves back and forth along the beam. It depends on the material''s stiffness and density. It is the fastest wave type, about 5900 m/s in steel. Testers use it for thickness and straight-beam work.','To supply the velocity constant for thickness measurement, straight-beam calibration, and velocity-based material checks.','Entered into thickness gauges and flaw detectors for compression-wave work and used to convert time-of-flight to thickness.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Shear-wave velocity','Longitudinal-wave probe','Straight-beam testing','Metal path','Back-wall echo','Acoustic impedance']::text[],ARRAY['Using a generic steel velocity for a different alloy and misreading thickness','Confusing longitudinal with shear velocity during setup']::text[],ARRAY['Setting the velocity to gauge steel wall thickness','Calibrating a straight-beam probe on a known-velocity block']::text[],'intermediate','c_l = √(E(1−ν) / [ρ(1+ν)(1−2ν)])','Longitudinal velocity equals the square root of Young''s modulus times one minus Poisson''s ratio, divided by density times one plus Poisson''s ratio times one minus twice Poisson''s ratio.','3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Longitudinal-wave velocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1bc7753b-cc18-5f14-a08e-4ee01433f4bf','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1bc7753b-cc18-5f14-a08e-4ee01433f4bf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1bc7753b-cc18-5f14-a08e-4ee01433f4bf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96e7834e-08c3-56ca-855f-cc95ad4945d3','Calibration block','A calibration block (reference or standard block) is a test piece of known material, geometry, and reflector content used to standardise an ultrasonic instrument and probe, establishing velocity, delay, refracted angle, index point, range, and sensitivity. Standard designs such as the IIW (V1/V2), step wedges, and DSC blocks carry defined radii, holes, and slots so setups are traceable and repeatable across instruments and technicians.','A calibration block is a known test piece used to set up the gear. It has set shapes, holes, and slots of known size. Testers use it to fix speed, delay, angle, and range. It also sets the sensitivity level. This keeps results steady and traceable.','To provide known references so instrument settings are accurate, traceable, and repeatable before inspection.','Used at the start of every job to set range, angle, index point, and reference sensitivity on standard blocks like the IIW.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Reference reflector','Side-drilled hole','Flat-bottom hole','Index point','Wedge delay','DAC curve']::text[],ARRAY['Calibrating on a block of different velocity or temperature than the test part','Using a worn or damaged block whose reflectors no longer match nominal dimensions']::text[],ARRAY['Setting range and angle on an IIW block before a welding inspection','Establishing reference sensitivity on a block with side-drilled holes']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calibration block');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96e7834e-08c3-56ca-855f-cc95ad4945d3','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96e7834e-08c3-56ca-855f-cc95ad4945d3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96e7834e-08c3-56ca-855f-cc95ad4945d3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b8d1768c-5f53-5a8a-bac4-09b21ff8aa32','Reference reflector','A reference reflector is a reflector of known type, size, and location (such as a side-drilled hole, flat-bottom hole, notch, or block radius) used to set a reproducible sensitivity or distance reference against which flaw indications are compared. Reference reflectors underpin sizing methods like DAC, TCG, and DGS by providing calibrated echo amplitudes at known ranges.','A reference reflector is a known, made target used to set sensitivity. It has a set size and depth, like a drilled hole or notch. Its echo gives a fixed level to compare flaws against. Sizing curves are built from these echoes. It makes flaw calls consistent.','To provide a known, repeatable echo for setting sensitivity and for comparing and sizing real indications.','Used to build DAC and TCG curves and to set DGS references for weld and forging inspection.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Calibration block','Side-drilled hole','Flat-bottom hole','Notch reflector','DAC curve','DGS method']::text[],ARRAY['Comparing a real flaw to a reference reflector of an unsuitable type or orientation','Assuming equal echo amplitude means equal flaw size regardless of reflector shape']::text[],ARRAY['Building a DAC from side-drilled-hole echoes at several depths','Setting reference level on a flat-bottom hole before sizing']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference reflector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b8d1768c-5f53-5a8a-bac4-09b21ff8aa32','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b8d1768c-5f53-5a8a-bac4-09b21ff8aa32') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b8d1768c-5f53-5a8a-bac4-09b21ff8aa32');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '164fc8d4-65e9-510a-a1c5-8bcae2f6f4e7','Side-drilled hole','A side-drilled hole (SDH) is a cylindrical hole drilled parallel to the test surface and perpendicular to the beam path, used as a reference reflector because it presents a consistent, orientation-independent cylindrical target at a known depth. Sets of side-drilled holes at graded depths are used to construct DAC/TCG curves and to verify sensitivity and resolution in calibration blocks.','A side-drilled hole is a hole bored sideways into a block. The beam hits its round side, so its echo stays steady from many angles. Holes are placed at set depths in the block. Their echoes build sizing curves. They also check sensitivity and resolution.','To provide a stable, angle-tolerant reference echo at known depth for building sizing curves and checking performance.','Used in calibration blocks to set DAC and TCG and to verify angle-beam sensitivity across a depth range.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Flat-bottom hole','Reference reflector','Calibration block','DAC curve','TCG','Notch reflector']::text[],ARRAY['Treating a side-drilled-hole reference as equivalent to a flat-bottom-hole (equivalent-area) reference','Ignoring beam-spread effects when holes are closely spaced in depth']::text[],ARRAY['Building an angle-beam DAC from graded side-drilled holes','Checking resolution between two closely spaced holes']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Side-drilled hole');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '164fc8d4-65e9-510a-a1c5-8bcae2f6f4e7','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='164fc8d4-65e9-510a-a1c5-8bcae2f6f4e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='164fc8d4-65e9-510a-a1c5-8bcae2f6f4e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3101fc61-1816-5152-8332-f94085681134','Flat-bottom hole','A flat-bottom hole (FBH) is a hole drilled with a flat, disc-shaped bottom oriented perpendicular to the beam, used as a reference reflector whose flat end acts as an ideal disc reflector of known diameter at a known distance. Flat-bottom holes underpin equivalent-reflector-size sizing and DGS/AVG references and are common in immersion and straight-beam calibration standards.','A flat-bottom hole is a hole with a flat, round bottom facing the beam. Its flat end reflects like a small disc of known size. It sits at a known depth in the block. Testers use it to size flaws by equivalent disc area. It also sets DGS references.','To provide a disc-like reference of known area and depth for equivalent-size flaw sizing and sensitivity setting.','Used in straight-beam and immersion calibration for equivalent-reflector sizing and DGS reference setting in forgings and plate.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Side-drilled hole','Reference reflector','DGS method','Calibration block','Straight-beam testing','Indication sizing']::text[],ARRAY['Assuming a real flaw reflects like an ideal flat disc of the same equivalent size','Poor hole-bottom flatness or tilt giving a low, misleading reference echo']::text[],ARRAY['Setting equivalent-flaw-size sensitivity on flat-bottom holes','Referencing a DGS setup to a flat-bottom-hole echo']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flat-bottom hole');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3101fc61-1816-5152-8332-f94085681134','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3101fc61-1816-5152-8332-f94085681134') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3101fc61-1816-5152-8332-f94085681134');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf0a8f4e-8a48-5d19-90fc-b1bed6b7244b','Notch reflector','A notch reflector is a machined rectangular or V-shaped slot, cut to a defined depth and length on a surface (or a specified location) of a reference standard, used to simulate surface-breaking or near-surface planar flaws such as cracks. Notches provide corner-trap and tip responses for calibrating the detection and sizing of surface-connected defects, notably in weld and tubular inspection.','A notch reflector is a cut slot of set depth and length in a block. It mimics a surface crack for the beam. The beam traps in the corner and reflects strongly. Testers use it to set up crack detection and sizing. It is common in weld and pipe checks.','To simulate surface-breaking planar flaws for calibrating the detection and sizing of cracks and similar defects.','Used to set sensitivity for surface-crack detection and to calibrate corner and tip echoes in weld and tube inspection.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Reference reflector','Side-drilled hole','Crack-tip diffraction','Calibration block','Indication sizing','Angle-beam testing']::text[],ARRAY['Assuming a machined notch reflects exactly like a real, rough, tight crack','Using a notch of the wrong depth or orientation for the target flaw type']::text[],ARRAY['Setting crack sensitivity on an inner-diameter notch in a pipe standard','Calibrating corner and tip echoes on a machined notch']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Notch reflector');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf0a8f4e-8a48-5d19-90fc-b1bed6b7244b','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf0a8f4e-8a48-5d19-90fc-b1bed6b7244b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf0a8f4e-8a48-5d19-90fc-b1bed6b7244b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7a40741-cd6a-533f-a9a6-9b25c94102d4','DAC curve','A DAC (distance-amplitude correction) curve is a reference line drawn on the A-scan by recording the peak echo amplitudes from identical reference reflectors (typically side-drilled holes) at increasing sound-path distances, then connecting the points. Because attenuation and beam spread reduce echo height with range, the DAC compensates for distance so that indications can be assessed against a distance-adjusted reference regardless of depth.','A DAC curve shows how a set target''s echo fades with distance. Testers record echoes from equal reflectors at several depths. The points are joined into a curve on the screen. Deeper echoes are weaker because of spread and loss. The curve lets flaws be judged fairly at any depth.','To correct for the drop in echo height with distance so reflectors at different depths are assessed on a common reference.','Built at setup from side-drilled holes and used as the accept/reject reference line during weld and forging inspection.','Ultrasonics, NDT & Industrial Inspection',ARRAY['TCG','Reference reflector','Side-drilled hole','Indication sizing','Calibration block','DGS method']::text[],ARRAY['Building a DAC on a material of different attenuation than the test part','Applying a DAC beyond the depth range of the reflectors used to construct it']::text[],ARRAY['Plotting a DAC from side-drilled holes for weld acceptance','Comparing a weld indication to the DAC reference line']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='DAC curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7a40741-cd6a-533f-a9a6-9b25c94102d4','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7a40741-cd6a-533f-a9a6-9b25c94102d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7a40741-cd6a-533f-a9a6-9b25c94102d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0192456b-bafb-517e-bb5a-d959f3449305','TCG','Time-corrected gain (TCG) is an instrument function that applies depth-dependent gain to the received signal so that echoes from identical reference reflectors appear at the same screen amplitude regardless of sound-path distance, effectively flattening the DAC to a horizontal reference line. TCG compensates for attenuation and beam spread electronically, easing evaluation and improving consistency, especially in phased-array and automated inspection.','TCG adds extra gain to echoes from deeper reflectors. It raises weak far echoes so equal targets read the same height. This flattens the sloping DAC into a straight line. It makes flaw judging easier at all depths. It is common in phased-array work.','To equalise echo amplitudes from equal reflectors across depth by boosting gain with time, simplifying evaluation.','Set from reference reflectors at several depths so a single threshold applies at all ranges in weld and automated inspection.','Ultrasonics, NDT & Industrial Inspection',ARRAY['DAC curve','Reference reflector','Side-drilled hole','Indication sizing','Electronic scanning','Calibration block']::text[],ARRAY['Setting TCG so high at depth that noise is amplified into false indications','Building TCG on reflectors that do not span the full inspection depth']::text[],ARRAY['Setting TCG points on side-drilled holes for even sensitivity','Using a flat TCG reference in a phased-array weld scan']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='TCG');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0192456b-bafb-517e-bb5a-d959f3449305','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0192456b-bafb-517e-bb5a-d959f3449305') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0192456b-bafb-517e-bb5a-d959f3449305');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '70598722-6c11-55b0-ab01-60204f362dcf','DGS method','The DGS (distance-gain-size) method, known in German as AVG, is a sizing technique that uses theoretically derived curves relating echo amplitude (gain) to sound-path distance for a family of equivalent flat-bottom-hole reflector sizes, normalised to a probe''s characteristics. By comparing an indication''s amplitude and range to the appropriate curve, the equivalent reflector size is estimated using a single reference echo (such as a back wall or block radius) rather than many reference holes.','The DGS method sizes flaws using a chart of curves. Each curve is for one equivalent flaw size. The curves link echo strength to distance for a probe. Testers match a flaw''s echo and range to a curve. That gives an equivalent size from just one reference echo.','To estimate equivalent reflector size from echo amplitude and distance using probe-specific curves and a single reference, reducing the need for many reference blocks.','Used with calibrated probes for forging and weld sizing where the equivalent flat-bottom-hole size is estimated from a back-wall or radius reference.','Ultrasonics, NDT & Industrial Inspection',ARRAY['DAC curve','TCG','Flat-bottom hole','Reference reflector','Indication sizing','Calibration block']::text[],ARRAY['Applying DGS curves for the wrong probe or frequency to an indication','Treating the equivalent reflector size as the true physical flaw size']::text[],ARRAY['Sizing a forging inclusion by matching its echo to a DGS curve','Setting a recording level from an equivalent flat-bottom-hole size']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='DGS method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '70598722-6c11-55b0-ab01-60204f362dcf','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='70598722-6c11-55b0-ab01-60204f362dcf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='70598722-6c11-55b0-ab01-60204f362dcf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '271c228d-5190-53b9-b4f2-bc11e707bbb9','Indication sizing','Indication sizing is the process of estimating the dimensions (length, height or through-wall extent, and position) of a detected ultrasonic indication to support fitness-for-service and accept/reject decisions. Methods include amplitude-based sizing against references (DAC, TCG, DGS), the 6 dB or 20 dB drop techniques for length, and tip-diffraction or time-of-flight techniques for through-wall height, chosen according to code and flaw type.','Indication sizing means estimating how big a found flaw is. Testers judge its length, height, and place. Some methods compare echo height to references. Others move the probe and track amplitude drops. Tip and time-of-flight methods give the through-wall height.','To quantify flaw dimensions so acceptance, rejection, and fitness-for-service decisions can be made against code limits.','Performed on weld and component flaws using drop techniques and tip diffraction to feed acceptance criteria and engineering assessment.','Ultrasonics, NDT & Industrial Inspection',ARRAY['DAC curve','DGS method','Crack-tip diffraction','Lack-of-fusion indication','Reference reflector','TCG']::text[],ARRAY['Using amplitude-drop length sizing on flaws smaller than the beam width and overstating size','Relying on amplitude alone for through-wall height instead of tip-based methods']::text[],ARRAY['Sizing a weld crack''s through-wall height by tip diffraction','Measuring indication length with the 6 dB drop technique']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Indication sizing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '271c228d-5190-53b9-b4f2-bc11e707bbb9','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='271c228d-5190-53b9-b4f2-bc11e707bbb9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='271c228d-5190-53b9-b4f2-bc11e707bbb9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c1b2a14-cc3e-5eed-9bc3-8f02df727b96','Lack-of-fusion indication','A lack-of-fusion indication is an ultrasonic response from an incomplete metallurgical bond in a weld (between weld metal and base metal at the sidewall, or between passes) where the surfaces did not coalesce. Being planar and often favourably oriented to an angle beam striking the fusion face, lack of fusion typically produces a strong, well-defined reflection and is a critical, often rejectable, weld defect.','A lack-of-fusion indication is an echo from a weld that did not fully bond. The weld metal did not fuse to the base metal or to a prior pass. This leaves a flat gap along the fusion line. An angled beam hits it squarely and gives a strong echo. It is a serious weld flaw.','To identify a planar bonding defect in welds that an angle beam can detect strongly and that usually fails acceptance.','Sought during angle-beam weld inspection by aiming the beam at the sidewall fusion faces at the correct skip position.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Angle-beam testing','Indication sizing','Refracted angle','Skip distance','Crack-tip diffraction','Reference reflector']::text[],ARRAY['Missing sidewall lack of fusion by not aiming the beam perpendicular to the fusion face','Confusing a geometric root or cap echo with a lack-of-fusion indication']::text[],ARRAY['Detecting sidewall lack of fusion at the correct skip distance','Distinguishing a lack-of-fusion echo from a geometry signal']::text[],'intermediate',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lack-of-fusion indication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c1b2a14-cc3e-5eed-9bc3-8f02df727b96','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c1b2a14-cc3e-5eed-9bc3-8f02df727b96') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c1b2a14-cc3e-5eed-9bc3-8f02df727b96');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '59aa2d34-0f78-55d7-96c1-f7d95e1c2e65','Crack-tip diffraction','Crack-tip diffraction is the scattering of ultrasonic energy from the tip (edge) of a crack, producing a weak diffracted wavelet distinct from the strong specular reflection off the crack face. Because the diffracted signal originates at the tip, timing the diffracted arrivals allows accurate measurement of a crack''s through-wall height, forming the basis of tip-diffraction sizing and of the time-of-flight diffraction (TOFD) technique.','Crack-tip diffraction is a faint echo from the very edge of a crack. The crack face gives a strong echo, but the tip scatters a weak one. That tip signal marks where the crack ends. Timing it gives the crack''s height through the wall. This idea drives the TOFD method.','To locate a crack''s tip so its through-wall height can be measured accurately, independent of face-reflection amplitude.','Used in tip-diffraction sizing and TOFD to measure crack height for fitness-for-service assessment of welds.','Ultrasonics, NDT & Industrial Inspection',ARRAY['Indication sizing','Lack-of-fusion indication','Notch reflector','Angle-beam testing','Refracted angle','Time-of-flight diffraction']::text[],ARRAY['Overlooking the weak tip signal because it is far smaller than the face reflection','Mistaking a mode-converted or geometry echo for the true tip-diffracted signal']::text[],ARRAY['Sizing crack height by timing the tip-diffracted signal','Using TOFD to measure the through-wall extent of a weld crack']::text[],'advanced',NULL,NULL,'3a0d6514-af65-43d9-abc4-f4e84efeaba2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crack-tip diffraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '59aa2d34-0f78-55d7-96c1-f7d95e1c2e65','3a0d6514-af65-43d9-abc4-f4e84efeaba2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='59aa2d34-0f78-55d7-96c1-f7d95e1c2e65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='59aa2d34-0f78-55d7-96c1-f7d95e1c2e65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5f4b2212-a783-587a-a2f1-c6b5cb7bdb89','Direct sonification','Direct sonification is any approach in which the data themselves continuously determine sound through an explicit transfer function, so each data value drives an audible property such as frequency, level, or playback speed. It groups the data-driven techniques (audification and parameter mapping) and stands in contrast to indirect, symbolic representations such as earcons, where the sound is an arbitrary code chosen by the designer rather than a continuous image of the numbers.','In direct sonification, the data set the sound. A number is turned straight into a sound property. Bigger values might mean a higher or louder tone. The sound is a real picture of the numbers. It is not a made-up code you must memorize.','To let listeners hear the actual shape and trend of data by binding sound properties to values through a defined rule, rather than to fixed symbolic cues.','Used when an analyst wants the raw pattern of a signal to be audible, for example turning a sensor trace directly into a rising and falling tone in a monitoring tool.','Data Sonification & Auditory Display',ARRAY['Parameter mapping sonification','Audification','Model-based sonification','Earcon','Auditory display']::text[],ARRAY['Treating direct sonification as a synonym for audification, when audification is only one case of it','Assuming any sound tied to data is direct, even when the sounds are arbitrary symbolic codes']::text[],ARRAY['Turning a live temperature stream straight into a changing tone','Contrasting a data-driven display with an earcon menu in a design review']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direct sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5f4b2212-a783-587a-a2f1-c6b5cb7bdb89','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5f4b2212-a783-587a-a2f1-c6b5cb7bdb89') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5f4b2212-a783-587a-a2f1-c6b5cb7bdb89');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6f1be5f-fc21-5caf-9523-6159e1d69203','Interactive sonification','Interactive sonification is the use of sound to convey information in a system where the listener continuously controls the mapping or the data excitation through their own actions, so the sound responds in a tight perception-action loop. The user may scrub through data, adjust mapping parameters, or physically excite a data model, and the immediate auditory feedback guides the next action, making exploration an active rather than passive process.','Here the listener does not just hear data. They also act on it. You might drag through the data or poke a model. The sound answers right away. Your next move depends on what you just heard.','To close a fast feedback loop between user actions and sound so people can probe data actively and discover structure that a fixed playback would hide.','Seen in tools where a user moves a cursor over a plot and hears the values under it, or shakes a data model to hear how it responds.','Data Sonification & Auditory Display',ARRAY['Model-based sonification','Exploratory sonification','Brushing and linking','Auditory display','Real-time sonification']::text[],ARRAY['Confusing interactive sonification with any real-time sound, even when the user has no control','Ignoring latency, which breaks the perception-action loop that defines the technique']::text[],ARRAY['Scrubbing a cursor across a chart and hearing values under the pointer','Exciting a physical data model by hand and listening to its response']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interactive sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6f1be5f-fc21-5caf-9523-6159e1d69203','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6f1be5f-fc21-5caf-9523-6159e1d69203') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6f1be5f-fc21-5caf-9523-6159e1d69203');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f0ded4b9-bf97-5a55-8ca6-fa84f0e3f320','Exploratory sonification','Exploratory sonification is the application of auditory display to open-ended data analysis, where the goal is to discover unknown structure, trends, or anomalies rather than to monitor for a predefined event. It parallels exploratory data analysis in statistics: the listener forms and tests hypotheses by listening, often adjusting mappings and time scales to reveal features that were not anticipated in advance.','This is listening to data to find surprises. You do not know yet what is there. You try different sounds and speeds. You listen for patterns or odd events. It is like poking around a data set by ear.','To support hypothesis-forming analysis by letting the ear pick out patterns, clusters, and outliers that were not specified ahead of time.','Used by researchers scanning long or complex records, such as listening through a night of sensor data to spot unusual episodes worth closer study.','Data Sonification & Auditory Display',ARRAY['Interactive sonification','Auditory graph','Overview sonification','Multivariate sonification','Auditory display']::text[],ARRAY['Confusing exploratory use with alarm or monitoring use, which targets a known event','Expecting a single fixed mapping to reveal everything, instead of trying several']::text[],ARRAY['Scanning a long telescope time series by ear for unexpected bursts','Trying several mappings to find hidden structure in survey data']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exploratory sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f0ded4b9-bf97-5a55-8ca6-fa84f0e3f320','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f0ded4b9-bf97-5a55-8ca6-fa84f0e3f320') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f0ded4b9-bf97-5a55-8ca6-fa84f0e3f320');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '051ce3b9-7592-547b-af23-2ec65bfe3cdc','Real-time sonification','Real-time sonification renders data to sound as the data arrive, with only a short and bounded delay, so the auditory output tracks an ongoing process moment by moment. It requires the mapping and synthesis to keep pace with the incoming data rate, and it is the basis of live monitoring displays where the listener must react to current conditions.','The sound plays as the data come in. There is only a tiny delay. What you hear is happening now. This lets you react while a process runs. It is the base of live sound monitoring.','To give an immediate audible picture of a live process so operators can notice changes and respond without waiting for a later report.','Found in patient monitors, process-control rooms, and live sensor dashboards where a technician listens to current status while doing other work.','Data Sonification & Auditory Display',ARRAY['Offline sonification','Streaming sonification','Live data sonification','Alarm sonification','Auditory display']::text[],ARRAY['Assuming real-time means zero delay, when a small bounded latency is always present','UNSAFE: relying on a monitoring tone alone for a safety-critical alarm without a tested backup indicator']::text[],ARRAY['Listening to a patient monitor while attending to a procedure','Hearing a plant sensor stream change as conditions shift']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-time sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '051ce3b9-7592-547b-af23-2ec65bfe3cdc','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='051ce3b9-7592-547b-af23-2ec65bfe3cdc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='051ce3b9-7592-547b-af23-2ec65bfe3cdc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1d415b3e-01b9-532e-884d-175584af5082','Offline sonification','Offline sonification renders a stored data set to sound after it has been fully collected, so the time base of the display is decoupled from the time of acquisition. Because the whole record is available in advance, the designer can freely rescale time, apply global normalization, and iterate on the mapping, at the cost of not tracking a live process.','Here the data are already saved. You make the sound later, not live. You can speed up or slow down time. You can also try mappings again and again. But it does not follow a live process.','To allow careful, repeatable rendering and analysis of complete records, with full freedom to rescale time and tune the mapping.','Used to review recorded logs, such as compressing a day of data into a short clip that an analyst plays back and re-plays.','Data Sonification & Auditory Display',ARRAY['Real-time sonification','Time compression','Exploratory sonification','Audification','Auditory display']::text[],ARRAY['Treating offline results as if they reflect live timing, which has been rescaled','Assuming offline rendering cannot be interactive, when a stored set can still be explored']::text[],ARRAY['Compressing a recorded day of readings into a short review clip','Re-rendering a saved data set with several mappings to compare them']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Offline sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1d415b3e-01b9-532e-884d-175584af5082','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1d415b3e-01b9-532e-884d-175584af5082') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1d415b3e-01b9-532e-884d-175584af5082');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd289e3d8-a98b-5f4a-8005-82d19fab9cb6','Live data sonification','Live data sonification is real-time auditory display driven by a continuously updating source, such as a sensor feed, network telemetry, or a market ticker, so the sound reflects the current state of an external system. It emphasizes that the data are genuinely being generated now, rather than replayed, and therefore that the display must handle open-ended, unpredictable input.','This turns a live feed into sound. The data are being made right now. The sound changes as the source changes. It never stops or repeats a fixed file. You hear the world as it happens.','To keep a listener aware of a running external source by mapping its current values to sound as they update.','Used to make ambient displays of ongoing feeds, such as turning live network traffic or weather sensors into a background soundscape.','Data Sonification & Auditory Display',ARRAY['Real-time sonification','Streaming sonification','Alarm sonification','Auditory display','Peripheral monitoring']::text[],ARRAY['Confusing live data sonification with playback of a recording, which is not live','Overloading the listener with detail so important changes are missed']::text[],ARRAY['Turning a live weather feed into an ambient background sound','Monitoring live network traffic by ear in an operations room']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Live data sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd289e3d8-a98b-5f4a-8005-82d19fab9cb6','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d289e3d8-a98b-5f4a-8005-82d19fab9cb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d289e3d8-a98b-5f4a-8005-82d19fab9cb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14b78db9-848a-59cd-b5bd-c8adee217f9b','Streaming sonification','Streaming sonification processes and renders data as an unbounded, continuously arriving sequence, updating the sound incrementally without ever holding the whole record in memory. It stresses the data-flow constraint: each sample must be mapped and sounded as it passes, so the mapping cannot depend on future values or on a global view of the entire set.','The data flow past in a long stream. You handle each piece as it arrives. You never store the whole thing. The mapping cannot peek ahead. The sound is built one step at a time.','To sonify open-ended feeds where the full data set is never available at once, using rules that work on each incoming value alone.','Applied to continuous telemetry and log streams, where a display must sound each event on arrival within a fixed memory budget.','Data Sonification & Auditory Display',ARRAY['Live data sonification','Real-time sonification','Event-based sonification','Auditory display','Buffering']::text[],ARRAY['Assuming a mapping can normalize to the global maximum, which is unknown in a stream','Confusing streaming with batch offline rendering of a saved file']::text[],ARRAY['Sounding each log event as it arrives in a server feed','Sonifying a continuous telemetry stream with only local scaling']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Streaming sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14b78db9-848a-59cd-b5bd-c8adee217f9b','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14b78db9-848a-59cd-b5bd-c8adee217f9b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14b78db9-848a-59cd-b5bd-c8adee217f9b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97c52373-9e5b-5729-9563-0e8531142da6','Pitch mapping','Pitch mapping assigns a data variable to the fundamental frequency of a tone, so changes in the value are heard as changes in pitch. Because pitch perception is roughly logarithmic in frequency, designers often map data to log-frequency (or to musical intervals) rather than to linear hertz, and must choose polarity and range so that higher values reliably read as higher pitch across the display.','Pitch mapping turns a value into how high a tone sounds. A bigger value gives a higher pitch. Our ears hear pitch in steps, not flat hertz. So designers often space tones by musical steps. This keeps the changes easy to hear.','To exploit the ear''s fine sensitivity to pitch, giving a clear and well-ordered channel for showing how one variable rises and falls.','The most common mapping in auditory graphs and monitors, such as a rising tone for a climbing value on a pulse oximeter.','Data Sonification & Auditory Display',ARRAY['Log-frequency mapping','Pitch-scale mapping','Parameter mapping sonification','Auditory graph','Loudness mapping']::text[],ARRAY['Mapping data to linear frequency, which makes low-value changes hard to hear','Reversing polarity so higher values sound lower, confusing listeners']::text[],ARRAY['Encoding a stock price as a rising and falling tone','Showing blood oxygen level as pitch on a patient monitor']::text[],'beginner','f = f_min · (f_max/f_min)^((d − d_min)/(d_max − d_min))','The tone frequency scales exponentially between a chosen low and high frequency as the data value moves from its minimum to its maximum, giving equal pitch steps for equal value steps.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pitch mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97c52373-9e5b-5729-9563-0e8531142da6','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97c52373-9e5b-5729-9563-0e8531142da6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97c52373-9e5b-5729-9563-0e8531142da6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2de1456-d757-59c5-a3a2-31a601b8f4e7','Loudness mapping','Loudness mapping assigns a data variable to the perceived loudness of a sound, usually by controlling amplitude or level in decibels. Because loudness perception is compressive and context-dependent, and because absolute loudness judgments are weak, it is treated as a coarse, secondary channel, better suited to emphasis and salience than to reading precise values.','Loudness mapping ties a value to how loud a sound is. Bigger values sound louder. Our ears judge loudness poorly in exact terms. So this channel is rough, not precise. It works best to grab attention.','To draw attention or show rough magnitude through level, complementing pitch, which carries finer detail.','Used to make important events stand out or to show gross intensity, such as a louder tone as a value grows large.','Data Sonification & Auditory Display',ARRAY['Pitch mapping','Parameter mapping sonification','Auditory variable','Timbre mapping','Alarm sonification']::text[],ARRAY['Relying on loudness for precise readings, which the ear cannot judge well','UNSAFE: mapping data to very high playback levels that risk hearing damage over long sessions']::text[],ARRAY['Making an alert grow louder as a value approaches a limit','Using level to show rough signal strength in a monitor']::text[],'beginner','L = L_min + (L_max − L_min)·(d − d_min)/(d_max − d_min)  [dB]','The playback level in decibels moves linearly between a chosen quiet and loud limit as the data value rises from its minimum to its maximum.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudness mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2de1456-d757-59c5-a3a2-31a601b8f4e7','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2de1456-d757-59c5-a3a2-31a601b8f4e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2de1456-d757-59c5-a3a2-31a601b8f4e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1a5de49-d37c-5a8b-a3ad-0ce425206449','Timbre mapping','Timbre mapping assigns a data variable to aspects of a sound''s spectral quality, such as brightness, harmonic content, or the choice of instrument, so different values take on different tone colors. Timbre is multidimensional and partly categorical, which makes it useful for distinguishing several data streams by their character, but hard to use for reading a value along a single ordered scale.','Timbre mapping ties a value to a sound''s tone color. Think of a flute versus a reed. Different values get a different quality. This is great for telling streams apart. It is weak for reading an exact amount.','To separate or label multiple data streams by giving each a distinct sonic character that the ear groups and tells apart.','Used to assign different instruments or tone colors to different variables so a listener can follow several at once.','Data Sonification & Auditory Display',ARRAY['Filter mapping','Modulation mapping','Auditory variable','Multivariate sonification','Pitch mapping']::text[],ARRAY['Treating timbre as an ordered scale for reading values, when it is largely categorical','Choosing tone colors so similar that streams blur together']::text[],ARRAY['Giving each sensor its own instrument in a multi-channel display','Using brightness to distinguish two overlapping variables']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Timbre mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1a5de49-d37c-5a8b-a3ad-0ce425206449','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1a5de49-d37c-5a8b-a3ad-0ce425206449') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1a5de49-d37c-5a8b-a3ad-0ce425206449');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6183771e-9f6d-5741-8684-623f0ca241b8','Duration mapping','Duration mapping assigns a data variable to the length of a sound event, so larger values produce longer notes or gaps and smaller values produce shorter ones. It is a straightforward temporal channel, but it competes with the overall time base of the display and with rhythm, so long events can blur ordering and reduce the rate at which data can be presented.','Duration mapping ties a value to how long a sound lasts. A bigger value gives a longer note. A smaller value gives a short one. Very long notes can slow the display. They can also blur the order of events.','To carry a variable in the time domain through note length, useful alongside pitch when a second ordered channel is needed.','Used to encode magnitude as note length in melodic data displays or to space events in a timeline.','Data Sonification & Auditory Display',ARRAY['Rhythm mapping','Parameter mapping sonification','Auditory variable','Pitch mapping','Time compression']::text[],ARRAY['Using durations so long that events overlap and ordering is lost','Confusing duration mapping with tempo or rhythm, which act on the whole pattern']::text[],ARRAY['Encoding transaction size as note length in a data melody','Spacing timeline events by their measured length']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Duration mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6183771e-9f6d-5741-8684-623f0ca241b8','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6183771e-9f6d-5741-8684-623f0ca241b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6183771e-9f6d-5741-8684-623f0ca241b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d62cc3c-25a1-5c42-9186-a0d541e034ed','Rhythm mapping','Rhythm mapping assigns data to the temporal pattern of events, controlling inter-onset intervals, tempo, or the grouping and accenting of sounds, so structure in the data is heard as rhythmic structure. Because listeners are highly sensitive to timing and to breaks in an established beat, rhythm is a powerful channel for signaling regularity, change, and events against a steady background.','Rhythm mapping ties data to timing patterns. It sets the gaps between sounds and the beat. A steady beat is easy to follow. A break in it grabs attention fast. So rhythm is strong for showing change.','To use the ear''s keen sense of timing so that regularity, tempo, and disruptions in a beat carry meaning.','Used to speed a click train as a value rises, or to break a steady rhythm when an event occurs, as in a Geiger-style display.','Data Sonification & Auditory Display',ARRAY['Duration mapping','Tempo','Parameter mapping sonification','Auditory variable','Event-based sonification']::text[],ARRAY['Setting event rates so high that individual onsets fuse into a tone','Assuming listeners read exact tempo values, when they mainly notice change']::text[],ARRAY['Speeding a click train as a counter increases','Breaking a steady beat to flag a threshold crossing']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rhythm mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d62cc3c-25a1-5c42-9186-a0d541e034ed','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d62cc3c-25a1-5c42-9186-a0d541e034ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d62cc3c-25a1-5c42-9186-a0d541e034ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be340d36-1c18-5735-932f-6e0142aede1a','Spatial mapping','Spatial mapping assigns a data variable to the apparent position of a sound source, using cues such as inter-aural level and time differences, or head-related filtering, to place sounds left-right, and with more effort in depth and elevation. It provides an additional channel that can separate concurrent streams and give a spatial sense of where data lie, though vertical and distance cues are weaker and more listener-dependent.','Spatial mapping ties a value to where a sound seems to come from. It can move a sound left or right. This helps separate many streams at once. Left-right works best for our ears. Up-down and distance are harder to hear.','To add a location channel that helps listeners separate simultaneous streams and sense where values sit in space.','Used in headphone and multi-speaker displays to place each data stream at its own position so several can be followed together.','Data Sonification & Auditory Display',ARRAY['Auditory variable','Multivariate sonification','Timbre mapping','Auditory display','Panning']::text[],ARRAY['Relying on elevation or distance cues, which are weak and vary by listener','Assuming loudspeaker panning gives the same precise image as headphone rendering']::text[],ARRAY['Placing each sensor stream at a different pan position in headphones','Using left-right position to separate two data channels']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be340d36-1c18-5735-932f-6e0142aede1a','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be340d36-1c18-5735-932f-6e0142aede1a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be340d36-1c18-5735-932f-6e0142aede1a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '43b4dcb4-0864-5027-9007-4f87e3f2a91d','Filter mapping','Filter mapping assigns a data variable to the parameters of a filter applied to a sound source, most often the cutoff frequency or resonance of a low-pass or band-pass filter, so the value is heard as a change in brightness or spectral emphasis. It is a specific way to achieve timbral mapping, giving a continuous, ordered-sounding change in tone color that is easy to synthesize.','Filter mapping ties a value to a filter''s setting. Moving the cutoff makes a sound brighter or duller. So the value is heard as tone color. It is a simple way to shape timbre. Higher values often sound brighter.','To provide a continuous, easily generated timbral channel by sweeping filter settings with the data value.','Used in synthesis-based displays where a value opens or closes a filter, brightening a tone as it rises.','Data Sonification & Auditory Display',ARRAY['Timbre mapping','Modulation mapping','Parameter mapping sonification','Auditory variable','Cutoff frequency']::text[],ARRAY['Confusing filter mapping with pitch change, though it alters spectrum, not fundamental','Sweeping the filter so subtly that the change is inaudible']::text[],ARRAY['Opening a low-pass filter as a value climbs to brighten the tone','Mapping a second variable to filter resonance for extra emphasis']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '43b4dcb4-0864-5027-9007-4f87e3f2a91d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='43b4dcb4-0864-5027-9007-4f87e3f2a91d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='43b4dcb4-0864-5027-9007-4f87e3f2a91d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd2c30089-d34c-5feb-8302-12a901b7e0c3','Modulation mapping','Modulation mapping assigns a data variable to the rate or depth of a modulation applied to a carrier sound, such as amplitude modulation (tremolo), frequency modulation (vibrato), or timbral modulation. The resulting fluctuation gives a distinctive, attention-getting quality whose speed or intensity tracks the data, useful as a secondary channel or to flag a condition.','Modulation mapping ties a value to a wobble in the sound. It can shake the volume or the pitch. A faster or deeper wobble means a bigger value. This adds a lively, catchy channel. It is good for flagging a state.','To carry a variable through the rate or depth of a periodic fluctuation, adding a salient secondary cue.','Used to add vibrato or tremolo that deepens as a value grows, or to mark a special condition with a distinctive wobble.','Data Sonification & Auditory Display',ARRAY['Timbre mapping','Filter mapping','Parameter mapping sonification','Auditory variable','Tremolo']::text[],ARRAY['Setting modulation so deep it obscures pitch or level readings on the same tone','Confusing tremolo (amplitude) with vibrato (frequency) when specifying the mapping']::text[],ARRAY['Deepening vibrato as a variable increases','Adding tremolo to flag an out-of-range condition']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modulation mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd2c30089-d34c-5feb-8302-12a901b7e0c3','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d2c30089-d34c-5feb-8302-12a901b7e0c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d2c30089-d34c-5feb-8302-12a901b7e0c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd578fc2-aac7-5e08-ac5d-41780ca70f65','Auditory variable','An auditory variable is a controllable perceptual dimension of sound, such as pitch, loudness, timbre, duration, or spatial position, that a designer can use to carry information in an auditory display. The concept mirrors the visual variables of graphic design, and each auditory variable differs in resolution, ordering, polarity, and how much it interacts with the others when combined.','An auditory variable is a sound property you can control. Pitch, loudness, and timbre are examples. Each one can carry a piece of data. They are the sound versions of visual variables. Some are better for order or detail than others.','To give designers a named toolbox of sound dimensions from which to build a mapping, each with known strengths and limits.','Referenced when choosing which sound property should carry which variable in a display design.','Data Sonification & Auditory Display',ARRAY['Auditory display variable','Parameter mapping sonification','Pitch mapping','Loudness mapping','Timbre mapping']::text[],ARRAY['Assuming auditory variables are independent, when pitch and loudness interact perceptually','Treating all of them as equally good for reading precise values']::text[],ARRAY['Choosing pitch for the key variable and timbre to label streams','Comparing auditory variables when planning a mapping']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory variable');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd578fc2-aac7-5e08-ac5d-41780ca70f65','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd578fc2-aac7-5e08-ac5d-41780ca70f65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd578fc2-aac7-5e08-ac5d-41780ca70f65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e553fd2b-c42d-5b21-ac36-b3faf323161a','Auditory display variable','An auditory display variable is a perceptual sound dimension considered specifically in its role within a display, that is, as a mapped channel with a defined data range, scale, and polarity. The term is used interchangeably with auditory variable, but it emphasizes the applied context of a working display rather than the abstract perceptual dimension itself.','An auditory display variable is a sound property in use. It is a sound channel set up to carry data. It has a range and a direction chosen for the task. The idea is the same as an auditory variable. The focus is on the working display.','To name a sound dimension as it is actually configured in a display, with its assigned range and scaling.','Used in design documents to specify each mapped channel and the data range it covers.','Data Sonification & Auditory Display',ARRAY['Auditory variable','Parameter mapping sonification','Auditory scale','Sonic encoding','Auditory display']::text[],ARRAY['Drawing a hard distinction from auditory variable, when the terms overlap','Forgetting to fix the range and polarity that make the channel usable']::text[],ARRAY['Documenting each mapped sound channel in a design spec','Setting the data range and direction for a pitch channel']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory display variable');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e553fd2b-c42d-5b21-ac36-b3faf323161a','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e553fd2b-c42d-5b21-ac36-b3faf323161a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e553fd2b-c42d-5b21-ac36-b3faf323161a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e56acbb-47e2-5de7-9ce1-e92e161748cb','Sonic encoding','Sonic encoding is the process of representing data or information in sound by assigning meaning to chosen acoustic properties, whether through continuous mappings, discrete symbolic sounds, or a mixture of both. It is the general act of casting information into an auditory form, and its quality depends on how learnable and discriminable the resulting sounds are for the intended listeners.','Sonic encoding means putting information into sound. You decide what each sound property means. It can be a smooth mapping or set symbols. The goal is sounds people can tell apart. They must also be easy to learn.','To turn abstract data or messages into an auditory form that a listener can decode reliably.','Underlies any design step where a technician decides how data values or states will be signaled by sound.','Data Sonification & Auditory Display',ARRAY['Parameter mapping sonification','Earcon','Auditory icon','Auditory variable','Auditory display']::text[],ARRAY['Choosing encodings that sound alike, so listeners confuse them','Assuming an encoding obvious to the designer is obvious to users without training']::text[],ARRAY['Deciding how each machine state will sound in an interface','Designing a set of tones that users must reliably tell apart']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic encoding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e56acbb-47e2-5de7-9ce1-e92e161748cb','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e56acbb-47e2-5de7-9ce1-e92e161748cb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e56acbb-47e2-5de7-9ce1-e92e161748cb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f4dc303-d6f8-569d-ba15-cfb02495f5bb','Auditory legend','An auditory legend is a reference cue that tells the listener how the sound relates to the data, playing the role that a key or legend plays in a visual chart. It may present sample tones at known values, state the mapping range, or play calibration reference points, so that listeners can interpret the display in absolute terms rather than only relative change.','An auditory legend is a key made of sound. It tells you what the tones mean. It may play a tone for a known value. This helps you read real amounts, not just change. It works like a chart''s legend.','To give listeners a reference so they can map heard sounds back to actual data values and units.','Used to play reference tones at the start of an auditory graph so a user can anchor later readings.','Data Sonification & Auditory Display',ARRAY['Auditory graph','Auditory scale','Reference tone','Sonic encoding','Auditory display']::text[],ARRAY['Omitting a legend, leaving listeners unable to read absolute values','Assuming one reference at the start is remembered through a long display']::text[],ARRAY['Playing reference tones before an auditory graph','Giving low and high anchor tones so a user can gauge the scale']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory legend');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f4dc303-d6f8-569d-ba15-cfb02495f5bb','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f4dc303-d6f8-569d-ba15-cfb02495f5bb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f4dc303-d6f8-569d-ba15-cfb02495f5bb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '903a899a-3672-572e-a69c-79dcf4fe790c','Auditory scale','An auditory scale is the rule that relates data values to positions along a sound dimension, defining its endpoints, spacing, and whether the progression is linear, logarithmic, or quantized to discrete steps such as musical intervals. It is the auditory counterpart of an axis scale, and choosing it well is what makes changes in the data map onto perceptually even, readable changes in sound.','An auditory scale is the ruler for a sound channel. It sets the low and high ends. It also sets how values are spaced. The spacing can be even, log, or in steps. A good scale makes changes easy to hear.','To fix how data values are spaced along a sound dimension so the display is even and readable.','Chosen when setting up a mapping, such as deciding a log-pitch scale for a wide-range variable.','Data Sonification & Auditory Display',ARRAY['Auditory legend','Log-frequency mapping','Pitch-scale mapping','Auditory variable','Auditory graph']::text[],ARRAY['Using a linear scale where a logarithmic one matches perception better','Leaving endpoints undefined, so identical sounds mean different values across displays']::text[],ARRAY['Choosing a log-pitch scale for a wide-ranging variable','Fixing the low and high anchors of a mapped channel']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory scale');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '903a899a-3672-572e-a69c-79dcf4fe790c','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='903a899a-3672-572e-a69c-79dcf4fe790c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='903a899a-3672-572e-a69c-79dcf4fe790c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4128c5e1-0658-5dce-aa24-5ec61c7fe0a3','Pitch-scale mapping','Pitch-scale mapping quantizes a data variable to the discrete pitches of a musical scale, so values snap to the nearest scale degree instead of taking any continuous frequency. Constraining pitches to a familiar scale can make relations and steps easier to judge and the result more listenable, at the cost of resolution, since values within one step become indistinguishable.','Pitch-scale mapping puts values onto musical notes. Each value snaps to the nearest note in a scale. This makes steps easier to hear. It also sounds more musical. But close values may land on the same note.','To improve listenability and step judgment by limiting pitch to the notes of a chosen musical scale.','Used in melodic data displays where snapping to a scale helps listeners compare values by ear.','Data Sonification & Auditory Display',ARRAY['Pitch mapping','Log-frequency mapping','Auditory scale','Quantization','Auditory graph']::text[],ARRAY['Assuming fine resolution when values are quantized to a small set of notes','Picking a scale so sparse that distinct values collapse onto one note']::text[],ARRAY['Snapping data to a pentatonic scale for a pleasant melodic display','Quantizing values to notes so users can compare steps by ear']::text[],'intermediate','m = round(m_min + (m_max − m_min)·(d − d_min)/(d_max − d_min))','The data value is scaled across a range of scale degrees and then rounded to the nearest degree, so each value snaps to a discrete note of the chosen scale.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pitch-scale mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4128c5e1-0658-5dce-aa24-5ec61c7fe0a3','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4128c5e1-0658-5dce-aa24-5ec61c7fe0a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4128c5e1-0658-5dce-aa24-5ec61c7fe0a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac16c879-aec9-56a9-a83e-850f80ab292f','Log-frequency mapping','Log-frequency mapping relates a data variable to frequency on a logarithmic axis, so equal steps in the data produce equal ratios in frequency and therefore equal musical intervals. This matches the roughly logarithmic nature of pitch perception, keeping the perceived pitch change per unit of data constant across a wide range, unlike a linear hertz mapping which compresses low values.','Log-frequency mapping spaces tones by ratio, not by flat hertz. Equal value steps give equal musical steps. This fits how we hear pitch. It keeps changes even across a wide range. A flat hertz scale would hide low-end changes.','To make pitch changes perceptually even across the data range by mapping onto frequency ratios rather than linear hertz.','The standard choice for wide-range variables in auditory graphs, so a doubling of value gives a fixed interval.','Data Sonification & Auditory Display',ARRAY['Pitch mapping','Pitch-scale mapping','Auditory scale','Octave','Auditory graph']::text[],ARRAY['Using linear hertz, which makes low-value changes nearly inaudible','Forgetting that each octave is a doubling, not a fixed hertz addition']::text[],ARRAY['Mapping a wide-range sensor value to log frequency','Setting each data octave to one musical octave in a graph']::text[],'intermediate','f = f_ref · 2^(k·(d − d_ref))','Frequency equals a reference frequency multiplied by two raised to a constant times the data value''s offset from a reference, so a fixed data step multiplies frequency by a fixed ratio.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Log-frequency mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac16c879-aec9-56a9-a83e-850f80ab292f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac16c879-aec9-56a9-a83e-850f80ab292f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac16c879-aec9-56a9-a83e-850f80ab292f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2377c493-03ee-5889-9c58-b846cc69afa0','Earcon','An earcon is an abstract, synthetic sound, typically a short structured motif built from pitch, rhythm, timbre, and register, used as a symbolic message in an auditory interface. Earcons have no natural link to what they represent, so their meaning must be learned; families of earcons can be built with shared musical grammar so related messages share related motifs.','An earcon is a short made-up sound that stands for something. It is like a musical icon. Its meaning is not natural, so you learn it. Related earcons can share a pattern. This links related messages by ear.','To signal events, states, or menu items with brief symbolic motifs whose structure can encode relationships between messages.','Used for interface feedback such as alerts, confirmations, and menu cues in software and devices.','Data Sonification & Auditory Display',ARRAY['Auditory icon','Spearcon','Categorical earcon','Sonic encoding','Auditory display']::text[],ARRAY['Confusing earcons with auditory icons, which use natural, meaningful sounds','Building too many similar motifs that users cannot learn or tell apart']::text[],ARRAY['Playing a motif when an email arrives','Building a menu whose items share a family of motifs']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Earcon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2377c493-03ee-5889-9c58-b846cc69afa0','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2377c493-03ee-5889-9c58-b846cc69afa0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2377c493-03ee-5889-9c58-b846cc69afa0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b42ef47f-337e-5ff8-9daa-b15ab9003359','Auditory icon','An auditory icon is an everyday sound used to represent an object, action, or event by analogy to its real-world source, so a listener can infer its meaning from familiar experience rather than by learning an arbitrary code. Auditory icons draw on the way people naturally hear events in the environment, which makes them quick to interpret when a suitable everyday sound exists.','An auditory icon is a real-world sound that stands for something. A paper crumple can mean deleting a file. You guess its meaning from life. You do not need to memorize it. It works when a fitting sound exists.','To convey meaning quickly by borrowing familiar everyday sounds that listeners already associate with events.','Used in interfaces for intuitive feedback, such as a trash sound when a file is deleted.','Data Sonification & Auditory Display',ARRAY['Earcon','Spearcon','Sonic encoding','Auditory display','Everyday listening']::text[],ARRAY['Confusing auditory icons with earcons, which are abstract, learned motifs','Forcing an everyday sound onto a concept that has no natural sonic match']::text[],ARRAY['Playing a crumple sound when a file is deleted','Using a knock to signal an incoming message']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory icon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b42ef47f-337e-5ff8-9daa-b15ab9003359','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b42ef47f-337e-5ff8-9daa-b15ab9003359') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b42ef47f-337e-5ff8-9daa-b15ab9003359');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bcfe7c7e-b2aa-5eaf-9c73-f70f0b56ac60','Spearcon','A spearcon is a brief auditory cue created by speeding up a spoken phrase, often to the point where it is no longer fully intelligible as speech, so it acts as a compact acoustic fingerprint of the underlying word or item. Because spearcons derive directly from the spoken label, they are learned faster than abstract earcons and support quick navigation of long menus.','A spearcon is a sped-up spoken word. It may be too fast to fully understand. Still, it is tied to the real word. So it is quick to learn. It helps users skim long menus by ear.','To give each menu item a short, unique cue derived from its spoken name, speeding auditory navigation.','Used in auditory menus, such as speeding a list of contacts or settings for eyes-free browsing.','Data Sonification & Auditory Display',ARRAY['Earcon','Auditory icon','Auditory menu','Sonic encoding','Auditory display']::text[],ARRAY['Confusing spearcons with plain sped-up speech meant to stay fully intelligible','Compressing so hard that even the learned link to the word is lost']::text[],ARRAY['Speeding menu labels for eyes-free phone navigation','Giving each contact a spearcon cue in a long list']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spearcon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bcfe7c7e-b2aa-5eaf-9c73-f70f0b56ac60','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bcfe7c7e-b2aa-5eaf-9c73-f70f0b56ac60') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bcfe7c7e-b2aa-5eaf-9c73-f70f0b56ac60');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76989402-d15a-5eef-8b80-10cee249595a','Categorical earcon','A categorical earcon is an earcon designed to signal membership in a category rather than a value on a continuous scale, using a distinct motif, timbre, or register for each class. Sets of categorical earcons are built so that different categories are easy to tell apart, and a shared musical grammar can indicate that certain categories belong to the same higher-level group.','A categorical earcon marks which group something belongs to. Each category gets its own motif. The sounds are made easy to tell apart. Related groups can share a pattern. It shows type, not an amount.','To label discrete categories in a display with distinct, learnable motifs that the ear separates cleanly.','Used to signal event types or classes, such as a different motif for each kind of system message.','Data Sonification & Auditory Display',ARRAY['Earcon','Discrete parameter mapping','Auditory icon','Sonic encoding','Auditory display']::text[],ARRAY['Using categorical earcons to imply an order that categories do not have','Designing motifs so similar that categories are confused']::text[],ARRAY['Assigning a distinct motif to each type of alert','Grouping related message classes under a shared musical pattern']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Categorical earcon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76989402-d15a-5eef-8b80-10cee249595a','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76989402-d15a-5eef-8b80-10cee249595a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76989402-d15a-5eef-8b80-10cee249595a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6962426b-aca1-5fc9-960c-e1b681dbd801','Continuous parameter mapping','Continuous parameter mapping is parameter-mapping sonification in which a continuous data variable drives a continuous sound parameter through a smooth transfer function, so small changes in the data yield proportionally small changes in the sound. The designer selects the function''s shape (linear, logarithmic, or otherwise), its range, and its polarity so that the perceived change matches the intended reading of the data.','Continuous parameter mapping turns a smooth value into a smooth sound change. A small value change gives a small sound change. A rule links the two. The rule can be straight or curved. Its direction and range are chosen with care.','To represent continuously varying data with continuously varying sound, preserving fine trends and gradients.','Used in auditory graphs and monitors where a value glides a tone up and down without steps.','Data Sonification & Auditory Display',ARRAY['Parameter mapping sonification','Discrete parameter mapping','Pitch mapping','Auditory scale','Transfer function']::text[],ARRAY['Choosing a linear function where perception is logarithmic, distorting the reading','Setting polarity so higher values map to a lower-seeming sound']::text[],ARRAY['Gliding a tone up and down with a live sensor value','Mapping a smooth trend to continuous brightness change']::text[],'intermediate','p = p_min + (p_max − p_min)·(d − d_min)/(d_max − d_min)','The sound parameter moves smoothly between a low and high limit in proportion to how far the data value lies between its minimum and maximum, with the direction set by the chosen polarity.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous parameter mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6962426b-aca1-5fc9-960c-e1b681dbd801','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6962426b-aca1-5fc9-960c-e1b681dbd801') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6962426b-aca1-5fc9-960c-e1b681dbd801');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2091be2a-c468-5510-a8d3-fc2a64d36141','Discrete parameter mapping','Discrete parameter mapping assigns data to a finite set of distinct sound values, either because the data are categorical or because a continuous variable is quantized into steps, so the output takes only specific levels such as fixed pitches or timbres. It trades resolution for discriminability, making individual levels easy to identify and label at the cost of hiding variation within a step.','Discrete parameter mapping uses a fixed set of sounds. Values fall into steps, not a smooth range. Each step is easy to tell apart. But changes inside a step are hidden. It fits categories or coarse levels.','To make individual levels or categories clearly identifiable by mapping data to a small set of distinct sounds.','Used for state or class displays, such as three fixed tones for low, normal, and high.','Data Sonification & Auditory Display',ARRAY['Continuous parameter mapping','Categorical earcon','Quantization','Pitch-scale mapping','Auditory display']::text[],ARRAY['Using too few levels, so meaningful variation is lost','Reading discrete output as if it showed continuous detail']::text[],ARRAY['Signaling low, normal, and high with three fixed tones','Mapping event categories to a set of distinct timbres']::text[],'intermediate','k = floor(N·(d − d_min)/(d_max − d_min)) ,  0 ≤ k ≤ N−1','The value''s position within its range is scaled by the number of levels and rounded down to select one of a fixed set of discrete sound steps.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Discrete parameter mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2091be2a-c468-5510-a8d3-fc2a64d36141','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2091be2a-c468-5510-a8d3-fc2a64d36141') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2091be2a-c468-5510-a8d3-fc2a64d36141');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7b0c247-2441-53e1-9287-260bcf9ed861','Audification','Audification is the direct translation of a data series into an audio waveform by interpreting the data samples as sound-pressure samples and playing them back, usually after shifting the data''s time and frequency content into the audible range through resampling. It is the most direct form of sonification, preserving the waveform''s structure so periodicities and transients in the data are heard as pitch and timbre.','Audification plays data as if it were a sound wave. Each data point becomes a sound sample. The data are sped up or slowed to be heard. Patterns in the data become pitch and tone. It is the most direct kind of sonification.','To let listeners hear the structure of a waveform-like data series directly, revealing rhythms and events in its shape.','Used on seismic, acoustic, or physiological records, where speeding the data brings its features into the hearing range.','Data Sonification & Auditory Display',ARRAY['Scientific audification','Parameter mapping sonification','Sample rate','Resampling','Direct sonification']::text[],ARRAY['Confusing audification with parameter mapping, which assigns data to chosen sound controls','Forgetting that resampling shifts the frequencies you hear relative to the data']::text[],ARRAY['Speeding a seismogram so an earthquake becomes audible','Playing a physiological signal as a waveform to hear its rhythm']::text[],'beginner','f_audio = f_data · (f_s,play / f_s,data)','Playing the data samples at an audio sample rate different from the rate they represent scales every frequency in the data by the ratio of the playback rate to the original data rate.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7b0c247-2441-53e1-9287-260bcf9ed861','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7b0c247-2441-53e1-9287-260bcf9ed861') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7b0c247-2441-53e1-9287-260bcf9ed861');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '63d19840-b75c-56f4-b9ce-2132e7b3ec26','Time compression','Time compression renders data over a shorter interval than the period they were collected in, so a long record is heard quickly and slow trends become audible fluctuations. The compression factor is the ratio of original duration to playback duration; in audification it simultaneously raises the pitch, so its effect on both time and frequency must be considered together.','Time compression plays a long record in a short time. Days of data can pass in seconds. Slow trends turn into faster changes you can hear. In audification it also raises the pitch. So it changes both time and pitch.','To bring slow processes into a listenable time span so long-term structure can be perceived quickly.','Used to review long logs, such as compressing a day of readings into a few seconds of sound.','Data Sonification & Auditory Display',ARRAY['Time expansion','Audification','Playback-rate mapping','Offline sonification','Time scaling']::text[],ARRAY['Ignoring that compression in audification also shifts pitch upward','Compressing so hard that events blur together and are missed']::text[],ARRAY['Playing a day of sensor data in a few seconds','Speeding a slow geophysical record to reveal its structure']::text[],'intermediate','c = T_original / T_playback ,  c > 1','The compression factor is the original data duration divided by the shorter playback duration; a factor above one means the record plays faster than real time.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '63d19840-b75c-56f4-b9ce-2132e7b3ec26','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='63d19840-b75c-56f4-b9ce-2132e7b3ec26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='63d19840-b75c-56f4-b9ce-2132e7b3ec26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '735e65b8-3e15-5ccb-bb44-2bcb6cf3fef9','Time expansion','Time expansion renders data over a longer interval than the period they represent, stretching a brief event so its fine internal structure can be examined by ear. The expansion factor is the ratio of playback duration to original duration; in audification it also lowers the pitch, so a fast transient can be slowed into an audible, drawn-out sound.','Time expansion stretches a short event out. A quick burst is slowed down. Its fine detail becomes easier to hear. In audification it also lowers the pitch. So a fast click can become a long sound.','To slow rapid events so their fine internal structure becomes audible and examinable.','Used to study brief transients, such as slowing an ultrasonic bat call into the hearing range.','Data Sonification & Auditory Display',ARRAY['Time compression','Audification','Playback-rate mapping','Time scaling','Scientific audification']::text[],ARRAY['Forgetting that expansion in audification also lowers pitch','Stretching so far that the sound drops below audible frequencies']::text[],ARRAY['Slowing an ultrasonic bat call into the audible range','Stretching a brief transient to inspect its fine structure']::text[],'intermediate','e = T_playback / T_original ,  e > 1','The expansion factor is the longer playback duration divided by the original data duration; a factor above one means the record plays slower than real time.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time expansion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '735e65b8-3e15-5ccb-bb44-2bcb6cf3fef9','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='735e65b8-3e15-5ccb-bb44-2bcb6cf3fef9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='735e65b8-3e15-5ccb-bb44-2bcb6cf3fef9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'beb368da-24c7-5e77-b321-3c7f8b880a2e','Playback-rate mapping','Playback-rate mapping assigns a data variable to the speed at which a stored sound or data series is played, so the value controls how fast the material advances. Because changing playback rate on a fixed recording alters pitch and duration together by the same factor, the mapping couples the two, which is useful when a single value should shift both the tempo and the pitch of the output.','Playback-rate mapping ties a value to playback speed. A bigger value plays faster. On a fixed recording, faster also means higher pitch. So speed and pitch move together. One value changes both at once.','To control playback speed with data, shifting tempo and pitch together as a coupled cue.','Used when a value should scrub through a clip faster or slower, as in interactive audification.','Data Sonification & Auditory Display',ARRAY['Audification','Time compression','Time expansion','Parameter mapping sonification','Resampling']::text[],ARRAY['Expecting to change speed without changing pitch on a plain resampled clip','Confusing rate mapping with time-stretching that holds pitch fixed']::text[],ARRAY['Scrubbing an audified record faster as a control value rises','Coupling tempo and pitch to one variable in a display']::text[],'intermediate','r = v / v_ref ;  f_out = r · f_ref ,  T_out = T_ref / r','The playback rate is the data value divided by a reference; the output frequency scales up by that rate while the duration scales down by the same factor.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Playback-rate mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'beb368da-24c7-5e77-b321-3c7f8b880a2e','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='beb368da-24c7-5e77-b321-3c7f8b880a2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='beb368da-24c7-5e77-b321-3c7f8b880a2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '963b3d2b-4dc3-5ada-908c-b720142d2c8d','Auditory zooming','Auditory zooming lets a listener change the level of temporal or data detail in a sonification, moving between a compressed overview and an expanded, fine-grained rendering of a chosen region. Like visual zoom, it is usually interactive, allowing the user to select a range and hear it in greater resolution while the surrounding context is reduced or dropped.','Auditory zooming changes how much detail you hear. You can zoom out for a quick overview. You can zoom in on one part for detail. It works like zoom on a map. The listener usually controls it.','To let listeners move between overview and detail, hearing a selected region at higher resolution on demand.','Used in interactive data browsers where a user selects a span and hears it stretched out in detail.','Data Sonification & Auditory Display',ARRAY['Focus-plus-context sonification','Overview sonification','Detail sonification','Interactive sonification','Time expansion']::text[],ARRAY['Losing all context when zoomed in, so the region cannot be located','Confusing auditory zoom with simple volume change']::text[],ARRAY['Selecting a span of data and hearing it in fine detail','Switching between an overview pass and a zoomed segment']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory zooming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '963b3d2b-4dc3-5ada-908c-b720142d2c8d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='963b3d2b-4dc3-5ada-908c-b720142d2c8d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='963b3d2b-4dc3-5ada-908c-b720142d2c8d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '885183cb-dc3b-5d96-9633-82d86468a197','Focus-plus-context sonification','Focus-plus-context sonification presents a chosen region of data in detail while simultaneously keeping a reduced representation of the surrounding data audible, so the listener perceives fine structure without losing the overall setting. Borrowed from information visualization, it balances resolution against context, typically emphasizing the focus with greater detail or salience and rendering the rest more sparsely.','This shows one part in detail and keeps the rest in the background. You hear the focus clearly. You still hear the wider setting softly. So you do not lose your place. It comes from visual focus-plus-context ideas.','To give detailed listening to a region while preserving an audible sense of the whole around it.','Used in exploratory tools so a user can study one segment without losing track of the full data set.','Data Sonification & Auditory Display',ARRAY['Auditory zooming','Overview sonification','Detail sonification','Interactive sonification','Multivariate sonification']::text[],ARRAY['Letting the context mask the focus, or the reverse','Assuming users hold a mental overview without any audible context']::text[],ARRAY['Emphasizing a selected region while a sparse background continues','Studying one segment while the whole data set stays faintly audible']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Focus-plus-context sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '885183cb-dc3b-5d96-9633-82d86468a197','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='885183cb-dc3b-5d96-9633-82d86468a197') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='885183cb-dc3b-5d96-9633-82d86468a197');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e9b7b15-f563-5bef-a8fd-b84531536bf3','Overview sonification','Overview sonification renders a whole data set compactly, usually with strong time compression, to give the listener a quick gestalt of its overall shape, major trends, and gross anomalies before any detailed inspection. It is the auditory analogue of an overview-first strategy, trading fine resolution for a fast, big-picture impression that guides where to look more closely.','Overview sonification gives a quick summary by ear. The whole data set plays fast. You catch the big shape and trends. You also hear any large oddities. It points you to where to look closer.','To supply a fast big-picture impression of a data set that guides deeper, detailed listening.','Used as a first pass over a record, such as a quick sweep before zooming into interesting parts.','Data Sonification & Auditory Display',ARRAY['Detail sonification','Focus-plus-context sonification','Auditory zooming','Time compression','Exploratory sonification']::text[],ARRAY['Expecting fine detail from a compressed overview','Skipping the overview and getting lost in detail']::text[],ARRAY['Sweeping quickly through a whole record to find hotspots','Playing a compressed summary before detailed inspection']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Overview sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e9b7b15-f563-5bef-a8fd-b84531536bf3','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e9b7b15-f563-5bef-a8fd-b84531536bf3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e9b7b15-f563-5bef-a8fd-b84531536bf3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8448eb69-fa46-5b62-8a76-3342c4ff25c6','Detail sonification','Detail sonification renders a limited region of data at high resolution so the listener can examine its fine structure, individual events, and small variations that a compressed overview would blur. It complements overview sonification in an overview-first, detail-on-demand workflow, typically applied after the overview has identified a region worth closer listening.','Detail sonification plays a small part slowly and fully. You hear fine changes and single events. A fast overview would blur these. You use it after an overview points the way. It is the close-up listen.','To expose the fine structure of a selected region that an overview pass cannot resolve.','Used after an overview to inspect a chosen segment closely, such as one suspicious episode.','Data Sonification & Auditory Display',ARRAY['Overview sonification','Focus-plus-context sonification','Auditory zooming','Time expansion','Exploratory sonification']::text[],ARRAY['Applying detail rendering to a whole large set, which takes too long','Losing the surrounding context while focused on detail']::text[],ARRAY['Inspecting one suspicious episode after an overview pass','Listening closely to a short segment for individual events']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Detail sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8448eb69-fa46-5b62-8a76-3342c4ff25c6','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8448eb69-fa46-5b62-8a76-3342c4ff25c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8448eb69-fa46-5b62-8a76-3342c4ff25c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '953e0cd1-2ca3-52df-a21e-e179f2d7ef69','Brushing and linking','Brushing and linking is an interaction technique in which selecting a subset of data in one view highlights the same items in other linked views, and in an auditory setting the selection is rendered as sound so the chosen subset is heard while related displays update together. It supports coordinated exploration across visual and auditory representations of the same data.','Brushing and linking connects several views of data. You pick a subset in one view. The same items light up or sound in the others. Here the chosen data are played as sound. All the views stay in step.','To coordinate multiple linked views so a selection made in one is reflected, including audibly, in the others.','Used in analysis tools where selecting points on a chart plays those points and updates linked panels.','Data Sonification & Auditory Display',ARRAY['Interactive sonification','Multivariate sonification','Auditory graph','Exploratory sonification','Auditory display']::text[],ARRAY['Confusing brushing with plain playback, without any linked selection','Overwhelming the listener by sounding a huge selection at once']::text[],ARRAY['Selecting chart points and hearing just those play','Linking a table and an auditory view so a pick updates both']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Brushing and linking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '953e0cd1-2ca3-52df-a21e-e179f2d7ef69','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='953e0cd1-2ca3-52df-a21e-e179f2d7ef69') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='953e0cd1-2ca3-52df-a21e-e179f2d7ef69');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b07fbcd0-81cc-52da-830f-f17517083d3d','Multivariate sonification','Multivariate sonification represents several data variables at once by mapping each to a different auditory dimension, such as pitch, loudness, timbre, and spatial position, so multiple streams of information are conveyed in parallel. Its success depends on choosing dimensions that interact little, since some auditory attributes influence one another and can distort concurrent readings.','Multivariate sonification shows several variables together. Each variable gets its own sound property. One may use pitch, another timbre. The listener follows them at once. The channels must not blur each other.','To convey multiple variables in parallel by assigning each to a separate, weakly interacting auditory dimension.','Used when several sensor streams must be heard together, each on its own sound property.','Data Sonification & Auditory Display',ARRAY['High-dimensional sonification','Parameter mapping sonification','Auditory variable','Spatial mapping','Timbre mapping']::text[],ARRAY['Mapping two variables to dimensions that interact, distorting both','Adding so many streams that the listener cannot separate them']::text[],ARRAY['Assigning pitch, timbre, and position to three sensor streams','Following several variables in one display at once']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multivariate sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b07fbcd0-81cc-52da-830f-f17517083d3d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b07fbcd0-81cc-52da-830f-f17517083d3d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b07fbcd0-81cc-52da-830f-f17517083d3d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71df55d6-17c4-55b3-b90d-53fcdabd4420','High-dimensional sonification','High-dimensional sonification conveys data with many variables per observation, where direct one-to-one mapping to auditory dimensions is impossible because sound offers only a few well-separated channels. It relies on strategies such as dimensionality reduction, feature selection, or model-based excitation to compress the space into an audible form while preserving the structure of interest.','High-dimensional sonification handles data with many variables. Sound has only a few clear channels. So you cannot map each variable to its own. You first shrink or model the data. Then you play the key structure.','To make data with many variables audible by reducing or modeling them, since sound has few clear channels.','Used on complex datasets, such as sounding clusters after projecting many features to fewer dimensions.','Data Sonification & Auditory Display',ARRAY['Multivariate sonification','Model-based sonification','Dimensionality reduction','Parameter mapping sonification','Auditory display']::text[],ARRAY['Trying to map every variable to its own sound channel, which the ear cannot separate','Reducing dimensions in a way that discards the structure of interest']::text[],ARRAY['Sounding clusters after projecting many features to fewer axes','Exciting a model built from a high-dimensional dataset']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='High-dimensional sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71df55d6-17c4-55b3-b90d-53fcdabd4420','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71df55d6-17c4-55b3-b90d-53fcdabd4420') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71df55d6-17c4-55b3-b90d-53fcdabd4420');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '811cbe72-58b1-5938-b37b-957182251a99','Auditory graph','An auditory graph is the auditory counterpart of a line or scatter plot, presenting a data series as sound, most often by mapping the dependent variable to pitch while time advances along the independent axis. Reference cues such as tick sounds and context tones can mark axis values, allowing the listener to read trends, extrema, and relationships much as a sighted reader scans a chart.','An auditory graph is a chart you listen to. Time moves along one axis. The value sets the pitch. Tick sounds can mark the scale. You hear trends, peaks, and dips like reading a line chart.','To let listeners read trends and features of plotted data by ear, giving non-visual access to graphs.','Used in accessible tools and eyes-free contexts, turning a spreadsheet series into a pitch line over time.','Data Sonification & Auditory Display',ARRAY['Auditory histogram','Accessible chart sonification','Pitch mapping','Auditory legend','Auditory scale']::text[],ARRAY['Omitting axis reference cues, so absolute values cannot be read','Assuming listeners judge exact values from pitch without any anchors']::text[],ARRAY['Turning a spreadsheet column into a pitch line over time','Giving a blind student non-visual access to a line chart']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory graph');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '811cbe72-58b1-5938-b37b-957182251a99','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='811cbe72-58b1-5938-b37b-957182251a99') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='811cbe72-58b1-5938-b37b-957182251a99');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '69694790-a10f-588c-a8c8-6f9b484787c4','Auditory histogram','An auditory histogram sonifies the distribution of a variable by representing each bin''s count or frequency through a sound property, so the listener perceives the shape of the distribution, its peaks, and its spread. Bins are typically stepped through in order, with count mapped to a dimension such as pitch, loudness, or event density, giving an audible profile of where data concentrate.','An auditory histogram lets you hear a distribution. Each bin is played in turn. Its count sets a sound property. Tall bins may sound higher or louder. You hear where the data pile up.','To convey the shape of a distribution, its peaks and spread, through sound stepped across the bins.','Used to hear whether data are skewed or bimodal, stepping through bins with count mapped to pitch.','Data Sonification & Auditory Display',ARRAY['Auditory graph','Distribution','Pitch mapping','Accessible chart sonification','Auditory scale']::text[],ARRAY['Confusing an auditory histogram with an auditory graph of a series over time','Choosing bins so coarse the distribution''s shape is lost']::text[],ARRAY['Stepping through bins to hear if data are skewed','Detecting two peaks in a distribution by ear']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory histogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '69694790-a10f-588c-a8c8-6f9b484787c4','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='69694790-a10f-588c-a8c8-6f9b484787c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='69694790-a10f-588c-a8c8-6f9b484787c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f9617ebb-c461-5874-82bf-7f92d5402c9d','Threshold sonification','Threshold sonification produces or changes a sound when a data value crosses a defined limit, drawing attention to boundary events rather than to the full continuous course of the data. It focuses the display on when a value enters or leaves a region of interest, and is a building block of monitoring and alarm systems where only limit crossings need to be signaled.','Threshold sonification reacts when a value crosses a set line. It stays quiet until then. When the value passes the limit, the sound changes. So it flags boundary events. It is a base for alarms and monitors.','To signal when a value crosses a defined limit, focusing attention on boundary events rather than continuous detail.','Used in monitors that sound only when a reading enters or leaves a safe range.','Data Sonification & Auditory Display',ARRAY['Alarm sonification','Real-time sonification','Event-based sonification','Monitoring','Auditory display']::text[],ARRAY['Setting a single hard limit that chatters when the value hovers near it','Confusing threshold cues with a full continuous mapping of the data']::text[],ARRAY['Sounding a cue when a reading leaves the safe band','Flagging the moment a level rises past a set point']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Threshold sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f9617ebb-c461-5874-82bf-7f92d5402c9d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f9617ebb-c461-5874-82bf-7f92d5402c9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f9617ebb-c461-5874-82bf-7f92d5402c9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '574ca766-1b38-584a-8d4f-33295d4b9dee','Alarm sonification','Alarm sonification is the design of sounds that signal urgent or abnormal conditions and demand a listener''s attention and response, balancing detectability and urgency against annoyance and the risk of alarm fatigue. Effective alarms are learnable, distinguishable from one another, appropriately urgent for the hazard, and designed to avoid masking or false triggering in the working environment.','Alarm sonification makes sounds that warn of a problem. They must be easy to notice. They must also match how urgent the issue is. Too many alarms cause fatigue. Good ones are clear and easy to tell apart.','To alert operators to urgent or abnormal states with sounds tuned for detectability, urgency, and discriminability.','Used in medical, industrial, and vehicle systems where distinct alarms signal specific hazards.','Data Sonification & Auditory Display',ARRAY['Threshold sonification','Auditory icon','Earcon','Real-time sonification','Auditory display']::text[],ARRAY['UNSAFE: designing many loud, similar alarms that cause fatigue and get ignored or muted','Making an alarm''s urgency mismatch the true severity of the event']::text[],ARRAY['Signaling a critical vital sign on a patient monitor','Warning of a machine fault with a distinct, urgent alarm']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Alarm sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '574ca766-1b38-584a-8d4f-33295d4b9dee','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='574ca766-1b38-584a-8d4f-33295d4b9dee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='574ca766-1b38-584a-8d4f-33295d4b9dee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd1f925d8-9506-5c46-bfb0-be2197db5d5c','Accessible chart sonification','Accessible chart sonification converts a visual chart into sound to give blind and low-vision users non-visual access to its data, typically rendering a plotted series as pitch over time with axis cues and navigable structure. It is a core accessibility application of auditory graphs, and effective designs include reference tones, keyboard navigation, and summaries so users can both scan and inspect the data.','Accessible chart sonification turns a chart into sound for people who cannot see it. The line becomes a pitch over time. Axis cues mark the scale. Users can move through the data by key. It opens charts to blind users.','To give non-visual access to charted data, making graphs usable by blind and low-vision people.','Used in accessible dashboards and documents so a screen-reader user can hear a chart''s trends.','Data Sonification & Auditory Display',ARRAY['Auditory graph','Auditory histogram','Auditory legend','Pitch mapping','Auditory display']::text[],ARRAY['Providing sound without navigation or reference cues, limiting real reading','Assuming one quick pass replaces the ability to scan and re-inspect']::text[],ARRAY['Letting a screen-reader user hear a line chart''s trend','Adding navigable audio to a dashboard chart for accessibility']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Accessible chart sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd1f925d8-9506-5c46-bfb0-be2197db5d5c','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d1f925d8-9506-5c46-bfb0-be2197db5d5c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d1f925d8-9506-5c46-bfb0-be2197db5d5c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e02c52e4-0555-5eda-9a00-701fc987f269','Scientific audification','Scientific audification is the application of audification to scientific measurement data, such as seismic, gravitational-wave, plasma, or physiological signals, translating the recorded waveform directly into sound, usually with time-and-frequency shifting into the audible band. It lets researchers exploit auditory pattern recognition to detect events, periodicities, and signal types that are hard to spot in a visual trace.','Scientific audification plays science data as sound. The recorded wave is turned straight into audio. It is sped up or slowed to be heard. Researchers then use their ears to spot events. Some patterns are easier to hear than to see.','To harness auditory pattern recognition on scientific waveforms, revealing events and periodicities in measured signals.','Used in seismology and physics to listen for characteristic events in recorded waveforms.','Data Sonification & Auditory Display',ARRAY['Audification','Time compression','Time expansion','Direct sonification','Resampling']::text[],ARRAY['Forgetting that time-shifting also shifts the frequencies you hear','Treating audification as a rigorous measurement rather than a detection aid']::text[],ARRAY['Listening to a sped-up seismogram for an earthquake''s signature','Hearing characteristic events in a recorded physics signal']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scientific audification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e02c52e4-0555-5eda-9a00-701fc987f269','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e02c52e4-0555-5eda-9a00-701fc987f269') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e02c52e4-0555-5eda-9a00-701fc987f269');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e93a36a2-b1c7-5a3d-bf47-785428d2f96f','Model-based sonification','Model-based sonification builds a virtual, physics-inspired dynamic system whose parameters are configured from the data, and produces sound only when a user excites the model through interaction, so the data shape the system''s sonic response rather than being mapped directly to sound parameters. Because sound arises from the model''s dynamics under the user''s probing, the approach ties listening tightly to action and can reveal structure such as clustering.','Model-based sonification builds a virtual object from the data. The object stays silent until you poke it. Then it rings in a way the data shaped. So you learn by probing it. It links your actions to what you hear.','To let data define a dynamic system that a user excites, so structure is revealed through interactive listening.','Used in exploratory analysis where a user strikes or perturbs a data model and hears how it responds.','Data Sonification & Auditory Display',ARRAY['Interactive sonification','High-dimensional sonification','Parameter mapping sonification','Data model','Auditory display']::text[],ARRAY['Confusing model-based sonification with parameter mapping, which maps data straight to sound','Expecting output without interaction, since the model must be excited to sound']::text[],ARRAY['Striking a data-shaped model and hearing clusters ring','Perturbing a dynamic model to explore high-dimensional structure']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Model-based sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e93a36a2-b1c7-5a3d-bf47-785428d2f96f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e93a36a2-b1c7-5a3d-bf47-785428d2f96f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e93a36a2-b1c7-5a3d-bf47-785428d2f96f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea7e3b2b-49fc-5708-a524-db3a6dfa2ece','Event-based sonification','Event-based sonification produces a discrete sound for each event or record in the data, rather than a continuous stream, so the timing, rate, and attributes of individual events are conveyed by distinct sonic markers. Each event can carry extra information through the pitch, timbre, or level of its marker, making the approach well suited to discrete occurrences such as transactions, detections, or log entries.','Event-based sonification plays a sound for each event. The data are discrete happenings, not a smooth signal. Each event gets its own marker. Its pitch or tone can add detail. You hear how often and when events occur.','To convey discrete events, their timing and rate, and their attributes through individual sonic markers.','Used for logs, detections, or transactions, sounding a marked cue as each event arrives.','Data Sonification & Auditory Display',ARRAY['Rhythm mapping','Streaming sonification','Threshold sonification','Earcon','Auditory display']::text[],ARRAY['Applying event sounds to a continuous signal that needs a smooth mapping','Setting event rates so high the markers fuse into a tone']::text[],ARRAY['Sounding a marker as each server event arrives','Encoding each transaction''s size in its marker''s pitch']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Event-based sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea7e3b2b-49fc-5708-a524-db3a6dfa2ece','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea7e3b2b-49fc-5708-a524-db3a6dfa2ece') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea7e3b2b-49fc-5708-a524-db3a6dfa2ece');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d7c0506-98d7-5194-bab3-c26b59dbd909','bioacoustics','Bioacoustics is the scientific study of sound production, propagation, and reception in living organisms, including how animals generate vocalizations, how sound travels through their environment, and how it is perceived and used for communication, navigation, and sensing. It spans mechanisms from the anatomy of sound-producing organs to the behavioral and ecological roles of acoustic signals.','Bioacoustics is the study of sound in living things. It looks at how animals make sounds. It also studies how those sounds travel and are heard. It covers calls, songs, and hearing. It links sound to behavior.','To understand how organisms produce, transmit, and perceive sound and how they use it to communicate and sense.','Applied in wildlife monitoring, species identification, and study of animal communication from recordings.','Data Sonification & Auditory Display',ARRAY['Ecoacoustics','Animal vocalization','Acoustic communication','Passive acoustic monitoring','Spectrogram']::text[],ARRAY['Confusing bioacoustics with ecoacoustics, which studies whole soundscapes and ecosystems','Assuming it covers only audible sound, when many signals are ultrasonic or infrasonic']::text[],ARRAY['Identifying a species from its recorded call','Studying how a whale''s sound travels underwater']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='bioacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d7c0506-98d7-5194-bab3-c26b59dbd909','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d7c0506-98d7-5194-bab3-c26b59dbd909') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d7c0506-98d7-5194-bab3-c26b59dbd909');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ae8665ad-757c-5b5b-9394-c064bec8f14f','ecoacoustics','Ecoacoustics is the study of sound across whole ecosystems and landscapes, treating the soundscape, the combined biological, geophysical, and human-made sounds of an environment, as an indicator of ecological state and change. It works at population, community, and landscape scales, using acoustic patterns to monitor biodiversity, habitat quality, and the effects of disturbance.','Ecoacoustics studies the sound of whole environments. It listens to the full soundscape of a place. That mix reflects the health of the ecosystem. It tracks wildlife and human noise together. Changes in sound signal changes in nature.','To use the whole soundscape as an indicator of biodiversity, habitat quality, and ecological change.','Applied in long-term environmental monitoring, using recorders to track ecosystem health over time.','Data Sonification & Auditory Display',ARRAY['Bioacoustics','Soundscape','Passive acoustic monitoring','Acoustic index','Biodiversity monitoring']::text[],ARRAY['Treating ecoacoustics as identical to bioacoustics, which focuses on individual organisms','Ignoring geophysical and human-made sounds that are part of the soundscape']::text[],ARRAY['Monitoring a forest''s health from its changing soundscape','Comparing soundscapes to gauge disturbance in a habitat']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ecoacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ae8665ad-757c-5b5b-9394-c064bec8f14f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ae8665ad-757c-5b5b-9394-c064bec8f14f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ae8665ad-757c-5b5b-9394-c064bec8f14f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '944da4b8-5922-5125-9f85-05ef1c0c13e3','animal vocalization','An animal vocalization is a sound produced by an animal through a dedicated sound-producing mechanism, such as the mammalian larynx or the avian syrinx, and used for functions including communication, mating, territory defense, and warning. Vocalizations vary in pitch, timbre, duration, and temporal pattern, and these acoustic features often encode species identity, individual identity, and message content.','An animal vocalization is a sound an animal makes on purpose. Birds, mammals, and frogs all do it. They use it to communicate. Calls can signal mating, territory, or danger. The sound''s pitch and pattern carry meaning.','To carry information between animals for functions like mating, warning, and defending territory.','Studied and recorded to identify species, count individuals, and interpret behavior in the field.','Data Sonification & Auditory Display',ARRAY['Bioacoustics','Ecoacoustics','Acoustic communication','Spectrogram','Call']::text[],ARRAY['Assuming all animal sounds are vocalizations, when many are made by other body parts','Reading human musical meaning into calls that serve survival functions']::text[],ARRAY['Recording bird calls to identify species at dawn','Analyzing a call''s spectrogram to read its structure']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='animal vocalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '944da4b8-5922-5125-9f85-05ef1c0c13e3','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='944da4b8-5922-5125-9f85-05ef1c0c13e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='944da4b8-5922-5125-9f85-05ef1c0c13e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '04ac9eb8-e864-53f7-9e6a-acb61db44d9d','call repertoire','The complete set of distinct acoustic signal types that an individual animal, or a population or species, produces, catalogued by their spectro-temporal structure and behavioral function. Repertoire size, the count of discriminable call or song types, is a core measure of vocal complexity in studies of animal communication.','A call repertoire is the full set of sounds an animal can make. Each sound type has its own shape and use. Scientists count how many different calls an animal or group has. A bigger repertoire often points to richer signaling.','Quantifying repertoire size lets researchers compare vocal complexity across individuals, populations, and species, and relate it to social structure, mating systems, and vocal learning.','A field bioacoustician records many hours of audio, sorts calls into types on a spectrogram, and tallies the repertoire to study a bird or mammal population.','Data Sonification & Auditory Display',ARRAY['song dialect','bird song syntax','cetacean song','vocal learning','spectrogram']::text[],ARRAY['Assuming repertoire size is fixed when many species add or drop call types with age or season','Confusing the repertoire of one individual with that of the whole population','Counting recording artifacts or noise as distinct call types']::text[],ARRAY['Cataloguing the song types of a songbird population across a breeding season','Comparing click and whistle repertoires between two dolphin pods','Measuring how a young bird''s repertoire grows as it learns from adults']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='call repertoire');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '04ac9eb8-e864-53f7-9e6a-acb61db44d9d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='04ac9eb8-e864-53f7-9e6a-acb61db44d9d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='04ac9eb8-e864-53f7-9e6a-acb61db44d9d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8dd7dd6a-2364-5991-981c-81a1ad9528ed','song dialect','A geographically or socially localized variant in the learned acoustic structure of a species'' song, in which populations share song features that differ consistently from those of other populations. Dialects arise chiefly through vocal learning and cultural transmission and are documented in songbirds, some cetaceans, and other vocal learners.','A song dialect is a local accent in an animal''s song. Animals in one area share song features that differ from other areas. These patterns are learned, not inborn. They pass from one animal to the next like a tradition.','Dialects mark local group membership, can shape mate choice and settlement, and give researchers a window into how vocal culture spreads and changes over space and time.','Researchers map recordings across sites, measure shared song features, and draw dialect boundaries to study gene flow and cultural transmission in a species.','Data Sonification & Auditory Display',ARRAY['call repertoire','vocal learning','bird song syntax','cetacean song','acoustic adaptation hypothesis']::text[],ARRAY['Treating a dialect as a genetic subspecies marker rather than a learned trait','Assuming dialect boundaries are sharp when they often grade gradually','Sampling too few individuals to tell a real dialect from individual variation']::text[],ARRAY['Mapping sparrow song dialects across a mountain range','Tracking how a whale song theme spreads between populations','Testing whether females prefer mates singing the local dialect']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='song dialect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8dd7dd6a-2364-5991-981c-81a1ad9528ed','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8dd7dd6a-2364-5991-981c-81a1ad9528ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8dd7dd6a-2364-5991-981c-81a1ad9528ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fdcdbd4a-bceb-5118-bd19-57df07891144','echolocation click','A brief, broadband transient sound emitted by an echolocating animal, such as a toothed whale or a bat, whose returning echoes are analyzed to detect, localize, and characterize targets. Clicks are typically short, high-frequency impulses produced in trains, with inter-click interval and source level adjusted to target range.','An echolocation click is a short, sharp sound an animal sends out. It then listens for the echo that bounces back. From the echo it learns where a target is and what it is. Bats and toothed whales use clicks to hunt in the dark.','Clicks provide the outgoing probe of a biosonar system, letting the animal build an acoustic picture of its surroundings and prey where vision is limited.','Bioacousticians detect and classify species from click trains on hydrophone or ultrasonic-detector recordings, using click rate and spectrum to identify the animal.','Data Sonification & Auditory Display',ARRAY['biosonar','odontocete click','bat call','interclick interval','echolocation']::text[],ARRAY['Confusing the outgoing click with the returning echo','Assuming all clicks are identical when animals adjust rate and level by task','Ignoring that recording bandwidth must exceed the click''s high frequencies']::text[],ARRAY['Identifying a porpoise from its narrowband high-frequency clicks','Studying how a bat shortens its click interval during prey capture','Estimating target range from an animal''s inter-click interval']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='echolocation click');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fdcdbd4a-bceb-5118-bd19-57df07891144','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fdcdbd4a-bceb-5118-bd19-57df07891144') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fdcdbd4a-bceb-5118-bd19-57df07891144');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7c50747-c16f-59fb-bca0-8cfdc0f4a8ec','biosonar','The biological sonar system by which certain animals emit sound and interpret returning echoes to sense their environment, encompassing signal production, hearing, and neural processing of echo delay, intensity, and spectrum. It is exemplified by toothed whales and echolocating bats.','Biosonar is an animal''s built-in sonar. The animal makes a sound and listens to the echo. Its brain uses the echo to sense nearby objects. Bats and toothed whales rely on it to find prey.','Biosonar lets animals detect, locate, and identify objects and prey in darkness or murky water where sight fails, driving foraging and navigation.','It is studied to understand hearing and neural processing and to inform sonar design; researchers record calls and measure hearing to map biosonar performance.','Data Sonification & Auditory Display',ARRAY['echolocation click','bat call','odontocete click','echolocation','target strength']::text[],ARRAY['Treating biosonar as identical to human-made sonar rather than a biological system','Assuming only bats use it, overlooking toothed whales and other animals','Ignoring the role of hearing and brain processing, not just the emitted sound']::text[],ARRAY['Comparing bat and dolphin biosonar signal design','Modeling how a dolphin separates a target echo from clutter','Explaining why some prey evolved to detect a predator''s biosonar']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='biosonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7c50747-c16f-59fb-bca0-8cfdc0f4a8ec','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7c50747-c16f-59fb-bca0-8cfdc0f4a8ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7c50747-c16f-59fb-bca0-8cfdc0f4a8ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '924e9f21-db3e-5acc-aa39-0df0310d96ed','ultrasonic vocalization','An animal vocalization whose energy lies above the upper limit of human hearing, roughly above 20 kHz, produced by rodents, bats, and other species for communication or echolocation. In laboratory rodents, ultrasonic vocalizations are widely used as behavioral indicators of affective and social state.','An ultrasonic vocalization is an animal sound too high for people to hear. It sits above about 20,000 cycles per second. Rats, mice, and bats make these sounds. Scientists record them to study behavior and mood.','These calls carry social, mating, and alarm information, and in lab animals serve as measurable readouts of emotional and social state for research.','Neuroscientists record mouse and rat ultrasonic calls with special microphones to score social behavior, pain, and drug effects in experiments.','Data Sonification & Auditory Display',ARRAY['ultrasound','bat call','call repertoire','spectrogram','biosonar']::text[],ARRAY['Recording with gear that cannot capture frequencies above 20 kHz, missing the calls','Assuming ultrasonic means the animal cannot also hear lower sounds','Treating call presence alone as meaning, ignoring call type and context']::text[],ARRAY['Scoring rat pup isolation calls in a developmental study','Recording mouse courtship songs above human hearing','Separating bat social calls from echolocation clicks']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ultrasonic vocalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '924e9f21-db3e-5acc-aa39-0df0310d96ed','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='924e9f21-db3e-5acc-aa39-0df0310d96ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='924e9f21-db3e-5acc-aa39-0df0310d96ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9880daa-ecf6-52d4-affe-db8059f3a6c2','stridulation','Sound production by rubbing two specialized body parts together, in which a scraper moves across a file-like ridged surface to generate a train of impulses radiated as sound. It is common in insects such as crickets, katydids, and grasshoppers, and in some other invertebrates and vertebrates.','Stridulation is making sound by rubbing body parts together. One rough edge scrapes across a ridged surface. Each ridge makes a tiny click, and together they form a buzz or chirp. Crickets and grasshoppers sing this way.','Stridulation produces mating calls, territorial signals, and alarm sounds, letting small animals broadcast species identity and location without a voice organ.','Bioacousticians identify insect species and estimate temperature or abundance from stridulation recordings, since call rate often tracks temperature.','Data Sonification & Auditory Display',ARRAY['call repertoire','phonotaxis','dawn chorus','acoustic index','spectrogram']::text[],ARRAY['Confusing stridulation with vocal sound made by airflow through a voice organ','Assuming only crickets stridulate, ignoring many other insects and animals','Forgetting that call rate can change with temperature, not just species']::text[],ARRAY['Identifying a cricket species from its chirp structure','Estimating air temperature from cricket stridulation rate','Surveying grassland insect diversity by their calls']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='stridulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9880daa-ecf6-52d4-affe-db8059f3a6c2','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9880daa-ecf6-52d4-affe-db8059f3a6c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9880daa-ecf6-52d4-affe-db8059f3a6c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2cab696-2a1d-51d4-bce5-59ddcb2f88c8','phonotaxis','Oriented movement of an animal toward or away from a sound source, classified as positive when the animal approaches and negative when it withdraws. It is a key behavioral assay in studies of acoustic communication, especially female approach to male calling songs in insects and frogs.','Phonotaxis is moving toward or away from a sound. Moving toward it is positive; moving away is negative. Many female insects walk toward a male''s call. Scientists use this to test which sounds animals prefer.','Phonotaxis reveals which acoustic signals attract or repel animals, letting researchers probe mate choice, species recognition, and the tuning of the auditory system.','In a lab arena or field playback, researchers play candidate calls and measure whether and how directly an animal approaches, to test signal preferences.','Data Sonification & Auditory Display',ARRAY['call repertoire','stridulation','song dialect','acoustic masking','playback experiment']::text[],ARRAY['Assuming approach always means mate choice rather than curiosity or aggression','Ignoring that background noise can mask the signal and disrupt the response','Using playback levels far louder than natural calls, biasing the result']::text[],ARRAY['Testing which cricket song a female walks toward in a maze','Measuring frog approach to competing male calls','Checking whether traffic noise reduces phonotaxis in the field']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='phonotaxis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2cab696-2a1d-51d4-bce5-59ddcb2f88c8','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2cab696-2a1d-51d4-bce5-59ddcb2f88c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2cab696-2a1d-51d4-bce5-59ddcb2f88c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '986b5e6a-f998-5afa-b243-2eecc58324d2','dawn chorus','The concentrated peak of animal vocal activity, chiefly bird song, that occurs around sunrise, when many individuals and species sing at high rates within a short window. It is a well-documented daily pattern studied in soundscape ecology and in the behavioral ecology of acoustic timing.','The dawn chorus is the burst of bird song near sunrise. Many birds sing at once for a short time. It is the loudest, busiest part of the daily sound cycle. Scientists study why so much singing happens then.','The timing concentrates signaling when conditions favor sound travel and mate advertisement, and gives ecologists a repeatable window to sample bird activity and diversity.','Ecologists schedule recordings and point counts at dawn to survey species presence and abundance when vocal activity peaks.','Data Sonification & Auditory Display',ARRAY['acoustic index','call repertoire','soundscape','acoustic masking','song dialect']::text[],ARRAY['Assuming every species peaks at exactly the same time within the chorus','Sampling only at dawn and missing species that call later in the day','Treating chorus loudness as a direct count of individual birds']::text[],ARRAY['Timing an automated recorder to capture the dawn peak','Comparing dawn chorus richness between forest and city sites','Studying how light pollution shifts the chorus earlier']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='dawn chorus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '986b5e6a-f998-5afa-b243-2eecc58324d2','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='986b5e6a-f998-5afa-b243-2eecc58324d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='986b5e6a-f998-5afa-b243-2eecc58324d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d1f9532-9024-55b2-8091-9a57f9a7f31e','acoustic masking','The reduction in an animal''s ability to detect or discriminate a sound of interest caused by other sound, in which a masker raises the detection threshold for the signal. It is central to understanding communication in noise and the impact of human-made noise on wildlife.','Acoustic masking is when one sound hides another. Noise makes a wanted sound harder to hear. The listener needs the signal to be louder to notice it. Traffic and machine noise can mask animal calls.','Understanding masking predicts how far a signal can be heard in noise and how added noise shrinks the range over which animals communicate or detect predators.','Bioacousticians estimate active space and noise impact by comparing signal spectra with background-noise spectra to find when calls become undetectable.','Data Sonification & Auditory Display',ARRAY['masked threshold','acoustic adaptation hypothesis','dawn chorus','critical band','signal-to-noise ratio']::text[],ARRAY['Assuming only louder noise masks, ignoring that overlapping frequency matters most','Treating masking as all-or-nothing rather than a graded rise in threshold','Confusing masking of a signal with damage to hearing']::text[],ARRAY['Estimating how ship noise masks whale calls','Predicting the range a bird call carries in city noise','Designing playback tests that account for background masking']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic masking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d1f9532-9024-55b2-8091-9a57f9a7f31e','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d1f9532-9024-55b2-8091-9a57f9a7f31e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d1f9532-9024-55b2-8091-9a57f9a7f31e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '276a77e2-357a-56e6-8152-30797c4d979a','acoustic adaptation hypothesis','The hypothesis that animal acoustic signals evolve to transmit efficiently through the habitat in which they are used, so signal structure such as frequency and temporal pattern matches the sound-transmission properties of the environment. It predicts, for example, lower frequencies and slower modulation in dense forest than in open habitat.','This idea says animal calls evolve to travel well in their home habitat. A sound that carries far in a forest differs from one that carries in open land. So forest animals often use lower, slower calls. The habitat shapes the signal.','It provides a testable framework linking signal design to habitat acoustics, guiding predictions about why calls differ between environments.','Researchers compare call features across habitats and run transmission experiments, broadcasting and re-recording calls to test which structures survive best.','Data Sonification & Auditory Display',ARRAY['song dialect','acoustic masking','call repertoire','sound transmission','habitat acoustics']::text[],ARRAY['Assuming habitat is the only force shaping calls, ignoring body size and history','Testing the idea with too few species or habitats to generalize','Confusing better transmission with louder rather than clearer at distance']::text[],ARRAY['Comparing forest and grassland bird song frequencies','Broadcasting calls through habitat to measure degradation','Explaining why low-frequency calls dominate dense vegetation']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic adaptation hypothesis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '276a77e2-357a-56e6-8152-30797c4d979a','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='276a77e2-357a-56e6-8152-30797c4d979a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='276a77e2-357a-56e6-8152-30797c4d979a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '861458b9-43e1-50cf-8a3d-fd62eabc52bc','cetacean song','The long, patterned, and often hierarchically structured vocal sequences produced by certain whales, most famously humpback whales, in which repeated units form phrases and themes that recur and change over time. Cetacean song is a leading model system for vocal culture and learning in animals.','Cetacean song is the long, patterned sound made by some whales. Small units repeat to form phrases, and phrases form themes. Humpback whales are famous for it. Their songs change over time and spread between groups.','Song functions in mating and social contexts and, because it is learned and culturally transmitted, serves as a key system for studying animal culture and vocal change.','Marine bioacousticians record song with hydrophones, break it into units on spectrograms, and track how themes evolve across seasons and populations.','Data Sonification & Auditory Display',ARRAY['song dialect','call repertoire','bird song syntax','odontocete click','vocal learning']::text[],ARRAY['Assuming all whales sing, when structured song is limited to certain species','Treating song as fixed, when humpback song changes year to year','Confusing song with echolocation clicks, which serve a different purpose']::text[],ARRAY['Tracking a humpback song''s theme changes across a season','Comparing song between two ocean populations','Separating baleen whale song from toothed whale clicks']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='cetacean song');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '861458b9-43e1-50cf-8a3d-fd62eabc52bc','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='861458b9-43e1-50cf-8a3d-fd62eabc52bc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='861458b9-43e1-50cf-8a3d-fd62eabc52bc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8828d6f9-c0b2-5666-b97c-0d2a0d28b655','bird song syntax','The rules governing how discrete song elements, such as notes and syllables, are ordered and combined into sequences in birdsong, describing the permissible transitions and higher-order structure of a song. Syntax is studied with transition statistics and formal grammars to characterize sequencing complexity.','Bird song syntax is the rules for ordering song parts. It describes which notes follow which. Some birds keep a strict order; others vary it. Scientists map these rules to study how complex a song is.','Characterizing syntax reveals how much structure and information a song carries and supports comparisons of sequencing complexity across species.','Researchers label song elements, build transition matrices, and fit sequence models to quantify a species'' song syntax from recordings.','Data Sonification & Auditory Display',ARRAY['call repertoire','song dialect','cetacean song','vocal learning','spectrogram']::text[],ARRAY['Equating song syntax directly with the grammar of human language','Labeling elements inconsistently, which corrupts the transition statistics','Assuming fixed order when many species allow variable sequencing']::text[],ARRAY['Building a transition matrix for a warbler''s song elements','Comparing sequencing complexity across songbird species','Testing whether syntax rules differ between dialects']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='bird song syntax');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8828d6f9-c0b2-5666-b97c-0d2a0d28b655','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8828d6f9-c0b2-5666-b97c-0d2a0d28b655') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8828d6f9-c0b2-5666-b97c-0d2a0d28b655');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '842db8dd-7ca0-57e2-a5d4-c69e5d1efb05','bat call','An ultrasonic vocalization emitted by a bat for echolocation or communication, characterized by parameters such as frequency range, sweep shape, duration, and repetition rate that vary with species and behavioral phase. Echolocation calls are often frequency-modulated sweeps or constant-frequency components used to detect and track prey.','A bat call is a high sound a bat makes to sense or to signal. Many calls sweep from a high pitch to a lower one. The call''s shape and rate change as the bat hunts. Most bat calls are too high for people to hear.','Echolocation calls probe the environment for prey and obstacles, while social calls carry communication; call features let bats match sensing to their task.','Ecologists identify bat species and activity from call recordings on acoustic detectors, classifying calls by frequency and sweep shape.','Data Sonification & Auditory Display',ARRAY['echolocation click','biosonar','ultrasonic vocalization','interclick interval','call repertoire']::text[],ARRAY['Assuming one call type per species, ignoring search, approach, and terminal phases','Using microphones that cannot capture the call''s high frequencies','Confusing social calls with echolocation calls during identification']::text[],ARRAY['Classifying bat species from detector recordings on a survey','Studying the feeding buzz as a bat closes on an insect','Separating echolocation from social calls in a roost recording']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='bat call');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '842db8dd-7ca0-57e2-a5d4-c69e5d1efb05','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='842db8dd-7ca0-57e2-a5d4-c69e5d1efb05') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='842db8dd-7ca0-57e2-a5d4-c69e5d1efb05');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e81d3e1-6a1c-5591-80ca-bfe008a56662','odontocete click','A short, broadband echolocation click produced by a toothed whale using nasal air-driven sound generators and focused by the melon, used to detect and characterize prey and surroundings. Click source levels, spectra, and inter-click intervals vary among species and foraging phases.','An odontocete click is a sharp sound made by a toothed whale. The whale makes it in its nasal passages and aims it with a fatty forehead. It listens for the echo to find prey. Dolphins and sperm whales click this way.','Clicks form the outgoing signal of toothed-whale biosonar, enabling foraging and navigation in dark or turbid water.','Marine researchers detect and classify species from click trains on hydrophones and study foraging by tracking click rate and the terminal buzz.','Data Sonification & Auditory Display',ARRAY['echolocation click','biosonar','cetacean song','interclick interval','target strength']::text[],ARRAY['Confusing clicks with whistles, which are tonal communication sounds','Assuming clicks come from the larynx rather than the nasal system','Undersampling the click''s high frequencies with slow recorders']::text[],ARRAY['Identifying sperm whales from regular echolocation clicks','Detecting a foraging buzz as a dolphin captures prey','Estimating animal range from inter-click interval']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='odontocete click');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e81d3e1-6a1c-5591-80ca-bfe008a56662','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e81d3e1-6a1c-5591-80ca-bfe008a56662') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e81d3e1-6a1c-5591-80ca-bfe008a56662');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67fdff39-6924-5edd-acd6-a6847357cb51','acoustic index','A quantitative metric computed from an audio recording to summarize a property of a soundscape, such as acoustic complexity, diversity, or the balance of biological and human sound, used as a proxy for biodiversity or habitat condition in ecoacoustics. Examples include the Acoustic Complexity Index and the Acoustic Diversity Index.','An acoustic index is a number that sums up a soundscape. It is computed from a recording to measure things like sound variety. Ecologists use it as a quick stand-in for wildlife richness. Different indices capture different features.','Indices let researchers compare and monitor many sites and long recordings automatically, without hand-identifying every sound, to track biodiversity and habitat change.','Ecoacousticians run software over long recordings to compute indices and compare habitats, seasons, or disturbance levels.','Data Sonification & Auditory Display',ARRAY['dawn chorus','soundscape','acoustic masking','call repertoire','spectrogram']::text[],ARRAY['Treating a single index as a direct, exact count of species','Ignoring that noise and rain can distort index values','Comparing indices computed with different settings or software']::text[],ARRAY['Comparing acoustic complexity between protected and logged forest','Tracking soundscape change across seasons at one site','Screening long recordings before detailed manual analysis']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67fdff39-6924-5edd-acd6-a6847357cb51','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67fdff39-6924-5edd-acd6-a6847357cb51') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67fdff39-6924-5edd-acd6-a6847357cb51');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a941878-a643-5db1-886f-3ee4152b6fd2','tympanometry','An objective clinical test of middle-ear function that measures the acoustic admittance, or immittance, of the ear as air pressure in the sealed ear canal is varied, producing a tympanogram that reflects eardrum and middle-ear mobility. It helps identify conditions such as middle-ear effusion, eustachian-tube dysfunction, or ossicular problems.','Tympanometry is a test of how well the middle ear moves. A probe changes the air pressure in the ear canal and measures sound flow. The result is a graph called a tympanogram. It helps find fluid or pressure problems behind the eardrum.','It provides an objective, quick check of middle-ear status that complements hearing tests and helps distinguish conductive problems from other causes of hearing loss.','Audiologists run tympanometry during a hearing assessment to detect middle-ear fluid, especially in children with suspected ear infections.','Data Sonification & Auditory Display',ARRAY['middle-ear compliance','acoustic reflex','acoustic immittance','conductive hearing loss','audiometry']::text[],ARRAY['Reading a flat tympanogram as deafness rather than a middle-ear or seal issue','Failing to get an airtight probe seal, giving invalid results','Interpreting the tympanogram without the patient''s history and other tests']::text[],ARRAY['Screening a child for middle-ear fluid before treatment','Distinguishing conductive from sensorineural hearing loss','Checking eustachian-tube function after a pressure complaint']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='tympanometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a941878-a643-5db1-886f-3ee4152b6fd2','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a941878-a643-5db1-886f-3ee4152b6fd2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a941878-a643-5db1-886f-3ee4152b6fd2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '91135d6e-f608-5977-89d4-361b9ff147ce','masked threshold','The sound level at which a signal becomes just detectable in the presence of a specified masker, as opposed to the quiet, or absolute, threshold. The elevation of threshold caused by the masker quantifies the amount of masking and depends on the spectral and temporal relationship between signal and masker.','A masked threshold is the softest a sound can be and still be heard over noise. It is higher than the threshold in quiet. The more the noise overlaps the sound, the higher it climbs. It measures how much the noise hides the sound.','The masked threshold quantifies masking, underpinning models of hearing in noise, audio coding that hides quantization noise, and predictions of signal detectability.','Audiologists and psychoacousticians measure masked thresholds to study hearing in noise, and audio-coder designers use masking models to keep quantization noise inaudible.','Data Sonification & Auditory Display',ARRAY['acoustic masking','critical band','absolute threshold','signal-to-noise ratio','psychoacoustics']::text[],ARRAY['Confusing the masked threshold with the absolute threshold in quiet','Assuming masking depends only on level and not on frequency overlap','Ignoring that timing between signal and masker changes the threshold']::text[],ARRAY['Measuring speech detection in background noise','Setting bit allocation in a perceptual audio coder','Comparing masked thresholds in normal and impaired listeners']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='masked threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '91135d6e-f608-5977-89d4-361b9ff147ce','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='91135d6e-f608-5977-89d4-361b9ff147ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='91135d6e-f608-5977-89d4-361b9ff147ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd7431da-b928-53c6-923f-464c127b3997','acoustic reflex','An involuntary contraction of the middle-ear muscles, chiefly the stapedius, in response to intense sound, which stiffens the ossicular chain and reduces sound transmission to the inner ear. Its threshold and decay are measured clinically to assess middle-ear, cochlear, and auditory-nerve function.','The acoustic reflex is a muscle response in the ear to loud sound. A small muscle tightens and stiffens the tiny ear bones. This lowers how much loud sound reaches the inner ear. Clinicians measure it to test hearing pathways.','The reflex offers some protection against sustained loud low-frequency sound and, clinically, its threshold and decay help locate problems along the auditory pathway.','Audiologists measure acoustic reflex thresholds and decay during immittance testing to help distinguish middle-ear, cochlear, and nerve disorders.','Data Sonification & Auditory Display',ARRAY['tympanometry','middle-ear compliance','acoustic immittance','stapedius muscle','auditory pathway']::text[],ARRAY['UNSAFE: believing the acoustic reflex fully protects hearing from loud or sudden sounds','Assuming it responds fast enough to guard against impulse noise like gunfire','Reading an absent reflex as one fixed diagnosis rather than several possibilities']::text[],ARRAY['Measuring reflex thresholds during a diagnostic hearing workup','Using reflex decay to help flag a retrocochlear problem','Explaining why the reflex cannot protect against a gunshot']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic reflex');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd7431da-b928-53c6-923f-464c127b3997','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd7431da-b928-53c6-923f-464c127b3997') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd7431da-b928-53c6-923f-464c127b3997');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd50389b9-f8fb-513b-ade2-9e76328dabb0','tinnitus matching','A psychoacoustic procedure in which a patient adjusts or selects external tones or noises to match the perceived pitch and loudness of their tinnitus, yielding estimates of tinnitus frequency and loudness level. It supports characterization, counseling, and sound-therapy planning, though matches can be variable.','Tinnitus matching is finding a sound that matches a person''s ringing. The patient compares tones until one matches the pitch. They also match how loud it seems. This gives a rough measure of the tinnitus.','Matching quantifies otherwise private tinnitus so clinicians can describe it, track change, and plan sound-based therapy, while noting its variability.','Audiologists present test tones and ask the patient to match pitch and loudness during a tinnitus assessment, recording the matched frequency and level.','Data Sonification & Auditory Display',ARRAY['masked threshold','tinnitus','audiometry','loudness matching','psychoacoustics']::text[],ARRAY['Treating a single match as an exact, stable measure of the tinnitus','Confusing the matched loudness level with how bothersome the tinnitus is','Skipping octave-confusion checks when matching pitch']::text[],ARRAY['Estimating a patient''s tinnitus pitch during assessment','Setting a sound-therapy tone based on the match','Tracking match changes over a course of treatment']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='tinnitus matching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd50389b9-f8fb-513b-ade2-9e76328dabb0','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d50389b9-f8fb-513b-ade2-9e76328dabb0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d50389b9-f8fb-513b-ade2-9e76328dabb0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b0690fa8-9831-52ae-b2ae-6a2cb809a03f','cochlear microphonic','An alternating-current electrical potential generated by the cochlear hair cells, chiefly the outer hair cells, that follows the waveform of the stimulating sound and can be recorded from the round window or ear canal. It reflects hair-cell transduction and is used, for example, to help identify auditory neuropathy.','The cochlear microphonic is an electrical signal from the inner ear. It follows the shape of the incoming sound wave. Hair cells in the cochlea produce it. Clinicians use it to check how those cells respond.','Because it mirrors the sound waveform and arises from hair cells, it provides a physiological probe of cochlear function that helps separate sensory from neural disorders.','In electrophysiology and newborn testing, the cochlear microphonic is examined within evoked-response recordings to help detect auditory neuropathy.','Data Sonification & Auditory Display',ARRAY['acoustic reflex','otoacoustic emission','auditory brainstem response','hair cell','cochlea']::text[],ARRAY['Confusing the cochlear microphonic with an otoacoustic emission','Mistaking stimulus electrical artifact for the true response','Assuming its presence alone proves normal hearing']::text[],ARRAY['Helping identify auditory neuropathy in an infant','Separating hair-cell from nerve responses in electrophysiology','Verifying a response is biological, not stimulus artifact']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='cochlear microphonic');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b0690fa8-9831-52ae-b2ae-6a2cb809a03f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b0690fa8-9831-52ae-b2ae-6a2cb809a03f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b0690fa8-9831-52ae-b2ae-6a2cb809a03f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7abc949b-4f46-5478-8c23-be1156cda50d','middle-ear compliance','A measure of the ease with which the tympanic membrane and ossicular chain move in response to sound or pressure, expressed as acoustic compliance or admittance and assessed during tympanometry. Abnormal compliance indicates stiffening or discontinuity of the middle-ear system.','Middle-ear compliance is how easily the eardrum and ear bones move. High compliance means they move loosely. Low compliance means they are stiff. Tympanometry measures it to find middle-ear problems.','Compliance quantifies middle-ear mobility, helping detect fluid, stiffening, or a break in the ossicular chain that alters sound conduction.','Audiologists read middle-ear compliance from the tympanogram peak to assess conditions such as effusion, otosclerosis, or ossicular discontinuity.','Data Sonification & Auditory Display',ARRAY['tympanometry','acoustic immittance','acoustic reflex','conductive hearing loss','ossicular chain']::text[],ARRAY['Confusing compliance with hearing sensitivity itself','Ignoring ear-canal volume when interpreting the compliance value','Assuming one compliance value fits all ages and ear sizes']::text[],ARRAY['Reading tympanogram peak height to judge middle-ear mobility','Flagging low compliance that suggests fluid or stiffening','Detecting high compliance from a loose ossicular chain']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='middle-ear compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7abc949b-4f46-5478-8c23-be1156cda50d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7abc949b-4f46-5478-8c23-be1156cda50d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7abc949b-4f46-5478-8c23-be1156cda50d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77ad9ed4-4fe4-5f9f-8765-aec375b1b7c5','lithotripsy','A medical procedure that uses focused acoustic shock waves to fragment stones, most commonly kidney or ureteral stones in extracorporeal shock wave lithotripsy, so the fragments can pass or be removed. Shock waves are generated outside the body and focused on the stone through coupling to the tissue.','Lithotripsy uses focused sound shock waves to break stones in the body. It most often targets kidney stones. The waves are made outside the body and aimed at the stone. The broken pieces can then pass out.','It breaks hard stones without surgery so they can clear naturally, avoiding or reducing the need for an operation.','Urologists position the focus on a kidney stone under imaging guidance and deliver repeated shock waves to fragment it in an outpatient setting.','Data Sonification & Auditory Display',ARRAY['HIFU','shock wave','medical ultrasound','cavitation','focused ultrasound']::text[],ARRAY['Confusing shock-wave lithotripsy with laser stone treatment used endoscopically','Assuming it works equally on all stone sizes and compositions','Ignoring that cavitation and tissue effects require careful dosing']::text[],ARRAY['Fragmenting a kidney stone without surgery','Targeting the shock-wave focus under imaging guidance','Selecting patients by stone size and location']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='lithotripsy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77ad9ed4-4fe4-5f9f-8765-aec375b1b7c5','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77ad9ed4-4fe4-5f9f-8765-aec375b1b7c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77ad9ed4-4fe4-5f9f-8765-aec375b1b7c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ae8d4fe-c653-54d0-aebd-7e163344a3cf','HIFU','High-intensity focused ultrasound, a therapeutic technique that concentrates ultrasonic energy at a focal point to raise tissue temperature enough for thermal ablation, or to induce mechanical effects, without incising the body. It is used to treat tumors and other targets under image guidance.','HIFU stands for high-intensity focused ultrasound. It focuses sound energy to a tiny point inside the body. There the sound heats and destroys tissue. Doctors use it to treat some tumors without cutting.','HIFU delivers targeted, non-invasive tissue destruction, sparing surrounding structures and avoiding an incision.','Clinicians use image-guided HIFU to ablate tumors such as uterine fibroids or prostate tissue, monitoring the focal heating in real time.','Data Sonification & Auditory Display',ARRAY['lithotripsy','focused ultrasound','medical ultrasound','cavitation','thermal ablation']::text[],ARRAY['Confusing HIFU''s thermal ablation with diagnostic imaging ultrasound','Assuming it poses no risk to tissue in the beam path','Overlooking the need for motion tracking and temperature monitoring']::text[],ARRAY['Ablating a uterine fibroid under image guidance','Treating localized prostate tissue without an incision','Monitoring focal temperature during treatment']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='HIFU');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ae8d4fe-c653-54d0-aebd-7e163344a3cf','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ae8d4fe-c653-54d0-aebd-7e163344a3cf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ae8d4fe-c653-54d0-aebd-7e163344a3cf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7cca005-0710-5c72-8704-5af82a59d7be','ENF analysis','Electric Network Frequency analysis, a forensic audio technique that extracts the small fluctuations of the mains power frequency, nominally 50 or 60 Hz, captured incidentally in a recording and compares them against a reference database to authenticate, date, or time-align the recording. The ENF signal enters recordings through electrical interference or device coupling.','ENF analysis uses the power-grid hum captured in a recording. The grid frequency drifts slightly over time in a unique pattern. Investigators match that pattern to grid records. This can show when a recording was made or if it was edited.','It provides an independent timestamp and integrity check for recordings, helping confirm when audio was captured and detect cuts or edits.','Forensic analysts extract the ENF trace from a recording and correlate it with a grid-frequency database to verify time and continuity in casework.','Data Sonification & Auditory Display',ARRAY['spectrographic comparison','acoustic event reconstruction','mains hum','authentication','spectrogram']::text[],ARRAY['Assuming every recording contains a usable ENF trace','Ignoring that heavy compression can destroy the ENF signal','Treating an ENF match as proof without corroborating evidence']::text[],ARRAY['Estimating when a disputed recording was made','Checking whether a recording was cut or spliced','Aligning several recordings by their shared grid signature']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ENF analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7cca005-0710-5c72-8704-5af82a59d7be','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7cca005-0710-5c72-8704-5af82a59d7be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7cca005-0710-5c72-8704-5af82a59d7be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96fc3c20-ac3a-5821-892a-8b306ca73c2c','gunshot acoustics','The study of the sound produced by firearms, comprising the muzzle blast from expanding propellant gases and, for supersonic projectiles, a ballistic shock wave, together with reflections. Analysis of these components supports forensic tasks such as locating the shooter, counting shots, and estimating firearm type.','Gunshot acoustics studies the sound a gun makes. A shot has a blast from the muzzle and, for fast bullets, a sharp crack. Echoes follow from nearby surfaces. Experts read these sounds to learn where and how a shot was fired.','It lets investigators reconstruct shooting events from audio, estimating shooter location, number of shots, and sometimes weapon or distance.','Forensic audio experts analyze recordings from phones, body cameras, or gunshot sensors to locate and count shots in an investigation.','Data Sonification & Auditory Display',ARRAY['muzzle blast','ballistic shock wave','shot-timing analysis','impulse localization','acoustic event reconstruction']::text[],ARRAY['Confusing the muzzle blast with the bullet''s shock wave','Assuming a single loud peak equals a single shot in echoic scenes','Ignoring how recording clipping distorts the true peak level']::text[],ARRAY['Locating a shooter from multiple recordings','Counting rounds fired in a disputed incident','Distinguishing gunfire from fireworks on a recording']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='gunshot acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96fc3c20-ac3a-5821-892a-8b306ca73c2c','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96fc3c20-ac3a-5821-892a-8b306ca73c2c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96fc3c20-ac3a-5821-892a-8b306ca73c2c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1adcd2ae-40e1-51e5-8f3b-c1056b769c79','muzzle blast','The acoustic pressure wave generated by the rapid expansion of high-pressure propellant gases as they exit a firearm''s muzzle, radiating a loud, roughly omnidirectional impulsive sound whose amplitude and directivity depend on the weapon and load. In forensic audio it is one of the two main gunshot components, distinct from the ballistic shock wave.','A muzzle blast is the loud bang from a gun''s muzzle. It comes from hot gases bursting out behind the bullet. The sound spreads in all directions, loudest toward the front. It is one of the main parts of a gunshot sound.','The muzzle blast marks the moment and location of firing, providing the acoustic feature used to detect, locate, and time shots.','Forensic analysts and gunshot-detection systems use the muzzle blast''s arrival times across sensors to locate the firing point.','Data Sonification & Auditory Display',ARRAY['gunshot acoustics','ballistic shock wave','shot-timing analysis','impulse localization','impulse noise']::text[],ARRAY['UNSAFE: treating a firearm muzzle blast as safe for unprotected ears, when peak levels can cause immediate hearing damage','Confusing the muzzle blast with the supersonic bullet''s shock wave','Reading a clipped recording peak as the true blast level']::text[],ARRAY['Locating a shooter from muzzle-blast arrival times','Separating the blast from the bullet''s crack on a recording','Estimating firing direction from blast directivity']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='muzzle blast');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1adcd2ae-40e1-51e5-8f3b-c1056b769c79','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1adcd2ae-40e1-51e5-8f3b-c1056b769c79') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1adcd2ae-40e1-51e5-8f3b-c1056b769c79');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'efa3d961-5957-5001-b367-07f37a4833d2','ballistic shock wave','The conical shock wave, or Mach cone, generated by a projectile traveling faster than the speed of sound, heard as a sharp crack that precedes the muzzle blast at points near the trajectory. Its arrival and geometry encode the projectile''s path and speed, making it valuable for shooter and trajectory reconstruction.','A ballistic shock wave is the crack from a supersonic bullet. A bullet faster than sound pushes a cone-shaped wave, like a tiny sonic boom. Near the bullet''s path you hear this crack first. Its timing reveals the bullet''s path.','The shock wave carries trajectory and speed information independent of the muzzle blast, helping reconstruct where a bullet passed and its direction.','Forensic and defense sensor systems use the shock wave, together with the muzzle blast, to compute bullet trajectory and shooter location.','Data Sonification & Auditory Display',ARRAY['muzzle blast','gunshot acoustics','shot-timing analysis','impulse localization','Mach cone']::text[],ARRAY['Assuming every gunshot produces a shock wave, when subsonic rounds do not','Confusing the shock-wave crack with the muzzle blast','Ignoring that the crack is heard only near the bullet''s path']::text[],ARRAY['Reconstructing a bullet''s trajectory from shock-wave timing','Distinguishing supersonic from subsonic gunfire on a recording','Combining crack and blast to locate a shooter']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ballistic shock wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'efa3d961-5957-5001-b367-07f37a4833d2','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='efa3d961-5957-5001-b367-07f37a4833d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='efa3d961-5957-5001-b367-07f37a4833d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d7f40f3-d02e-5c7e-a575-54e03ffa8d6d','shot-timing analysis','The forensic examination of the temporal spacing between gunshot sounds in a recording to determine the number of shots, their sequence, rate of fire, and whether more than one firearm was involved. It relies on identifying discrete impulsive events and measuring inter-shot intervals despite echoes and overlapping sounds.','Shot-timing analysis studies the gaps between gunshots in a recording. It counts shots and measures how fast they came. The pattern can show if more than one gun fired. Echoes make this tricky to do well.','It reconstructs the sequence and rate of gunfire, informing questions about shot count, automatic versus manual fire, and the number of shooters.','Forensic audio experts mark impulsive peaks on a waveform, separate echoes from true shots, and measure intervals to build a timeline for court.','Data Sonification & Auditory Display',ARRAY['gunshot acoustics','muzzle blast','ballistic shock wave','acoustic event reconstruction','impulse localization']::text[],ARRAY['Counting reflections and echoes as additional shots','Assuming even spacing proves automatic fire','Ignoring recording clipping that can merge or hide closely spaced shots']::text[],ARRAY['Determining how many shots were fired in an incident','Estimating rate of fire to help infer weapon type','Testing whether two firearms were present']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='shot-timing analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d7f40f3-d02e-5c7e-a575-54e03ffa8d6d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d7f40f3-d02e-5c7e-a575-54e03ffa8d6d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d7f40f3-d02e-5c7e-a575-54e03ffa8d6d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d97b5d0-58c3-5c05-ae89-5dd69fcf3458','voice comparison','Forensic speaker comparison, the examination of questioned and known voice recordings to assess whether they were produced by the same speaker, using auditory-phonetic and acoustic-phonetic analysis and, increasingly, automatic speaker-recognition methods, with conclusions expressed as likelihood ratios. It must account for within-speaker variation and recording conditions.','Voice comparison checks if two recordings are the same speaker. Experts listen and also measure speech sounds. Software can help score the match. Results give the strength of evidence, not proof.','It supports investigations and courts in weighing whether a suspect''s voice matches a questioned recording, while expressing uncertainty honestly.','Forensic phoneticians analyze speech samples with listening and acoustic measurement, and may run speaker-recognition systems, reporting a likelihood ratio.','Data Sonification & Auditory Display',ARRAY['spectrographic comparison','background-noise profiling','microphone fingerprint','codec fingerprint','speaker recognition']::text[],ARRAY['Treating a voice match as a unique, certain identification','Ignoring that phones, codecs, and noise alter voice features','Relying on the discredited voiceprint idea of one-to-one voice patterns']::text[],ARRAY['Comparing a suspect''s voice with a threatening call','Reporting speaker-comparison evidence as a likelihood ratio','Accounting for codec effects before comparing samples']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='voice comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d97b5d0-58c3-5c05-ae89-5dd69fcf3458','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d97b5d0-58c3-5c05-ae89-5dd69fcf3458') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d97b5d0-58c3-5c05-ae89-5dd69fcf3458');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4eb12b3d-9675-5979-8dc2-7689e5a7a815','acoustic event reconstruction','The forensic process of interpreting the sounds captured in a recording to reconstruct the sequence, timing, location, and nature of physical events, such as gunshots, impacts, or speech, from their acoustic traces. It integrates signal analysis, room acoustics, and knowledge of source mechanisms.','Acoustic event reconstruction rebuilds what happened from a recording''s sounds. Experts work out the order, timing, and place of events. They use knowledge of how sounds are made and how rooms echo. It helps explain incidents caught on audio.','It turns a raw recording into a timeline of physical events for investigations, clarifying what happened, when, and where.','Forensic analysts examine body-camera or surveillance audio to reconstruct an incident''s shots, movements, and speech for legal proceedings.','Data Sonification & Auditory Display',ARRAY['gunshot acoustics','shot-timing analysis','impulse localization','reverberant signature','ENF analysis']::text[],ARRAY['Overreading ambiguous sounds as specific, certain events','Ignoring room reflections that duplicate or delay sounds','Assuming a recording captured every event that occurred']::text[],ARRAY['Reconstructing a shooting timeline from body-camera audio','Placing events in sequence from surveillance sound','Combining acoustic clues with other evidence']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic event reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4eb12b3d-9675-5979-8dc2-7689e5a7a815','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4eb12b3d-9675-5979-8dc2-7689e5a7a815') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4eb12b3d-9675-5979-8dc2-7689e5a7a815');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53205c65-8925-5ff0-987b-0d8472e621bf','impulse localization','The estimation of the spatial position or bearing of a transient sound source, such as a gunshot or impact, from the differences in arrival time, level, or phase of the impulse across spatially separated microphones. It underlies gunshot-detection systems and forensic shooter-location analysis.','Impulse localization finds where a sharp sound came from. It compares when the sound reaches spread-out microphones. Small timing differences point to the source. Gunshot-detection systems work this way.','It converts multi-microphone timing data into a source location or direction, enabling automatic gunshot detection and forensic shooter placement.','Engineers and analysts use time-difference-of-arrival across a microphone array to compute the position of a gunshot or impact.','Data Sonification & Auditory Display',ARRAY['gunshot acoustics','muzzle blast','time difference of arrival','shot-timing analysis','microphone array']::text[],ARRAY['Ignoring reflections that give false arrival times','Assuming accurate results from poorly synchronized microphones','Using too small an array spacing for the source distance']::text[],ARRAY['Locating a gunshot with a sensor array in a city','Estimating shooter bearing from spread microphones','Correcting timing for sensor clock offsets']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='impulse localization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53205c65-8925-5ff0-987b-0d8472e621bf','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53205c65-8925-5ff0-987b-0d8472e621bf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53205c65-8925-5ff0-987b-0d8472e621bf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c742444d-7f3a-5916-a7a3-636052e099d6','reverberant signature','The characteristic pattern of reflections and reverberation that a specific environment imprints on sound recorded within it, determined by room geometry, surfaces, and source-receiver positions. In forensic and audio analysis it can help associate a recording with a particular space or reveal editing.','A reverberant signature is the echo pattern a space adds to sound. Each room reflects sound in its own way. That pattern is stamped onto any recording made there. Experts use it to link audio to a place or spot edits.','It provides an acoustic fingerprint of the recording space, supporting authentication, place association, and detection of splices where the reverberation changes.','Forensic analysts compare reverberation and reflection patterns to test whether a recording was made in a claimed room or was edited.','Data Sonification & Auditory Display',ARRAY['roomprint','reverberation time','acoustic event reconstruction','microphone fingerprint','impulse response']::text[],ARRAY['Assuming the signature is fixed when microphone position changes it','Confusing added artificial reverb with a real room''s signature','Ignoring that moving sources smear the reflection pattern']::text[],ARRAY['Testing whether audio was recorded in a claimed room','Detecting a splice from a sudden reverberation change','Associating a recording with a specific space']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='reverberant signature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c742444d-7f3a-5916-a7a3-636052e099d6','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c742444d-7f3a-5916-a7a3-636052e099d6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c742444d-7f3a-5916-a7a3-636052e099d6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '027ff6b6-79a2-52cf-a1f2-3e8a0775dc45','roomprint','A distinctive acoustic characterization of a specific room, analogous to a fingerprint, derived from the room''s impulse response or reverberation features and used to identify or verify the space in which a recording was made. It captures how the room uniquely colors sound through its reflections and modes.','A roomprint is a room''s unique sound signature. Like a fingerprint, it points to one room. It comes from how the room echoes and colors sound. Experts can match a recording to the room it was made in.','It enables associating recordings with specific spaces and verifying recording location, useful in forensics and media authentication.','Analysts estimate a room''s response from a recording and compare it against known roomprints to confirm or refute where audio came from.','Data Sonification & Auditory Display',ARRAY['reverberant signature','impulse response','microphone fingerprint','reverberation time','acoustic event reconstruction']::text[],ARRAY['Assuming a roomprint is perfectly unique and unchanging','Ignoring that furniture and occupancy change room acoustics','Confusing the roomprint with the microphone''s own signature']::text[],ARRAY['Matching a recording to a suspected room','Verifying claimed recording locations in casework','Detecting a relocation edit within one file']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='roomprint');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '027ff6b6-79a2-52cf-a1f2-3e8a0775dc45','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='027ff6b6-79a2-52cf-a1f2-3e8a0775dc45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='027ff6b6-79a2-52cf-a1f2-3e8a0775dc45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75bf4986-a2ea-5458-a516-e0ee48aae6d7','microphone fingerprint','A distinctive pattern of characteristics that a specific microphone or recording device imparts to its output, arising from frequency response, nonlinearities, and self-noise, used forensically to associate a recording with a particular device or class. It is one form of acoustic-device identification.','A microphone fingerprint is the mark a specific mic leaves on its recordings. Each mic has small quirks in tone and noise. These quirks can link a recording to one device. Investigators use them to trace a recording''s source.','It supports linking recordings to a suspected device and detecting mismatches that suggest editing or a different source.','Forensic analysts measure device-specific features such as noise and response to test whether a recording came from a given microphone or phone.','Data Sonification & Auditory Display',ARRAY['codec fingerprint','roomprint','reverberant signature','voice comparison','background-noise profiling']::text[],ARRAY['Assuming every microphone leaves a unique, stable fingerprint','Confusing microphone effects with codec or room effects','Ignoring that processing can erase device features']::text[],ARRAY['Testing whether a recording came from a seized phone','Detecting a device change within one file','Separating microphone traits from room and codec effects']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='microphone fingerprint');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75bf4986-a2ea-5458-a516-e0ee48aae6d7','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75bf4986-a2ea-5458-a516-e0ee48aae6d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75bf4986-a2ea-5458-a516-e0ee48aae6d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6cc820a4-3d59-5e9d-9582-fdb182c3120d','codec fingerprint','The characteristic traces left in an audio signal by a specific compression codec and its settings, such as frame boundaries, quantization patterns, and spectral cutoffs, used forensically to infer a recording''s processing history or detect re-encoding and edits. Different codecs and bit rates leave distinguishable artifacts.','A codec fingerprint is the mark that audio compression leaves behind. Each codec and setting alters the sound in its own way. Experts read these traces to learn how a file was made. They can spot re-saving or edits.','It reveals a recording''s compression history, helping detect tampering, re-encoding, and inconsistencies with a claimed origin.','Forensic analysts inspect spectral cutoffs and frame patterns to identify the codec and detect double compression or splicing.','Data Sonification & Auditory Display',ARRAY['compression artifact','microphone fingerprint','spectrographic comparison','ENF analysis','background-noise profiling']::text[],ARRAY['Assuming an uncompressed-looking file has never been compressed before','Confusing codec artifacts with real acoustic content','Ignoring that re-encoding can hide an earlier codec''s traces']::text[],ARRAY['Identifying the codec used on a submitted file','Detecting double compression as a sign of editing','Checking whether a file matches its claimed source device']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='codec fingerprint');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6cc820a4-3d59-5e9d-9582-fdb182c3120d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6cc820a4-3d59-5e9d-9582-fdb182c3120d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6cc820a4-3d59-5e9d-9582-fdb182c3120d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '142216b4-c1cb-5ea4-b67d-0c1e3f5e7c61','compression artifact','An audible or measurable distortion introduced into audio by lossy data compression, such as pre-echo, spectral cutoff, warbling of tonal components, and loss of stereo detail, resulting from the codec discarding information judged perceptually irrelevant. Artifact type and severity depend on the codec, bit rate, and content.','A compression artifact is a flaw added by lossy audio compression. To shrink files, codecs throw away some sound data. This can cause swirling, dull highs, or smearing. Lower bit rates make these flaws worse.','Recognizing artifacts lets engineers judge audio quality and choose bit rates, and lets forensic analysts detect that a file was compressed.','Mastering and broadcast engineers audition codecs to avoid audible artifacts, and forensic analysts use artifacts to reveal a file''s compression history.','Data Sonification & Auditory Display',ARRAY['codec fingerprint','lossy compression','pre-echo','spectrographic comparison','bit rate']::text[],ARRAY['Blaming the source or microphone for distortion caused by the codec','Assuming a high bit rate always removes all artifacts','Re-encoding already compressed audio, stacking new artifacts']::text[],ARRAY['Choosing a streaming bit rate that hides artifacts','Spotting pre-echo before a sharp transient','Detecting prior compression in a forensic file']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='compression artifact');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '142216b4-c1cb-5ea4-b67d-0c1e3f5e7c61','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='142216b4-c1cb-5ea4-b67d-0c1e3f5e7c61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='142216b4-c1cb-5ea4-b67d-0c1e3f5e7c61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0bdbb3b8-43b1-5197-905f-83e964ef40a4','background-noise profiling','The characterization of the persistent ambient noise in a recording, such as hum, hiss, and environmental sound, to support authentication, source association, denoising, and detection of edits where the noise floor changes. The stable noise floor acts as a contextual signature of the recording conditions.','Background-noise profiling studies the steady noise under a recording. This includes hum, hiss, and room sounds. The noise floor is fairly stable within one recording. A sudden change in it can reveal an edit.','It provides a baseline signature of recording conditions used to authenticate audio, spot splices, guide noise reduction, and associate recordings.','Forensic analysts measure the noise spectrum across a file to detect where the background suddenly changes, flagging a possible edit.','Data Sonification & Auditory Display',ARRAY['codec fingerprint','microphone fingerprint','reverberant signature','spectrographic comparison','noise floor']::text[],ARRAY['Assuming the background is meaningless and safe to ignore','Removing noise before profiling and destroying the evidence','Reading natural noise changes as edits without corroboration']::text[],ARRAY['Detecting a splice from a noise-floor jump','Characterizing the ambient conditions of a recording','Guiding denoising with a measured noise profile']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='background-noise profiling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0bdbb3b8-43b1-5197-905f-83e964ef40a4','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0bdbb3b8-43b1-5197-905f-83e964ef40a4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0bdbb3b8-43b1-5197-905f-83e964ef40a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6871681a-dde0-5214-a826-9f84f835ae84','spectrographic comparison','The visual and quantitative comparison of spectrograms, time-frequency displays of sound, to assess similarity between signals for tasks such as species identification, signal matching, or forensic examination. It complements listening and numerical measures but must guard against subjective bias.','Spectrographic comparison lines up two spectrograms to compare sounds. A spectrogram shows how a sound''s energy spreads over pitch and time. Analysts look for matching patterns. It backs up listening with a visual check.','It gives a visual, shareable basis for judging whether two sounds are alike, aiding identification, matching, and forensic review.','Bioacousticians and forensic analysts overlay spectrograms to compare calls, tones, or voices, supporting conclusions with measurements.','Data Sonification & Auditory Display',ARRAY['spectrogram','voice comparison','codec fingerprint','background-noise profiling','compression artifact']::text[],ARRAY['Treating a visual spectrogram match as proof of identity','Comparing spectrograms made with different analysis settings','Reviving the discredited voiceprint claim of unique voice images']::text[],ARRAY['Comparing a questioned and known voice spectrogram','Matching animal calls to a reference library','Checking a signal against a suspected source']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='spectrographic comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6871681a-dde0-5214-a826-9f84f835ae84','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6871681a-dde0-5214-a826-9f84f835ae84') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6871681a-dde0-5214-a826-9f84f835ae84');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0163291a-d04c-5d11-b135-fd0df1e0649f','hydroacoustic channel','A layer in the ocean where the sound-speed profile forms a waveguide, notably the deep SOFAR channel around the sound-speed minimum, that traps and guides acoustic energy over very long ranges with low loss. Sound rays refract toward the speed minimum, confining propagation to the channel.','A hydroacoustic channel is an ocean layer that traps sound. Sound bends toward the depth where it travels slowest. Trapped there, it can travel across whole oceans. This deep channel is called the SOFAR channel.','The channel lets low-frequency sound travel thousands of kilometers, enabling long-range detection, whale communication, and ocean monitoring.','Oceanographers and defense analysts exploit the deep sound channel for long-range hydrophone detection and for acoustic monitoring of the ocean.','Data Sonification & Auditory Display',ARRAY['sound speed profile','sonar equation','SOFAR channel','refraction','underwater acoustics']::text[],ARRAY['Assuming sound travels in straight lines underwater rather than refracting','Ignoring how depth and season shift the channel axis','Confusing a surface duct with the deep sound channel']::text[],ARRAY['Detecting distant sources through the deep sound channel','Explaining long-range whale call propagation','Planning hydrophone depth to use the channel']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='hydroacoustic channel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0163291a-d04c-5d11-b135-fd0df1e0649f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0163291a-d04c-5d11-b135-fd0df1e0649f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0163291a-d04c-5d11-b135-fd0df1e0649f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ebaaa649-f0da-5c5d-90a1-86aafeec916c','sound speed profile','The variation of the speed of sound with depth in a water column, governed by temperature, salinity, and pressure, which controls how acoustic rays refract and thus determines propagation paths, ducts, and shadow zones. It is a fundamental input for underwater sound modeling.','A sound speed profile shows how fast sound travels at each depth. It depends on temperature, salt, and pressure. Because speed changes with depth, sound rays bend. This bending decides where sound can and cannot reach.','It is the key environmental input for predicting underwater propagation, revealing ducts, shadow zones, and the paths sonar signals will follow.','Sonar operators and oceanographers measure the profile to predict detection ranges and to plan sensor depths for a mission.','Data Sonification & Auditory Display',ARRAY['hydroacoustic channel','sonar equation','refraction','shadow zone','underwater acoustics']::text[],ARRAY['Assuming a single fixed sound speed for all depths','Ignoring seasonal and daily changes in the profile','Overlooking salinity, and focusing only on temperature']::text[],ARRAY['Predicting sonar range from a measured profile','Finding a surface duct that traps sound near the top','Explaining a shadow zone where a target is missed']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='sound speed profile');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ebaaa649-f0da-5c5d-90a1-86aafeec916c','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ebaaa649-f0da-5c5d-90a1-86aafeec916c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ebaaa649-f0da-5c5d-90a1-86aafeec916c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6bebb19-5da2-55a5-8987-cbee072753ac','reverberation-limited detection','A regime in active sonar in which the dominant interference masking the target echo is reverberation, the backscattered return from boundaries and scatterers of the sonar''s own transmission, rather than ambient noise. In this regime, raising source level does not improve detection because the reverberation scales with it.','This is active sonar limited by its own echoes. The pulse scatters off the seabed, surface, and objects, returning as clutter. This clutter, not background noise, hides the target. Making the pulse louder does not help, since the clutter grows too.','Recognizing this regime steers sonar design and operation toward tactics that reduce reverberation rather than simply adding power.','Sonar engineers counter reverberation-limited conditions with waveform choice, Doppler processing, and beam control instead of more source level.','Data Sonification & Auditory Display',ARRAY['noise-limited detection','sonar equation','backscatter','reverberation','matched filter']::text[],ARRAY['Raising source level to beat reverberation, which does not help','Confusing reverberation clutter with ambient noise','Ignoring Doppler that could separate a moving target from clutter']::text[],ARRAY['Detecting a slow target in shallow-water clutter','Choosing waveforms to reduce reverberation masking','Explaining why more power fails against reverberation']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='reverberation-limited detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6bebb19-5da2-55a5-8987-cbee072753ac','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6bebb19-5da2-55a5-8987-cbee072753ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6bebb19-5da2-55a5-8987-cbee072753ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd1b5a6aa-cc9e-5acb-99d8-8e1a2de6f064','noise-limited detection','A regime in sonar in which the dominant interference masking the signal is ambient or self noise rather than reverberation, so detection improves with increased signal-to-noise ratio through higher source level, array gain, or processing. It is the complementary case to reverberation-limited detection.','This is sonar limited by background noise. Ocean noise or the platform''s own noise hides the signal. Here, raising the signal above the noise helps detection. More power, bigger arrays, or better processing all improve it.','Identifying this regime tells operators that boosting signal-to-noise ratio will improve detection, unlike the reverberation-limited case.','Sonar designers improve noise-limited passive and active detection with quieter platforms, larger arrays, and integration gain.','Data Sonification & Auditory Display',ARRAY['reverberation-limited detection','sonar equation','noise floor','array gain','signal-to-noise ratio']::text[],ARRAY['Assuming all sonar conditions improve with more source level','Confusing ambient noise with self-noise from the platform','Ignoring array gain as a way to beat noise']::text[],ARRAY['Detecting a quiet target in deep, calm water','Improving detection with a longer towed array','Reducing platform self-noise to hear better']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='noise-limited detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd1b5a6aa-cc9e-5acb-99d8-8e1a2de6f064','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d1b5a6aa-cc9e-5acb-99d8-8e1a2de6f064') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d1b5a6aa-cc9e-5acb-99d8-8e1a2de6f064');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57211ec4-fbaf-56fd-9411-69b6f76246f4','sonar equation','An energy-accounting relation that balances the terms governing sonar detection, including source level, transmission loss, target strength, noise level, directivity index, and detection threshold, to predict whether a target echo is detectable. It exists in active and passive forms and is the central design and prediction tool of sonar performance analysis.','The sonar equation adds up the gains and losses in sonar. It weighs how strong the signal starts and how much it fades. It subtracts noise and the level needed to detect. The result predicts if a target can be heard.','It lets engineers predict detection range and design sonar by trading off source level, array gain, noise, and target strength before deployment.','Sonar engineers plug measured environmental and system values into the equation to estimate detection ranges and set design requirements.','Data Sonification & Auditory Display',ARRAY['noise-limited detection','reverberation-limited detection','transmission loss','target strength','directivity index']::text[],ARRAY['Mixing the active and passive forms of the equation','Using a single transmission-loss number where the environment varies','Forgetting that reverberation, not noise, may set the limit']::text[],ARRAY['Estimating detection range for a new sonar','Trading source level against array gain in design','Predicting performance for a given sound speed profile']::text[],'advanced','Active: SL - 2*TL + TS - (NL - DI) >= DT ; Passive: SL - TL - (NL - DI) >= DT','For active sonar, source level minus two-way transmission loss plus target strength, less noise level reduced by the directivity index, must reach the detection threshold; the passive form uses one-way transmission loss and drops target strength.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='sonar equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57211ec4-fbaf-56fd-9411-69b6f76246f4','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57211ec4-fbaf-56fd-9411-69b6f76246f4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57211ec4-fbaf-56fd-9411-69b6f76246f4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '839ead37-b3c4-57ea-8489-5ef0a68e90df','backscatter','The portion of transmitted acoustic energy that scatterers or boundaries return in the direction of the source, quantified by a backscattering strength, which contributes reverberation in active sonar and carries information in imaging and remote sensing. It arises from volume scatterers and from rough surface or seabed boundaries.','Backscatter is sound that bounces back toward the source. It comes off rough surfaces, the seabed, or particles in the water. In sonar it can be clutter that hides targets. In imaging it carries useful information about a surface.','Backscatter both limits detection as reverberation and provides the return signal that sonar imaging and remote sensing rely on.','Sidescan and multibeam sonar map the seabed from backscatter strength, while sonar designers treat it as reverberation to suppress.','Data Sonification & Auditory Display',ARRAY['reverberation-limited detection','target strength','sidescan sonar','sonar equation','reverberation']::text[],ARRAY['Confusing backscatter with a discrete target echo','Assuming backscatter strength is fixed regardless of angle','Ignoring how frequency changes the backscatter level']::text[],ARRAY['Mapping seabed type from backscatter strength','Treating backscatter as reverberation to suppress','Interpreting a sidescan image from backscatter']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='backscatter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '839ead37-b3c4-57ea-8489-5ef0a68e90df','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='839ead37-b3c4-57ea-8489-5ef0a68e90df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='839ead37-b3c4-57ea-8489-5ef0a68e90df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56b543e2-6469-592f-b282-b39d1b31c3e3','towfish','A hydrodynamic towed body that houses sonar transducers or other sensors and is pulled behind a survey vessel below the surface, positioning the sensor away from ship noise and at a chosen depth. It is standard for sidescan sonar, magnetometer, and other geophysical surveys.','A towfish is a sensor pod towed behind a boat underwater. It carries sonar or other instruments. Towing it deep keeps it away from ship noise and near the seabed. It is common in seabed surveys.','The towfish places sensors at a useful depth and clear of surface noise and vessel motion, improving survey data quality.','Survey crews tow a sidescan or magnetometer towfish at a set altitude above the seabed to map the bottom or find objects.','Data Sonification & Auditory Display',ARRAY['sidescan sonar','backscatter','synthetic aperture sonar','hydrographic survey','transducer']::text[],ARRAY['Confusing the towfish with a self-propelled underwater vehicle','Ignoring cable layback when fixing the towfish position','Towing at the wrong altitude, degrading sonar coverage']::text[],ARRAY['Towing a sidescan towfish to map a harbor floor','Setting towfish altitude for good sonar coverage','Correcting the position for cable layback']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='towfish');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56b543e2-6469-592f-b282-b39d1b31c3e3','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56b543e2-6469-592f-b282-b39d1b31c3e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56b543e2-6469-592f-b282-b39d1b31c3e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9000cb7f-e5dd-5e0e-8040-b05d994f9d7d','sidescan sonar','An active sonar that emits fan-shaped beams to either side of a moving platform and builds an acoustic image of the seabed from the timing and strength of backscattered returns. It produces high-resolution imagery of bottom texture and objects but not direct depth soundings.','Sidescan sonar makes a picture of the seabed. It sends wide sound beams out to each side as it moves. The strength and timing of returns form an image. It shows bottom texture and objects, but not exact depth.','It provides efficient, high-resolution imaging of the seabed for search, survey, and habitat mapping over wide swaths.','Surveyors tow a sidescan towfish to find wrecks, pipelines, or debris and to map bottom type across a survey area.','Data Sonification & Auditory Display',ARRAY['towfish','backscatter','synthetic aperture sonar','sonar equation','hydrographic survey']::text[],ARRAY['Expecting accurate water depth from sidescan, which images texture instead','Misreading acoustic shadows as objects rather than gaps behind them','Ignoring speed and altitude effects on image geometry']::text[],ARRAY['Searching for a wreck on the seabed','Mapping bottom texture across a survey swath','Reading target shadows to judge object height']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='sidescan sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9000cb7f-e5dd-5e0e-8040-b05d994f9d7d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9000cb7f-e5dd-5e0e-8040-b05d994f9d7d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9000cb7f-e5dd-5e0e-8040-b05d994f9d7d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4d8faa8-6ac8-5198-a17c-391e3208e775','synthetic aperture sonar','A sonar imaging technique that coherently combines echoes collected along a platform''s track to synthesize a much longer aperture than the physical array, yielding along-track resolution that is largely independent of range and frequency. It provides higher-resolution seabed imagery than conventional sidescan but demands precise motion estimation.','Synthetic aperture sonar builds a sharp seabed image. It combines many echoes taken along the vehicle''s path. This acts like a much longer sonar than the real one. The result stays sharp even far from the sensor.','It delivers high, range-independent resolution for detailed seabed mapping and small-object detection beyond conventional sonar limits.','Underwater vehicles use synthetic aperture sonar for mine hunting and detailed seabed surveys, relying on precise navigation to combine echoes.','Data Sonification & Auditory Display',ARRAY['sidescan sonar','backscatter','towfish','matched filter','hydrographic survey']::text[],ARRAY['Assuming it works without precise platform motion estimation','Confusing it with conventional real-aperture sidescan','Ignoring that navigation errors blur the synthesized image']::text[],ARRAY['Imaging small objects on the seabed for mine hunting','Producing high-resolution surveys from an underwater vehicle','Correcting motion errors before combining echoes']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='synthetic aperture sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4d8faa8-6ac8-5198-a17c-391e3208e775','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4d8faa8-6ac8-5198-a17c-391e3208e775') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4d8faa8-6ac8-5198-a17c-391e3208e775');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '299e8d00-4fea-5f50-b217-a64069e3fb13','acoustic Doppler current profiler','An instrument that measures water-current velocity at multiple depths by transmitting acoustic pulses and detecting the Doppler frequency shift of energy backscattered from particles moving with the water. Range gating of the return resolves velocity into depth cells, producing a profile through the water column.','This instrument measures water currents at many depths. It sends sound pulses and listens for echoes off drifting particles. Moving particles shift the echo''s pitch. That shift reveals the water''s speed at each depth.','It provides depth-resolved current measurements for oceanography, hydrology, and engineering without placing sensors throughout the water column.','Oceanographers and engineers deploy these profilers from vessels, moorings, or riverbeds to measure currents and estimate discharge.','Data Sonification & Auditory Display',ARRAY['backscatter','Doppler shift','sound speed profile','hydroacoustic channel','transducer']::text[],ARRAY['Assuming it measures the water directly rather than particles moving with it','Ignoring that sparse particles weaken the return','Neglecting sound-speed and beam-geometry corrections']::text[],ARRAY['Measuring ocean currents from a moored profiler','Estimating river discharge from a boat-mounted unit','Profiling how current changes with depth']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic Doppler current profiler');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '299e8d00-4fea-5f50-b217-a64069e3fb13','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='299e8d00-4fea-5f50-b217-a64069e3fb13') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='299e8d00-4fea-5f50-b217-a64069e3fb13');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7efe1e34-b1fd-5230-ac5c-0b05e470da5f','sound insulation','The reduction of airborne sound transmission between spaces by a building element such as a wall, floor, or partition, quantified by a frequency-dependent sound reduction index and single-number ratings. It depends on element mass, stiffness, damping, and construction such as multiple leaves and cavities.','Sound insulation is how well a wall or floor blocks sound between rooms. Heavier, well-sealed structures block more. It is measured across frequencies and given a single rating. Gaps and thin panels let sound through.','It controls noise transfer between spaces to meet privacy, comfort, and regulatory requirements in buildings.','Acousticians measure and design partitions to meet sound-insulation ratings for apartments, offices, and studios.','Data Sonification & Auditory Display',ARRAY['impact sound insulation','sound reduction index','transmission loss','flanking transmission','mass law']::text[],ARRAY['Assuming a single number describes performance at all frequencies','Ignoring flanking paths around the partition itself','Believing thin acoustic foam blocks airborne sound between rooms']::text[],ARRAY['Designing a party wall to meet a privacy rating','Diagnosing why speech passes between offices','Comparing partition build-ups for a studio']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='sound insulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7efe1e34-b1fd-5230-ac5c-0b05e470da5f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7efe1e34-b1fd-5230-ac5c-0b05e470da5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7efe1e34-b1fd-5230-ac5c-0b05e470da5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2769e63-8d41-5e0c-951e-40e8bcf9f9ea','impact sound insulation','The performance of a floor-ceiling assembly in reducing structure-borne sound generated by impacts such as footsteps, measured with a standard tapping machine and expressed by frequency-dependent and single-number impact ratings. Improvement relies on resilient layers, floating floors, and decoupling.','Impact sound insulation is how well a floor blocks footstep noise. Impacts send sound through the structure, not the air. A standard tapping machine measures it. Soft layers and floating floors reduce the noise below.','It controls footfall and impact noise passing through floors, protecting occupants below and meeting building standards.','Acousticians specify floating floors and resilient underlays and test with a tapping machine to meet impact-noise limits between dwellings.','Data Sonification & Auditory Display',ARRAY['sound insulation','floating floor','structure-borne sound','tapping machine','resilient layer']::text[],ARRAY['Confusing impact insulation with airborne sound insulation','Assuming soft carpet alone meets impact requirements at low frequency','Ignoring flanking transmission through the surrounding structure']::text[],ARRAY['Reducing footstep noise between stacked apartments','Testing a floor with a standard tapping machine','Choosing a resilient underlay to meet a rating']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='impact sound insulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2769e63-8d41-5e0c-951e-40e8bcf9f9ea','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2769e63-8d41-5e0c-951e-40e8bcf9f9ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2769e63-8d41-5e0c-951e-40e8bcf9f9ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a1226d9-f33a-5110-9ea1-0053f2871452','privacy index','A single-number measure of speech privacy between two spaces, expressed as a percentage and derived from the articulation index of the transmitted speech. It is defined so that a value of zero means fully intelligible speech leakage and a value near one hundred means speech that cannot be understood; values around ninety-five percent or above are commonly treated as confidential privacy.','The privacy index shows how private speech is between two spaces. It is a percentage from zero to one hundred. A high number means leaked speech is hard to follow. About ninety-five percent counts as confidential. It comes from a speech clarity score.','It gives a single, easy percentage so designers can set and check speech-privacy goals without reading full frequency data.','Applied in open-plan offices, exam rooms, and banks to rate confidentiality; it is derived from measured speech and background-noise levels.','Data Sonification & Auditory Display',ARRAY['Articulation index','Speech privacy','Speech Privacy Class','Signal-to-noise ratio','Sound masking']::text[],ARRAY['Confusing the privacy index with a partition''s sound transmission class','Chasing more insulation while ignoring background masking noise','Assuming one value applies at every listener position']::text[],ARRAY['Rating confidentiality in an open office','Checking privacy of a consultation room','Adding sound masking to raise privacy']::text[],'intermediate','PI = (1 − AI) × 100%','The privacy index equals one minus the articulation index, times one hundred percent.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='privacy index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a1226d9-f33a-5110-9ea1-0053f2871452','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a1226d9-f33a-5110-9ea1-0053f2871452') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a1226d9-f33a-5110-9ea1-0053f2871452');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '46901299-8d75-58c0-a7dc-b66785f9ceda','façade insulation','The airborne sound insulation provided by a building''s outer envelope, including its walls, windows, doors, and roof, against outdoor noise such as road, rail, or aircraft. It is quantified by standardized level differences or apparent sound reduction indices measured with the façade in place, and reported as a single number with low-frequency spectrum adaptation terms.','Façade insulation is how well a building''s outer skin blocks outside noise. Walls, windows, doors, and the roof all take part. Engineers measure the drop in sound from outside to inside. Traffic and aircraft are common targets. Weak windows usually leak the most sound.','It protects indoor spaces from environmental noise and helps a building meet indoor noise limits set for health and comfort.','Assessed when siting homes near roads, railways, or airports; the windows and their seals are the usual weak link a technician checks.','Data Sonification & Auditory Display',ARRAY['Sound reduction index','Sound transmission class','Outdoor-indoor transmission class','Airborne sound insulation','Spectrum adaptation term']::text[],ARRAY['Judging a façade by the wall alone and ignoring the windows','Forgetting low-frequency traffic energy when choosing a rating','Overlooking flanking through the roof or trickle vents']::text[],ARRAY['Specifying windows for a home beside a motorway','Checking indoor noise near an airport','Diagnosing traffic-noise complaints in a flat']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='façade insulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '46901299-8d75-58c0-a7dc-b66785f9ceda','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='46901299-8d75-58c0-a7dc-b66785f9ceda') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='46901299-8d75-58c0-a7dc-b66785f9ceda');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e081916-a621-5e1b-9dec-c58579cd3edf','outdoor-indoor transmission class','A single-number rating of the sound isolation of an exterior building element, such as a window, wall, or door, against typical outdoor noise. It is computed from transmission loss over roughly the 80 to 4000 hertz range using a reference spectrum weighted toward the low-frequency energy of aircraft, road, and rail noise, making it more representative of outdoor sources than the speech-based sound transmission class.','This rating shows how well a wall or window blocks outdoor noise. It uses a sound mix like traffic and planes. That mix has strong low tones. A higher rating means better blocking. It suits outside noise better than the speech-based rating.','It gives designers a rating tuned to real outdoor noise, which holds more low-frequency energy than the speech range behind the sound transmission class.','Quoted on architectural window and curtain-wall data sheets for buildings near airports, highways, or rail lines.','Data Sonification & Auditory Display',ARRAY['Sound transmission class','Façade insulation','Transmission loss','Sound reduction index','Spectrum adaptation term']::text[],ARRAY['Treating this rating and the sound transmission class as interchangeable','Ignoring that low-frequency noise drives the value','Comparing labels from different test conditions blindly']::text[],ARRAY['Selecting glazing near an airport','Comparing windows for a highway-side building','Meeting a code''s exterior noise rating']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='outdoor-indoor transmission class');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e081916-a621-5e1b-9dec-c58579cd3edf','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e081916-a621-5e1b-9dec-c58579cd3edf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e081916-a621-5e1b-9dec-c58579cd3edf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e141da61-7a0f-5d63-ac40-770919bb3e33','plenum crosstalk','Unwanted transmission of speech or noise between adjacent rooms through a shared ceiling void, or plenum, or through connecting ductwork that bypasses the dividing partition. Sound leaks up through one room''s suspended ceiling, crosses the common plenum, and drops into the neighbouring room, degrading speech privacy even when the partition itself is well rated.','Plenum crosstalk is sound sneaking over a wall through the ceiling space. Many rooms share the gap above a dropped ceiling. Speech rises into that gap and falls into the next room. The wall may look solid but still leaks. Barriers in the ceiling space help stop it.','Naming this flanking path helps designers close it, since a good partition alone cannot protect privacy if the ceiling void is open.','Investigated when speech privacy fails between offices despite a good wall; fixed with plenum barriers or high ceiling-attenuation tiles.','Data Sonification & Auditory Display',ARRAY['Flanking transmission','Ceiling attenuation class','Speech privacy','Sound transmission class','Partition']::text[],ARRAY['Blaming the partition when the ceiling plenum is the real path','Stopping partitions at the ceiling grid, not the deck above','Ignoring shared ducts and grilles as crosstalk paths']::text[],ARRAY['Fixing privacy loss between offices','Auditing a boardroom for eavesdropping paths','Specifying plenum barriers above private rooms']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='plenum crosstalk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e141da61-7a0f-5d63-ac40-770919bb3e33','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e141da61-7a0f-5d63-ac40-770919bb3e33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e141da61-7a0f-5d63-ac40-770919bb3e33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a0e65d5-6d17-5bf4-a402-af6586750606','vibration isolation','The use of resilient elements such as steel springs, elastomer mounts, or air springs to reduce the transmission of vibratory forces between a machine and its supporting structure. Isolation occurs when the disturbing frequency lies well above the mount''s natural frequency, where transmissibility falls below one; near the natural frequency the mount instead amplifies vibration at resonance.','Vibration isolation keeps a machine''s shaking out of the building. Springs or rubber mounts sit under the machine. They work when the shaking is much faster than the mount''s own bounce. Then less force reaches the floor. Near the mount''s own rate, they make things worse.','It cuts structure-borne noise and protects sensitive gear by breaking the solid path that carries vibration into a building.','Used to mount fans, pumps, generators, and studio floors; mounts are chosen so the natural frequency sits well below the running speed.','Data Sonification & Auditory Display',ARRAY['Structure-borne noise','Transmissibility','Natural frequency','Resilient mount','Resonance']::text[],ARRAY['UNSAFE: wrongly sizing or overloading isolation springs so a heavy machine becomes unstable or tips','Picking mounts whose natural frequency sits near the running speed, causing resonance','Rigidly bridging an isolator with a pipe or conduit and shorting it out']::text[],ARRAY['Isolating a rooftop chiller from offices below','Floating a studio floor to block footfall','Mounting a pump to stop pipe hum']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='vibration isolation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a0e65d5-6d17-5bf4-a402-af6586750606','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a0e65d5-6d17-5bf4-a402-af6586750606') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a0e65d5-6d17-5bf4-a402-af6586750606');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd24fea95-3ea5-51de-a6a3-47eeddefc1e2','structure-borne noise','Noise that travels through the solid parts of a structure, such as floors, walls, beams, and pipes, as vibrational energy before being radiated as audible airborne sound at a distant surface. It arises from impacts or vibrating machinery in contact with the structure and can travel long distances with little loss, unlike airborne sound that must cross partitions.','Structure-borne noise moves as shaking through a building''s solid parts. Footsteps, pumps, or pipes can start it. The vibration runs through floors and walls. Far away, a surface turns it back into sound you hear. It can travel far with little loss.','Telling this path apart from airborne noise directs the right fix, namely isolation and damping rather than added mass or sealing gaps.','Diagnosed when a distant room hears machinery or footfall; treated with resilient mounts, floating floors, and breaks in the structural path.','Data Sonification & Auditory Display',ARRAY['Airborne noise','Vibration isolation','Impact noise','Flanking transmission','Damping']::text[],ARRAY['Trying to fix it with airborne treatments like seals or absorption','Overlooking pipes and conduits as vibration paths','Confusing it with airborne noise leaking through gaps']::text[],ARRAY['Tracing a hum from a basement plant room','Reducing footfall heard a floor below','Isolating a generator from the building frame']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='structure-borne noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd24fea95-3ea5-51de-a6a3-47eeddefc1e2','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d24fea95-3ea5-51de-a6a3-47eeddefc1e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d24fea95-3ea5-51de-a6a3-47eeddefc1e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ab47f4c-76e1-5c42-8bcd-695a26c03f4a','turbulent boundary layer noise','Noise associated with the fluctuating pressures within the turbulent boundary layer of fluid flowing over a surface. The convecting eddies impose random pressure fluctuations on the wall that both radiate sound and, on a flush-mounted sensor, appear as flow-induced pseudo-noise; the effect governs flow noise on aircraft skins, sonar domes, and microphones exposed to wind.','Fast flow over a surface forms a thin, churning layer. That layer presses on the surface in a random way. The pressure makes noise and shakes sensors in the flow. Aircraft skins and sonar domes meet this problem. A microphone in wind hears it too.','Understanding it lets engineers separate true acoustic signals from flow noise and design quieter surfaces and sensor housings.','Limits sonar and flush-mounted microphone performance in flow; it drives windscreen, fairing, and dome design on aircraft and vehicles.','Data Sonification & Auditory Display',ARRAY['Boundary layer','Flow noise','Aeroacoustics','Pseudo-sound','Wind noise']::text[],ARRAY['Treating convective pseudo-noise as radiated sound','Ignoring how strongly flow speed raises the noise','Expecting a simple windscreen to remove it fully']::text[],ARRAY['Measuring hull noise on a moving sonar','Reducing flow noise on an aircraft skin microphone','Assessing wind noise on an outdoor mic']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='turbulent boundary layer noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ab47f4c-76e1-5c42-8bcd-695a26c03f4a','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ab47f4c-76e1-5c42-8bcd-695a26c03f4a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ab47f4c-76e1-5c42-8bcd-695a26c03f4a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '151837fd-caae-53c2-98f1-86df42d0a792','fan noise','The aerodynamic and mechanical noise produced by a rotating fan, made up of tonal components at the blade-passing frequency and its harmonics plus broadband noise from turbulence and flow separation. Tones arise as each blade passes a fixed point or obstruction, while broadband content comes from turbulent inflow and from boundary-layer and trailing-edge sources, making fans a dominant noise source in ventilation and cooling systems.','Fan noise comes from spinning blades pushing air. It has clear tones plus a broad hiss. The tones fall at the rate blades pass a point. Rough, swirling air makes the hiss. Fans are a top noise source in air and cooling systems.','Separating the tonal and broadband parts guides fixes such as changing blade count, spacing, and speed or adding silencers.','Addressed in ventilation design, computer and equipment cooling, and studio quietening; spectra are measured to find blade-passing tones for treatment.','Data Sonification & Auditory Display',ARRAY['Blade passing frequency','Broadband noise','Tonal noise','HVAC noise','Aeroacoustics']::text[],ARRAY['Only slowing the fan without fixing tonal blade-passing sources','Ignoring inlet turbulence that raises broadband noise','Confusing blade-passing tones with motor electrical hum']::text[],ARRAY['Quieting a ventilation air handler','Reducing computer cooling-fan noise','Adding silencers to a duct']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='fan noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '151837fd-caae-53c2-98f1-86df42d0a792','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='151837fd-caae-53c2-98f1-86df42d0a792') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='151837fd-caae-53c2-98f1-86df42d0a792');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aeb233a5-7a87-5c20-b17b-8629cd58b3e0','propeller noise','The sound radiated by a rotating propeller, dominated by tonal components at the blade-passing frequency that arise from blade thickness and from steady and unsteady blade loading, plus broadband noise from turbulence. In marine propellers, cavitation usually becomes the dominant and highly broadband source once vapour bubbles form and collapse on the blades.','Propeller noise comes from spinning blades moving air or water. Each blade''s shape and lift make strong tones. The tones sit at the blade-passing rate. Rough flow adds a broad hiss. In water, collapsing bubbles can take over the sound.','Separating thickness, loading, and cavitation sources guides quieter blade design and safe operating limits.','Central to aircraft, drone, ship, and submarine acoustics; measurements track blade-passing tones and the onset of cavitation.','Data Sonification & Auditory Display',ARRAY['Blade passing frequency','Thickness noise','Loading noise','Cavitation','Aeroacoustics']::text[],ARRAY['Ignoring cavitation as the main marine source at speed','Assuming more blades always means less noise','Treating loading and thickness noise as one source']::text[],ARRAY['Measuring drone propeller noise','Assessing ship propeller cavitation','Reducing aircraft propeller tones']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='propeller noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aeb233a5-7a87-5c20-b17b-8629cd58b3e0','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aeb233a5-7a87-5c20-b17b-8629cd58b3e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aeb233a5-7a87-5c20-b17b-8629cd58b3e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20c27ee1-27fa-581e-88eb-1752e6e70a05','rotor-stator interaction','In turbomachinery, the unsteady aerodynamic interaction between a rotating blade row and an adjacent stationary vane row, whose wakes and potential fields chop periodically to generate strong tonal noise at the blade-passing frequency and its harmonics. The blade and vane counts determine which spinning acoustic modes form and whether they propagate or cut off within the duct.','In an engine or fan, spinning blades pass fixed vanes. Their airflows strike each other again and again. This makes loud tones at the blade-passing rate. The blade and vane counts shape the sound. Good counts can trap tones so they fade.','Choosing blade and vane counts so unwanted modes cut off is a key tool for quieting fans and engines at the source.','Exploited in turbofan and cooling-fan design to suppress tones; analysed with spinning-mode theory during engine noise work.','Data Sonification & Auditory Display',ARRAY['Blade passing frequency','Tyler-Sofrin modes','Turbomachinery noise','Tonal noise','Cut-off frequency']::text[],ARRAY['Choosing equal blade and vane counts, which strengthens tones','Ignoring duct cut-off when predicting radiated tones','Treating the noise as broadband rather than tonal']::text[],ARRAY['Designing a quiet turbofan stage','Choosing vane counts to cut off a tone','Diagnosing a strong engine tone']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='rotor-stator interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20c27ee1-27fa-581e-88eb-1752e6e70a05','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20c27ee1-27fa-581e-88eb-1752e6e70a05') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20c27ee1-27fa-581e-88eb-1752e6e70a05');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6cd63261-e1a0-5fc2-975a-ed6cf16d368e','broadband self-noise','Broadband noise produced by an airfoil or blade moving through smooth, non-turbulent flow, generated mainly by its own boundary layer interacting with the trailing edge, together with related sources such as flow separation, laminar vortex shedding, and blunt trailing-edge shedding. It sets a lower noise limit even in clean inflow and is central to wind-turbine and fan trailing-edge noise.','Even in smooth air, a blade makes its own hiss. The thin flow layer on the blade reaches the sharp back edge. There it turns into broadband noise. Stalls and blunt edges add more. Wind turbines and fans meet this limit.','It marks the noise floor of a blade in clean flow, guiding trailing-edge shaping and serrations meant to lower it.','Modelled with established airfoil self-noise methods in wind-turbine and fan design and treated with trailing-edge serrations.','Data Sonification & Auditory Display',ARRAY['Trailing-edge noise','Airfoil self-noise','Boundary layer','Broadband noise','Vortex shedding']::text[],ARRAY['Blaming inflow turbulence for what is really self-noise','Assuming a perfectly smooth blade is silent','Ignoring trailing-edge bluntness as a tonal source']::text[],ARRAY['Reducing wind-turbine blade hiss','Designing quiet fan blades','Testing serrated trailing edges']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='broadband self-noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6cd63261-e1a0-5fc2-975a-ed6cf16d368e','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6cd63261-e1a0-5fc2-975a-ed6cf16d368e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6cd63261-e1a0-5fc2-975a-ed6cf16d368e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f3349521-41a2-5b5c-a33a-72fe520e548f','tonal aerodynamic noise','Aerodynamically generated noise concentrated at discrete frequencies rather than spread across a band, arising from periodic flow phenomena such as blade passing, rotor-stator interaction, and vortex shedding from cylinders or edges. Because the ear is sensitive to pure tones, such components are often more annoying and more strictly regulated than broadband noise of the same energy.','Some flow noise sits at sharp, single pitches. These tones come from steady, repeating flow events. Passing blades or shedding swirls cause them. People notice tones more than a broad hiss. So rules often treat tones more strictly.','Flagging tonal content matters because tones draw complaints and carry noise-rating penalties, changing how a source must be treated.','Identified as sharp peaks in fan, propeller, and wind noise spectra; a tonal penalty is added during environmental noise assessment.','Data Sonification & Auditory Display',ARRAY['Blade passing frequency','Vortex shedding','Aeolian tone','Strouhal number','Broadband noise']::text[],ARRAY['Ignoring the added annoyance and rating penalty of tones','Confusing a structural resonance tone with an aerodynamic one','Assuming a lower overall level removes an audible tone']::text[],ARRAY['Adding a tonal penalty in a noise assessment','Diagnosing a whistle from a vent','Separating tones from broadband in a fan spectrum']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='tonal aerodynamic noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f3349521-41a2-5b5c-a33a-72fe520e548f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f3349521-41a2-5b5c-a33a-72fe520e548f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f3349521-41a2-5b5c-a33a-72fe520e548f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '667a57cf-8948-52f3-9e38-f31d1c448347','microphone windscreen','A porous cover, made of foam, an open-cell sphere, or synthetic fur, fitted over a microphone to reduce wind-induced noise by keeping turbulent airflow off the diaphragm while letting the acoustic signal pass. It forms a region of stiller air and breaks up large eddies, cutting low-frequency wind rumble with only slight high-frequency loss when correctly sized.','A windscreen is a soft cover over a microphone. Foam or fake fur is common. It keeps gusty air off the mic''s thin diaphragm. Real sound still passes through. This cuts low wind rumble with little loss of highs.','It protects recordings from wind noise and plosive blasts so the wanted sound stays clean and usable.','Used in field recording, film sound, and outdoor measurement; a fur cover is added for stronger wind and a foam pop filter for close vocals.','Data Sonification & Auditory Display',ARRAY['Wind noise','Pop filter','Windjammer','Turbulent boundary layer noise','Diaphragm']::text[],ARRAY['Expecting foam alone to handle strong outdoor wind','Assuming a windscreen has no effect on high frequencies','Confusing a pop filter''s job with wind protection']::text[],ARRAY['Recording dialogue outdoors on a boom','Measuring environmental noise in a breeze','Taming plosives on a vocal mic']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='microphone windscreen');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '667a57cf-8948-52f3-9e38-f31d1c448347','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='667a57cf-8948-52f3-9e38-f31d1c448347') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='667a57cf-8948-52f3-9e38-f31d1c448347');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'de88421e-f259-5a3b-865d-24b4f439bdfe','porous windscreen','A windscreen that reduces flow-induced noise by surrounding the microphone with an open, air-permeable material such as reticulated foam or a wire-framed porous shell. The porous layer slows and diffuses the airflow, creating a low-turbulence region around the diaphragm, while its open structure lets the acoustic wave pass with little attenuation; larger diameters give more low-frequency wind reduction.','A porous windscreen is made of open, airy material. Air can pass slowly through its many holes. This calms the flow right around the mic. Sound still travels through with little loss. A bigger screen blocks more wind rumble.','It gives strong, broadband wind-noise reduction while staying nearly transparent to the sound being measured or recorded.','Seen as large foam or basket windshields on measurement and film microphones outdoors; its size is chosen for the wind and low-frequency needs.','Data Sonification & Auditory Display',ARRAY['Microphone windscreen','Windjammer','Wind noise','Turbulent boundary layer noise','Acoustic transparency']::text[],ARRAY['Using too small a screen for the wind present','Letting rain or dirt clog the pores and change the response','Assuming denser material always works better']::text[],ARRAY['Outdoor environmental noise measurement','Film location sound in wind','Long-term unattended outdoor monitoring']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='porous windscreen');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'de88421e-f259-5a3b-865d-24b4f439bdfe','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='de88421e-f259-5a3b-865d-24b4f439bdfe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='de88421e-f259-5a3b-865d-24b4f439bdfe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '862680b5-f3ce-5fe5-a718-224139f468e8','ultrasonic testing','A non-destructive testing method that introduces high-frequency ultrasonic waves, typically from about 0.5 to 25 megahertz, into a material with a transducer to detect internal or surface-breaking flaws and to measure thickness. In the common pulse-echo mode the probe emits a pulse and times the echoes returning from flaws and the far wall; echo amplitude and transit time locate and size discontinuities.','Ultrasonic testing sends high sound into a part to find hidden flaws. The sound is far above human hearing. A probe fires a pulse and listens for echoes. A flaw or the back wall sends sound back. Echo timing and size show where a flaw is.','It finds internal cracks, voids, and thinning without cutting the part open, and it measures remaining wall thickness.','Used on welds, forgings, castings, pipes, and rails; a technician couples a probe to the surface and reads echoes on an A-scan.','Data Sonification & Auditory Display',ARRAY['Pulse-echo','Couplant','Flaw echo','Backwall echo','Transducer']::text[],ARRAY['Poor couplant or contact giving weak, misleading echoes','Missing flaws in the probe''s dead zone near the surface','Confusing geometry echoes with real flaw echoes']::text[],ARRAY['Inspecting a weld for internal cracks','Measuring pipe wall thickness for corrosion','Checking a forging before service']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ultrasonic testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '862680b5-f3ce-5fe5-a718-224139f468e8','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='862680b5-f3ce-5fe5-a718-224139f468e8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='862680b5-f3ce-5fe5-a718-224139f468e8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24a023bd-ef01-5cd2-a4b2-52bdc16e803d','through-transmission','An ultrasonic testing arrangement in which a transmitting transducer on one side of a part and a receiving transducer on the opposite side measure the sound that passes through the material. A flaw between them scatters or blocks energy, so it is detected as a drop in received amplitude rather than by a returning echo; the method needs two-sided access but avoids the dead-zone limits of pulse-echo.','Through-transmission puts one probe on each side of a part. One probe sends sound and the other receives it. A flaw in between blocks some of the sound. So the received signal grows weaker. It needs to reach both sides of the part.','It detects flaws by lost signal when a clean returning echo is hard to use, such as in highly scattering or very thin materials.','Common on composite panels and bonded structures where both faces are reachable; an amplitude threshold flags drops as defects.','Data Sonification & Auditory Display',ARRAY['Pulse-echo','Ultrasonic testing','Attenuation','Transducer','Signal amplitude']::text[],ARRAY['Assuming it can find a flaw''s depth like pulse-echo','Needing but lacking access to both sides','Misreading coupling changes as flaw signals']::text[],ARRAY['Scanning a composite aircraft panel','Checking an adhesive bond','Inspecting thin sheet where echoes overlap']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='through-transmission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24a023bd-ef01-5cd2-a4b2-52bdc16e803d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24a023bd-ef01-5cd2-a4b2-52bdc16e803d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24a023bd-ef01-5cd2-a4b2-52bdc16e803d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3a6ae325-ae77-5553-ac50-29fb108bc05a','phased-array ultrasonic testing','An ultrasonic method that uses a transducer built from many small elements pulsed with individually programmed time delays, so their wavelets combine to steer and focus the beam electronically without moving the probe. Varying the delay laws sweeps the beam through a range of angles or focal depths, producing cross-sectional images and improving flaw detection and sizing.','This test uses a probe with many tiny elements. Each element fires at a slightly different moment. The pulses add up to aim and focus the beam. The beam can sweep angles with no probe movement. This builds a picture of the inside of the part.','It inspects faster and images flaws by steering and focusing the beam, replacing many single-angle probes with one array.','Used for weld inspection, corrosion mapping, and complex shapes; the operator sets a delay law and reads sector or linear scans.','Data Sonification & Auditory Display',ARRAY['Full matrix capture','Sectorial scan','Delay law','Ultrasonic testing','Probe wedge']::text[],ARRAY['Trusting the image without proper calibration and a focal law','Skipping wedge and element checks before scanning','Assuming more elements alone guarantee better sizing']::text[],ARRAY['Imaging a pipeline girth weld','Mapping corrosion across a scan','Inspecting a complex forged shape']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='phased-array ultrasonic testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3a6ae325-ae77-5553-ac50-29fb108bc05a','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3a6ae325-ae77-5553-ac50-29fb108bc05a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3a6ae325-ae77-5553-ac50-29fb108bc05a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9406d45-9ad3-5fb2-ba7f-4767df30fcce','full matrix capture','A phased-array ultrasonic acquisition scheme in which each array element transmits in turn while every element records the returned signal, yielding the complete matrix of element-to-element A-scans for the aperture. This full dataset is stored and post-processed, most often with the total focusing method, to focus at every point in the image and to allow flexible, repeatable reconstruction after the scan.','Full matrix capture records every probe path through the part. Each element sends while all elements listen, one at a time. This saves a complete set of signals. Software can then focus at every point later. The result is a sharp, flexible image.','It captures all the raw element data so imaging can be focused everywhere in software, instead of fixing the focus during the scan.','Paired with the total focusing method for high-resolution flaw imaging and sizing in advanced weld and component inspection.','Data Sonification & Auditory Display',ARRAY['Total focusing method','Phased-array ultrasonic testing','Sectorial scan','A-scan','Delay law']::text[],ARRAY['Underestimating the large data volume and processing load','Assuming raw data alone is an image without focusing','Ignoring element dropout that corrupts the matrix']::text[],ARRAY['High-resolution imaging of a critical weld','Sizing a crack with the total focusing method','Reprocessing stored data after inspection']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='full matrix capture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9406d45-9ad3-5fb2-ba7f-4767df30fcce','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9406d45-9ad3-5fb2-ba7f-4767df30fcce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9406d45-9ad3-5fb2-ba7f-4767df30fcce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e1e3bfe-7caf-5cfd-9f5f-0a0031284e37','acoustic emission testing','A passive non-destructive method that detects the transient elastic stress waves spontaneously released when a stressed material undergoes local changes such as crack growth, plastic deformation, or fibre breakage. Sensors mounted on the structure listen while it is loaded, and the timing of arrivals across several sensors locates active sources, so the method finds growing defects rather than static ones.','Acoustic emission testing listens for a part''s own tiny cracks. A growing crack sends out a small burst of sound. Sensors on the surface catch these bursts under load. Comparing arrival times locates the source. It finds flaws that are actively changing.','It detects and locates active, growing damage in real time during loading or service, not just existing static flaws.','Used to monitor pressure vessels, tanks, bridges, and composites during proof tests or in service; a technician watches for emission bursts as load rises.','Data Sonification & Auditory Display',ARRAY['Stress wave','Source location','Kaiser effect','Hit','Transient signal']::text[],ARRAY['Confusing background or friction noise with real emissions','Expecting it to find static flaws that are not growing','Letting poor sensor coupling miss weak bursts']::text[],ARRAY['Proof-testing a pressure vessel','Monitoring a bridge under traffic load','Watching a composite tank for damage']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic emission testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e1e3bfe-7caf-5cfd-9f5f-0a0031284e37','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e1e3bfe-7caf-5cfd-9f5f-0a0031284e37') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e1e3bfe-7caf-5cfd-9f5f-0a0031284e37');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eac2de7d-543a-58dc-88a3-43f293e9cf87','guided-wave testing','A long-range ultrasonic technique that launches low-frequency guided waves, which propagate along and are bounded by the walls of a structure such as a pipe, plate, or rail, to screen many metres from a single test position. Reflections from wall-thickness changes, corrosion, or cracks return to the transducer ring; the method rapidly finds regions that need follow-up rather than precisely sizing each flaw.','Guided-wave testing sends low sound waves along a pipe or rail. The waves follow the walls for a long way. Corrosion or cracks send some sound back. One ring of sensors can screen many metres. It flags spots that need a closer look.','It screens long, buried, or hard-to-reach runs quickly from one point, focusing detailed inspection on the suspect areas.','Used on pipelines, insulated or buried pipe, and rails; a transducer collar is clamped on and reflections are mapped along the length.','Data Sonification & Auditory Display',ARRAY['Guided wave','Torsional mode','Ultrasonic testing','Long-range screening','Attenuation']::text[],ARRAY['Treating a screening result as a precise flaw size','Ignoring how coatings and bends raise attenuation','Missing features hidden by strong weld reflections']::text[],ARRAY['Screening an insulated pipeline for corrosion','Inspecting a road-crossing buried pipe','Checking a rail for cracks over distance']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='guided-wave testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eac2de7d-543a-58dc-88a3-43f293e9cf87','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eac2de7d-543a-58dc-88a3-43f293e9cf87') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eac2de7d-543a-58dc-88a3-43f293e9cf87');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ae586051-0121-5fac-939d-d7a1816d806d','flaw echo','In pulse-echo ultrasonic testing, the reflected signal returned to the probe by an internal discontinuity such as a crack, void, or inclusion. On an A-scan display it appears as an indication positioned in time between the initial pulse and the backwall echo; its transit time gives the flaw''s depth, and its amplitude, compared with a reference, helps estimate the flaw''s size.','A flaw echo is sound bounced back by a hidden defect. A probe sends a pulse into the part. A crack or void reflects some sound to the probe. On the screen it shows before the back-wall signal. Its timing gives the flaw''s depth.','It is the main indication a technician reads to detect, locate, and size internal flaws in pulse-echo testing.','Read on an A-scan during weld and forging inspection; its position and height are compared to a calibration reference.','Data Sonification & Auditory Display',ARRAY['Backwall echo','Pulse-echo','A-scan','Ultrasonic testing','Dead zone']::text[],ARRAY['Mistaking a geometry or mode-converted echo for a real flaw','Sizing on raw amplitude without a reference','Missing flaws whose echoes hide near the initial pulse']::text[],ARRAY['Reading a weld inspection A-scan','Locating a crack''s depth from echo time','Comparing an echo to a calibration block']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='flaw echo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ae586051-0121-5fac-939d-d7a1816d806d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ae586051-0121-5fac-939d-d7a1816d806d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ae586051-0121-5fac-939d-d7a1816d806d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77732e0a-da64-5bd6-884c-b56b21df1c47','backwall echo','In pulse-echo ultrasonic testing, the reflection returned from the far, or back, surface of the test piece. It marks the full material thickness on the A-scan and is used to calibrate the timebase, gauge thickness, and monitor attenuation; a drop or loss of the backwall echo can itself indicate a flaw, high attenuation, or poor coupling between the probe and the surface.','The backwall echo is sound bounced from the far side of a part. It shows how thick the material is. Testers use it to set up and check the machine. If it suddenly drops, something may be wrong. A hidden flaw or bad contact can cause that.','It provides a reference for calibration, thickness measurement, and a coupling check, and its loss is itself a flaw indicator.','Used to set the A-scan range, measure thickness, and confirm good coupling; a missing backwall prompts a closer look.','Data Sonification & Auditory Display',ARRAY['Flaw echo','Pulse-echo','A-scan','Attenuation','Couplant']::text[],ARRAY['Dismissing a lost backwall as poor coupling when a flaw is present','Calibrating on the wrong backwall multiple','Overlooking attenuation that lowers the backwall in thick parts']::text[],ARRAY['Calibrating the timebase before inspection','Measuring plate thickness','Spotting a flaw from a missing backwall']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='backwall echo');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77732e0a-da64-5bd6-884c-b56b21df1c47','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77732e0a-da64-5bd6-884c-b56b21df1c47') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77732e0a-da64-5bd6-884c-b56b21df1c47');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf2f14b1-bef3-5461-9a81-77b8425ab738','couplant','A liquid, gel, or paste applied between an ultrasonic probe and the test surface to displace the air film and give sound an efficient path across the interface. Because the large acoustic-impedance mismatch of an air gap would reflect almost all the ultrasound, the couplant wets both surfaces so energy enters the part; its type is chosen for surface finish, temperature, and material compatibility.','A couplant is a gel or liquid between the probe and the part. A thin air gap would block almost all the sound. The couplant fills that gap so sound can pass. Water, gel, and oil are common. The right one suits the surface and heat.','It removes the air gap so ultrasound can pass efficiently between probe and part, giving strong, repeatable echoes.','Applied by hand or flowed on during contact scanning; a technician keeps enough couplant to hold steady echo amplitude.','Data Sonification & Auditory Display',ARRAY['Acoustic impedance','Ultrasonic testing','Transducer','Contact testing','Attenuation']::text[],ARRAY['Using too little couplant, causing weak, drifting echoes','Choosing a couplant that corrodes or contaminates the part','Changing couplant mid-scan and shifting calibrated amplitude']::text[],ARRAY['Hand-scanning a weld with gel','Hot-surface inspection needing a special couplant','Keeping steady coupling on a rough casting']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='couplant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf2f14b1-bef3-5461-9a81-77b8425ab738','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf2f14b1-bef3-5461-9a81-77b8425ab738') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf2f14b1-bef3-5461-9a81-77b8425ab738');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '110f5f02-b584-594c-9701-baac670e5e43','probe wedge','A shaped block, usually of a low-attenuation plastic such as cross-linked polystyrene, mounted between an ultrasonic transducer and the test surface to introduce the beam at a controlled refracted angle. Refraction and mode conversion at the wedge-to-part interface, governed by Snell''s law, set the beam angle, commonly a shear wave, needed for angle-beam and phased-array weld inspection; the wedge delay must be included in calibration.','A probe wedge is an angled plastic block under the probe. It bends the sound beam as it enters the part. This sends the beam in at a slanted angle. Angled beams are needed to inspect welds. The wedge''s delay must be set during calibration.','It refracts the beam to the angle needed for angle-beam and phased-array inspection of welds and awkward geometry.','Fitted for shear-wave weld inspection and on phased-array probes; its angle and delay are entered during setup.','Data Sonification & Auditory Display',ARRAY['Angle beam','Snell''s law','Phased-array ultrasonic testing','Mode conversion','Shear wave']::text[],ARRAY['Forgetting to add the wedge delay in calibration','Using a worn wedge that shifts the true beam angle','Ignoring temperature changes that alter wedge velocity']::text[],ARRAY['Shear-wave inspection of a weld','Setting a phased-array delay law with a wedge','Recalibrating after wedge wear']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='probe wedge');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '110f5f02-b584-594c-9701-baac670e5e43','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='110f5f02-b584-594c-9701-baac670e5e43') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='110f5f02-b584-594c-9701-baac670e5e43');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85c399ce-3958-5537-8e58-6abd953157de','near-surface resolution','In ultrasonic testing, the ability of a system to detect and resolve flaws lying just beneath the entry surface, limited by the dead zone created while the initial pulse and transducer ringing recover. Higher frequencies, shorter pulses, well-damped probes, and delay lines or dual-element probes shorten the dead zone and improve how close to the surface a flaw can be reliably found.','Near-surface resolution is how close to the top a test can spot flaws. Right after the probe fires, it keeps ringing. During that time it is briefly blind, called the dead zone. Flaws in that zone can be missed. Short pulses and special probes shrink the blind spot.','It sets the shallow limit of reliable detection, guiding probe and frequency choices when flaws sit near the surface.','Matters when inspecting for near-surface cracks; addressed with dual-element or delay-line probes and higher frequencies.','Data Sonification & Auditory Display',ARRAY['Dead zone','Pulse-echo','Delay line','Dual-element probe','Ultrasonic testing']::text[],ARRAY['Ignoring the dead zone and missing shallow flaws','Using a low frequency that worsens near-surface blindness','Assuming a single-element contact probe suits near-surface work']::text[],ARRAY['Inspecting for near-surface cracking','Choosing a delay-line probe for shallow flaws','Setting frequency for near-surface sizing']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='near-surface resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85c399ce-3958-5537-8e58-6abd953157de','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85c399ce-3958-5537-8e58-6abd953157de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85c399ce-3958-5537-8e58-6abd953157de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b25d2ae-8726-5235-b957-b8325a341601','phoneme','The smallest unit of speech sound in a language that can distinguish one word from another, defined by its contrastive function rather than its exact acoustic form. Substituting one phoneme for another can change meaning, as in pat versus bat; each phoneme is an abstract category realised in speech by one or more physical variants, called allophones, shaped by context.','A phoneme is a basic speech sound that can change a word. Swapping one for another makes a new word. The sounds in pat and bat differ by just one. A phoneme is a sound category, not one fixed sound. Its exact sound shifts with its neighbors.','Phonemes give a language its set of minimal contrasts, the basis for writing systems, speech technology, and pronunciation teaching.','Used in speech recognition and synthesis dictionaries, pronunciation training, and phonetic transcription of recordings.','Data Sonification & Auditory Display',ARRAY['Allophone','Minimal pair','Phonetics','Phonology','Grapheme']::text[],ARRAY['Equating a phoneme with a letter of the alphabet','Confusing an abstract phoneme with its allophone variants','Assuming phoneme sets are the same across languages']::text[],ARRAY['Building a pronunciation dictionary for speech tech','Teaching a sound contrast to learners','Transcribing speech phonemically']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='phoneme');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b25d2ae-8726-5235-b957-b8325a341601','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b25d2ae-8726-5235-b957-b8325a341601') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b25d2ae-8726-5235-b957-b8325a341601');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93b56478-efe4-5664-aea3-e64bf373660f','allophone','One of the several context-dependent phonetic realisations of a single phoneme that do not change a word''s meaning. For example, English p is aspirated in pin but unaspirated in spin; the two are distinct sounds yet belong to the same phoneme, because swapping them never creates a different word, and their distribution is usually predictable from phonetic context.','An allophone is one way a single phoneme is actually said. The exact sound changes with its neighbors. In English, the p in pin has a puff of air. The p in spin does not. Both still count as the same sound to speakers.','Recognising allophones explains why one sound category varies acoustically, which matters for natural synthesis, robust recognition, and accent work.','Modelled in text-to-speech to pick natural variants and in recognition to map varied sounds back to one phoneme.','Data Sonification & Auditory Display',ARRAY['Phoneme','Coarticulation','Aspiration','Phonetics','Complementary distribution']::text[],ARRAY['Thinking allophones change word meaning','Treating every audible variant as a separate phoneme','Ignoring the predictable context rules behind them']::text[],ARRAY['Choosing natural variants in speech synthesis','Explaining an accent''s sound changes','Training recognition to group variants']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='allophone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93b56478-efe4-5664-aea3-e64bf373660f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93b56478-efe4-5664-aea3-e64bf373660f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93b56478-efe4-5664-aea3-e64bf373660f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf609d23-057d-5967-89a9-ef3d83120f2e','F0','The fundamental frequency of a periodic or quasi-periodic sound; in voiced speech it equals the rate at which the vocal folds open and close. Measured in hertz as the reciprocal of the glottal period, it is the physical quantity most closely tied to perceived pitch and it sets the spacing of the harmonic series in the voice spectrum; typical speaking values are roughly 100 hertz for men and 200 hertz for women.','F0 is the base rate of the voice''s vibration. It counts how often the vocal folds open and close each second. We hear it mainly as pitch. A higher F0 sounds higher. Men average near 100 hertz and women near 200.','F0 carries pitch, intonation, and stress and anchors the harmonic spacing used in speech analysis, synthesis, and voice assessment.','Tracked in speech analysis software, pitch-correction tools, singing feedback, and clinical voice evaluation.','Data Sonification & Auditory Display',ARRAY['Pitch','Intonation','Harmonic','Glottal period','Voiced speech']::text[],ARRAY['Treating F0 and perceived pitch as exactly identical','Confusing F0 with the first formant','Assuming F0 stays fixed within an utterance']::text[],ARRAY['Tracking pitch in a speech analysis tool','Correcting a singer''s pitch','Assessing a patient''s voice pitch range']::text[],'intermediate','F0 = 1 / T0','The fundamental frequency equals one divided by the glottal period.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='F0');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf609d23-057d-5967-89a9-ef3d83120f2e','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf609d23-057d-5967-89a9-ef3d83120f2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf609d23-057d-5967-89a9-ef3d83120f2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d920e92-f480-54ad-bfe9-bb8efc758dd2','vowel space','The two-dimensional region occupied by a speaker''s or language''s vowels when plotted by their first two formant frequencies, with the first formant relating to vowel height and the second to frontness or backness. The corner vowels, as in heed, hod, and who''d, bound the space, and its size and shape describe articulatory range, used to compare speakers, accents, and speech clarity.','Vowel space is a map of a speaker''s vowels. Each vowel is placed by two of its resonances. One axis tracks how open the mouth is. The other tracks tongue front-to-back position. Corner vowels mark the edges of the map.','It summarises how a speaker spreads their vowels apart, a useful measure of clarity, accent, and speech-motor range.','Used in accent study, clinical speech assessment, and forensic or speaker comparison from measured formants.','Data Sonification & Auditory Display',ARRAY['Formant','First formant','Second formant','Vowel','Articulation']::text[],ARRAY['Reading the formant axes as literal tongue positions','Comparing spaces without controlling for vocal-tract length','Using too few vowels to define the space']::text[],ARRAY['Comparing vowels across accents','Measuring vowel clarity in a clinic','Analysing formants in forensic speech work']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='vowel space');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d920e92-f480-54ad-bfe9-bb8efc758dd2','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d920e92-f480-54ad-bfe9-bb8efc758dd2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d920e92-f480-54ad-bfe9-bb8efc758dd2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49f09eac-efe9-5c84-a7c6-2ba0155a1089','fricative','A consonant produced by forcing airflow through a narrow constriction in the vocal tract, creating turbulent, noise-like sound. The place of the constriction, at the lips, teeth, alveolar ridge, palate, or glottis, sets the fricative''s identity, as in f, s, or sh; the sound is aperiodic broadband noise and may be voiced or voiceless depending on whether the vocal folds vibrate at the same time.','A fricative is a consonant made by squeezing air through a narrow gap. The tight gap makes a hissy, noisy sound. Where the gap sits decides the sound, like f or s. It can come with or without voice. The noise has no clear pitch.','Fricatives add a large class of consonant contrasts, marked by noise energy that analysis and recognition must handle differently from vowels.','Identified by high-frequency noise bands in spectrograms; important in de-essing, speech coding, and recognition.','Data Sonification & Auditory Display',ARRAY['Sibilant','Affricate','Turbulence','Place of articulation','Voiceless']::text[],ARRAY['Confusing all fricatives with sibilants','Treating fricative noise as having a fundamental pitch','Ignoring voicing differences like f versus v']::text[],ARRAY['Spotting fricatives in a spectrogram','De-essing harsh speech sounds','Coding consonant noise in speech tech']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='fricative');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49f09eac-efe9-5c84-a7c6-2ba0155a1089','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49f09eac-efe9-5c84-a7c6-2ba0155a1089') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49f09eac-efe9-5c84-a7c6-2ba0155a1089');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '87513170-f1e7-54a6-ab43-524a59fee158','affricate','A consonant that begins with a complete stop closure and releases not abruptly but into a fricative at the same place of articulation, so the two phases act as a single sound. English examples are the ch in church, which is voiceless, and the j in judge, which is voiced; acoustically an affricate shows a brief silence or burst followed by a short interval of frication.','An affricate is a stop and a fricative joined as one sound. It starts by fully blocking the air. Then it releases into a hissy sound. The ch in church is one. The j in judge is its voiced partner.','Affricates form their own contrast class, and their stop-plus-noise structure must be segmented correctly in analysis and recognition.','Seen in spectrograms as a burst followed by frication and handled as single units in transcription and speech models.','Data Sonification & Auditory Display',ARRAY['Fricative','Stop','Place of articulation','Sibilant','Voice onset time']::text[],ARRAY['Splitting an affricate into two separate sounds','Confusing it with a stop plus a separate fricative','Ignoring the voiced-voiceless pair difference']::text[],ARRAY['Segmenting affricates in transcription','Reading a burst-plus-frication pattern','Modelling affricates in recognition']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='affricate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '87513170-f1e7-54a6-ab43-524a59fee158','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='87513170-f1e7-54a6-ab43-524a59fee158') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='87513170-f1e7-54a6-ab43-524a59fee158');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20b7abae-4cb5-5ce6-99ac-203dfdcb6cad','sibilant','A subclass of fricatives and affricates produced by directing a high-velocity air jet against the teeth, generating intense, high-frequency noise concentrated roughly above four kilohertz. English sibilants include s, z, sh, and the sound in measure; their loud, sharp character makes them the targets of de-essers and the sounds most stressed by limited high-frequency bandwidth or clipping.','A sibilant is a sharp, hissy speech sound. Air is aimed at the teeth to make it. The sound has strong, high-pitched noise. The s and sh sounds are examples. Engineers tame them with a de-esser.','Naming sibilants matters because their strong high-frequency energy drives de-essing, microphone choice, and bandwidth decisions.','Controlled with de-essers in vocal mixing and watched for harshness on bright microphones and in low-bandwidth codecs.','Data Sonification & Auditory Display',ARRAY['Fricative','De-esser','Affricate','High-frequency energy','Vocal recording']::text[],ARRAY['Confusing sibilance with general fricative noise','Over-de-essing and dulling the voice','Blaming the mic when technique or a codec causes harshness']::text[],ARRAY['De-essing a bright vocal track','Choosing a mic for a sibilant singer','Diagnosing harsh s sounds in a codec']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='sibilant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20b7abae-4cb5-5ce6-99ac-203dfdcb6cad','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20b7abae-4cb5-5ce6-99ac-203dfdcb6cad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20b7abae-4cb5-5ce6-99ac-203dfdcb6cad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '047a54fa-c218-55eb-8fc2-a5c2e95e4716','voice onset time','The interval between the release of a stop consonant and the onset of vocal-fold vibration for the following vowel, measured in milliseconds. It is the primary acoustic cue distinguishing voiced from voiceless stops, as in bin versus pin: a short or negative value signals a voiced stop, while a long positive lag signals a voiceless, aspirated stop, with the exact boundary varying by language.','Voice onset time is a short gap in a consonant. It runs from a stop''s release to when the voice starts. A long gap sounds like p; a short one like b. It is measured in milliseconds. Languages draw the line at different points.','It is a precise, measurable cue that separates stop categories, central to phonetic research, accent study, and clinical speech timing.','Measured from waveforms and spectrograms in phonetics work, second-language pronunciation study, and speech-timing assessment.','Data Sonification & Auditory Display',ARRAY['Stop','Aspiration','Voicing','Phoneme','Spectrogram']::text[],ARRAY['Ignoring that the boundary differs across languages','Confusing it with total consonant duration','Measuring from the wrong landmark on the waveform']::text[],ARRAY['Measuring the cue to study an accent','Assessing stop timing in a clinic','Comparing voiced and voiceless stops']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='voice onset time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '047a54fa-c218-55eb-8fc2-a5c2e95e4716','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='047a54fa-c218-55eb-8fc2-a5c2e95e4716') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='047a54fa-c218-55eb-8fc2-a5c2e95e4716');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd1f8a24-4308-5ace-b244-380f9501813d','intonation','The pattern of pitch variation across a phrase or sentence, carried physically by changes in fundamental frequency, that conveys meaning beyond the words themselves. Intonation signals functions such as marking questions versus statements, focus and emphasis, phrase boundaries, and speaker attitude; it operates over stretches larger than a single sound and is a core part of prosody.','Intonation is the tune of a sentence. It is how the voice''s pitch rises and falls. A rise at the end can mark a question. It also shows stress and feeling. It works over whole phrases, not single sounds.','Intonation carries grammatical and emotional meaning, making it essential for natural speech synthesis and for judging a speaker''s intent.','Modelled in text-to-speech for natural prosody, analysed in emotion and intent detection, and taught in language learning.','Data Sonification & Auditory Display',ARRAY['Prosody','F0','Pitch','Stress','Fundamental frequency']::text[],ARRAY['Confusing intonation with loudness or stress alone','Treating pitch marks on single words as full intonation','Assuming rising pitch always means a question']::text[],ARRAY['Adding natural prosody in speech synthesis','Detecting a question from pitch','Teaching intonation to learners']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='intonation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd1f8a24-4308-5ace-b244-380f9501813d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd1f8a24-4308-5ace-b244-380f9501813d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd1f8a24-4308-5ace-b244-380f9501813d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6b4f48f4-1024-5283-aeb6-a5e5d579f9fe','coarticulation','The overlapping and blending of articulatory gestures in connected speech, so that the production and acoustics of one sound are shaped by the sounds before and after it. Because the articulators move continuously and anticipate upcoming targets, a phoneme''s exact realisation varies with its neighbours; this context sensitivity underlies allophonic variation and challenges speech segmentation and recognition.','Coarticulation is speech sounds blending into each other. The mouth is always moving toward the next sound. So each sound is colored by its neighbors. The same phoneme can sound a bit different each time. This makes clean sound boundaries hard to find.','It explains why speech sounds are not separate beads, driving the context-dependent models used in recognition and synthesis.','Handled with context units such as triphones in recognition and with unit selection in synthesis to sound natural.','Data Sonification & Auditory Display',ARRAY['Allophone','Articulation','Assimilation','Phoneme','Speech segmentation']::text[],ARRAY['Assuming each phoneme has one fixed acoustic form','Expecting clean gaps between sounds in a waveform','Ignoring context when labelling segments']::text[],ARRAY['Building context units for recognition','Explaining variable segment sounds','Improving naturalness in synthesis']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='coarticulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6b4f48f4-1024-5283-aeb6-a5e5d579f9fe','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6b4f48f4-1024-5283-aeb6-a5e5d579f9fe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6b4f48f4-1024-5283-aeb6-a5e5d579f9fe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '285295ec-c33a-538b-824f-b17d4131ad50','harmonic-to-noise ratio','An acoustic measure of voice quality expressing the ratio of periodic, harmonic energy to aperiodic, noise energy in a voiced signal, usually given in decibels. A high value indicates a clear, strongly periodic voice, while a low value reflects added turbulent or irregular energy heard as breathiness or hoarseness; it is a common quantitative index in clinical voice assessment.','This ratio compares two parts of a voice. One part is the clean, repeating tone. The other is added hiss or noise. A high ratio means a clear voice. A low one means a breathy or rough voice.','It gives a single number for how clean versus noisy a voice is, useful for tracking voice disorders and therapy progress.','Computed in voice analysis software from sustained vowels for clinical screening and monitoring.','Data Sonification & Auditory Display',ARRAY['Cepstral peak prominence','Breathy voice','Jitter','Voice quality','Signal-to-noise ratio']::text[],ARRAY['Comparing values from different software or settings directly','Measuring on unstable or too-short samples','Treating the ratio as a full diagnosis on its own']::text[],ARRAY['Screening a hoarse voice in a clinic','Tracking therapy progress over weeks','Comparing voice quality before and after surgery']::text[],'advanced','HNR = 10·log₁₀(E_h / E_n) dB','The ratio in decibels is ten times the base-ten log of harmonic energy divided by noise energy.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='harmonic-to-noise ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '285295ec-c33a-538b-824f-b17d4131ad50','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='285295ec-c33a-538b-824f-b17d4131ad50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='285295ec-c33a-538b-824f-b17d4131ad50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92f221b2-f343-5f45-8f76-2be3d1467bfe','cepstral peak prominence','An acoustic measure of voice quality derived from the cepstrum, defined as the height of the cepstral peak, which corresponds to the fundamental period, relative to a regression line fitted through the cepstrum at that quefrency. A strongly periodic voice yields a prominent, well-defined peak and a high value, whereas a breathy or disordered voice gives a weaker peak; it is valued for staying reliable on continuous speech.','This measure rates how clear a voice is. It looks at a transformed version of the sound. A steady voice makes one strong peak there. A breathy voice makes a weaker peak. A higher value means a healthier voice.','It provides a robust voice-quality index that works on running speech, not just steady vowels, aiding disorder screening.','Computed in clinical voice software as a marker of breathiness and disordered voice and to track treatment.','Data Sonification & Auditory Display',ARRAY['Cepstrum','Harmonic-to-noise ratio','Breathy voice','Dysphonia','Quefrency']::text[],ARRAY['Comparing values across tools that use different methods','Ignoring smoothing settings that shift the value','Reading it as a standalone diagnosis']::text[],ARRAY['Screening breathiness on connected speech','Tracking a voice disorder over time','Comparing pre- and post-treatment voice']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='cepstral peak prominence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92f221b2-f343-5f45-8f76-2be3d1467bfe','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92f221b2-f343-5f45-8f76-2be3d1467bfe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92f221b2-f343-5f45-8f76-2be3d1467bfe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7fab9843-0eba-521c-aedd-bf5d188b1e26','breathy voice','A phonation type in which the vocal folds vibrate while staying somewhat apart, so air escapes continuously and adds turbulent noise to the voiced signal. Acoustically it shows a steep spectral tilt with strong fundamental energy, weaker high harmonics, and raised aperiodic noise, giving a low harmonic-to-noise ratio; it can be a normal linguistic contrast in some languages or a sign of a voice disorder.','Breathy voice is a soft, airy way of speaking. The vocal folds do not fully close. So extra air leaks out as a hiss. The voice sounds whispery mixed with tone. It can be a style or a sign of a voice problem.','Identifying breathiness matters for voice-health screening and for capturing a deliberate soft, intimate vocal style.','Assessed in clinical voice work and noted in singing and voice-over; mic technique and gentle compression handle its soft, noisy character.','Data Sonification & Auditory Display',ARRAY['Creaky voice','Phonation','Harmonic-to-noise ratio','Glottal closure','Spectral tilt']::text[],ARRAY['Confusing breathy voice with simply low volume','Assuming it is always a disorder','Treating it the same as creaky voice']::text[],ARRAY['Screening a breathy voice in a clinic','Recording an intimate vocal style','Distinguishing phonation types in analysis']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='breathy voice');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7fab9843-0eba-521c-aedd-bf5d188b1e26','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7fab9843-0eba-521c-aedd-bf5d188b1e26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7fab9843-0eba-521c-aedd-bf5d188b1e26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aec5f528-ebb7-51a5-b176-94224fdcab38','creaky voice','A phonation type, also called vocal fry, produced by tightly held vocal folds that vibrate slowly and irregularly at very low fundamental frequency with low airflow. It is heard as a rough, popping or crackly quality and shows widely spaced, often irregular glottal pulses; it can mark phrase endings, serve as a linguistic contrast in some languages, or appear as a stylistic or disordered voice feature.','Creaky voice is a low, crackly way of speaking. The vocal folds are tight and vibrate slowly. This makes a rough, popping sound. It often appears at the end of sentences. It is also called vocal fry.','Recognising creak matters for pitch tracking, which often fails on it, and for voice styling and clinical or forensic description.','Noted in voice-over and singing styles, flagged where it breaks pitch tracking, and described in clinical and forensic analysis.','Data Sonification & Auditory Display',ARRAY['Breathy voice','Phonation','Vocal fry','F0','Glottal pulse']::text[],ARRAY['Assuming pitch trackers handle creak reliably','Treating all creak as a disorder','Confusing creaky with breathy voice']::text[],ARRAY['Explaining pitch-tracking errors on creak','Describing a vocal-fry singing style','Noting creak in forensic voice work']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='creaky voice');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aec5f528-ebb7-51a5-b176-94224fdcab38','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aec5f528-ebb7-51a5-b176-94224fdcab38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aec5f528-ebb7-51a5-b176-94224fdcab38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bdae2d17-9226-5dfb-8c0e-4a8b5b6d12b6','sideband','The bands of frequencies above and below a carrier that are created when the carrier is modulated by an information signal. In amplitude modulation each message component produces an upper and a lower sideband symmetric about the carrier, and these sidebands carry the actual information; their spacing and number depend on the modulating frequencies and, in frequency modulation, on the modulation index.','A sideband is a set of frequencies beside a carrier. Modulation creates them from the carrier. They sit just above and below it. The sidebands hold the real information. Their spacing depends on the modulating signal.','Sidebands are where modulated information actually lives, so they set the bandwidth a channel must carry and the filtering a receiver needs.','Central to radio and telemetry link design and to frequency-modulation synthesis, where sideband spacing shapes timbre; they are watched on a spectrum analyser.','Data Sonification & Auditory Display',ARRAY['Carrier','Modulation','Modulation index','Bandwidth','Frequency modulation']::text[],ARRAY['Thinking the carrier itself carries the information','Ignoring that sidebands set the required bandwidth','Assuming frequency modulation has only one pair of sidebands']::text[],ARRAY['Sizing bandwidth for a radio link','Reading modulation sidebands on an analyser','Designing timbre with frequency-modulation synthesis']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='sideband');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bdae2d17-9226-5dfb-8c0e-4a8b5b6d12b6','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bdae2d17-9226-5dfb-8c0e-4a8b5b6d12b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bdae2d17-9226-5dfb-8c0e-4a8b5b6d12b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38c3c9ef-d86d-59dc-86d1-3fafd79e5ef8','channel','The medium or path, physical or logical, through which a signal travels from a transmitter to a receiver, characterised by a finite bandwidth and by added noise, attenuation, and distortion. A channel''s capacity to carry information without error is limited by its bandwidth and signal-to-noise ratio; in audio, the word channel also denotes an independent signal path, as in a console strip or a stereo channel.','A channel is the path a signal travels to a receiver. It can be a wire, the air, or water. Every channel has limited bandwidth and adds some noise. These limits cap how much data it can carry. In audio, a channel is also one signal path.','The channel concept frames the limits of bandwidth, noise, and capacity that every transmission and coding scheme must work within.','Considered when designing radio, telemetry, or underwater links and when routing independent audio paths on a console.','Data Sonification & Auditory Display',ARRAY['Bandwidth','Bit error rate','Signal-to-noise ratio','Channel capacity','Noise']::text[],ARRAY['Ignoring the noise and bandwidth limits of a real channel','Confusing a communication channel with an audio channel in context','Assuming a channel is error-free']::text[],ARRAY['Estimating the capacity of a noisy radio link','Planning an underwater acoustic channel','Routing separate audio channels on a desk']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='channel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38c3c9ef-d86d-59dc-86d1-3fafd79e5ef8','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38c3c9ef-d86d-59dc-86d1-3fafd79e5ef8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38c3c9ef-d86d-59dc-86d1-3fafd79e5ef8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c83614fb-7ca6-5f49-ba5a-09a1b1beb654','bit error rate','A measure of digital transmission quality equal to the number of bits received in error divided by the total number of bits transmitted over a given interval. It captures the combined effect of noise, interference, and distortion on a link and is often plotted against signal-to-noise ratio; error-correcting codes lower the effective value, and a target rate sets the minimum acceptable link margin.','Bit error rate tells how often digital bits arrive wrong. It is the count of wrong bits over all bits sent. A low value means a clean link. Noise and interference push it up. Error-correcting codes help bring it down.','It quantifies link reliability, letting engineers set margins, compare schemes, and decide when coding or more power is needed.','Measured with a bit-error-rate tester on radio, telemetry, and data links; a target value drives design margins.','Data Sonification & Auditory Display',ARRAY['Channel','Signal-to-noise ratio','Error correction','Telemetry','Modulation']::text[],ARRAY['Quoting the value without the measurement time or bit count','Ignoring that error correction changes the effective rate','Assuming the rate stays constant as conditions vary']::text[],ARRAY['Testing a radio link''s error rate','Setting a target for a telemetry link','Comparing modulation schemes by error rate']::text[],'intermediate','BER = N_e / N_t','The bit error rate equals the number of errored bits divided by the total bits sent.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='bit error rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c83614fb-7ca6-5f49-ba5a-09a1b1beb654','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c83614fb-7ca6-5f49-ba5a-09a1b1beb654') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c83614fb-7ca6-5f49-ba5a-09a1b1beb654');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96707f9d-c189-5f1a-9445-36764d589f14','ultrasonic communication','The transmission of information using acoustic waves at ultrasonic frequencies, above the roughly twenty kilohertz upper limit of human hearing, sent through air, water, or solid media. It is used for short-range device-to-device links, for example through smartphone speakers and microphones, for underwater data links where radio propagates poorly, and inside structures; range and data rate are limited by strong high-frequency absorption and by multipath.','Ultrasonic communication sends data as sound too high to hear. It uses waves above about twenty kilohertz. Phones, underwater gear, and sensors can use it. Water blocks radio, so sound works better there. High sound fades fast, so range is short.','It enables data links where radio is unavailable or unwanted, such as underwater or between nearby consumer devices.','Used in underwater modems, proximity and pairing between phones, and indoor location beacons.','Data Sonification & Auditory Display',ARRAY['Ultrasound','Chirp spread spectrum','Channel','Telemetry','Multipath']::text[],ARRAY['Expecting long range despite strong high-frequency absorption','Ignoring multipath and echoes in rooms or water','Assuming inaudible means undetectable by other devices']::text[],ARRAY['Sending data through an underwater modem','Pairing two phones by sound','Beaconing indoor location by ultrasound']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ultrasonic communication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96707f9d-c189-5f1a-9445-36764d589f14','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96707f9d-c189-5f1a-9445-36764d589f14') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96707f9d-c189-5f1a-9445-36764d589f14');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0dd381e-6156-52a9-b22f-7cc2b17c54ec','chirp spread spectrum','A spread-spectrum modulation in which each symbol is encoded onto a chirp, a signal whose frequency sweeps continuously across a wide band, rather than onto a fixed tone. Spreading the energy over a broad bandwidth makes the link robust to narrowband interference, multipath, and Doppler shift and allows reception below the noise floor; it underlies the LoRa radio scheme and is common in sonar and underwater acoustic links.','Chirp spread spectrum sends data on sweeping tones. Each chirp slides across a wide band of frequencies. Spreading the energy out resists noise and interference. Signals can be read even below the noise. It is used in LoRa radios and in sonar.','It trades bandwidth for robustness, giving reliable low-power links over distance in noisy, fading, or moving conditions.','Used in low-power wide-area radio, in radar and sonar ranging, and in underwater acoustic communication.','Data Sonification & Auditory Display',ARRAY['Spread spectrum','Chirp','Bandwidth','Multipath','Doppler shift']::text[],ARRAY['Confusing the wide bandwidth with a high data rate','Ignoring the processing gain that enables below-noise reception','Assuming it is immune to all interference']::text[],ARRAY['Designing a long-range sensor radio link','Ranging with sonar chirps','Communicating through a noisy underwater channel']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='chirp spread spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0dd381e-6156-52a9-b22f-7cc2b17c54ec','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0dd381e-6156-52a9-b22f-7cc2b17c54ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0dd381e-6156-52a9-b22f-7cc2b17c54ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd03d929-ea66-5cb5-be0b-3639ea42cbf9','telemetry','The automated measurement of physical quantities at a remote or inaccessible source and the transmission of that data over a communication link to a receiving station for monitoring or recording. Sensor outputs are conditioned, digitised, and modulated onto a channel, whether radio, wired, or acoustic, so distant or moving systems such as spacecraft, aircraft, pipelines, and patients can be observed in real time.','Telemetry means measuring something far away and sending the data back. Sensors read values like temperature or pressure. The readings are turned into a signal and transmitted. A base station receives and records them. Rockets, race cars, and patients all use it.','It lets operators monitor and control systems that are remote, moving, hazardous, or otherwise hard to reach.','Used in spaceflight, motorsport, industrial and pipeline monitoring, weather balloons, and medical patient monitoring.','Data Sonification & Auditory Display',ARRAY['Channel','Bit error rate','Modulation','Sensor','Data link']::text[],ARRAY['Ignoring link budget and error rate over distance','Assuming telemetry is only radio, not wired or acoustic','Overlooking the sensor calibration behind the data']::text[],ARRAY['Monitoring a spacecraft''s systems','Streaming race-car sensor data','Watching a remote pipeline''s pressure']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='telemetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd03d929-ea66-5cb5-be0b-3639ea42cbf9','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd03d929-ea66-5cb5-be0b-3639ea42cbf9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd03d929-ea66-5cb5-be0b-3639ea42cbf9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c7e8eaf-b7b1-5dc8-8a5f-56f89845dda8','long-range acoustic device','A highly directional acoustic hailing device that projects intelligible speech or warning tones at high sound-pressure levels in a narrow beam, so messages carry clearly over hundreds of metres to a targeted area. An array of transducers concentrates the energy forward; because levels close to the device can exceed safe exposure limits, it serves both for long-distance communication and as a deterrent.','A long-range acoustic device sends speech or tones a long way. It aims sound in a tight, forward beam. This keeps the message loud and clear far off. Up close it can be painfully loud. It is used to warn or to communicate at distance.','It delivers clear messages or warnings across long distances by beaming high-level, directional sound at a chosen area.','Used for maritime and perimeter hailing, crowd and emergency notification, and wildlife dispersal.','Data Sonification & Auditory Display',ARRAY['Acoustic hailing device','Directivity','Sound pressure level','Sonic deterrent','Beamforming']::text[],ARRAY['UNSAFE: standing in or aiming the close-range beam at people, risking immediate hearing damage','Assuming the narrow beam is equally loud in all directions','Underestimating reflections that spread the sound']::text[],ARRAY['Hailing an approaching vessel at sea','Broadcasting emergency warnings to a crowd','Dispersing birds from an airfield']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='long-range acoustic device');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c7e8eaf-b7b1-5dc8-8a5f-56f89845dda8','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c7e8eaf-b7b1-5dc8-8a5f-56f89845dda8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c7e8eaf-b7b1-5dc8-8a5f-56f89845dda8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac81c5b1-2098-556d-9ec8-b2fa2050a89c','acoustic hailing device','The general category of highly directional loudspeaker systems designed to transmit intelligible voice messages or warning tones over long distances to a specific area or target. Acoustic hailing devices use transducer arrays and horn or parametric techniques to achieve high directivity and output; they serve communication, warning, and deterrence roles, and close to the device they can produce hazardous sound-pressure levels.','An acoustic hailing device is a very directional loudspeaker. It sends clear speech or tones far away. The sound stays in a narrow beam. This lets it reach a chosen spot at distance. Close up, it can be dangerously loud.','It communicates or warns clearly at long range by focusing sound into a controllable, high-output beam.','Deployed in security, maritime, military, and public-safety settings for hailing, warning, and crowd communication.','Data Sonification & Auditory Display',ARRAY['Long-range acoustic device','Directivity','Parametric loudspeaker','Sonic deterrent','Sound pressure level']::text[],ARRAY['UNSAFE: exposing people to the close-range beam at levels that can harm hearing','Confusing all such devices with a single brand name','Expecting even coverage rather than a narrow beam']::text[],ARRAY['Warning an intruder at a secured site','Communicating with a distant boat','Addressing a crowd over long distance']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic hailing device');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac81c5b1-2098-556d-9ec8-b2fa2050a89c','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac81c5b1-2098-556d-9ec8-b2fa2050a89c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac81c5b1-2098-556d-9ec8-b2fa2050a89c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd04a3b54-b9dc-525c-b765-5925b224b770','sonic deterrent','A device that emits audible sound, often loud, harsh, or startling tones, to discourage or drive animals or people away from an area. Sonic deterrents work by triggering aversion, alarm, or discomfort; their effectiveness varies and often fades as targets habituate, and at high levels they raise sound-nuisance and, close up, hearing-safety concerns.','A sonic deterrent uses sound to scare something away. It plays loud or harsh tones. The noise annoys or alarms the target. Animals and people tend to leave the area. Over time, targets may get used to it.','It keeps unwanted animals or people away from an area using aversive sound instead of a physical barrier.','Used for bird and pest scaring on farms and airfields, wildlife control, and some security deterrence.','Data Sonification & Auditory Display',ARRAY['Ultrasonic deterrent','Acoustic hailing device','Habituation','Sound pressure level','Nuisance noise']::text[],ARRAY['Ignoring habituation that weakens the long-term effect','Assuming audible deterrents do not disturb neighbours or non-target species','UNSAFE: running high-level deterrents where people come close enough for hearing risk']::text[],ARRAY['Scaring birds from a runway','Deterring pests from a crop field','Discouraging loitering with sound']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='sonic deterrent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd04a3b54-b9dc-525c-b765-5925b224b770','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d04a3b54-b9dc-525c-b765-5925b224b770') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d04a3b54-b9dc-525c-b765-5925b224b770');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'caaa6adf-d787-578d-ab4f-0c79d5e24371','ultrasonic deterrent','A device that emits high-frequency ultrasonic sound, above the human hearing range, intended to repel pests or animals such as rodents, insects, or cats without audible nuisance to people. It relies on the target''s sensitivity to frequencies humans cannot hear; scientific evidence for lasting effectiveness is mixed, because many species habituate and ultrasound attenuates quickly and is easily blocked by objects.','An ultrasonic deterrent plays sound too high for people to hear. It aims to repel pests like rodents or insects. Those animals can hear the high sound. People nearby notice nothing. Studies show the effect is often weak or short-lived.','It tries to repel target animals with inaudible high-frequency sound so people are not disturbed, though results are inconsistent.','Sold for rodent, insect, and pet deterrence in homes and gardens; its effectiveness should be verified in practice.','Data Sonification & Auditory Display',ARRAY['Sonic deterrent','Ultrasound','Habituation','Attenuation','Pest control']::text[],ARRAY['Assuming strong, reliable effects despite weak evidence','Ignoring that ultrasound is quickly blocked by walls and objects','Forgetting that pets like dogs and cats may also hear it']::text[],ARRAY['Trying to repel rodents indoors','Deterring cats from a garden','Evaluating a pest-repeller''s real effect']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ultrasonic deterrent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'caaa6adf-d787-578d-ab4f-0c79d5e24371','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='caaa6adf-d787-578d-ab4f-0c79d5e24371') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='caaa6adf-d787-578d-ab4f-0c79d5e24371');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e0e37324-b25d-5311-b67e-f1a2d1948f30','infrasound exposure','Human exposure to infrasound, acoustic energy below about twenty hertz, at the lower edge of or beneath the hearing threshold. Because sensitivity falls steeply at low frequencies, infrasound must reach high levels to be perceived, often felt as pressure, vibration, or fullness rather than as clear tone; it is measured with a special low-frequency weighting and comes from sources such as wind turbines, ventilation, transport, and industrial plant.','Infrasound is sound below about twenty hertz. It is at or under the low edge of hearing. People feel it more than hear it, as pressure or vibration. It must be strong to be noticed. Wind turbines, engines, and big fans can make it.','Understanding this exposure guides measurement, complaint investigation, and the setting of low-frequency limits with proper weighting.','Assessed near wind farms, industrial plants, and ventilation systems; measured with low-frequency weighting and microphones that reach very low frequencies.','Data Sonification & Auditory Display',ARRAY['Infrasound','G-weighting','Low-frequency noise','Hearing threshold','Sound pressure level']::text[],ARRAY['Measuring infrasound with A-weighting, which hides it','Assuming inaudible means it cannot be perceived or measured','Using microphones that roll off before the infrasonic range']::text[],ARRAY['Investigating low-frequency complaints near a wind farm','Measuring ventilation infrasound in a building','Assessing industrial low-frequency exposure']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='infrasound exposure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e0e37324-b25d-5311-b67e-f1a2d1948f30','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e0e37324-b25d-5311-b67e-f1a2d1948f30') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e0e37324-b25d-5311-b67e-f1a2d1948f30');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '703eace8-27eb-558b-a1e6-b99992ee8579','acoustic startle','The acoustic startle response is a fast, involuntary reflex — including an eyeblink, muscle contraction, and orienting reaction — triggered by a sudden, intense sound with a rapid onset. In auditory warning and alarm design it describes how an abrupt high-level signal can seize attention almost instantly, at the cost of momentary disruption, defensive behaviour, and, at very high levels, a risk of panic or injury.','A sudden loud sound can make you jump. This quick, built-in reaction is the acoustic startle. It grabs your attention at once. Alarm designers use it, but with care. Too strong a jolt can cause panic or harm.','It explains why an abrupt, loud onset captures attention involuntarily, informing how urgent alarms are designed and how startle-related risks are kept in check.','Warning-system and vehicle-alarm designers weigh startle when setting alarm level, onset, and rise time so a signal alerts without provoking dangerous reactions.','Data Sonification & Auditory Display',ARRAY['Auditory warning','Alerting signal','Warning tone','Loudness','Reaction time']::text[],ARRAY['Assuming a louder, sharper alarm is always safer or more effective','UNSAFE: setting alarm levels so high the startle reaction itself risks panic or injury','Confusing the reflexive startle with a considered response to a warning']::text[],ARRAY['Tuning a reversing alarm so it alerts without startling','Designing a fire-alarm onset that grabs attention safely','Testing reactions to a sudden signal in a warning-sound trial']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic startle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '703eace8-27eb-558b-a1e6-b99992ee8579','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='703eace8-27eb-558b-a1e6-b99992ee8579') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='703eace8-27eb-558b-a1e6-b99992ee8579');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2a70d6d-1e33-50d4-8946-769552e1db2b','acoustic harassment device','An acoustic harassment device (AHD) is a high-power underwater sound projector that broadcasts loud, aversive signals to deter marine mammals — typically seals and sea lions — from fish farms, nets, or other sites. It works by producing sound at levels and frequencies unpleasant or painful enough to drive animals away, which distinguishes it from lower-power acoustic deterrent pingers meant only to alert.','An acoustic harassment device is a loud underwater sound source. It plays harsh sound to scare seals from fish farms. The noise is strong enough to be unpleasant. This pushes the animals out of the area. It is louder than a simple warning pinger.','It protects fish stocks and gear by using high-level aversive sound to keep predatory marine mammals away from a site.','Aquaculture operators deploy AHDs around fish pens to reduce seal predation, though their noise impact on non-target species is closely regulated.','Data Sonification & Auditory Display',ARRAY['Acoustic deterrent device','Marine mammal pinger','Underwater sound','Bycatch','Marine bioacoustics']::text[],ARRAY['Confusing a high-power harassment device with a low-power warning pinger','UNSAFE: exposing non-target marine life or divers to harmful sound through misuse of high output','Assuming target animals never habituate to the deterrent over time']::text[],ARRAY['Deterring seals from a coastal salmon farm','Assessing an AHD''s noise impact on nearby porpoises','Comparing an AHD with a quieter pinger for bycatch control']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic harassment device');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2a70d6d-1e33-50d4-8946-769552e1db2b','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2a70d6d-1e33-50d4-8946-769552e1db2b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2a70d6d-1e33-50d4-8946-769552e1db2b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf260c3a-6d08-5e9a-8ddf-b83ddfce4d76','marine mammal pinger','A marine mammal pinger is a small, battery-powered acoustic deterrent device attached to fishing nets that emits brief, intermittent tonal pings to warn marine mammals — especially porpoises and dolphins — of the net''s presence and so reduce accidental bycatch. Unlike a harassment device, it uses modest source levels intended to alert rather than to repel through discomfort.','A marine mammal pinger is a small device on a fishing net. It gives short beeps under water. The beeps warn dolphins and porpoises that a net is near. This helps them avoid getting caught. It is far quieter than a scaring device.','It reduces accidental entanglement of small cetaceans by making a net acoustically noticeable to the animals.','Gillnet fishers fit pingers along the net headline to cut porpoise bycatch, often as a legal requirement in managed fisheries.','Data Sonification & Auditory Display',ARRAY['Acoustic deterrent device','Acoustic harassment device','Bycatch','Echolocation','Gillnet']::text[],ARRAY['Thinking a pinger repels animals rather than simply alerting them','Spacing pingers too far apart to cover the whole net','Assuming a pinger with a dead battery still prevents bycatch']::text[],ARRAY['Fitting pingers to a gillnet to protect harbour porpoises','Checking pinger spacing along a net','Comparing bycatch with and without active pingers']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='marine mammal pinger');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf260c3a-6d08-5e9a-8ddf-b83ddfce4d76','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf260c3a-6d08-5e9a-8ddf-b83ddfce4d76') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf260c3a-6d08-5e9a-8ddf-b83ddfce4d76');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92bd8030-68e5-59ad-b29c-6c40e7683989','crowd-control acoustics','Crowd-control acoustics refers to the use of high-directivity, high-intensity sound to influence, move, or disperse crowds and to broadcast intelligible commands over long distances. It encompasses long-range acoustic hailing devices that project a tight beam of loud speech or deterrent tones, and it raises significant safety and legal questions because such levels can damage hearing at close range.','Crowd-control acoustics uses focused, loud sound aimed at crowds. It can send clear spoken commands over long distances. It can also play harsh tones to move people. The beam is narrow and very loud. Up close it can harm hearing.','It lets authorities send clear messages or deterrent sound across distance and over noise, to manage or disperse large groups.','Security and emergency teams use long-range acoustic hailing devices for mass notification, area denial, and crowd management at events or borders.','Data Sonification & Auditory Display',ARRAY['Long-range acoustic device','Sound pressure level','Directivity','Hearing damage risk','Auditory warning']::text[],ARRAY['UNSAFE: operating a long-range acoustic device at close range, where levels can damage hearing','Assuming the loud beam affects only the intended target and no bystanders','Confusing acoustic hailing with ordinary public-address use']::text[],ARRAY['Broadcasting evacuation instructions over a noisy crowd','Assessing a safe standoff distance for an acoustic hailing device','Managing crowd movement at a large public event']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='crowd-control acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92bd8030-68e5-59ad-b29c-6c40e7683989','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92bd8030-68e5-59ad-b29c-6c40e7683989') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92bd8030-68e5-59ad-b29c-6c40e7683989');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df200eaf-dfe9-5b7c-b835-6964c4f3c408','warning tone','A warning tone is a deliberately designed non-speech auditory signal used to alert a person to a hazard, fault, or condition needing attention. Effective warning tones are specified to be audible above background noise, to convey an appropriate sense of urgency through frequency, level, tempo, and harmonic content, and to be clearly distinguishable from other signals in the same environment, as codified in danger-signal ergonomics standards.','A warning tone is a sound that tells you something is wrong. It is not speech. It must be heard over background noise. Its pitch and speed suggest how urgent it is. Good tones are easy to tell apart from other sounds.','It conveys a hazard or fault quickly and without words, so people notice and respond even when they cannot look at a display.','Designers choose warning tones for machinery, vehicles, and medical devices so alerts stay audible and clearly urgent in real workplaces.','Data Sonification & Auditory Display',ARRAY['Auditory warning','Alerting signal','Alarm','Urgency mapping','Masking']::text[],ARRAY['Choosing a tone that is masked by the machine''s own background noise','Using so many similar tones that operators cannot tell them apart','Assuming a louder tone always feels more urgent']::text[],ARRAY['Designing a machine-fault tone audible over factory noise','Setting a medical monitor''s alarm pitch for urgency','Testing whether a warning tone is heard in a noisy cab']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='warning tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df200eaf-dfe9-5b7c-b835-6964c4f3c408','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df200eaf-dfe9-5b7c-b835-6964c4f3c408') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df200eaf-dfe9-5b7c-b835-6964c4f3c408');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c25fbd7c-b7cf-5186-97b2-ad460ce1c1bc','alerting signal','An alerting signal is an auditory (or multimodal) cue whose primary purpose is to capture attention and prompt a shift of focus toward a source of information or a required action, without necessarily encoding the details of the situation. In auditory display design it is distinguished from an informative or status signal by its emphasis on detectability and an orienting response rather than on conveying specific data.','An alerting signal is a sound made to grab your attention. It tells you to look or act now. It need not explain the whole situation. Its job is to make you notice. The details can come from another display.','It redirects a person''s attention to something important, acting as the first stage before more detailed information is taken in.','Interface designers use alerting signals in cockpits, control rooms, and phones to pull attention to a new event before the operator reads the detail.','Data Sonification & Auditory Display',ARRAY['Warning tone','Auditory warning','Notification sound','Attention','Earcon']::text[],ARRAY['Overloading an alert with detail it cannot reliably convey','Using alerts so often that people learn to ignore them','Confusing an attention-getting alert with a full status message']::text[],ARRAY['Signalling a new alarm in a control room','Prompting a pilot to check a warning display','Cueing a user to an incoming message']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='alerting signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c25fbd7c-b7cf-5186-97b2-ad460ce1c1bc','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c25fbd7c-b7cf-5186-97b2-ad460ce1c1bc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c25fbd7c-b7cf-5186-97b2-ad460ce1c1bc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6c8f0c5-1d6a-5ef7-8e01-0c7865d900c7','auditory risk zone','An auditory risk zone is a region — around a high-intensity sound source or within a noisy environment — in which sound exposure is high enough to threaten hearing or to provoke strong involuntary reactions. Defining such a zone combines the source''s radiated level and directivity with distance-based attenuation and accepted noise-exposure limits, so a boundary can be drawn beyond which exposure is judged acceptable.','An auditory risk zone is an area where sound is loud enough to be dangerous. Being inside it can harm your hearing. Its size depends on the source level and direction. Distance lowers the sound. A safe limit sets the edge of the zone.','It marks how close people can be to a loud source before exposure threatens hearing, guiding safe standoff distances and protection.','Safety planners map risk zones around sirens, acoustic hailing devices, and machinery to set exclusion distances and hearing-protection rules.','Data Sonification & Auditory Display',ARRAY['Noise exposure','Sound pressure level','Hearing damage risk','Permissible exposure limit','Directivity']::text[],ARRAY['UNSAFE: entering the high-level zone of a loud source without hearing protection','Ignoring source directivity when estimating where the zone ends','Assuming a brief exposure inside the zone is always harmless']::text[],ARRAY['Setting a safe standoff distance from an acoustic hailing device','Marking a hearing-hazard area around loud machinery','Planning crowd distance from a high-level siren']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='auditory risk zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6c8f0c5-1d6a-5ef7-8e01-0c7865d900c7','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6c8f0c5-1d6a-5ef7-8e01-0c7865d900c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6c8f0c5-1d6a-5ef7-8e01-0c7865d900c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6fda63a7-3fb9-5ef0-9b82-160b63e4a241','product sound','Product sound is the sound emitted by a product during use — whether an unavoidable by-product of its operation or a deliberately engineered signal — considered as a designed attribute that shapes user perception of quality, function, brand, and safety. Its study, product sound quality, applies psychoacoustic metrics and listening tests to characterise and tune these sounds rather than treating them merely as noise to be minimised.','Product sound is the sound a product makes when you use it. A car-door thunk or a keyboard click are examples. Designers work on this sound on purpose. It shapes how good the product feels. Some sounds are tuned, not just made quieter.','It treats a product''s sound as a design feature that signals quality, operation, and brand, not just noise to reduce.','Sound-quality engineers measure and tune the sounds of car doors, appliances, and switches using psychoacoustic metrics and listening panels.','Data Sonification & Auditory Display',ARRAY['Sound quality','Psychoacoustics','Sound design','Loudness','Sharpness']::text[],ARRAY['Treating all product sound as noise to be minimised','Judging product sound by level alone and ignoring its character','Skipping listening tests and relying only on numbers']::text[],ARRAY['Tuning the closing sound of a car door','Designing a satisfying click for a switch','Rating appliance sound quality with a listening panel']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='product sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6fda63a7-3fb9-5ef0-9b82-160b63e4a241','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6fda63a7-3fb9-5ef0-9b82-160b63e4a241') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6fda63a7-3fb9-5ef0-9b82-160b63e4a241');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd41866d8-404d-563b-a11a-8bbd876db0ef','notification sound','A notification sound is a short non-speech audio cue that signals the arrival of an event, message, or status change in a device or interface, without demanding the immediate, high-urgency response of an alarm. Well-designed notification sounds are brief, recognisable, distinguishable from one another, and pitched at an urgency appropriate to the event''s importance.','A notification sound is a short cue from a device. It tells you something has happened. A new message often makes one. It is calmer than an alarm. Good ones are short and easy to recognise.','It tells a user that an event has occurred so they can attend to it when convenient, without the pressure of an alarm.','Interface and operating-system designers craft notification sounds for phones and apps so events are noticed but not alarming, and distinct from each other.','Data Sonification & Auditory Display',ARRAY['Earcon','Auditory icon','Alerting signal','Interaction sound','Confirmation tone']::text[],ARRAY['Making a routine notification as urgent-sounding as an alarm','Using near-identical sounds for very different events','Ignoring that repeated notifications become annoying']::text[],ARRAY['Choosing a message-received sound for a phone','Distinguishing an email cue from a calendar cue','Setting notification volume for a quiet office']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='notification sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd41866d8-404d-563b-a11a-8bbd876db0ef','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d41866d8-404d-563b-a11a-8bbd876db0ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d41866d8-404d-563b-a11a-8bbd876db0ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b1d890d2-31d8-5554-af3d-ec6f4e88b47d','confirmation tone','A confirmation tone is a brief auditory feedback signal indicating that a user action has been received and accepted by a system — for example a keypress, a successful transaction, or a completed command. It closes the interaction loop by reassuring the user that input registered, and is typically designed to sound positive and to be clearly distinct from error or warning signals.','A confirmation tone is a short sound that says an action worked. A beep after a card payment is one. It tells you the system got your input. It usually sounds positive. It differs clearly from an error sound.','It reassures the user that an input was received and accepted, closing the feedback loop for an action.','Designers add confirmation tones to card readers, keypads, and voice systems so users know a step succeeded without looking.','Data Sonification & Auditory Display',ARRAY['Interaction sound','Error tone','Auditory feedback','Notification sound','Earcon']::text[],ARRAY['Making the confirmation tone sound like an error tone','Confirming success before the action has actually completed','Adding a tone so long it slows down repeated use']::text[],ARRAY['Beeping when a payment card is accepted','Confirming a keypad entry on a lock','Signalling that a voice command was understood']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='confirmation tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b1d890d2-31d8-5554-af3d-ec6f4e88b47d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b1d890d2-31d8-5554-af3d-ec6f4e88b47d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b1d890d2-31d8-5554-af3d-ec6f4e88b47d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '933525c8-b94f-5525-b622-c16db2f659a5','error tone','An error tone is a short non-speech audio signal indicating that a user action or system operation has failed or been rejected — for example invalid input, a blocked command, or a fault. It is designed to be clearly distinguishable from confirmation and notification sounds, often using a negative or dissonant character, so the user recognises failure and can correct course.','An error tone is a short sound that says something went wrong. You hear one after a wrong password. It marks a failed or rejected action. It sounds clearly different from a success tone. This helps you notice and fix the problem.','It tells the user that an action failed or was rejected, prompting them to correct the input or try again.','Designers assign error tones to keypads, forms, and machines so a rejected action is obvious without reading the screen.','Data Sonification & Auditory Display',ARRAY['Confirmation tone','Interaction sound','Auditory feedback','Warning tone','Earcon']::text[],ARRAY['Using an error tone that sounds like a success tone','Making the error tone harsh enough to feel like an alarm','Giving no error sound at all for a failed action']::text[],ARRAY['Signalling a wrong PIN on a keypad','Marking rejected input on a form','Indicating a blocked command on a device']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='error tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '933525c8-b94f-5525-b622-c16db2f659a5','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='933525c8-b94f-5525-b622-c16db2f659a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='933525c8-b94f-5525-b622-c16db2f659a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2dc656ef-499e-5fef-a629-099b27a15778','affordance sound','An affordance sound is an auditory cue whose acoustic character suggests the action a control or object supports, or the result it will produce, by drawing on listeners'' everyday experience of how things sound. Rooted in ecological acoustics and the auditory-icon tradition, it uses naturalistic, source-evocative sound so meaning is grasped intuitively rather than learned as an arbitrary code.','An affordance sound hints at what you can do or what will happen. It uses sounds like those from real objects. A click that sounds like a real switch is one. You get the meaning without learning a code. It draws on everyday listening.','It makes an interface''s possibilities and outcomes understandable through familiar, real-world sound rather than arbitrary tones.','Interaction designers use affordance sounds so a control''s sound reveals its function, easing learning in apps, games, and devices.','Data Sonification & Auditory Display',ARRAY['Auditory icon','Ecological acoustics','Interaction sound','Skeuomorphism','Sonic interaction design']::text[],ARRAY['Assuming an arbitrary beep conveys function as well as a real-world sound','Using a source sound that mismatches the actual action','Confusing affordance sounds with abstract earcons']::text[],ARRAY['Designing a drag sound that suggests weight in an app','Making a control sound reveal what it does','Using a real-object sound for an on-screen button']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='affordance sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2dc656ef-499e-5fef-a629-099b27a15778','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2dc656ef-499e-5fef-a629-099b27a15778') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2dc656ef-499e-5fef-a629-099b27a15778');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77b66571-ee2d-5d84-a8db-61fafd4aa671','interaction sound','An interaction sound is audio produced in direct response to a user''s action with a system or object, providing continuous or discrete feedback that supports control, engagement, and understanding. Central to the field of sonic interaction design, it spans confirmation and error cues, continuous action sounds, and expressive sound that couples tightly to gesture and manipulation.','An interaction sound is audio made when you act on a device. A slider that whooshes as you drag it is one. It gives feedback while you use the system. It can be a single beep or a continuous sound. It links closely to what you do.','It gives immediate feedback tied to user action, supporting control, engagement, and a sense of direct manipulation.','Designers of apps, instruments, and games add interaction sounds so gestures feel responsive and actions are confirmed by ear.','Data Sonification & Auditory Display',ARRAY['Sonic interaction design','Auditory feedback','Affordance sound','Confirmation tone','Gesture']::text[],ARRAY['Adding sound that lags behind the action and breaks the link','Overusing interaction sounds until they become fatiguing','Treating feedback sound as decoration rather than function']::text[],ARRAY['Sounding a slider as the user drags it','Giving a game control audible feedback','Making a virtual instrument respond to gesture']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='interaction sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77b66571-ee2d-5d84-a8db-61fafd4aa671','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77b66571-ee2d-5d84-a8db-61fafd4aa671') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77b66571-ee2d-5d84-a8db-61fafd4aa671');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4aaf2f42-95d6-5fc7-a647-0f1f5e8c0969','haptic audio','Haptic audio refers to the tightly coupled or shared use of audio and vibrotactile signals, in which sound and touch-borne vibration are generated together — often from related signals and overlapping low-frequency content — to reinforce feedback and perceived impact. Because audible sound and body-felt vibration share physical origins at low frequencies, systems can drive tactile transducers from audio so events are felt as well as heard.','Haptic audio joins sound with felt vibration. You both hear and feel an event. A phone buzz paired with a tone is a simple case. Low sounds and vibration share the same roots. Systems drive shakers from audio to add touch feedback.','It strengthens feedback and immersion by letting users feel vibration alongside sound, especially for low-frequency impact and alerts.','Designers use haptic audio in game controllers, phones, and seats to pair felt vibration with sound for impact and alerts.','Data Sonification & Auditory Display',ARRAY['Vibrotactile feedback','Tactile transducer','Low-frequency effects','Multimodal display','Bone conduction']::text[],ARRAY['Assuming any audio signal works well as a tactile signal without shaping','Ignoring that touch and hearing differ in their useful frequency range','Confusing haptic audio with ordinary loudspeaker vibration']::text[],ARRAY['Adding felt rumble to a game controller','Pairing a phone buzz with an alert tone','Driving a tactile seat from a film''s low bass']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='haptic audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4aaf2f42-95d6-5fc7-a647-0f1f5e8c0969','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4aaf2f42-95d6-5fc7-a647-0f1f5e8c0969') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4aaf2f42-95d6-5fc7-a647-0f1f5e8c0969');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6a7fe36-b093-56ec-965c-4c7570001c13','skeuomorphism','Skeuomorphism is a design approach in which a new artefact keeps sensory features derived from an older, physical original that are no longer functionally necessary, in order to signal familiarity and function. In audio and interface design it appears as skeuomorphic sounds — such as a synthetic camera-shutter click or key-tap sound — that imitate a legacy physical event to make a digital action feel recognisable.','Skeuomorphism copies features of an old, real object in a new one. The copied feature is no longer needed to work. A phone''s fake shutter click is an example. It makes a digital action feel familiar. The sound imitates a real event.','It borrows familiar looks or sounds from physical originals so users instantly recognise and trust a digital action.','Interface sound designers add skeuomorphic cues, like shutter or typewriter sounds, so digital actions echo familiar real-world events.','Data Sonification & Auditory Display',ARRAY['Affordance sound','Auditory icon','Interaction sound','Sound design','Metaphor']::text[],ARRAY['Assuming a skeuomorphic sound is always clearer than an abstract cue','Keeping an imitation whose original reference users no longer know','Confusing skeuomorphism with realistic high-fidelity audio']::text[],ARRAY['Adding a shutter sound to a silent phone camera','Using a typewriter click for on-screen typing','Designing app sounds that echo real devices']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='skeuomorphism');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6a7fe36-b093-56ec-965c-4c7570001c13','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6a7fe36-b093-56ec-965c-4c7570001c13') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6a7fe36-b093-56ec-965c-4c7570001c13');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1985d9d8-b310-5593-9c6c-3deca173a532','auditory display','An auditory display is any system that uses sound — usually non-speech sound — to present information to a listener, encompassing alarms, status and process monitoring, data sonification, and sound in human–computer interaction. As the organising concept of the field served by the International Community for Auditory Display, it treats sound as a deliberate information-bearing channel and studies how to map data and events to sound that listeners can interpret.','An auditory display shows information using sound. It usually uses non-speech sound. Alarms and data turned into sound are examples. It treats sound as a way to carry information. Designers study how to map data to sounds people can read by ear.','It uses sound as an information channel, so people can monitor data and events by listening, freeing or supplementing vision.','Engineers build auditory displays for cockpits, control rooms, medical monitors, and accessibility tools where operators must listen while watching other things.','Data Sonification & Auditory Display',ARRAY['Sonification','Non-speech audio','Earcon','Auditory icon','Data-to-sound mapping']::text[],ARRAY['Equating auditory display only with alarms and ignoring data monitoring','Assuming sound needs no design as careful as a visual display','Overloading the ear with too many concurrent streams']::text[],ARRAY['Monitoring patient vitals by ear in an operating room','Presenting network status as sound in a control room','Giving eyes-free feedback in a cockpit']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='auditory display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1985d9d8-b310-5593-9c6c-3deca173a532','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1985d9d8-b310-5593-9c6c-3deca173a532') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1985d9d8-b310-5593-9c6c-3deca173a532');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bcfe4f99-2df6-5190-9489-11a0adfc40e1','non-speech audio','Non-speech audio is sound used to convey information or feedback without relying on spoken language — including tones, earcons, auditory icons, and sonified data. It is the core medium of auditory display, chosen because it can be fast, language-independent, and effective for continuous monitoring, while avoiding the time cost and cognitive load of listening to speech.','Non-speech audio is sound that carries meaning without words. Beeps, earcons, and sonified data all count. It is the main medium of auditory display. It can be fast and language-free. It suits monitoring where speech would be too slow.','It conveys information by sound without words, giving fast, language-independent cues well suited to alerts and continuous monitoring.','Designers use non-speech audio for alarms, progress cues, and data sonification where speech would be too slow or intrusive.','Data Sonification & Auditory Display',ARRAY['Auditory display','Earcon','Auditory icon','Sonification','Warning tone']::text[],ARRAY['Assuming non-speech cues need no learning by the listener','Using too many abstract tones that users cannot recall','Believing speech is always clearer than a well-chosen sound']::text[],ARRAY['Signalling progress with a rising tone','Using earcons in a phone menu','Sonifying data for eyes-free monitoring']::text[],'beginner',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='non-speech audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bcfe4f99-2df6-5190-9489-11a0adfc40e1','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bcfe4f99-2df6-5190-9489-11a0adfc40e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bcfe4f99-2df6-5190-9489-11a0adfc40e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '16beecff-ecb6-5d0b-95f6-236b3713d5ae','accessibility audio cue','An accessibility audio cue is a sound provided specifically to make a system usable by people with disabilities — most often to convey visual information non-visually for blind or low-vision users, or to supplement other channels. Examples include screen-reader event sounds, audible focus and state changes, and sonified feedback, and their design follows accessibility guidance on offering information through more than one sensory channel.','An accessibility audio cue is a sound that helps people with disabilities use a system. It often gives visual information by ear. A sound marking a selected item is one. Blind users rely on such cues. Good design offers more than one way to sense information.','It conveys information through sound so users who cannot rely on a visual display can still perceive state, focus, and events.','Developers add audio cues in screen readers, apps, and kiosks so blind and low-vision users can track focus, status, and alerts.','Data Sonification & Auditory Display',ARRAY['Auditory display','Earcon','Screen reader','Multimodal display','Non-speech audio']::text[],ARRAY['Providing information by colour or sight alone with no audio alternative','Assuming captions and audio cues serve the same users','Making cues so subtle that assistive-technology users miss them']::text[],ARRAY['Sounding focus changes for a screen-reader user','Adding audio feedback to a self-service kiosk','Signalling an error by sound as well as colour']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='accessibility audio cue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '16beecff-ecb6-5d0b-95f6-236b3713d5ae','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='16beecff-ecb6-5d0b-95f6-236b3713d5ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='16beecff-ecb6-5d0b-95f6-236b3713d5ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7d2ad2c-bad8-5af2-ac38-772318cba568','parameter-mapping sonification','Parameter-mapping sonification is a technique in which data variables are mapped to the parameters of sound — such as pitch, loudness, tempo, timbre, or spatial position — so that changes in the data are heard as changes in the sound. It is the most widely used sonification method, and its effectiveness depends on choosing perceptually appropriate, well-scaled, and minimally interfering mappings between data dimensions and acoustic dimensions.','Parameter-mapping sonification turns data into sound settings. A value might control pitch or loudness. As the data changes, the sound changes with it. It is the most common way to sonify data. Good mappings must fit how we hear.','It lets people hear patterns in data by tying data values to controllable qualities of sound like pitch and loudness.','Analysts sonify time series, sensor streams, and scientific data by mapping variables to pitch, level, or tempo for listening analysis.','Data Sonification & Auditory Display',ARRAY['Sonification','Data-to-sound mapping','Auditory display','Pitch','Timbre']::text[],ARRAY['Mapping data to pitch without scaling it to how pitch is perceived','Using mappings that interfere, so one dimension masks another','Assuming any mapping is intuitive without testing on listeners']::text[],ARRAY['Mapping a stock price to pitch over time','Sonifying sensor data by loudness and tempo','Turning a data table into an audible pattern']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='parameter-mapping sonification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7d2ad2c-bad8-5af2-ac38-772318cba568','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7d2ad2c-bad8-5af2-ac38-772318cba568') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7d2ad2c-bad8-5af2-ac38-772318cba568');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9177d8fa-0d98-50f3-865a-4d1dd0ce39d9','acoustic display','An acoustic display is a presentation of information through sound; the phrase is used both as a synonym for auditory display and, in some engineering and defence contexts, to emphasise the physical acoustic presentation of data such as sonar or process signals. In all uses it denotes deliberately structured sound intended to inform a listener rather than incidental noise.','An acoustic display presents information through sound. The term often means the same as auditory display. In sonar work it stresses the physical sound itself. Either way, the sound is shaped on purpose. Its goal is to inform a listener.','It presents data or events as structured sound so a listener can interpret them, overlapping in meaning with auditory display.','The term appears in sonar, process-monitoring, and human-factors work where information is deliberately rendered as sound for an operator.','Data Sonification & Auditory Display',ARRAY['Auditory display','Sonification','Sonar','Non-speech audio','Data-to-sound mapping']::text[],ARRAY['Treating acoustic display as unrelated to auditory display','Assuming it always means loudspeaker hardware rather than the information','Ignoring listener perception when designing the sound']::text[],ARRAY['Presenting sonar returns as audible sound','Monitoring a process by an acoustic readout','Rendering data as sound for an operator']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9177d8fa-0d98-50f3-865a-4d1dd0ce39d9','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9177d8fa-0d98-50f3-865a-4d1dd0ce39d9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9177d8fa-0d98-50f3-865a-4d1dd0ce39d9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '15022714-52f7-59d7-bfcf-3e4d3e3f973d','multimodal display','A multimodal display presents information through two or more sensory channels — such as vision, hearing, and touch — either redundantly to improve robustness or complementarily to divide information across senses. In human–computer interaction and auditory display, combining modalities can raise detection and comprehension, reduce single-channel overload, and support accessibility, provided the channels are aligned in time and meaning.','A multimodal display gives information through more than one sense. It might use sight, sound, and touch together. The same message can repeat across senses for safety. Or different parts can go to different senses. The channels must agree in time and meaning.','It spreads information across several senses to improve detection, reduce overload on one channel, and support accessibility.','Designers combine visual, audio, and haptic cues in cockpits, cars, and phones so alerts are caught even when one sense is busy.','Data Sonification & Auditory Display',ARRAY['Auditory display','Haptic audio','Cross-modal perception','Redundancy','Accessibility audio cue']::text[],ARRAY['Presenting mismatched cues on different senses at different times','Assuming more channels always help and ignoring the added load','Using a second modality that merely repeats without benefit']::text[],ARRAY['Warning a driver by sound, light, and seat vibration','Combining visual and audio alerts in a cockpit','Adding haptic feedback to a touchscreen action']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='multimodal display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '15022714-52f7-59d7-bfcf-3e4d3e3f973d','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='15022714-52f7-59d7-bfcf-3e4d3e3f973d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='15022714-52f7-59d7-bfcf-3e4d3e3f973d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17d22022-effb-525e-a369-3dea40a04510','data-to-sound mapping','Data-to-sound mapping is the defined correspondence between data attributes and acoustic attributes that underlies a sonification — specifying which data variable controls which sound parameter, over what range, with what scaling and polarity. The choice of mapping determines whether relationships in the data are heard accurately, and poor mappings can distort, hide, or falsely imply structure.','Data-to-sound mapping sets how data becomes sound. It says which value controls which sound quality. It also fixes the range and direction of the change. A good mapping lets you hear the real pattern. A bad one can hide or fake structure.','It defines the rules that turn data into sound, so the resulting sonification represents the data faithfully and understandably.','Sonification designers specify data-to-sound mappings — variable, range, scaling, and polarity — when building any auditory data display.','Data Sonification & Auditory Display',ARRAY['Parameter-mapping sonification','Sonification','Auditory display','Scaling','Pitch']::text[],ARRAY['Using a linear mapping where perception is logarithmic','Reversing polarity so higher data sounds lower without reason','Mapping too many variables onto overlapping sound qualities']::text[],ARRAY['Deciding that higher temperature maps to higher pitch','Setting the value range a loudness mapping covers','Choosing scaling for a data-driven tempo change']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='data-to-sound mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17d22022-effb-525e-a369-3dea40a04510','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17d22022-effb-525e-a369-3dea40a04510') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17d22022-effb-525e-a369-3dea40a04510');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66071825-0017-50b9-ad82-1a15939808e5','music information retrieval','Music information retrieval (MIR) is the interdisciplinary field concerned with extracting, analysing, and using information from music — audio or symbolic — through signal processing and machine learning. It addresses tasks such as pitch and beat tracking, chord and key estimation, genre and mood classification, music similarity, and recommendation, and it underpins search, organisation, and analysis of large music collections.','Music information retrieval pulls useful information out of music. It works on audio or on scores. It can find the beat, key, or genre. It uses signal processing and machine learning. It powers music search and recommendation.','It lets computers describe, search, and organise music by extracting features like beat, key, and genre from audio or scores.','Engineers use MIR for music recommendation, automatic tagging, playlist generation, and search in streaming and library systems.','Data Sonification & Auditory Display',ARRAY['MFCC','Chroma feature','Beat tracking','Automatic transcription','Feature extraction']::text[],ARRAY['Assuming audio features capture musical meaning perfectly','Ignoring that labels like genre are subjective and noisy','Confusing retrieval on audio with retrieval on symbolic scores']::text[],ARRAY['Recommending songs from audio similarity','Auto-tagging a large music library','Estimating the key of a track for search']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='music information retrieval');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66071825-0017-50b9-ad82-1a15939808e5','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66071825-0017-50b9-ad82-1a15939808e5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66071825-0017-50b9-ad82-1a15939808e5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '583830be-e57f-5f99-b3d4-0445357ae72f','MFCC','Mel-frequency cepstral coefficients (MFCCs) are a compact set of features describing the short-term spectral envelope of a sound. They are computed by taking the magnitude spectrum of a short frame, warping it onto the perceptually motivated mel frequency scale with a filterbank, taking the logarithm of the band energies, and applying a discrete cosine transform to decorrelate them. The low-order coefficients capture timbre and are widely used in speech and music analysis.','MFCCs are a small set of numbers describing a sound''s timbre. They come from the sound''s short-term spectrum. The spectrum is warped to a scale that matches hearing. The band energies are logged and compressed. The result captures tone colour compactly.','They give a compact, perceptually motivated summary of spectral shape, so systems can compare and classify sounds by timbre.','MFCCs are standard input features for speech recognition, speaker identification, and music classification systems.','Data Sonification & Auditory Display',ARRAY['Mel scale','Cepstrum','Spectral envelope','Feature extraction','Music information retrieval']::text[],ARRAY['Treating MFCCs as a full, invertible description of the sound','Ignoring how frame size and filter count change the features','Assuming MFCCs are robust to noise without extra steps']::text[],ARRAY['Feeding MFCCs to a speech recogniser','Classifying instruments by MFCC features','Comparing timbre for music similarity']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MFCC');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '583830be-e57f-5f99-b3d4-0445357ae72f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='583830be-e57f-5f99-b3d4-0445357ae72f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='583830be-e57f-5f99-b3d4-0445357ae72f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d9b78bd-4c0e-55c3-8c4a-da8393238e1f','chroma feature','A chroma feature (or pitch-class profile) is a representation that collapses a sound''s spectral energy into the twelve pitch classes of the equal-tempered octave, folding all octaves together so the same note name in any register contributes to one bin. Because it captures harmonic and melodic content while being robust to timbre and octave, it is a standard feature for chord recognition, key estimation, and music alignment.','A chroma feature sorts a sound''s energy into the twelve note names. It folds all octaves together. So every C adds to the same bin, whatever its register. It captures harmony well. It ignores octave and much of timbre.','It summarises which pitch classes are present, giving a timbre- and octave-robust basis for chord, key, and harmony analysis.','MIR systems use chroma features for chord recognition, key detection, cover-song matching, and audio-to-score alignment.','Data Sonification & Auditory Display',ARRAY['Pitch class','Music information retrieval','Chord recognition','Key estimation','MFCC']::text[],ARRAY['Expecting chroma to capture timbre or octave, which it deliberately discards','Ignoring tuning offsets that smear energy across bins','Confusing chroma with a full spectrum representation']::text[],ARRAY['Recognising chords from audio','Estimating a song''s key','Matching cover versions by harmony']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='chroma feature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d9b78bd-4c0e-55c3-8c4a-da8393238e1f','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d9b78bd-4c0e-55c3-8c4a-da8393238e1f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d9b78bd-4c0e-55c3-8c4a-da8393238e1f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7ef2e0e-c3a3-5002-b6f4-98e3c29d5fa1','automatic transcription','Automatic transcription — in music, automatic music transcription — is the computational process of converting an audio recording into a symbolic representation such as notes, pitches, timing, or a score. It typically involves detecting concurrent pitches, onsets, and durations, and remains challenging for polyphonic material because overlapping harmonics make individual notes hard to separate.','Automatic transcription turns a recording into notes. A computer listens to the audio. It works out pitches, timing, and onsets. The result is a score or note list. It is hard when many notes sound at once.','It converts audio into notes automatically, so music can be scored, searched, or analysed without manual transcription.','It supports music-education tools, score following, search by melody, and analysis of recordings where no score exists.','Data Sonification & Auditory Display',ARRAY['Automatic music transcription','Pitch detection','Onset detection','Polyphony','Music information retrieval']::text[],ARRAY['Expecting perfect transcription of dense polyphonic audio','Assuming pitch detection alone gives a full transcription','Ignoring that timing and rhythm must also be estimated']::text[],ARRAY['Turning a piano recording into a score','Following a live performance against a score','Searching music by a sung melody']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='automatic transcription');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7ef2e0e-c3a3-5002-b6f4-98e3c29d5fa1','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7ef2e0e-c3a3-5002-b6f4-98e3c29d5fa1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7ef2e0e-c3a3-5002-b6f4-98e3c29d5fa1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '766c1fde-5a84-57d7-9e99-bc468958106b','latent audio representation','A latent audio representation is a learned, typically low-dimensional encoding of audio produced by a machine-learning model such as an autoencoder, variational autoencoder, or neural audio codec, in which perceptually or statistically salient structure is captured in a compact vector or feature space. Unlike hand-designed features, its dimensions are learned from data, and it supports tasks such as compression, generation, and similarity search in the learned space.','A latent audio representation is a learned code for sound. A neural network compresses audio into a small vector. The network learns what to keep from data. This is not designed by hand. Such codes help with generation, search, and compression.','It provides a compact, learned encoding of audio that supports generation, compression, and comparison in a data-driven feature space.','Engineers use latent representations in neural audio codecs, generative audio models, and similarity search for sound and music.','Data Sonification & Auditory Display',ARRAY['Autoencoder','Feature extraction','Neural audio codec','Embedding','Music information retrieval']::text[],ARRAY['Assuming latent dimensions have clear, human-readable meanings','Treating a learned code as exact and lossless','Comparing latents from different models as if interchangeable']::text[],ARRAY['Encoding audio in a neural codec','Generating sound from a latent vector','Searching sounds by latent-space distance']::text[],'advanced',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='latent audio representation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '766c1fde-5a84-57d7-9e99-bc468958106b','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='766c1fde-5a84-57d7-9e99-bc468958106b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='766c1fde-5a84-57d7-9e99-bc468958106b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20cd336c-542c-53a3-a9c9-e8dde6f5b384','moving coil','Moving coil describes the electrodynamic transducer principle in which a coil of wire, attached to a diaphragm and suspended in a fixed magnetic field, moves in response to current (as in a loudspeaker) or generates a voltage when moved by sound (as in a dynamic microphone). The force on the coil arises from the interaction of the current with the magnetic field, and the generated voltage arises from the coil''s motion through that field.','A moving coil is a coil of wire in a magnet''s field. A current in the coil makes it move. This drives a speaker cone. Sound moving the coil makes a voltage instead. That is how a dynamic microphone works.','It converts between electrical current and mechanical motion using a coil in a magnetic field, the basis of dynamic speakers and microphones.','Technicians meet the moving-coil principle in dynamic microphones, loudspeaker drivers, and headphones throughout audio systems.','Data Sonification & Auditory Display',ARRAY['Dynamic microphone','Loudspeaker driver','Electrodynamic transducer','Voice coil','Ribbon microphone']::text[],ARRAY['Confusing a moving-coil dynamic mic with a condenser mic','Assuming moving-coil mics need phantom power to work','Mixing up the voice coil with the magnet as the moving part']::text[],ARRAY['Choosing a rugged dynamic mic for live vocals','Servicing a loudspeaker voice coil','Explaining how a dynamic mic generates signal']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='moving coil');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20cd336c-542c-53a3-a9c9-e8dde6f5b384','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20cd336c-542c-53a3-a9c9-e8dde6f5b384') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20cd336c-542c-53a3-a9c9-e8dde6f5b384');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3cc62a2b-0b39-57a4-a16a-886fc0b662bd','piezoelectric transducer','A piezoelectric transducer converts between mechanical and electrical energy using the piezoelectric effect, in which certain crystalline or ceramic materials generate a charge when strained and deform when a voltage is applied. Used as both sensor and actuator, it suits high-frequency and high-impedance applications such as ultrasonic transmitters and receivers, contact pickups, and pressure sensing.','A piezoelectric transducer links force and electricity. Some crystals make a voltage when squeezed. They also bend when a voltage is applied. This lets them sense or make vibration. They work well at high frequencies, as in ultrasound.','It converts mechanical stress to an electrical signal and back, enabling ultrasonic transmit and receive, contact pickups, and pressure sensing.','Technicians find piezoelectric transducers in ultrasonic sensors, contact pickups on instruments, buzzers, and pressure or vibration sensors.','Data Sonification & Auditory Display',ARRAY['Piezoelectric effect','Ultrasonic transducer','Contact microphone','Transducer','Ceramic microphone']::text[],ARRAY['Loading a piezo pickup with too low an input impedance, thinning the bass','Assuming a piezo element handles large low-frequency motion well','Confusing piezoelectric with electromagnetic transduction']::text[],ARRAY['Using an ultrasonic piezo pair for distance sensing','Fitting a contact pickup to an acoustic instrument','Matching a piezo pickup to a high-impedance preamp']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='piezoelectric transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3cc62a2b-0b39-57a4-a16a-886fc0b662bd','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3cc62a2b-0b39-57a4-a16a-886fc0b662bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3cc62a2b-0b39-57a4-a16a-886fc0b662bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '169c1553-082c-5b14-9976-ae507ae7f5a1','magnetostriction','Magnetostriction is the property of ferromagnetic materials to change dimensions when magnetised, and conversely to change their magnetic state when mechanically strained. Quantified by the magnetostrictive strain — the fractional change in length — it enables magnetostrictive transducers that convert between magnetic and mechanical energy, historically used in early sonar projectors and still used in some high-power ultrasonic and sensing applications.','Some magnetic materials change size in a magnetic field. This effect is magnetostriction. The size change is very small. Pressing the material can also change its magnetism. Early sonar used it to make sound.','It converts between magnetic and mechanical energy, allowing transducers that produce strong vibration for sonar and ultrasonic use.','Engineers use magnetostrictive transducers in high-power ultrasonics, some sonar projectors, and position or force sensors.','Data Sonification & Auditory Display',ARRAY['Magnetostrictive transducer','Ultrasonic transducer','Sonar','Piezoelectric transducer','Transduction']::text[],ARRAY['Confusing magnetostriction with piezoelectric transduction','Assuming the length change is large rather than very small','Ignoring that the effect works in both directions']::text[],ARRAY['Driving a high-power ultrasonic cleaner','Explaining an early sonar projector','Sensing position with a magnetostrictive element']::text[],'advanced','λ = ΔL / L','The magnetostrictive strain equals the fractional change in a material''s length: the change in length divided by the original length.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='magnetostriction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '169c1553-082c-5b14-9976-ae507ae7f5a1','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='169c1553-082c-5b14-9976-ae507ae7f5a1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='169c1553-082c-5b14-9976-ae507ae7f5a1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2fe50ccd-8412-5a6a-a27d-2a3008f95693','velocity sensor','A velocity sensor is a transducer whose output is proportional to the velocity of motion rather than to displacement or acceleration. In acoustics and audio this includes pressure-gradient (velocity) microphones such as ribbons, which respond to the air''s particle velocity, and vibration velocity sensors such as geophones and moving-coil pickups used to measure the speed of a surface''s motion.','A velocity sensor gives an output that follows how fast something moves. It responds to speed, not position. A ribbon microphone senses the air''s motion this way. A geophone senses a surface''s speed. This differs from sensors that track displacement.','It measures the speed of motion of air or a surface, giving a signal proportional to velocity for sensing sound or vibration.','Engineers use velocity sensors as ribbon microphones, geophones in seismic and vibration work, and moving-coil vibration pickups.','Data Sonification & Auditory Display',ARRAY['Particle velocity','Ribbon microphone','Geophone','Accelerometer','Pressure-gradient microphone']::text[],ARRAY['Confusing a velocity sensor''s output with displacement or acceleration','Assuming all microphones respond to pressure, not velocity','Ignoring the phase relation between velocity and displacement']::text[],ARRAY['Recording with a ribbon (velocity) microphone','Measuring ground motion with a geophone','Sensing surface vibration by its velocity']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='velocity sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2fe50ccd-8412-5a6a-a27d-2a3008f95693','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2fe50ccd-8412-5a6a-a27d-2a3008f95693') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2fe50ccd-8412-5a6a-a27d-2a3008f95693');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93d8d2c8-0cee-52c2-aa16-dcfd3d419841','acoustic impedance matching','Acoustic impedance matching is the practice of arranging the specific acoustic impedances of adjacent media or elements so that sound energy is transferred efficiently across a boundary rather than reflected. Because the transmission of acoustic power depends on the ratio of the two impedances — each the product of density and sound speed — techniques such as matching layers, horns, and acoustic transformers are used to bridge large impedance mismatches, as between a transducer and air or tissue.','Acoustic impedance matching helps sound cross a boundary well. Each medium has an acoustic impedance. When two impedances differ a lot, sound reflects. Matching brings them closer so more sound passes. Horns and matching layers do this.','It maximises transfer of acoustic power across a boundary by reducing the impedance mismatch that would otherwise reflect the sound.','Designers use matching layers on ultrasonic and medical transducers, and horns on loudspeakers, to couple energy efficiently into air or tissue.','Data Sonification & Auditory Display',ARRAY['Acoustic impedance','Characteristic impedance','Matching layer','Horn loading','Reflection coefficient']::text[],ARRAY['Assuming a transducer couples well to air without any matching','Confusing acoustic impedance with electrical impedance','Ignoring the frequency dependence of a matching layer']::text[],ARRAY['Adding a matching layer to an ultrasound probe','Using a horn to load a compression driver','Coupling a transducer efficiently into water']::text[],'advanced','Z = ρ·c;  matched when Z₁ = Z₂','Specific acoustic impedance equals density times the speed of sound; energy transfers best when the two media''s impedances are equal.','b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='acoustic impedance matching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93d8d2c8-0cee-52c2-aa16-dcfd3d419841','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93d8d2c8-0cee-52c2-aa16-dcfd3d419841') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93d8d2c8-0cee-52c2-aa16-dcfd3d419841');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7addd45f-3af5-5cb2-bbfc-755fb8dee341','overload point','The overload point is the input level at which a device can no longer handle the signal linearly and begins to distort severely — through clipping, saturation, or, in a digital converter, full-scale limiting. It marks the upper boundary of the usable dynamic range; for a microphone it is often given as the maximum SPL for a stated distortion, and for a converter it corresponds to digital full scale.','The overload point is the level where a device starts to distort badly. Below it the signal stays clean. Above it the signal clips or saturates. For a mic it is the highest sound level it takes. For a converter it is full scale.','It defines the highest level a device can handle cleanly, setting the top of its dynamic range and guiding safe gain staging.','Engineers check overload points — microphone maximum SPL, converter full scale, preamp headroom — when setting gain to avoid distortion.','Data Sonification & Auditory Display',ARRAY['Clipping','Headroom','Maximum SPL','Dynamic range','Full scale']::text[],ARRAY['Setting gain so peaks pass the overload point and clip','Confusing the overload point with the noise floor at the other extreme','Assuming meters show true peaks that reach the overload point']::text[],ARRAY['Setting microphone gain below a converter''s full scale','Checking a mic''s maximum SPL for a loud source','Leaving headroom under a preamp''s overload point']::text[],'intermediate',NULL,NULL,'b87c9747-1e25-4a6d-9345-aceeb9441312' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='overload point');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7addd45f-3af5-5cb2-bbfc-755fb8dee341','b87c9747-1e25-4a6d-9345-aceeb9441312',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7addd45f-3af5-5cb2-bbfc-755fb8dee341') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7addd45f-3af5-5cb2-bbfc-755fb8dee341');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5bd62310-0d26-5d30-a152-36198e2ed179','AE hypocenter','In acoustic emission (AE) testing, the hypocenter is the located three-dimensional point of origin of an AE event within a material or structure, analogous to a seismic hypocenter. It is computed from the differences in arrival time of the elastic wave at several sensors together with an assumed wave velocity, allowing sources such as growing cracks to be pinpointed in depth as well as position.','Acoustic emission testing listens for tiny sounds from cracks in a material. The AE hypocenter is the point where such an event starts. It sits inside the structure, not just on the surface. It is found from when the sound reaches several sensors. This locates a flaw in three dimensions.','It pinpoints where inside a structure an acoustic emission source lies, so growing defects can be located, tracked, and assessed.','AE technicians compute hypocenters to locate active cracks inside pressure vessels, welds, and rock during structural monitoring.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic emission','Source localization','Time of arrival','Elastic wave','Nondestructive testing']::text[],ARRAY['Confusing the hypocenter (a three-dimensional origin) with a surface location','Trusting located points when the assumed wave velocity is wrong','Ignoring how sensor spacing limits accuracy']::text[],ARRAY['Locating a crack inside a pressure vessel','Monitoring microcracking in a rock sample','Mapping active flaws in a steel weld']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AE hypocenter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5bd62310-0d26-5d30-a152-36198e2ed179','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5bd62310-0d26-5d30-a152-36198e2ed179') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5bd62310-0d26-5d30-a152-36198e2ed179');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '36249c8f-9bf4-5178-90bb-4c496947d148','QEPAS','QEPAS (quartz-enhanced photoacoustic spectroscopy) is a trace-gas sensing technique in which modulated laser light absorbed by a target gas generates a periodic pressure wave that is detected not by a microphone but by a sharply resonant quartz tuning fork. The fork''s high quality factor and small size concentrate the acoustic signal, giving sensitive, selective detection from a very small gas volume.','QEPAS is a way to detect tiny amounts of a gas. A laser is tuned to the gas and switched on and off fast. The gas absorbs the light and makes a faint sound. A small quartz tuning fork picks up that sound. Its sharp resonance makes the method very sensitive.','It provides highly sensitive, compact trace-gas detection by using a resonant quartz fork instead of a microphone to sense the photoacoustic signal.','QEPAS sensors detect trace gases and pollutants in environmental monitoring, industrial leak detection, and breath analysis.','Sound Visualization & Acoustic Imaging',ARRAY['Photoacoustic spectroscopy','Photoacoustic effect','Quartz tuning fork','Trace-gas detection','Laser absorption spectroscopy']::text[],ARRAY['Assuming QEPAS needs a large acoustic cell like classic photoacoustics','Confusing the tuning fork''s resonance with the gas absorption line','Expecting a signal without tuning the laser to an absorption feature']::text[],ARRAY['Detecting a trace pollutant in air monitoring','Sensing a gas leak at low concentration','Measuring a marker gas in exhaled breath']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='QEPAS');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '36249c8f-9bf4-5178-90bb-4c496947d148','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='36249c8f-9bf4-5178-90bb-4c496947d148') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='36249c8f-9bf4-5178-90bb-4c496947d148');
